def resource_path(relative_path):
    if hasattr(sys, "_MEIPASS"):
        base_path = sys._MEIPASS
    else:
        base_path = str(Path(__file__).resolve().parent)
    return os.path.join(base_path, relative_path)

APP_INSTANCE_ID = "JBPad_SingleInstance"


def _single_instance_user_scope_tag() -> str:
    """Тег области single-instance для разведения пользователей на Unix.

    На Linux /tmp обычно общий, поэтому имя IPC и lock должны включать UID/EUID.
    На Windows возвращаем пустую строку (там temp по сути per-user).
    """
    try:
        if os.name != "posix":
            return ""
    except Exception:
        return ""
    try:
        uid = os.geteuid()
    except Exception:
        try:
            uid = os.getuid()
        except Exception:
            uid = None
    if uid is None:
        return ""
    try:
        return f"uid{int(uid)}"
    except Exception:
        return f"uid{uid}"


def _get_single_instance_server_name() -> str:
    """Имя локального IPC-сервера для single-instance.

    ВАЖНО:
    - Разводим .py и .exe (PyInstaller) по разным именам, чтобы они не перехватывали друг друга.
    - Оставляем базовый префикс стабильным для одного варианта запуска (py или exe) на одной OS/учётке.
    """
    try:
        variant = "exe" if getattr(sys, "frozen", False) else "py"
    except Exception:
        variant = "py"
    scope = _single_instance_user_scope_tag()
    if scope:
        return f"{APP_INSTANCE_ID}_{variant}_{scope}"
    return f"{APP_INSTANCE_ID}_{variant}"


def _get_single_instance_lock_path(server_name: str) -> str:
    """Путь к QLockFile для атомарного single-instance (кроссплатформенно)."""
    safe = re.sub(r"[^\w.-]+", "_", str(server_name or APP_INSTANCE_ID))
    return os.path.join(tempfile.gettempdir(), f"{safe}.lock")


def _single_instance_probe_live(server_name: str, timeout_ms: int = 300) -> bool:
    """True, если QLocalServer с server_name уже принимает подключения."""
    probe = QLocalSocket()
    try:
        probe.connectToServer(server_name)
        return bool(probe.waitForConnected(int(timeout_ms)))
    except Exception:
        return False


def _single_instance_send_activate(server_name: str) -> bytes:
    """Отправляет activate существующему инстансу; возвращает ответ сервера."""
    socket = QLocalSocket()
    try:
        socket.connectToServer(server_name)
        if not socket.waitForConnected(300):
            return b""
        socket.write(b"activate")
        socket.flush()
        socket.waitForBytesWritten(200)
        reply = b""
        if socket.waitForReadyRead(300):
            reply = bytes(socket.readAll())
        return reply
    except Exception:
        return b""


def _single_instance_wait_for_shutdown(server_name: str) -> bool:
    """True, если IPC-сервер исчез (предыдущий инстанс завершился)."""
    for _ in range(100):
        try:
            tmp = QLocalSocket()
            tmp.connectToServer(server_name)
            if not tmp.waitForConnected(100):
                return True
        except Exception:
            return True
        time.sleep(0.1)
    return False


def _single_instance_handoff_or_wait(server_name: str) -> bool:
    """Пробует передать управление живому инстансу. True — текущий процесс должен завершиться."""
    if not _single_instance_probe_live(server_name):
        return False

    reply = _single_instance_send_activate(server_name)
    if b"SHUTTING_DOWN" not in reply:
        return True

    if _single_instance_wait_for_shutdown(server_name):
        return False

    try:
        _qmessagebox_single_ok(
            QMessageBox.Information,
            None,
            "",
            tr(
                "message.instance_protection",
                "Приложение сейчас закрывается. Подождите пару секунд и запустите снова.",
            ),
        )
    except Exception:
        pass
    return True


def _single_instance_start_local_server(server_name: str):
    """Слушает QLocalServer; removeServer только если живого сервера нет."""
    server = QLocalServer()
    # На Unix ограничиваем доступ к сокету текущим пользователем.
    try:
        if os.name == "posix":
            server.setSocketOptions(QLocalServer.UserAccessOption)
    except Exception:
        pass
    if server.listen(server_name):
        return server

    if _single_instance_probe_live(server_name):
        return None

    try:
        QLocalServer.removeServer(server_name)
    except Exception:
        pass

    server = QLocalServer()
    try:
        if os.name == "posix":
            server.setSocketOptions(QLocalServer.UserAccessOption)
    except Exception:
        pass
    if server.listen(server_name):
        return server
    return None


def _acquire_single_instance(server_name: str):
    """Захват single-instance: QLockFile + безопасный QLocalServer.

    Returns:
        (should_exit, lock_file, server)
    """
    lock_path = _get_single_instance_lock_path(server_name)
    lock_file = QLockFile(lock_path)
    lock_file.setStaleLockTime(0)

    if not lock_file.tryLock(200):
        if _single_instance_handoff_or_wait(server_name):
            return True, None, None

        acquired = False
        for _ in range(30):
            time.sleep(0.05)
            if lock_file.tryLock(50):
                acquired = True
                break
            if _single_instance_probe_live(server_name):
                if _single_instance_handoff_or_wait(server_name):
                    return True, None, None

        if not acquired:
            lock_file.setStaleLockTime(3000)
            if not lock_file.tryLock(100):
                if _single_instance_probe_live(server_name):
                    if _single_instance_handoff_or_wait(server_name):
                        return True, None, None
                try:
                    lock_file.removeStaleLockFile()
                except Exception:
                    pass
                if not lock_file.tryLock(100):
                    if _single_instance_handoff_or_wait(server_name):
                        return True, None, None

    server = _single_instance_start_local_server(server_name)
    if server is None:
        try:
            lock_file.unlock()
        except Exception:
            pass
        if _single_instance_handoff_or_wait(server_name):
            return True, None, None
        server = QLocalServer()

    return False, lock_file, server


# Определение APP_DIR с учетом PyInstaller
if getattr(sys, 'frozen', False):
    executable_dir = Path(sys.executable).resolve()

    if sys.platform == "darwin":
        # macOS .app:
        # .../JBPad.app/Contents/MacOS/JBPad
        # portable root = каталог над JBPad.app
        APP_DIR = executable_dir.parents[3]
    else:
        APP_DIR = executable_dir.parent
else:
    # В обычном режиме используем директорию скрипта
    APP_DIR = Path(__file__).resolve().parent

def _shutdown_qthread_pair(thread, worker, *, signal_disconnects=(), worker_signal_disconnects=(), wait_ms=5000):
    """Останавливает QThread/worker: disconnect → quit → wait. Без moveToThread/sip.delete."""
    if thread is None:
        return
    for signal, slot in signal_disconnects:
        try:
            signal.disconnect(slot)
        except Exception:
            pass
    for signal, slot in worker_signal_disconnects:
        try:
            signal.disconnect(slot)
        except Exception:
            pass
    if worker is not None:
        try:
            thread.finished.disconnect(worker.deleteLater)
        except Exception:
            pass
    try:
        thread.finished.disconnect(thread.deleteLater)
    except Exception:
        pass
    if thread.isRunning():
        try:
            thread.quit()
        except Exception:
            pass
        try:
            if not thread.wait(int(wait_ms)):
                try:
                    thread.terminate()
                except Exception:
                    pass
                try:
                    thread.wait()
                except Exception:
                    pass
        except Exception:
            pass
    app = QApplication.instance()
    if app is not None:
        try:
            app.processEvents(QEventLoop.AllEvents, 200)
        except Exception:
            pass


def _py_exit_after_qt_teardown(exit_code):
    """Обход segfault PyQt5 при teardown интерпретатора на Linux/macOS (.py и frozen).

    После штатного app.exec_() и shutdown-логики Python/sip уничтожают QApplication
    и дочерние C++-объекты в порядке, который на Linux+X11/Wayland и macOS+PyQt 5.15
    даёт SIGSEGV (<no Python frame>). os._exit() завершает процесс без atexit/GC — данные
    уже сохранены shutdown-логикой внутри app.exec_().

    Windows: возвращает False — вызывающий код использует обычный sys.exit().
    """
    if sys.platform != "darwin" and not sys.platform.startswith("linux"):
        return False
    try:
        code = int(exit_code)
    except Exception:
        code = 0
    os._exit(code)
    return True  # unreachable


def _configure_macos_qaction_shortcut(action):
    """macOS без QMenuBar: TextHeuristicRole уводит ⌘+N и др. в нативное меню без triggered."""
    if sys.platform != "darwin" or action is None:
        return
    try:
        action.setShortcutContext(Qt.ApplicationShortcut)
        action.setMenuRole(QAction.NoRole)
    except Exception:
        pass


_WIN_LEGACY_PATH_LIMIT = 260
_WIN_EXTENDED_PATH_LIMIT = 32767

_TRUNCATION_TOOLTIP_RESHOW_COOLDOWN_MS = 800


def _truncation_tooltip_index_key(index):
    try:
        parts = []
        idx = index
        while idx.isValid():
            parts.append(int(idx.row()))
            idx = idx.parent()
        return tuple(reversed(parts))
    except Exception:
        try:
            return (int(index.row()),)
        except Exception:
            return ()


def _truncation_tooltip_should_show(widget, show_key):
    """QToolTip.isVisible() ненадёжен сразу после showText — dedupe по ключу и времени."""
    try:
        if getattr(widget, "_truncation_tooltip_show_key", None) != show_key:
            return True
        age_ms = (time.time() * 1000.0) - float(getattr(widget, "_truncation_tooltip_show_ms", 0.0) or 0.0)
        return age_ms >= float(_TRUNCATION_TOOLTIP_RESHOW_COOLDOWN_MS)
    except Exception:
        return True


def _truncation_tooltip_mark_shown(widget, show_key):
    widget._truncation_tooltip_show_key = show_key
    widget._truncation_tooltip_show_ms = time.time() * 1000.0


def _truncation_tooltip_clear_shown(widget):
    widget._truncation_tooltip_show_key = None
    widget._truncation_tooltip_show_ms = 0.0


def _truncation_tooltip_keepalive_should_restore(widget):
    try:
        age_ms = (time.time() * 1000.0) - float(getattr(widget, "_truncation_tooltip_show_ms", 0.0) or 0.0)
        if age_ms < float(_TRUNCATION_TOOLTIP_RESHOW_COOLDOWN_MS):
            return False
    except Exception:
        pass
    try:
        return not QToolTip.isVisible()
    except Exception:
        return True


def _fm_single_line_width(fm, text: str) -> int:
    """Надёжная ширина однострочного текста (кириллица/Linux: horizontalAdvance может занижать)."""
    if not text:
        return 0
    w_adv = 0
    w_bound = 0
    w_size = 0
    try:
        w_adv = int(fm.horizontalAdvance(text))
    except Exception:
        pass
    try:
        w_bound = int(fm.boundingRect(QRect(0, 0, 0, 0), Qt.AlignLeft | Qt.TextSingleLine, text).width())
    except Exception:
        pass
    try:
        w_size = int(fm.size(Qt.TextSingleLine, text).width())
    except Exception:
        pass
    return max(w_adv, w_bound, w_size)


def _fm_is_elided(fm, text, avail_w) -> bool:
    """True, если elidedText обрезает строку (та же логика, что в paint)."""
    if not text or avail_w <= 0:
        return False
    try:
        return fm.elidedText(str(text), Qt.ElideRight, int(avail_w)) != str(text)
    except Exception:
        return False


def _win_display_path(path):
    """Убирает префикс extended path (\\?\\) для отображения и сравнения."""
    if path is None:
        return path
    try:
        s = str(path)
    except Exception:
        return path
    if s.startswith("\\\\?\\UNC\\"):
        return "\\\\" + s[8:]
    if s.startswith("\\\\?\\"):
        return s[4:]
    return s


def _path_is_empty(path) -> bool:
    if path is None:
        return True
    try:
        return str(path) == ""
    except Exception:
        return True


def _normalize_path_string(path) -> str:
    """Нормализация строки пути: strip только на Windows (POSIX сохраняет пробелы в именах)."""
    s = str(path)
    if sys.platform == "win32":
        return s.strip()
    return s


def _strip_ini_path_value(path) -> str:
    """INI/конфиг: убрать только перевод строки, не пробелы в имени файла."""
    return str(path).rstrip("\r\n")


def _normalize_portable_relative_path(path) -> str:
    """INI relative path: \\ и / → разделители текущей ОС (portable read)."""
    s = _strip_ini_path_value(path)
    if sys.platform == "win32":
        s = s.strip()
    if not s:
        return s
    if os.path.isabs(s):
        return os.path.normpath(_win_display_path(s))
    s = s.replace("\\", "/")
    parts = [p for p in s.split("/") if p and p != "."]
    if not parts:
        return ""
    if ".." in parts:
        return os.path.normpath(os.path.join(*parts))
    return os.path.join(*parts)


def _portable_relative_path_for_ini(relative_path) -> str:
    """Канонический portable relative path для Setting.ini (forward slashes)."""
    try:
        s = str(relative_path or "")
    except Exception:
        return ""
    if not s:
        return s
    if os.path.isabs(s):
        return s
    return s.replace("\\", "/")


def _win_qt_path(path):
    """Абсолютный путь для Qt (QSaveFile и т.д.) — всегда без префикса \\\\?\\."""
    if path is None:
        return path
    try:
        s = _normalize_path_string(path)
    except Exception:
        return path
    if s == "":
        return s
    return os.path.normpath(os.path.abspath(_win_display_path(s)))


def _win_io_path(path):
    """Абсолютный путь для disk I/O; на Windows — extended (\\?\\) только для длинных путей."""
    if path is None:
        return path
    try:
        s = _normalize_path_string(path)
    except Exception:
        return path
    if s == "":
        return s
    if sys.platform != "win32":
        return os.path.normpath(os.path.abspath(s))
    if s.startswith("\\\\?\\"):
        return s
    abs_path = os.path.abspath(os.path.normpath(_win_display_path(s)))
    if len(abs_path) < _WIN_LEGACY_PATH_LIMIT:
        return abs_path
    if abs_path.startswith("\\\\"):
        return "\\\\?\\UNC\\" + abs_path[2:]
    return "\\\\?\\" + abs_path


def _win_path_length(path):
    try:
        return len(os.path.abspath(_win_display_path(str(path))))
    except Exception:
        try:
            return len(str(path or ""))
        except Exception:
            return 0


def _is_windows_legacy_path_too_long(path):
    if sys.platform != "win32":
        return False
    return _win_path_length(path) >= _WIN_LEGACY_PATH_LIMIT


def _is_windows_extended_path_too_long(path):
    if sys.platform != "win32":
        return False
    return _win_path_length(path) >= _WIN_EXTENDED_PATH_LIMIT


def _path_too_long_in_text(text):
    try:
        msg = str(text or "").lower()
    except Exception:
        return False
    return (
        "too long" in msg
        or "filename or extension is too long" in msg
    )


def _is_windows_path_too_long_error(exc):
    if sys.platform != "win32":
        return False
    if isinstance(exc, OSError):
        winerror = getattr(exc, "winerror", None)
        if winerror == 206:
            return True
        return _path_too_long_in_text(exc)
    if isinstance(exc, str):
        return _path_too_long_in_text(exc)
    return False


def _io_open(path, mode, *args, **kwargs):
    return open(_win_io_path(path), mode, *args, **kwargs)


def _io_exists(path):
    return os.path.exists(_win_io_path(path))


def _io_makedirs(path, exist_ok=False):
    return os.makedirs(_win_io_path(path), exist_ok=exist_ok)


def _io_getsize(path):
    return os.path.getsize(_win_io_path(path))


def _io_listdir(path):
    return os.listdir(_win_io_path(path))


def _io_isfile(path):
    return os.path.isfile(_win_io_path(path))


def _io_isdir(path):
    return os.path.isdir(_win_io_path(path))


def _io_replace(src, dst):
    return os.replace(_win_io_path(src), _win_io_path(dst))


def _io_fsync_file_fd(fd: int) -> None:
    try:
        os.fsync(int(fd))
    except OSError:
        pass


def _io_fsync_directory(directory) -> None:
    """Durable metadata каталога после rename/create (POSIX; best-effort)."""
    if not directory:
        return
    dir_path = _win_io_path(str(directory))
    flags = os.O_RDONLY
    if hasattr(os, "O_DIRECTORY"):
        flags |= os.O_DIRECTORY
    try:
        dir_fd = os.open(dir_path, flags)
    except OSError:
        return
    try:
        os.fsync(dir_fd)
    except OSError:
        pass
    finally:
        try:
            os.close(dir_fd)
        except OSError:
            pass


def _io_remove(path):
    return os.remove(_win_io_path(path))


def _posix_process_umask() -> int:
    """Текущая umask процесса (без изменения)."""
    mask = os.umask(0)
    os.umask(mask)
    return mask


def _default_file_mode() -> int:
    """Режим нового файла с учётом umask (POSIX; на Windows безопасен)."""
    return 0o666 & ~_posix_process_umask()


def _default_dir_mode() -> int:
    """Режим нового каталога с учётом umask (POSIX; на Windows безопасен)."""
    return 0o777 & ~_posix_process_umask()


def _io_existing_file_mode(path):
    """Текущий mode файла (только permission bits) или None."""
    if not _io_exists(path):
        return None
    try:
        return stat.S_IMODE(os.stat(_win_io_path(path)).st_mode)
    except OSError:
        return None


def _io_chmod_mode(path, mode: int) -> None:
    try:
        os.chmod(_win_io_path(path), int(mode))
    except OSError:
        pass


_dir_case_sensitivity_cache = {}
_volume_case_sensitivity_cache = {}
_CIPROBE_PREFIX = ".__jbp_ciprobe_"
_JBPAD_ATOMIC_PREFIX = ".jbpad_atomic_"
_JBPAD_EXPORT_PREFIX = ".jbpad_export_"
# QSaveFile (Qt): temp рядом с целевым файлом — «Setting.ini.cWyiPX», «note.json.a1B2c3».
_QSAVEFILE_ORPHAN_TEMP_RE = re.compile(r"^(.+\.(?:ini|json))\.([A-Za-z0-9]{6})$")


def _is_qsavefile_orphan_temp(name: str) -> bool:
    """True для осиротевших temp QSaveFile (6-символьный суффикс после .ini/.json)."""
    return bool(_QSAVEFILE_ORPHAN_TEMP_RE.match(str(name or "")))


def _directory_case_sensitivity_key(directory):
    """Канонический ключ каталога для кеша probe case-sensitivity."""
    try:
        return os.path.normcase(os.path.realpath(_win_io_path(str(directory))))
    except OSError:
        return None


def _directory_mount_id(directory):
    """Идентификатор тома (st_dev) для кеша probe case-sensitivity."""
    try:
        return os.stat(_win_io_path(str(directory))).st_dev
    except OSError:
        return None


def _probe_directory_case_insensitive(directory: str) -> bool:
    """Проверяет, считает ли ФС имена, отличающиеся только регистром, одним файлом."""
    token = f"{os.getpid()}_{time.time_ns()}"
    lower_name = f"{_CIPROBE_PREFIX}{token}_aaa"
    upper_name = f"{_CIPROBE_PREFIX}{token}_AAA"
    if lower_name == upper_name:
        return False
    path_lower = os.path.join(str(directory), lower_name)
    path_upper = os.path.join(str(directory), upper_name)
    fd = None
    try:
        fd = os.open(_win_io_path(path_lower), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
        os.close(fd)
        fd = None
        return _io_exists(path_upper)
    except OSError:
        return False
    finally:
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
        try:
            if _io_exists(path_lower):
                _io_remove(path_lower)
        except OSError:
            pass


def _directory_is_case_insensitive(directory) -> bool:
    """True, если каталог на case-insensitive томе (Windows или probe на POSIX)."""
    if sys.platform == "win32":
        return True
    if not directory:
        return False

    mount_id = _directory_mount_id(directory)
    if mount_id is not None:
        cached = _volume_case_sensitivity_cache.get(mount_id)
        if cached is not None:
            return cached

    cache_key = _directory_case_sensitivity_key(directory)
    if cache_key:
        cached = _dir_case_sensitivity_cache.get(cache_key)
        if cached is not None:
            if mount_id is not None:
                _volume_case_sensitivity_cache[mount_id] = cached
            return cached

    result = _probe_directory_case_insensitive(str(directory))
    if cache_key:
        _dir_case_sensitivity_cache[cache_key] = result
    if mount_id is not None:
        _volume_case_sensitivity_cache[mount_id] = result
    return result


def _cleanup_stale_ciprobe_files(*directories) -> None:
    """Удаляет осиротевшие probe-файлы после аварийного завершения."""
    seen = set()
    for directory in directories:
        if not directory:
            continue
        try:
            key = os.path.realpath(_win_io_path(str(directory)))
        except OSError:
            key = str(directory)
        if key in seen:
            continue
        seen.add(key)
        try:
            for name in _io_listdir(key):
                if str(name).startswith(_CIPROBE_PREFIX):
                    try:
                        _io_remove(os.path.join(key, name))
                    except OSError:
                        pass
        except OSError:
            pass


def _cleanup_stale_jbpad_temp_artifacts(*directories) -> None:
    """Удаляет осиротевшие atomic/export/QSaveFile temp после hard kill или сбоя commit."""
    seen = set()
    for directory in directories:
        if not directory:
            continue
        try:
            key = os.path.realpath(_win_io_path(str(directory)))
        except OSError:
            key = str(directory)
        if key in seen:
            continue
        seen.add(key)
        try:
            for name in _io_listdir(key):
                sname = str(name)
                full_path = os.path.join(key, sname)
                if sname.startswith(_JBPAD_ATOMIC_PREFIX) and sname.endswith(".tmp"):
                    try:
                        _io_remove(full_path)
                    except OSError:
                        pass
                elif _is_qsavefile_orphan_temp(sname):
                    try:
                        _io_remove(full_path)
                    except OSError:
                        pass
                elif sname.startswith(_JBPAD_EXPORT_PREFIX):
                    try:
                        if _io_isdir(full_path):
                            shutil.rmtree(_win_io_path(full_path), ignore_errors=True)
                    except OSError:
                        pass
        except OSError:
            pass


def _startup_filesystem_probe_init() -> None:
    """Startup: sweep ciprobe/temp-мусора и прогрев кеша CI для рабочих каталогов."""
    roots = [str(APP_DIR), str(APP_DIR / "Data")]
    _cleanup_stale_ciprobe_files(*roots)
    _cleanup_stale_jbpad_temp_artifacts(*roots)
    for root in roots:
        try:
            _directory_is_case_insensitive(root)
        except Exception:
            pass


def _use_case_insensitive_filename_compare(directory=None) -> bool:
    if sys.platform == "win32":
        return True
    if directory:
        return _directory_is_case_insensitive(directory)
    return False


def _filename_compare_key(name: str, *, directory=None) -> str:
    """Ключ сравнения имён: NFC+casefold на CI/Windows; на CS POSIX — точное имя."""
    try:
        s = str(name)
    except Exception:
        s = name
    if _use_case_insensitive_filename_compare(directory):
        try:
            s = unicodedata.normalize("NFC", s)
        except Exception:
            pass
        try:
            return s.casefold()
        except Exception:
            return s
    try:
        return os.path.normcase(s)
    except Exception:
        return s


def _abs_realpath_for_comparison(path):
    """Абсолютный путь с разрешением symlinks для сравнения (кроссплатформенно)."""
    if path is None:
        return None
    try:
        raw = _win_display_path(_normalize_path_string(path))
        if _path_is_empty(raw):
            return None
        if os.path.isabs(raw):
            abs_path = os.path.normpath(os.path.abspath(raw))
        else:
            # Относительные пути — от каталога программы, не от cwd (важно для Linux).
            abs_path = os.path.normpath(os.path.join(str(APP_DIR), raw))
    except Exception:
        return None
    try:
        try:
            return os.path.realpath(abs_path, strict=False)
        except TypeError:
            return os.path.realpath(abs_path)
    except (OSError, ValueError):
        return abs_path


def _paths_refer_to_same_file(a, b) -> bool:
    """True, если a и b указывают на один и тот же путь (symlinks, регистр, форма записи)."""
    if not a or not b:
        return False
    ca = _canonical_file_path(a)
    cb = _canonical_file_path(b)
    if ca and cb and ca == cb:
        return True
    ra = _abs_realpath_for_comparison(a)
    rb = _abs_realpath_for_comparison(b)
    if not ra or not rb:
        return False
    if ra == rb:
        return True
    try:
        ka = _filesystem_path_key(a)
        kb = _filesystem_path_key(b)
        if ka and kb and ka == kb:
            return True
    except Exception:
        pass
    try:
        if os.path.exists(ra) and os.path.exists(rb) and os.path.samefile(ra, rb):
            return True
    except (OSError, ValueError):
        pass
    return False


def _deleted_file_parent_is(directory_path, file_path) -> bool:
    """True, если файл лежит непосредственно в указанном каталоге."""
    file_resolved = _abs_realpath_for_comparison(file_path)
    if not file_resolved:
        return False
    parent = os.path.dirname(file_resolved)
    return _paths_refer_to_same_file(parent, directory_path)


def _filesystem_path_key(filepath):
    """Нормализованный ключ пути для сравнения/кеша с учётом CI-ФС."""
    if not filepath:
        return None
    abs_path = _abs_realpath_for_comparison(filepath)
    if not abs_path:
        return None
    if sys.platform == "win32":
        return os.path.normcase(abs_path)
    parent, base = os.path.split(abs_path)
    if parent and base and _directory_is_case_insensitive(parent):
        try:
            parent_key = _filesystem_path_key(parent)
            base_key = unicodedata.normalize("NFC", base).casefold()
        except Exception:
            parent_key = None
            base_key = base
        if parent_key:
            return os.path.join(parent_key, base_key)
    return os.path.normcase(abs_path)


def data_directory():
    """Каталог Data рядом с программой (блокноты, языки, темы)."""
    return APP_DIR / "Data"


def data_languages_dir():
    """Каталог файлов локализации: Data/languages."""
    return data_directory() / "languages"


def data_themes_dir():
    """Каталог файлов тем: Data/theme."""
    return data_directory() / "theme"


def ensure_data_languages_dir():
    """Создаёт Data/languages только при сохранении перевода."""
    _io_makedirs(str(data_languages_dir()), exist_ok=True)


def ensure_data_themes_dir():
    """Создаёт Data/theme только при сохранении темы."""
    _io_makedirs(str(data_themes_dir()), exist_ok=True)


_DATA_DIRECTORY_CREATE_FAIL_NOTIFIED = False


def ensure_data_directory() -> bool:
    """Создаёт каталог Data, если его нет. True — каталог существует и это директория."""
    global _DATA_DIRECTORY_CREATE_FAIL_NOTIFIED
    path = str(data_directory())
    try:
        if _io_exists(path) and not _io_isdir(path):
            return False
        if not _io_isdir(path):
            _io_makedirs(path, exist_ok=True)
        if _io_isdir(path):
            _DATA_DIRECTORY_CREATE_FAIL_NOTIFIED = False
            return True
        return False
    except OSError:
        return False


JBP_KIND_NOTEBOOK = "notebook"
JBP_KIND_THEME = "theme"
JBP_KIND_LOCALE = "locale"
JBP_KIND_FULL_DATE_LOCALES = "full_date_locale_file"
DEFAULT_DATE_LOCALES_FILENAME = "DEFAULT_DATE_LOCALES.json"
LOCALE_META_FULL_DATE_LOCALE_KEY = "full_date_locale"
LOCALE_META_NONE_VALUE = "None"
_FALLBACK_FULL_DATE_LOCALE = "ru"
_BASE_RU_LOCALE_NAME = "Русский"
_JBP_HEADER_PREFIX = "# JBPad "
_JBP_PEEK_BYTES = 128
_TXT_ENCODING_SAMPLE_BYTES = 256 * 1024
_NOTEBOOK_SIZE_WARN_BYTES = 50 * 1024 * 1024
_TXT_SIZE_WARN_BYTES = 5 * 1024 * 1024
_TXT_SIZE_MAX_BYTES = 50 * 1024 * 1024
_IMPORT_DIR_MAX_DEPTH = 64
_IMPORT_UI_BATCH_SIZE = 25
_NODE_EDITOR_DOC_CACHE_MAX = 24


def _editor_is_alive(editor) -> bool:
    """True, если QWidget ещё не уничтожен Qt (защита от use-after-free в QTimer)."""
    if editor is None:
        return False
    try:
        import sip
        if sip.isdeleted(editor):
            return False
    except Exception:
        pass
    try:
        editor.objectName()
        return True
    except RuntimeError:
        return False
    except Exception:
        return False


def _clear_editor_flag_safe(editor, attr, value=False):
    """setattr для отложенных таймеров: молча игнорирует удалённый C++-объект."""
    if not _editor_is_alive(editor):
        return
    try:
        setattr(editor, attr, value)
    except RuntimeError:
        pass
    except Exception:
        pass


def _read_txt_file_for_import(file_path):
    """Читает txt для импорта (worker thread). Возвращает str или None."""
    try:
        with _io_open(file_path, "rb") as f:
            raw = f.read()
    except Exception:
        return None
    if raw is None:
        return None
    encoding = _detect_txt_encoding_from_bytes(raw)
    try:
        return raw.decode(encoding, errors="replace")
    except Exception:
        return None


def _scan_txt_import_folder_entries(folder_path, visited=None, depth=0, rel_parts=()):
    """Список (abs_path, rel_parts, fail_label) для рекурсивного импорта папки."""
    entries = []
    if visited is None:
        visited = set()
    if depth > _IMPORT_DIR_MAX_DEPTH:
        return entries
    visit_key = _import_dir_visit_key(folder_path)
    if not visit_key or visit_key in visited:
        return entries
    visited.add(visit_key)
    try:
        items = []
        for item_name in _io_listdir(folder_path):
            item_path = os.path.join(folder_path, item_name)
            items.append((item_name, item_path))
        items.sort(key=lambda x: (_io_isdir(x[1]), x[0].lower()))
        for item_name, item_path in items:
            if _io_isfile(item_path) and item_name.lower().endswith(".txt"):
                entries.append((item_path, rel_parts, item_name))
            elif _io_isdir(item_path) and not os.path.islink(_win_io_path(item_path)):
                entries.extend(
                    _scan_txt_import_folder_entries(
                        item_path,
                        visited=visited,
                        depth=depth + 1,
                        rel_parts=rel_parts + (item_name,),
                    )
                )
    except (RecursionError, OSError):
        pass
    return entries


def _scan_txt_import_file_entries(file_paths):
    """Список (abs_path, rel_parts, fail_label) для импорта выбранных файлов."""
    entries = []
    for file_path in file_paths or []:
        if _io_isfile(file_path) and str(file_path).lower().endswith(".txt"):
            label = os.path.basename(file_path)
            entries.append((file_path, (), label))
    return entries


def _import_dir_visit_key(path):
    """Канонический ключ каталога для защиты от циклов (symlink/junction) при импорте."""
    try:
        return os.path.normcase(os.path.realpath(_win_io_path(path)))
    except OSError:
        return None


def _detect_txt_encoding_from_bytes(raw: bytes) -> str:
    """Определяет кодировку TXT по BOM и начальному фрагменту (без полного decode всего файла)."""
    if not raw:
        return "utf-8"
    if raw.startswith(b"\xff\xfe") or raw.startswith(b"\xfe\xff"):
        return "utf-16"
    if raw.startswith(b"\xef\xbb\xbf"):
        return "utf-8-sig"
    sample = raw[:_TXT_ENCODING_SAMPLE_BYTES]
    for enc in ("utf-8", "cp1251", "cp866", "koi8-r"):
        try:
            sample.decode(enc, errors="strict")
            return enc
        except UnicodeDecodeError:
            continue
    return "utf-8"


def _format_file_size_human(size_bytes) -> str:
    try:
        n = int(size_bytes)
    except (TypeError, ValueError):
        return "—"
    if n < 0:
        return "—"
    if n >= 1024 ** 3:
        return f"{n / (1024 ** 3):.1f} GB"
    return f"{max(1, round(n / (1024 ** 2)))} MB"


def jbp_header_line(kind):
    """Первая строка файла JBPad (kind: notebook | theme | locale)."""
    return f"{_JBP_HEADER_PREFIX}{kind}\n"


def jbp_peek_kind(path):
    """O(1): тип JBPad-файла или None, если это не наш JSON."""
    try:
        with _io_open(path, "rb") as f:
            raw = f.read(_JBP_PEEK_BYTES)
        if raw.startswith(b"\xef\xbb\xbf"):
            raw = raw[3:]
        line = raw.split(b"\n", 1)[0].decode("utf-8", errors="replace").strip()
        if not line.startswith(_JBP_HEADER_PREFIX):
            return None
        kind = line[len(_JBP_HEADER_PREFIX):].strip()
        return kind or None
    except OSError:
        return None


def jbp_is_valid(path, kind=None):
    """True, если файл помечен как JBPad (и опционально нужного kind)."""
    found = jbp_peek_kind(path)
    if found is None:
        return False
    if kind is None:
        return True
    return found == kind


def _jbp_normalize_full_date_locale_meta(value):
    """Нормализует значение full_date_locale из заголовка locale-файла."""
    if value is None:
        return None
    s = str(value).strip()
    if not s or s == LOCALE_META_NONE_VALUE:
        return None
    return s


def _jbp_parse_full_date_locale_comment_line(line):
    """Разбирает строку '# full_date_locale=...'; (value, matched)."""
    try:
        stripped = str(line or "").strip()
    except Exception:
        return None, False
    if not stripped.startswith("#"):
        return None, False
    body = stripped[1:].strip()
    prefix = LOCALE_META_FULL_DATE_LOCALE_KEY + "="
    if not body.startswith(prefix):
        return None, False
    raw = body[len(prefix):]
    return _jbp_normalize_full_date_locale_meta(raw), True


def _jbp_skip_header_and_comments(f, *, parse_locale_meta=False):
    """Читает заголовок JBPad и #-комментарии; возвращает (kind, full_date_locale|None)."""
    first = f.readline()
    if not first.strip().startswith(_JBP_HEADER_PREFIX):
        return None, None
    kind = first.strip()[len(_JBP_HEADER_PREFIX):].strip() or None
    full_date_locale = None
    while True:
        pos = f.tell()
        line = f.readline()
        if not line:
            return kind, full_date_locale
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith("#"):
            if parse_locale_meta:
                parsed, matched = _jbp_parse_full_date_locale_comment_line(stripped)
                if matched:
                    full_date_locale = parsed
            continue
        f.seek(pos)
        break
    return kind, full_date_locale


def jbp_load_locale(path):
    """Загружает locale JSON и full_date_locale из заголовка. (data, meta) или (None, None)."""
    if not jbp_is_valid(path, JBP_KIND_LOCALE):
        return None, None
    try:
        with _io_open(path, "r", encoding="utf-8-sig") as f:
            kind, full_date_locale = _jbp_skip_header_and_comments(
                f, parse_locale_meta=True
            )
            if kind != JBP_KIND_LOCALE:
                return None, None
            data = json.load(f)
            if not isinstance(data, dict):
                return None, None
            return data, full_date_locale
    except Exception:
        return None, None


def jbp_load_json(path, kind=None):
    """Загружает JSON после заголовка JBPad; None если файл чужой или битый."""
    if kind == JBP_KIND_LOCALE:
        data, _meta = jbp_load_locale(path)
        return data
    if kind is not None and not jbp_is_valid(path, kind):
        return None
    try:
        with _io_open(path, "r", encoding="utf-8-sig") as f:
            found_kind, _meta = _jbp_skip_header_and_comments(f, parse_locale_meta=False)
            if found_kind is None:
                return None
            if kind is not None and found_kind != kind:
                return None
            return json.load(f)
    except Exception:
        return None


def jbp_locale_json_bytes(data, full_date_locale=None, *, indent=2, compact=False) -> bytes:
    """UTF-8 bytes locale-файла с заголовком JBPad (для атомарной записи)."""
    meta_str = (
        LOCALE_META_NONE_VALUE
        if full_date_locale is None
        else str(full_date_locale)
    )
    if compact:
        body = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    else:
        body = json.dumps(data, ensure_ascii=False, indent=indent)
    text = (
        jbp_header_line(JBP_KIND_LOCALE)
        + f"# {LOCALE_META_FULL_DATE_LOCALE_KEY}={meta_str}\n"
        + body
    )
    return text.encode("utf-8")


def jbp_kind_json_bytes(kind, data, *, indent=2, compact=False) -> bytes:
    """UTF-8 bytes JBPad JSON с заголовком указанного kind."""
    if compact:
        body = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    else:
        body = json.dumps(data, ensure_ascii=False, indent=indent)
    return (jbp_header_line(kind) + body).encode("utf-8")


def _jbp_write_bytes_exclusive_create(path, data: bytes) -> None:
    """Создаёт новый файл атомарно (O_EXCL); не перезаписывает существующий."""
    display_path = _win_display_path(str(path))
    parent_dir = os.path.dirname(display_path)
    basename = os.path.basename(display_path)
    if (
        parent_dir
        and basename
        and find_filename_in_dir_case_insensitive(parent_dir, basename)
    ):
        raise FileExistsError(basename)

    qt_path = _win_qt_path(path)
    parent = os.path.dirname(qt_path) or "."
    _io_makedirs(parent, exist_ok=True)

    io_path = _win_io_path(qt_path)
    created = False
    try:
        fd = os.open(io_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, _default_file_mode())
        created = True
    except FileExistsError:
        raise FileExistsError(basename or os.path.basename(qt_path))
    except OSError as exc:
        if getattr(exc, "errno", None) == errno.EEXIST:
            raise FileExistsError(basename or os.path.basename(qt_path)) from exc
        raise

    try:
        with os.fdopen(fd, "wb") as f:
            if f.write(data) != len(data):
                raise OSError("incomplete write")
            f.flush()
            _io_fsync_file_fd(f.fileno())
    except Exception:
        if created:
            try:
                _io_remove(qt_path)
            except OSError:
                pass
        raise
    _io_fsync_directory(parent)


def _jbp_path_is_symlink(path) -> bool:
    """True, если финальный компонент пути — symlink (не следует за ссылкой)."""
    try:
        io_path = _win_io_path(_win_qt_path(path))
    except Exception:
        return False
    try:
        return bool(os.path.islink(io_path))
    except OSError:
        return False


def _jbp_symlink_aware_replace_target(path):
    """Путь для os.replace: при symlink — target, сам symlink не заменяется."""
    qt_path = _win_qt_path(path)
    io_path = _win_io_path(qt_path)
    if not os.path.islink(io_path):
        return qt_path
    try:
        return os.path.realpath(io_path)
    except OSError as exc:
        raise OSError(f"cannot resolve symlink for write: {qt_path}") from exc


def _jbp_write_bytes_atomic_python(path, data: bytes) -> None:
    """Атомарная запись через temp + replace (Python I/O, extended path на Windows).

    Если path — symlink, replace выполняется по target (как QSaveFile), symlink сохраняется.
    """
    replace_target = _jbp_symlink_aware_replace_target(path)
    directory = os.path.dirname(replace_target) or "."
    if directory:
        _io_makedirs(directory, exist_ok=True)
    file_mode = _io_existing_file_mode(replace_target)
    if file_mode is None:
        file_mode = _default_file_mode()
    tmp_path = None
    try:
        fd, tmp_path = tempfile.mkstemp(
            prefix=".jbpad_atomic_",
            suffix=".tmp",
            dir=_win_io_path(directory),
        )
        _io_chmod_mode(tmp_path, file_mode)
        try:
            with os.fdopen(fd, "wb") as f:
                if f.write(data) != len(data):
                    raise OSError("incomplete write")
                f.flush()
                _io_fsync_file_fd(f.fileno())
        except Exception:
            try:
                os.close(fd)
            except Exception:
                pass
            raise
        _io_replace(tmp_path, replace_target)
        tmp_path = None
        _io_fsync_directory(directory)
    finally:
        if tmp_path:
            try:
                _io_remove(tmp_path)
            except OSError:
                pass


def _jbp_write_bytes_atomic_qsavefile(qt_path, data: bytes) -> None:
    """Атомарная запись через QSaveFile (только обычные пути без \\\\?\\)."""
    save_file = QSaveFile(qt_path)
    flags = QIODevice.WriteOnly | QIODevice.Truncate
    if not save_file.open(flags):
        try:
            err = str(save_file.errorString() or "open failed")
        except Exception:
            err = "open failed"
        raise OSError(err)
    try:
        if save_file.write(data) != len(data):
            raise OSError("incomplete write")
    except Exception:
        try:
            save_file.cancelWriting()
        except Exception:
            pass
        raise
    if not save_file.commit():
        try:
            err = str(save_file.errorString() or "commit failed")
        except Exception:
            err = "commit failed"
        raise OSError(err)


def jbp_write_bytes_atomic(path, data: bytes, *, exclusive: bool = False) -> None:
    """Атомарно записывает bytes: QSaveFile (Windows) или temp+replace (POSIX / fallback).

    exclusive=True — создать новый файл через O_EXCL (без temp+replace и без перезаписи).
    """
    if exclusive:
        _jbp_write_bytes_exclusive_create(path, data)
        return
    qt_path = _win_qt_path(path)
    parent = os.path.dirname(qt_path)
    if parent:
        _io_makedirs(parent, exist_ok=True)
    if _jbp_path_is_symlink(path):
        _jbp_write_bytes_atomic_python(path, data)
        return
    if sys.platform == "win32" and _is_windows_legacy_path_too_long(path):
        _jbp_write_bytes_atomic_python(path, data)
        return
    # POSIX: QSaveFile оставляет «file.ini.XXXXXX» на vboxsf/NFS; Python temp+replace надёжнее.
    if sys.platform != "win32":
        _jbp_write_bytes_atomic_python(path, data)
        return
    try:
        _jbp_write_bytes_atomic_qsavefile(qt_path, data)
    except OSError:
        _jbp_write_bytes_atomic_python(path, data)


def _write_settings_ini_atomic(settings_path, config) -> None:
    """Атомарно записывает ConfigParser в Setting.ini (Python temp+replace, без QSaveFile)."""
    buf = io.StringIO()
    config.write(buf)
    _jbp_write_bytes_atomic_python(str(settings_path), buf.getvalue().encode("utf-8"))


def _read_settings_ini(settings_path) -> configparser.ConfigParser:
    """Читает Setting.ini через _io_* (Windows long paths)."""
    config = configparser.ConfigParser()
    if not settings_path:
        return config
    if not _io_exists(settings_path):
        return config
    try:
        with _io_open(settings_path, "r", encoding="utf-8") as f:
            config.read_file(f)
    except Exception:
        pass
    return config


def _os_settings_suffix() -> str:
    """Суффикс per-OS секций Setting.ini: '_Win' | '_Linux' | '_macOS' | '_Other'.

    Окно и шрифты хранятся раздельно для каждой ОС, чтобы одна универсальная сборка
    не переносила геометрию/шрифты одной ОС на другую.
    """
    try:
        platform = str(sys.platform or "")
    except Exception:
        return "_Other"
    if platform == "win32":
        return "_Win"
    if platform == "darwin":
        return "_macOS"
    if platform.startswith("linux"):
        return "_Linux"
    # Прочие POSIX: отдельная секция, чтобы не затрагивать секции известных ОС.
    return "_Other"


def _settings_section_name(config, base: str) -> str:
    """Секция настроек для чтения: сначала per-OS ([Window_Win]), затем общая ([Window]).

    Возвращает имя существующей секции или "" ("" — настройки этой группы не заданы).
    """
    if config is None:
        return ""
    try:
        candidates = (str(base) + _os_settings_suffix(), str(base))
    except Exception:
        return ""
    for name in candidates:
        try:
            if config.has_section(name):
                return name
        except Exception:
            continue
    return ""


def _ensure_settings_section(config, base: str) -> str:
    """Секция настроек для записи: всегда per-OS ([Window_Win]); создаётся при необходимости."""
    name = str(base) + _os_settings_suffix()
    try:
        if not config.has_section(name):
            config.add_section(name)
    except Exception:
        pass
    return name


def jbp_dump_json(path, data, kind, *, indent=2, compact=False, exclusive=False):
    """Записывает JSON с заголовком JBPad.

    exclusive=True — режим 'x' (O_EXCL: не перезаписывать существующий файл; на case-insensitive FS
    учитывает совпадение без учёта регистра через предварительный listdir).
    """
    if kind == JBP_KIND_LOCALE:
        jbp_dump_locale(path, data, full_date_locale=None, indent=indent, compact=compact)
        return
    if kind in (JBP_KIND_THEME, JBP_KIND_NOTEBOOK):
        payload = jbp_kind_json_bytes(kind, data, indent=indent, compact=compact)
        jbp_write_bytes_atomic(path, payload, exclusive=exclusive)
        return
    raise ValueError(f"unsupported jbp dump kind: {kind!r}")


def jbp_dump_locale(path, data, full_date_locale=None, *, indent=2, compact=False):
    """Записывает locale JSON с двухстрочным заголовком JBPad."""
    payload = jbp_locale_json_bytes(
        data, full_date_locale, indent=indent, compact=compact
    )
    jbp_write_bytes_atomic(path, payload)


def _notebook_schema_validate_node(data, path="root"):
    """Проверяет один узел дерева блокнота. Возвращает текст ошибки или None."""
    if not isinstance(data, dict):
        return f"{path}: expected object"
    if "name" in data and not isinstance(data["name"], str):
        return f"{path}.name: expected string"
    item_type = data.get("type", "file")
    if "type" in data:
        if not isinstance(data["type"], str):
            return f"{path}.type: expected string"
        if data["type"] not in ("file", "folder"):
            return f"{path}.type: invalid value"
        item_type = data["type"]
    if item_type == "file":
        if "content" in data and not isinstance(data["content"], (str, list)):
            return f"{path}.content: expected string or array"
    else:
        if "cover" in data and not isinstance(data["cover"], (str, list)):
            return f"{path}.cover: expected string or array"
    if "children" in data:
        children = data["children"]
        if not isinstance(children, list):
            return f"{path}.children: expected array"
        for i, child in enumerate(children):
            err = _notebook_schema_validate_node(child, f"{path}.children[{i}]")
            if err:
                return err
    return None


def notebook_schema_validate(data):
    """Проверяет схему блокнота JBPad (только структура, без содержимого текстов).

    Возвращает None если схема валидна, иначе строку с описанием ошибки.
    Вызывается один раз при загрузке в память — не при переключении между кэшированными файлами.
    """
    if not isinstance(data, dict):
        return "root: expected object"
    return _notebook_schema_validate_node(data, "root")


def _load_notebook_data_from_disk(filepath):
    """Читает и валидирует блокнот с диска. Возвращает dict или None."""
    filepath_norm = _win_qt_path(filepath) if filepath else filepath
    try:
        if (
            filepath_norm
            and _io_exists(filepath_norm)
            and jbp_is_valid(filepath_norm, JBP_KIND_NOTEBOOK)
        ):
            data = jbp_load_json(filepath_norm, JBP_KIND_NOTEBOOK)
            if isinstance(data, dict) and notebook_schema_validate(data) is None:
                return data
    except Exception:
        pass
    return None


def jbp_load_full_date_locales_data(path):
    """Загружает словарь языков полной даты из DEFAULT_DATE_LOCALES.json."""
    if not jbp_is_valid(path, JBP_KIND_FULL_DATE_LOCALES):
        return None
    try:
        with _io_open(path, "r", encoding="utf-8-sig") as f:
            kind, _meta = _jbp_skip_header_and_comments(f, parse_locale_meta=False)
            if kind != JBP_KIND_FULL_DATE_LOCALES:
                return None
            data = json.load(f)
            if not isinstance(data, dict):
                return None
            return data
    except Exception:
        return None


def full_date_locales_json_path():
    """Путь к DEFAULT_DATE_LOCALES.json или None."""
    path = data_languages_dir() / DEFAULT_DATE_LOCALES_FILENAME
    if path.is_file() and jbp_is_valid(str(path), JBP_KIND_FULL_DATE_LOCALES):
        return str(path)
    return None


def jbp_notebook_json_bytes(data):
    """UTF-8 bytes блокнота с заголовком (для QSaveFile в worker-потоке)."""
    body = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    return (jbp_header_line(JBP_KIND_NOTEBOOK) + body).encode("utf-8")


_MIN_NOTEBOOK_BYTES = len(jbp_header_line(JBP_KIND_NOTEBOOK)) + 2  # минимальное тело: {}


def jbp_prepare_notebook_save_bytes(payload):
    """Сериализует payload в bytes для атомарной записи блокнота.

    Raises:
        TypeError: неподдерживаемый тип payload.
        ValueError: пустой или невалидный результат сериализации.
    """
    if isinstance(payload, (dict, list)):
        def _normalize(obj):
            if isinstance(obj, dict):
                out = {}
                for k, v in obj.items():
                    if k in ("content", "cover") and isinstance(v, list):
                        try:
                            out[k] = "".join(v)
                        except Exception:
                            out[k] = ""
                    else:
                        out[k] = _normalize(v)
                return out
            if isinstance(obj, list):
                return [_normalize(x) for x in obj]
            return obj

        json_bytes = jbp_notebook_json_bytes(_normalize(payload))
    elif isinstance(payload, (bytes, bytearray)):
        json_bytes = bytes(payload)
    elif payload is not None and hasattr(payload, "data"):
        json_bytes = bytes(payload.data())
    else:
        raise TypeError(f"unsupported save payload type: {type(payload)!r}")

    if not json_bytes or len(json_bytes) < _MIN_NOTEBOOK_BYTES:
        raise ValueError("refusing to write empty notebook payload")
    header_prefix = _JBP_HEADER_PREFIX.encode("utf-8")
    if not json_bytes.startswith(header_prefix):
        raise ValueError("missing JBPad header in notebook payload")
    return json_bytes


def _ensure_jbp_header_in_file(path, kind):
    """Добавляет заголовок JBPad в существующий JSON без заголовка (миграция)."""
    if jbp_is_valid(path, kind):
        return
    existing_kind = jbp_peek_kind(path)
    if existing_kind is not None and existing_kind != kind:
        return
    try:
        path_obj = Path(path)
        if not _io_isfile(str(path_obj)):
            return
        if kind == JBP_KIND_LOCALE:
            data, full_date_locale = jbp_load_locale(str(path_obj))
            if data is None:
                with _io_open(path_obj, "r", encoding="utf-8-sig") as f:
                    f.seek(0)
                    data = json.load(f)
                if not isinstance(data, dict):
                    return
                full_date_locale = None
            jbp_dump_locale(str(path_obj), data, full_date_locale=full_date_locale)
            return
        with _io_open(path_obj, "r", encoding="utf-8-sig") as f:
            first = f.readline()
            if first.strip().startswith(_JBP_HEADER_PREFIX):
                data = json.load(f)
            else:
                f.seek(0)
                data = json.load(f)
        jbp_dump_json(str(path_obj), data, kind)
    except Exception:
        pass


