def language_json_path(name):
    """Путь к JSON локализации в Data/languages или None."""
    filename = os.path.basename(str(name or "").strip())
    if not filename:
        return None
    if not filename.lower().endswith(".json"):
        filename = f"{filename}.json"
    path = data_languages_dir() / filename
    if path.is_file() and jbp_is_valid(str(path), JBP_KIND_LOCALE):
        return str(path)
    # Case-insensitive fallback (для case-sensitive ФС); на промахе — один scandir().
    matched = _resolve_dir_entry_case_insensitive(data_languages_dir(), filename)
    if matched:
        alt = data_languages_dir() / matched
        if alt.is_file() and jbp_is_valid(str(alt), JBP_KIND_LOCALE):
            return str(alt)
    return None


def _resolve_dir_entry_case_insensitive(dir_path: Path, filename: str):
    """Ищет файл в каталоге по имени без учёта регистра.

    Возвращает реальное имя entry (с правильным регистром) или None.
    Если совпадений > 1 (например, Foo.json и foo.json на ext4) — возвращает None.

    Важно: функция сканирует каталог только при вызове (использовать как fallback).
    """
    try:
        wanted = os.path.basename(str(filename or "").strip())
    except Exception:
        wanted = str(filename or "").strip()
    if not wanted:
        return None
    try:
        wanted_cf = wanted.casefold()
    except Exception:
        wanted_cf = wanted.lower()

    found = None
    try:
        with os.scandir(str(dir_path)) as it:
            for entry in it:
                try:
                    if not entry.is_file():
                        continue
                except Exception:
                    continue
                try:
                    n = entry.name
                except Exception:
                    continue
                try:
                    n_cf = n.casefold()
                except Exception:
                    n_cf = n.lower()
                if n_cf == wanted_cf:
                    if found is not None:
                        return None  # неоднозначно
                    found = n
    except Exception:
        return None
    return found


def iter_language_filenames():
    """Имена *.json из Data/languages (без создания каталога)."""
    lang_dir = data_languages_dir()
    if not lang_dir.is_dir():
        return ()
    names = []
    try:
        for entry in os.listdir(str(lang_dir)):
            if not entry.lower().endswith(".json"):
                continue
            path = lang_dir / entry
            if path.is_file() and jbp_is_valid(str(path), JBP_KIND_LOCALE):
                names.append(entry)
    except Exception:
        pass
    return tuple(sorted(names))


def _locale_name_nfc(name) -> str:
    """Имя локали, нормализованное в NFC (для записи в Setting.ini и для сравнений).

    macOS отдаёт имена файлов в NFD (буква «й» = «и» + U+0306), а имена-константы в
    коде записаны в NFC. В Setting.ini всегда пишем NFC: иначе значение, записанное
    на macOS, не найдёт файл локали на Windows/Linux (их ФС имена не нормализует).
    """
    try:
        return unicodedata.normalize("NFC", str(name or "").strip())
    except Exception:
        try:
            return str(name or "").strip()
        except Exception:
            return str(name or "")


def _locale_name_key(name) -> str:
    """Ключ сравнения имён локалей: NFC + casefold.

    Нормализация повторяет _filename_compare_key()/_filesystem_path_key().
    """
    try:
        return _locale_name_nfc(name).casefold()
    except Exception:
        return _locale_name_nfc(name)


def _locale_names_equal(a, b) -> bool:
    """True, если имена локалей совпадают с точностью до Unicode-нормализации и регистра."""
    return bool(_locale_name_key(a) == _locale_name_key(b))


def _combo_index_by_locale_name(combo, name) -> int:
    """Индекс элемента комбобокса по имени локали (NFC-нормализация) или -1.

    Обычный QComboBox.findText() сравнивает строки точно и на macOS не находит
    имя, полученное из ini/кода (NFC), среди имён файлов с ФС (NFD).
    """
    if combo is None:
        return -1
    target = _locale_name_key(name)
    if not target:
        return -1
    try:
        count = int(combo.count())
    except Exception:
        return -1
    for i in range(count):
        try:
            item = combo.itemText(i)
        except Exception:
            continue
        if _locale_name_key(item) == target:
            return i
    return -1


def iter_notebook_filenames():
    """Имена *.json в корне Data/ (блокноты, без подкаталогов)."""
    data_dir = data_directory()
    if not data_dir.is_dir():
        return ()
    names = []
    try:
        for entry in os.listdir(str(data_dir)):
            if not entry.lower().endswith(".json"):
                continue
            path = data_dir / entry
            if path.is_file() and jbp_is_valid(str(path), JBP_KIND_NOTEBOOK):
                names.append(entry)
    except Exception:
        pass
    return tuple(sorted(names, key=lambda s: str(s).lower()))


def _canonical_file_path(path):
    """Нормализованный абсолютный путь для сравнения файлов."""
    try:
        if _path_is_empty(path):
            return ""
        raw = _normalize_path_string(path)
        if _path_is_empty(raw):
            return ""
        key = _filesystem_path_key(raw)
        if key:
            return key
        resolved = _abs_realpath_for_comparison(raw)
        if resolved:
            return os.path.normcase(resolved)
        raw = _win_display_path(raw)
        return os.path.normcase(os.path.normpath(os.path.abspath(raw)))
    except Exception:
        return ""


def _theme_file_display_label(filename, stem_counts):
    stem = _theme_file_stem(filename)
    if stem_counts.get(stem.lower(), 0) > 1:
        return f"{stem} ({filename})"
    return stem


def _build_theme_file_display_entries(filenames):
    """Список (подпись, имя файла) для тем в Data/theme/."""
    stem_counts = {}
    for filename in filenames:
        key = _theme_file_stem(filename).lower()
        stem_counts[key] = stem_counts.get(key, 0) + 1
    entries = []
    for filename in filenames:
        entries.append((_theme_file_display_label(filename, stem_counts), filename))
    return entries

