# -------------------------------------------------------
# Тип узла по-прежнему хранится в Qt.UserRole ("file"/"folder") — это маленькое значение.
ROLE_NODE_TYPE = Qt.UserRole
# Стабильный ID узла (int) — связывает item дерева с данными/контентом.
ROLE_NODE_ID = Qt.UserRole + 10
# Флаг "файл-ссылка" (bool). Храним как маленькое значение, чтобы не парсить контент на кликах.
ROLE_IS_LINK_FILE = Qt.UserRole + 11
# Черновик inline-create (РЕШЕНИЕ А + placeholder): временная строка, которая сдвигает элементы вниз,
# пока пользователь вводит имя. Не должна попадать в JSON и не должна открываться/перетаскиваться.
ROLE_IS_INLINE_CREATE_DRAFT = Qt.UserRole + 12
# Одноразовый флаг: только что созданный элемент (для спец. постановки курсора в редакторе).
ROLE_JUST_CREATED = Qt.UserRole + 13

# Имя приложения в заголовках окон и диалогов (не локализуется).
APP_BRAND = "JBPad"
# Фильтры QFileDialog (не локализуются).
FILE_FILTER_JSON = "JSON (*.json)"
FILE_FILTER_TXT = "(*.txt)"

_EMBEDDED_DATE_LOCALES_FALLBACK = {
    "ru": {
        "display_name": "Русский",
        "weekday_names": (
            "Понедельник", "Вторник", "Среда", "Четверг",
            "Пятница", "Суббота", "Воскресенье",
        ),
        "month_names": (
            "января", "февраля", "марта", "апреля", "мая", "июня",
            "июля", "августа", "сентября", "октября", "ноября", "декабря",
        ),
        "format": "{weekday}, {day} {month} {year} г.",
    },
}


def _validate_full_date_locale_entry(code, entry):
    if not isinstance(entry, dict):
        return None
    display_name = str(entry.get("display_name") or "").strip()
    weekdays = entry.get("weekday_names")
    months = entry.get("month_names")
    fmt = str(entry.get("format") or "").strip()
    if not display_name or not fmt:
        return None
    if not isinstance(weekdays, (list, tuple)) or len(weekdays) != 7:
        return None
    if not isinstance(months, (list, tuple)) or len(months) != 12:
        return None
    return {
        "display_name": display_name,
        "weekday_names": tuple(str(x) for x in weekdays),
        "month_names": tuple(str(x) for x in months),
        "format": fmt,
    }


class FullDateLocaleStore:
    """База названий для формата полной даты (DEFAULT_DATE_LOCALES.json + fallback ru)."""

    def __init__(self):
        self._entries = {}
        self.reload()

    def reload(self):
        entries = {}
        path = full_date_locales_json_path()
        if path:
            raw = jbp_load_full_date_locales_data(path)
            if isinstance(raw, dict):
                for code, item in raw.items():
                    key = str(code or "").strip()
                    if not key:
                        continue
                    validated = _validate_full_date_locale_entry(key, item)
                    if validated:
                        entries[key] = validated
        if not entries:
            entries = dict(_EMBEDDED_DATE_LOCALES_FALLBACK)
        self._entries = entries

    def is_valid_code(self, code):
        return str(code or "").strip() in self._entries

    def get(self, code):
        return self._entries.get(str(code or "").strip())

    def iter_for_combobox(self):
        items = [
            (code, self._entries[code]["display_name"])
            for code in self._entries
        ]
        items.sort(key=lambda pair: pair[1])
        return tuple(items)


full_date_locale_store = FullDateLocaleStore()

# Флаг: в ini указан translation, но файл локали не найден (ветка B).
_locale_translation_ini_invalid = False


class Translator:
    """Переводчик для приложения"""

    def __init__(self):
        self.translations = {}
        self.full_date_locale = None
        self.locale_file_loaded = False

    def load(self, path):
        # Безопасная загрузка: при любой ошибке оставляем "без перевода"
        # (в этом случае tr() вернёт дефолтные строки из кода, т.е. русский базовый интерфейс).
        self.translations = {}
        self.full_date_locale = None
        self.locale_file_loaded = False
        try:
            if not path:
                return
            data, meta = jbp_load_locale(path)
            if isinstance(data, dict):
                self.translations = data
                self.full_date_locale = meta
                self.locale_file_loaded = True
        except Exception:
            self.translations = {}
            self.full_date_locale = None
            self.locale_file_loaded = False

    def tr(self, key, default):
        return self.translations.get(key, default)


translator = Translator()


def tr(key, default):
    return translator.tr(key, default)


def _disk_io_fail_message(filepath=None, exc=None, error_text=None) -> str:
    """Сообщение об ошибке записи/чтения; отдельный текст для слишком длинного пути Windows."""
    if filepath and _is_windows_extended_path_too_long(filepath):
        return tr(
            "message.path_too_long_windows",
            "Путь к файлу слишком длинный для Windows. "
            "Переместите блокнот или выберите более короткий каталог для экспорта/импорта.",
        )
    if exc is not None and _is_windows_path_too_long_error(exc):
        return tr(
            "message.path_too_long_windows",
            "Путь к файлу слишком длинный для Windows. "
            "Переместите блокнот или выберите более короткий каталог для экспорта/импорта.",
        )
    if error_text is not None and _is_windows_path_too_long_error(error_text):
        return tr(
            "message.path_too_long_windows",
            "Путь к файлу слишком длинный для Windows. "
            "Переместите блокнот или выберите более короткий каталог для экспорта/импорта.",
        )
    return tr(
        "message.autosave_failed",
        "Не удается сохранить файл. Новые изменения не будут сохранены. "
        "Проверьте права доступа, свободное место на диске, не используется ли файл другой программой. "
        "В Windows причиной также может быть слишком длинный путь к файлу.",
    )


def _compose_disk_io_fail_message(
    filepath=None,
    exc=None,
    *,
    ui_reason_key=None,
    ui_reason_default=None,
    system_detail=None,
) -> str:
    """Сообщение об ошибке записи: UI (tr) + опционально техническая строка (язык системы)."""
    msg = _disk_io_fail_message(filepath=filepath, exc=exc, error_text=system_detail)
    path_msg = tr(
        "message.path_too_long_windows",
        "Путь к файлу слишком длинный для Windows. "
        "Переместите блокнот или выберите более короткий каталог для экспорта/импорта.",
    )
    parts = [msg]
    if ui_reason_key and msg != path_msg:
        reason = tr(ui_reason_key, ui_reason_default or "").strip()
        if reason:
            parts.append(reason)
    if system_detail is not None and msg != path_msg:
        detail = str(system_detail).strip()
        if detail and not _is_windows_path_too_long_error(system_detail):
            parts.append(detail)
    return "\n\n".join(parts)


def _tr_with_line(key, default_label, value) -> str:
    """Подпись из перевода + перенос + значение; пустое значение → «—»."""
    v = ("" if value is None else str(value)).strip()
    if not v:
        v = "—"
    return tr(key, default_label) + "\n" + v


def _format_statistics_text(count, lines, vowels) -> str:
    """Компактная статистика: подпись + пробел + число на каждой строке."""
    return "\n".join([
        tr("context_menu.statistics.chars", "Знаков:") + " " + str(int(count)),
        tr("context_menu.statistics.lines", "Строк:") + " " + str(int(lines)),
        tr("context_menu.statistics.vowels", "Гласных:") + " " + str(int(vowels)),
    ])


def get_effective_full_date_locale():
    """Код языка полной даты для текущей сессии или None, если long недоступен."""
    if translator.locale_file_loaded:
        code = translator.full_date_locale
        if code is None:
            return None
        if full_date_locale_store.is_valid_code(code):
            return code
        return None
    return _FALLBACK_FULL_DATE_LOCALE


def is_long_date_format_available():
    return get_effective_full_date_locale() is not None


def normalize_date_settings(settings_path=None, *, write_ini=True):
    """Нормализует date_format в ini; сбрасывает битый translation при необходимости."""
    global _locale_translation_ini_invalid
    if not settings_path:
        settings_path = str(APP_DIR / "Setting.ini")
    date_format = "short"
    include_time = False
    changed = False
    config = _read_settings_ini(settings_path)

    if config.has_section("General"):
        try:
            date_format = str(
                config.get("General", "date_format", fallback="short") or "short"
            ).strip() or "short"
        except Exception:
            date_format = "short"
        try:
            include_time = bool(
                config.getboolean("General", "date_include_time", fallback=False)
            )
        except Exception:
            include_time = False

    if date_format == "long" and not is_long_date_format_available():
        date_format = "short"
        changed = True

    if _locale_translation_ini_invalid:
        if config.has_section("languages") and config.has_option("languages", "translation"):
            try:
                config.remove_option("languages", "translation")
                changed = True
            except Exception:
                pass
        _locale_translation_ini_invalid = False

    if changed and write_ini:
        try:
            if not config.has_section("General"):
                config.add_section("General")
            config.set("General", "date_format", str(date_format))
            config.set("General", "date_include_time", "true" if include_time else "false")
            _write_settings_ini_atomic(settings_path, config)
        except Exception:
            pass

    return date_format, include_time


def _load_startup_translation_from_ini():
    """Загружает перевод из Setting.ini (если задан) до инициализации UI."""
    global _locale_translation_ini_invalid
    _locale_translation_ini_invalid = False
    settings_file = str(APP_DIR / "Setting.ini")
    try:
        if not _io_exists(settings_file):
            normalize_date_settings(settings_file)
            return
        config = _read_settings_ini(settings_file)
        try:
            name = str(config.get("languages", "translation", fallback="") or "").strip()
        except Exception:
            name = ""
        if not name:
            normalize_date_settings(settings_file)
            return

        filename = name if name.lower().endswith(".json") else (name + ".json")
        lang_path = language_json_path(filename)
        if lang_path:
            translator.load(lang_path)
        else:
            _locale_translation_ini_invalid = True
        normalize_date_settings(settings_file)
    except Exception:
        try:
            normalize_date_settings(settings_file)
        except Exception:
            pass


ensure_app_data_bootstrap()
full_date_locale_store.reload()
_load_startup_translation_from_ini()


def _legacy_custom_theme_filename(name):
    """Нормализует имя пользовательской темы (без ThemeManager)."""
    name = os.path.basename(str(name or "").strip())
    if not name:
        return None
    if not name.lower().endswith(".json"):
        name = f"{name}.json"
    return name


def _custom_theme_file_exists(filename):
    return resolve_theme_file_path(filename) is not None


def _normalize_theme_active(active):
    """Нормализует active из Setting.ini. Возвращает (resolved, needs_ini_fix)."""
    act = str(active or "").strip() or "light"
    if act == "light":
        return "light", False
    active_filename = _legacy_custom_theme_filename(act)
    if active_filename:
        path = resolve_theme_file_path(active_filename)
        if path:
            try:
                return os.path.basename(str(path)), False
            except Exception:
                return active_filename, False
    return "light", True


def _load_startup_theme_settings():
    """Читает [Theme] active из Setting.ini до инициализации UI."""
    default = ("light", False)
    try:
        settings_file = str(APP_DIR / "Setting.ini")
        if not _io_exists(settings_file):
            return default
        config = _read_settings_ini(settings_file)
        if not config.has_section("Theme"):
            return default

        raw_active = "light"
        try:
            if config.has_option("Theme", "active"):
                raw_active = str(config.get("Theme", "active", fallback="light") or "light").strip() or "light"
        except Exception:
            raw_active = "light"

        return _normalize_theme_active(raw_active)
    except Exception:
        return default


def _persist_theme_active_to_ini(active):
    """Записывает Theme/active в Setting.ini; удаляет устаревший custom_theme."""
    try:
        settings_file = str(APP_DIR / "Setting.ini")
        config = _read_settings_ini(settings_file)
        if not config.has_section("Theme"):
            config.add_section("Theme")
        config.set("Theme", "active", str(active))
        if config.has_option("Theme", "custom_theme"):
            config.remove_option("Theme", "custom_theme")
        for legacy_key in ("Theme", "dark_theme"):
            if config.has_option("Theme", legacy_key):
                config.remove_option("Theme", legacy_key)
        _write_settings_ini_atomic(settings_file, config)
    except Exception:
        pass


def _qmessagebox_single_ok(icon, parent, title, text):
    """Однокнопочный themed message; подпись Ok из JSON (dialog.button_ok)."""
    ThemedMessageDialog.single_ok(parent, title, text, icon=icon)


