# Универсальный набор гласных для подсчёта в выделении (независимо от языка UI).
# Только строчные — текст перед подсчётом приводится к нижнему регистру
# (важно для немецкой ß и греческих букв).
DEFAULT_VOWELS = (
    "aeiouy"  # английский, базовая латиница
    "аеёиоуыэюя"  # русский
    "äöü"  # немецкий
    "àâæéèêëîïôœùÿ"  # французский
    "áãåìíòóôõöúý"  # испанский, итальянский, португальский, чешский
    "ąęó"  # польский
    "іїє"  # украинский
    "іў"  # белорусский
    "әөұү"  # казахский кириллица (доп. к общей кириллице)
    "åæø"  # северная Европа (шведский, норвежский, датский)
    "őű"  # венгерский
    "ăâî"  # румынский
    "ıõ"  # турецкий, эстонский
    "āēīū"  # латышский
    "ėįų"  # литовский
    "αάεέηήιίϊοόυύϋωώ"  # греческий (монотоника)
    "աեևիոու"  # армянский
    "აეიოუ"  # грузинский
    "aäeıioöuüy"  # казахская латиница (2023)
    "ə"  # азербайджанская латиница (кириллица покрыта выше)
)

_VOWELS_SET = frozenset(DEFAULT_VOWELS)
_GREEK_VOWEL_BASES = frozenset("αεηιουω")


def _is_vowel_char(ch, vset) -> bool:
    if not ch or ch.isspace():
        return False
    if ch in vset:
        return True
    try:
        if unicodedata.name(ch, "").startswith("GREEK"):
            base = unicodedata.normalize("NFD", ch)[0]
            return base in _GREEK_VOWEL_BASES
    except Exception:
        pass
    return False


def count_vowels(text) -> int:
    """Считает количество гласных в тексте по DEFAULT_VOWELS."""
    try:
        s = "" if text is None else str(text)
    except Exception:
        s = ""
    try:
        s = s.lower()
        return sum(1 for ch in s if _is_vowel_char(ch, _VOWELS_SET))
    except Exception:
        return 0


def count_visual_lines(text_edit, cursor) -> int:
    """Считает визуальные (wrap-aware) строки в диапазоне: выделение или весь документ."""
    if text_edit is None or cursor is None:
        return 0

    try:
        doc = text_edit.document()
    except Exception:
        doc = None
    if doc is None:
        return 0

    try:
        if cursor.hasSelection():
            start = int(min(cursor.selectionStart(), cursor.selectionEnd()))
            end = int(max(cursor.selectionStart(), cursor.selectionEnd()))
        else:
            start = 0
            end = max(0, int(doc.characterCount()) - 1)
    except Exception:
        return 0
    if end <= start:
        return 0

    total = 0
    try:
        block = doc.findBlock(start)
    except Exception:
        block = None

    while block is not None and block.isValid():
        try:
            bpos = int(block.position())
        except Exception:
            bpos = 0
        if bpos >= end:
            break

        try:
            btext = block.text() or ""
        except Exception:
            btext = ""

        blen = len(btext)
        rel_start = max(0, start - bpos)
        rel_end = min(blen, end - bpos)
        if rel_end > rel_start:
            layout = None
            try:
                layout = block.layout()
            except Exception:
                layout = None

            line_count = 0
            try:
                line_count = int(layout.lineCount()) if layout is not None else 0
            except Exception:
                line_count = 0

            if line_count <= 0:
                seg = btext[rel_start:rel_end]
                if any((ch and (not ch.isspace())) for ch in seg):
                    total += 1
            else:
                for i in range(line_count):
                    try:
                        line = layout.lineAt(i)
                        ls = int(line.textStart())
                        le = ls + int(line.textLength())
                    except Exception:
                        continue

                    seg_start = max(rel_start, ls)
                    seg_end = min(rel_end, le)
                    if seg_end <= seg_start:
                        continue

                    seg = btext[seg_start:seg_end]
                    if any((ch and (not ch.isspace())) for ch in seg):
                        total += 1

        try:
            block = block.next()
        except Exception:
            break

    return int(total)


def show_copy_paste_context_menu_for_line_edit(line_edit: QLineEdit, position):
    """Контекстное меню (2 пункта): Копировать/Вставить — единая точка для переводов."""
    try:
        menu = QMenu(line_edit)

        copy_action = QAction(tr("context_menu.copy", "Копировать"), line_edit)
        copy_action.setShortcut("Ctrl+C")
        try:
            copy_action.triggered.connect(line_edit.copy)
        except Exception:
            pass
        menu.addAction(copy_action)

        paste_action = QAction(tr("context_menu.paste", "Вставить"), line_edit)
        paste_action.setShortcut("Ctrl+V")
        try:
            paste_action.triggered.connect(line_edit.paste)
        except Exception:
            pass
        menu.addAction(paste_action)

        try:
            menu.exec_(line_edit.mapToGlobal(position))
        except Exception:
            # position может быть уже в глобальных координатах для некоторых событий
            menu.exec_(position)
    except Exception:
        # Безопасный fallback: не ломаем ввод, даже если меню не показалось.
        return


