def show_copy_paste_context_menu_for_table_view(table_view, position):
    """Контекстное menu (2 пункта): Копировать/Вставить для QTableView (ячейка под курсором)."""
    try:
        menu = QMenu(table_view)

        def _copy_cell():
            try:
                editor = table_view.focusWidget()
                if isinstance(editor, QTextEdit):
                    editor.copy()
                    return
            except Exception:
                pass
            try:
                idx = table_view.indexAt(position)
                if not idx.isValid():
                    idx = table_view.currentIndex()
                if idx.isValid():
                    val = idx.data(Qt.DisplayRole)
                    QApplication.clipboard().setText("" if val is None else str(val))
            except Exception:
                pass

        def _paste_cell():
            try:
                editor = table_view.focusWidget()
                if isinstance(editor, QTextEdit):
                    editor.paste()
                    return
            except Exception:
                pass
            try:
                idx = table_view.currentIndex()
                if not idx.isValid():
                    idx = table_view.indexAt(position)
                if idx.isValid() and (idx.flags() & Qt.ItemIsEditable):
                    table_view.model().setData(idx, QApplication.clipboard().text(), Qt.EditRole)
            except Exception:
                pass

        copy_action = QAction(tr("context_menu.copy", "Копировать"), table_view)
        copy_action.setShortcut("Ctrl+C")
        copy_action.triggered.connect(_copy_cell)
        menu.addAction(copy_action)

        paste_action = QAction(tr("context_menu.paste", "Вставить"), table_view)
        paste_action.setShortcut("Ctrl+V")
        paste_action.triggered.connect(_paste_cell)
        menu.addAction(paste_action)

        try:
            menu.exec_(table_view.viewport().mapToGlobal(position))
        except Exception:
            try:
                menu.exec_(table_view.mapToGlobal(position))
            except Exception:
                menu.exec_(position)
    except Exception:
        return


def wire_copy_paste_context_menu_for_table_view(table_view):
    """Подключает кастомное контекстное menu Копировать/Вставить к QTableView."""
    if table_view is None:
        return
    try:
        table_view.setContextMenuPolicy(Qt.CustomContextMenu)
        table_view.customContextMenuRequested.connect(
            lambda pos, v=table_view: show_copy_paste_context_menu_for_table_view(v, pos)
        )
    except Exception:
        pass


