class ClickableIconLabel(QLabel):
    """Кликабельная иконка для control_panel"""
    
    def __init__(self, parent=None, click_callback=None):
        super().__init__(parent)
        self.click_callback = click_callback
        self.setCursor(Qt.PointingHandCursor)
    
    def mousePressEvent(self, event):
        """Обработчик клика по иконке"""
        if event.button() == Qt.LeftButton and self.click_callback:
            self.click_callback()
        super().mousePressEvent(event)


class FramelessWindowMixin:
    """Перетаскивание и resize frameless-окна через QWindow.startSystemMove/Resize (Qt 5.15+)."""

    _resize_edge_size = 4
    _resize_edge_size_top_extra = 0

    @staticmethod
    def clear_application_override_cursor():
        """Снимает весь стек QApplication.setOverrideCursor."""
        try:
            while QApplication.overrideCursor() is not None:
                QApplication.restoreOverrideCursor()
        except Exception:
            pass

    def frameless_activate_if_inactive(self):
        """Поднять и активировать окно, если оно ещё не foreground (кроссплатформенно)."""
        try:
            if not self.isActiveWindow():
                self.raise_()
                self.activateWindow()
                return True
        except Exception:
            pass
        return False

    def _frameless_resize_inset_px(self):
        """Дополнительный отступ hit-test зоны resize от края (тень, рамка)."""
        return 0

    def _frameless_resize_blocked_at(self, pos):
        """True — resize в этой точке запрещён (например titlebar)."""
        return False

    def _frameless_clear_override_cursor_stack_on_restore(self):
        """На Windows при сбросе очищаем весь стек override-курсоров."""
        return sys.platform == "win32"

    def _ensure_window_handle(self):
        wh = self.windowHandle()
        if wh is None:
            try:
                self.winId()
            except Exception:
                pass
            wh = self.windowHandle()
        return wh

    def frameless_start_system_move(self):
        wh = self._ensure_window_handle()
        if wh is not None and hasattr(wh, "startSystemMove"):
            try:
                return bool(wh.startSystemMove())
            except Exception:
                return False
        return False

    @staticmethod
    def _resize_edge_to_qt_edges(edge):
        if not edge:
            return Qt.Edges()
        qt_edges = Qt.Edges()
        if "left" in edge:
            qt_edges |= Qt.LeftEdge
        if "right" in edge:
            qt_edges |= Qt.RightEdge
        if "top" in edge:
            qt_edges |= Qt.TopEdge
        if "bottom" in edge:
            qt_edges |= Qt.BottomEdge
        return qt_edges

    def frameless_start_system_resize(self, edge):
        wh = self._ensure_window_handle()
        qt_edges = self._resize_edge_to_qt_edges(edge)
        if wh is not None and qt_edges and hasattr(wh, "startSystemResize"):
            try:
                return bool(wh.startSystemResize(qt_edges))
            except Exception:
                return False
        return False

    @staticmethod
    def _frameless_prefers_manual_resize():
        """macOS: startSystemResize для FramelessWindowHint не работает — ручной resize."""
        return sys.platform == "darwin"

    def _frameless_manual_resize_active(self):
        return bool(getattr(self, "_frameless_manual_resize_edge", None))

    def frameless_start_manual_resize(self, edge, global_pos):
        self._frameless_manual_resize_edge = edge
        self._frameless_manual_resize_start_geom = self.geometry()
        self._frameless_manual_resize_start_global = QPoint(global_pos)
        try:
            self.grabMouse()
        except Exception:
            pass
        return True

    def frameless_update_manual_resize(self, global_pos):
        edge = getattr(self, "_frameless_manual_resize_edge", None)
        start_geom = getattr(self, "_frameless_manual_resize_start_geom", None)
        start_global = getattr(self, "_frameless_manual_resize_start_global", None)
        if not edge or start_geom is None or start_global is None:
            return False

        delta = global_pos - start_global
        x = int(start_geom.x())
        y = int(start_geom.y())
        w = int(start_geom.width())
        h = int(start_geom.height())
        dx, dy = int(delta.x()), int(delta.y())

        if "left" in edge:
            x += dx
            w -= dx
        if "right" in edge:
            w += dx
        if "top" in edge:
            y += dy
            h -= dy
        if "bottom" in edge:
            h += dy

        min_w = max(1, int(self.minimumWidth()))
        min_h = max(1, int(self.minimumHeight()))
        if w < min_w:
            if "left" in edge and "right" not in edge:
                x += w - min_w
            w = min_w
        if h < min_h:
            if "top" in edge and "bottom" not in edge:
                y += h - min_h
            h = min_h

        max_w = int(self.maximumWidth())
        max_h = int(self.maximumHeight())
        if 0 < max_w < 16777215 and w > max_w:
            if "left" in edge and "right" not in edge:
                x += w - max_w
            w = max_w
        if 0 < max_h < 16777215 and h > max_h:
            if "top" in edge and "bottom" not in edge:
                y += h - max_h
            h = max_h

        self.setGeometry(x, y, w, h)
        return True

    def frameless_end_manual_resize(self):
        if not self._frameless_manual_resize_active():
            return False
        self._frameless_manual_resize_edge = None
        self._frameless_manual_resize_start_geom = None
        self._frameless_manual_resize_start_global = None
        try:
            if self.mouseGrabber() is self:
                self.releaseMouse()
        except Exception:
            pass
        return True

    def _get_resize_edge(self, pos):
        try:
            if self.isMaximized():
                return None
        except Exception:
            pass
        if self._frameless_resize_blocked_at(pos):
            return None

        rect = self.rect()
        x, y = pos.x(), pos.y()
        edge_size = int(getattr(self, "_resize_edge_size", 4))
        top_edge_size = edge_size + int(getattr(self, "_resize_edge_size_top_extra", 0))
        inset = int(self._frameless_resize_inset_px())
        width = rect.width()
        height = rect.height()

        if x <= edge_size + inset and y <= top_edge_size + inset:
            return "top-left"
        if x >= width - edge_size - inset and y <= top_edge_size + inset:
            return "top-right"
        if x <= edge_size + inset and y >= height - edge_size - inset:
            return "bottom-left"
        if x >= width - edge_size - inset and y >= height - edge_size - inset:
            return "bottom-right"
        if x <= edge_size + inset:
            return "left"
        if x >= width - edge_size - inset:
            return "right"
        if y <= top_edge_size + inset:
            return "top"
        if y >= height - edge_size - inset:
            return "bottom"
        return None

    @staticmethod
    def _get_cursor_for_edge(edge):
        if edge in ("left", "right"):
            return Qt.SizeHorCursor
        if edge in ("top", "bottom"):
            return Qt.SizeVerCursor
        if edge in ("top-left", "bottom-right"):
            return Qt.SizeFDiagCursor
        if edge in ("top-right", "bottom-left"):
            return Qt.SizeBDiagCursor
        return Qt.ArrowCursor

    @staticmethod
    def _popup_belongs_to_widget(popup, host):
        """True, если popup принадлежит host (QComboBox dropdown, QMenu и т.п.)."""
        if popup is None or host is None:
            return False
        try:
            if host.isAncestorOf(popup):
                return True
        except Exception:
            pass
        w = popup
        while w is not None:
            if w is host:
                return True
            try:
                w = w.parentWidget()
            except Exception:
                w = None
        # QComboBox dropdown на Wayland — отдельное top-level окно; combo внутри host.
        try:
            for combo in host.findChildren(QComboBox):
                view = combo.view()
                if view is not None and view.window() is popup:
                    return True
        except Exception:
            pass
        return False

    @staticmethod
    def _popup_contains_global_point(popup, global_pos):
        try:
            if popup is None or not popup.isVisible():
                return False
            local_pos = popup.mapFromGlobal(global_pos)
            return popup.rect().contains(local_pos)
        except Exception:
            return False

    @staticmethod
    def _frameless_modal_or_popup_active():
        try:
            return (
                QApplication.activeModalWidget() is not None
                or QApplication.activePopupWidget() is not None
            )
        except Exception:
            return False

    def _frameless_modal_or_popup_blocks_resize(self):
        """True — не показывать resize-курсор и не начинать resize (переопределяется в диалогах)."""
        return self._frameless_modal_or_popup_active()

    def frameless_restore_resize_cursor(self):
        try:
            if self._frameless_clear_override_cursor_stack_on_restore():
                FramelessWindowMixin.clear_application_override_cursor()
            elif QApplication.overrideCursor() is not None:
                QApplication.restoreOverrideCursor()
        except Exception:
            pass

    def _is_menu_open_at_position(self, global_pos):
        active_popup = QApplication.activePopupWidget()
        if isinstance(active_popup, QMenu):
            menu_rect = active_popup.geometry()
            if menu_rect.isValid():
                local_pos = active_popup.mapFromGlobal(global_pos)
                if active_popup.rect().contains(local_pos):
                    return True
        app = QApplication.instance()
        if app:
            for widget in app.allWidgets():
                if isinstance(widget, QMenu) and widget.isVisible():
                    local_pos = widget.mapFromGlobal(global_pos)
                    if widget.rect().contains(local_pos):
                        return True
        return False

    def _is_active_popup_at_position(self, global_pos):
        """True, если курсор над любым active popup (QComboBox list, QMenu, …)."""
        try:
            active_popup = QApplication.activePopupWidget()
            if self._popup_contains_global_point(active_popup, global_pos):
                return True
        except Exception:
            pass
        return self._is_menu_open_at_position(global_pos)

    def frameless_handle_mouse_move(self, event):
        if self._frameless_manual_resize_active():
            if event.buttons() & Qt.LeftButton:
                self.frameless_update_manual_resize(event.globalPos())
                return True
            self.frameless_end_manual_resize()

        if self._frameless_modal_or_popup_blocks_resize():
            self.frameless_restore_resize_cursor()
            return False
        try:
            if self.isMaximized():
                self.frameless_restore_resize_cursor()
                return False
        except Exception:
            pass
        if self._is_active_popup_at_position(event.globalPos()):
            self.frameless_restore_resize_cursor()
            return False

        edge = self._get_resize_edge(event.pos())
        if edge:
            cursor = self._get_cursor_for_edge(edge)
            current_cursor = QApplication.overrideCursor()
            if current_cursor is None or current_cursor.shape() != cursor:
                if getattr(self, "_frameless_resizable", False):
                    FramelessWindowMixin.clear_application_override_cursor()
                QApplication.setOverrideCursor(QCursor(cursor))
            return True

        if getattr(self, "_frameless_resizable", False):
            FramelessWindowMixin.clear_application_override_cursor()
        else:
            self.frameless_restore_resize_cursor()
        return False

    def frameless_handle_mouse_press(self, event):
        if event.button() != Qt.LeftButton:
            return False
        if self._frameless_modal_or_popup_blocks_resize():
            return False
        if self._is_active_popup_at_position(event.globalPos()):
            return False
        try:
            if self.isMaximized():
                return False
        except Exception:
            pass
        edge = self._get_resize_edge(event.pos())
        if edge:
            if not self._frameless_prefers_manual_resize() and self.frameless_start_system_resize(edge):
                event.accept()
                return True
            if self._frameless_prefers_manual_resize() and self.frameless_start_manual_resize(edge, event.globalPos()):
                event.accept()
                return True
        return False

    def frameless_handle_mouse_release(self, event):
        if event.button() != Qt.LeftButton:
            return False
        if self.frameless_end_manual_resize():
            event.accept()
            return True
        return False

    def _frameless_is_titlebar_drag_at(self, local_pos):
        """True — зона native drag titlebar (HTCAPTION / startSystemMove). Переопределяется в окнах."""
        return False

    @staticmethod
    def _frameless_native_event_type_bytes(eventType):
        try:
            if isinstance(eventType, bytes):
                return eventType
            if isinstance(eventType, bytearray):
                return bytes(eventType)
            if hasattr(eventType, "data"):
                return bytes(eventType.data())
            return bytes(eventType)
        except Exception:
            return b""

    @staticmethod
    def _frameless_win_lparam_xy(lparam):
        try:
            lp = int(lparam)
        except Exception:
            return None, None
        x = ctypes.c_int16(lp & 0xFFFF).value
        y = ctypes.c_int16((lp >> 16) & 0xFFFF).value
        return x, y

    def _frameless_native_ht_code_at(self, local_pos):
        """Win32 HT* для WM_NCHITTEST по координатам top-level окна или None."""
        _HT = {
            "left": 10,
            "right": 11,
            "top": 12,
            "top-left": 13,
            "top-right": 14,
            "bottom": 15,
            "bottom-left": 16,
            "bottom-right": 17,
        }
        try:
            if not self.rect().contains(local_pos):
                return None
        except Exception:
            pass
        try:
            if self.isMaximized():
                if self._frameless_is_titlebar_drag_at(local_pos):
                    return 2  # HTCAPTION
                return None
        except Exception:
            pass
        try:
            edge = self._get_resize_edge(local_pos)
            if edge:
                return _HT.get(edge)
        except Exception:
            pass
        try:
            if self._frameless_is_titlebar_drag_at(local_pos):
                return 2  # HTCAPTION
        except Exception:
            pass
        return None

    def _frameless_native_event_windows(self, eventType, message):
        if sys.platform != "win32":
            return None
        if self._frameless_native_event_type_bytes(eventType) != b"windows_generic_MSG":
            return None
        try:
            msg = ctypes.cast(int(message), ctypes.POINTER(ctypes.wintypes.MSG)).contents
        except Exception:
            return None

        WM_NCHITTEST = 0x0084
        WM_MOUSEACTIVATE = 0x0021
        MA_ACTIVATE = 1

        if int(msg.message) == WM_NCHITTEST:
            x, y = self._frameless_win_lparam_xy(msg.lParam)
            if x is None:
                return None
            try:
                local_pos = self.mapFromGlobal(QPoint(int(x), int(y)))
            except Exception:
                return None
            ht = self._frameless_native_ht_code_at(local_pos)
            if ht is not None:
                return True, int(ht)
            return None

        if int(msg.message) == WM_MOUSEACTIVATE:
            try:
                if not self.isActiveWindow():
                    return True, MA_ACTIVATE
            except Exception:
                pass
            return None

        return None

    def _frameless_native_event_x11(self, eventType, message):
        """X11: ранняя активация окна на ButtonPress (до доставки события в Qt)."""
        et = self._frameless_native_event_type_bytes(eventType)
        if et not in (b"xcb_generic_event_t", b"xcb_generic_event"):
            return None
        try:
            addr = int(message)
            response_type = int(ctypes.c_uint8.from_address(addr).value)
        except Exception:
            return None
        # XCB_BUTTON_PRESS = 4
        if response_type == 4:
            try:
                self.frameless_activate_if_inactive()
            except Exception:
                pass
        return None

    def _frameless_native_event_wayland(self, eventType, message):
        """Wayland: compositor управляет hit-test; безопасная активация только по pointer button."""
        et = self._frameless_native_event_type_bytes(eventType)
        if b"button" not in et:
            return None
        try:
            if not self.isActiveWindow():
                self.raise_()
                wh = self._ensure_window_handle()
                if wh is not None and hasattr(wh, "requestActivate"):
                    wh.requestActivate()
                else:
                    self.activateWindow()
        except Exception:
            pass
        return None

    def _frameless_native_event_macos(self, eventType, message):
        """macOS: NSEvent не разбираем (нет pyobjc); drag — startSystemMove, resize — ручной (см. _frameless_prefers_manual_resize)."""
        return None

    def _frameless_native_event_linux(self, eventType, message):
        if _is_linux_wayland_session():
            return self._frameless_native_event_wayland(eventType, message)
        return self._frameless_native_event_x11(eventType, message)

    def frameless_native_event(self, eventType, message):
        """Platform-native события frameless-окна. None — не обработано; иначе (handled, result)."""
        try:
            if sys.platform == "win32":
                result = self._frameless_native_event_windows(eventType, message)
                if result is not None:
                    return result
            elif sys.platform == "darwin":
                result = self._frameless_native_event_macos(eventType, message)
                if result is not None:
                    return result
            elif sys.platform.startswith("linux"):
                result = self._frameless_native_event_linux(eventType, message)
                if result is not None:
                    return result
        except Exception:
            pass
        return None

    def frameless_dispatch_native_event(self, eventType, message):
        """Обёртка для QWidget.nativeEvent: (handled, platform_result)."""
        try:
            native_result = self.frameless_native_event(eventType, message)
            if native_result is not None:
                handled, result = native_result
                if handled:
                    return True, int(result)
        except Exception:
            pass
        try:
            return super().nativeEvent(eventType, message)
        except Exception:
            return False, 0


class _TitleBarIconButton(QPushButton):
    """Кнопка titlebar: tooltip через QToolTip.showText с родителем-кнопкой.

    На Linux/Wayland стандартный popup без widget-parent часто не показывается,
    когда фокус в QTextEdit (text-input); явный parent работает на всех платформах.
    """

    def event(self, event):
        if event.type() == QEvent.ToolTip:
            tip = self.toolTip()
            if isinstance(tip, str) and tip:
                if isinstance(event, QHelpEvent):
                    pos = event.globalPos()
                else:
                    try:
                        pos = event.globalPos()
                    except AttributeError:
                        pos = self.mapToGlobal(event.pos())
                QToolTip.showText(pos, tip, self, self.rect())
            else:
                QToolTip.hideText()
            event.ignore()
            return True
        return super().event(event)


class _TitleBarCloseButton(_TitleBarIconButton):
    """Кнопка закрытия окна: чёрный крестик в обычном состоянии, белый — при hover."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._icon_normal = QIcon()
        self._icon_hover = QIcon()

    def set_close_icons(self, normal_icon, hover_icon):
        self._icon_normal = normal_icon if normal_icon is not None else QIcon()
        self._icon_hover = hover_icon if hover_icon is not None else QIcon()
        self.update()

    def paintEvent(self, event):
        opt = QStyleOptionButton()
        self.initStyleOption(opt)
        hovered = bool(opt.state & QStyle.State_MouseOver)
        opt.icon = QIcon()
        opt.text = ""
        painter = QPainter(self)
        try:
            self.style().drawControl(QStyle.CE_PushButton, opt, painter, self)
            icon = self._icon_hover if hovered else self._icon_normal
            if not icon.isNull():
                icon_sz = self.iconSize()
                pm = icon.pixmap(icon_sz, QIcon.Normal, QIcon.Off)
                if not pm.isNull():
                    x = (self.width() - pm.width()) // 2
                    y = (self.height() - pm.height()) // 2
                    painter.drawPixmap(x, y, pm)
        finally:
            painter.end()


class DialogTitleBar(QWidget):
    """Упрощённая панель заголовка для frameless-диалогов: иконка, заголовок, закрыть."""

    TITLEBAR_HEIGHT_PX = 28
    TITLE_BAR_ICON_SIZE = 24
    APP_ICON_SIZE = 16
    TITLE_LEFT_PADDING_PX = 4

    def __init__(self, dialog):
        super().__init__(dialog)
        self._dialog = dialog
        self.setObjectName("DialogTitleBar")
        self.setAttribute(Qt.WA_StyledBackground, True)
        bar_h = int(self.TITLEBAR_HEIGHT_PX)
        icon_px = int(self.TITLE_BAR_ICON_SIZE)
        self.setFixedHeight(bar_h)

        layout = QHBoxLayout(self)
        layout.setContentsMargins(int(self.TITLE_LEFT_PADDING_PX), 0, 0, 0)
        layout.setSpacing(4)

        self._app_icon_label = QLabel(self)
        self._app_icon_label.setFixedSize(int(self.APP_ICON_SIZE), int(self.APP_ICON_SIZE))
        layout.addWidget(self._app_icon_label, 0, Qt.AlignVCenter)

        self._title_label = QLabel(self)
        self._title_label.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
        layout.addWidget(self._title_label, 1)

        self._close_btn_style = (
            "QPushButton { border: none; background: transparent; padding: 0px; margin: 0px; }"
        )
        self.close_button = _TitleBarCloseButton(self)
        self.close_button.setFixedSize(bar_h, bar_h)
        self.close_button.setIconSize(QSize(icon_px, icon_px))
        self.close_button.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        self.close_button.setFocusPolicy(Qt.NoFocus)
        self.close_button.setCursor(Qt.ArrowCursor)
        self.close_button.clicked.connect(self._on_close_clicked)
        layout.addWidget(self.close_button, 0, Qt.AlignVCenter)

        self.apply_theme_styles(self._theme_dict())

    @staticmethod
    def _theme_dict():
        try:
            return ThemeManager.instance().theme()
        except Exception:
            pass
        try:
            return LIGHT_THEME
        except NameError:
            return {}

    def _on_close_clicked(self):
        if self._dialog is not None:
            self._dialog.close()

    def set_title_text(self, text):
        self._title_label.setText(text or "")

    def _is_drag_region(self, pos):
        try:
            close_x = self.close_button.x()
            return 0 <= pos.x() < close_x and 0 <= pos.y() < self.height()
        except Exception:
            return False

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton and self._dialog is not None:
            if self._is_drag_region(event.pos()):
                if self._dialog.frameless_start_system_move():
                    event.accept()
                    return
        super().mousePressEvent(event)

    def _update_icons(self):
        app_icon = QIcon()
        if self._dialog is not None:
            app_icon = self._dialog.windowIcon()
        if app_icon.isNull():
            try:
                app_icon = QIcon(resource_path("resources/icons/JBPad_windowicon.ico"))
            except Exception:
                pass
        self._app_icon_label.setPixmap(
            app_icon.pixmap(int(self.APP_ICON_SIZE), int(self.APP_ICON_SIZE))
        )
        try:
            im = IconManager.instance()
            self.close_button.set_close_icons(im.icon("close_window"), im.icon("close_window_hover"))
        except Exception:
            pass

    def apply_theme_styles(self, theme):
        bg = theme.get("dialog_titlebar_background", "#ffffff")
        text_color = theme.get("palette_window_text", "#000000")
        close_hover = theme.get("titlebar_close_button_hover_background", "#e81123")
        self.setAutoFillBackground(False)
        self.setStyleSheet(
            f"QWidget#DialogTitleBar {{ background-color: {bg}; border: none; }}"
        )
        self._title_label.setStyleSheet(
            f"QLabel {{ color: {text_color}; background: transparent; border: none; }}"
        )
        self._close_btn_style = (
            "QPushButton { border: none; background: transparent; padding: 0px; margin: 0px; }"
            f"QPushButton:hover {{ background-color: {close_hover}; }}"
        )
        self.close_button.setStyleSheet(self._close_btn_style)
        self._update_icons()


class _ResizableDialogCursorAppFilter(QObject):
    """Глобальный фильтр: сброс resize-курсора, когда мышь вне resizable frameless-диалога."""

    _instance = None

    @classmethod
    def instance(cls):
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    def __init__(self):
        super().__init__()
        self._dialogs = []
        self._app_filter_installed = False

    def register_dialog(self, dialog):
        if dialog is None:
            return
        if dialog not in self._dialogs:
            self._dialogs.append(dialog)
        app = QApplication.instance()
        if app is not None and not self._app_filter_installed:
            app.installEventFilter(self)
            self._app_filter_installed = True

    def unregister_dialog(self, dialog):
        try:
            self._dialogs.remove(dialog)
        except ValueError:
            pass

    @staticmethod
    def _dialog_contains_global_point(dialog, global_pos):
        try:
            if dialog is None or not dialog.isVisible():
                return False
            local = dialog.mapFromGlobal(global_pos)
            return dialog.rect().contains(local)
        except Exception:
            return False

    def eventFilter(self, obj, event):
        if not self._dialogs:
            return False
        if isinstance(event, QMouseEvent) and event.type() == QEvent.MouseMove:
            gp = event.globalPos()
            for d in list(self._dialogs):
                popup = QApplication.activePopupWidget()
                if (
                    popup is not None
                    and FramelessWindowMixin._popup_belongs_to_widget(popup, d)
                    and FramelessWindowMixin._popup_contains_global_point(popup, gp)
                ):
                    FramelessWindowMixin.clear_application_override_cursor()
                    return False
            if not any(self._dialog_contains_global_point(d, gp) for d in list(self._dialogs)):
                FramelessWindowMixin.clear_application_override_cursor()
        return False


class _MainWindowResizeCursorAppFilter(QObject):
    """Глобальный фильтр: сброс resize-курсора главного окна, когда мышь вне MainWindow."""

    _instance = None

    @classmethod
    def instance(cls):
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    def __init__(self):
        super().__init__()
        self._main_windows = []
        self._app_filter_installed = False

    def register_main_window(self, main_window):
        if main_window is None:
            return
        if main_window not in self._main_windows:
            self._main_windows.append(main_window)
        app = QApplication.instance()
        if app is not None and not self._app_filter_installed:
            app.installEventFilter(self)
            self._app_filter_installed = True

    def unregister_main_window(self, main_window):
        try:
            self._main_windows.remove(main_window)
        except ValueError:
            pass

    @staticmethod
    def _main_window_contains_global_point(main_window, global_pos):
        try:
            if main_window is None or not main_window.isVisible():
                return False
            local = main_window.mapFromGlobal(global_pos)
            return main_window.rect().contains(local)
        except Exception:
            return False

    def eventFilter(self, obj, event):
        if not self._main_windows:
            return False
        if isinstance(event, QMouseEvent) and event.type() == QEvent.MouseMove:
            gp = event.globalPos()
            for mw in list(self._main_windows):
                popup = QApplication.activePopupWidget()
                if (
                    popup is not None
                    and FramelessWindowMixin._popup_belongs_to_widget(popup, mw)
                    and FramelessWindowMixin._popup_contains_global_point(popup, gp)
                ):
                    FramelessWindowMixin.clear_application_override_cursor()
                    return False
            if not any(
                self._main_window_contains_global_point(mw, gp) for mw in list(self._main_windows)
            ):
                FramelessWindowMixin.clear_application_override_cursor()
        return False


class ThemedFramelessDialog(FramelessWindowMixin, QDialog):
    """Frameless-диалог с кастомным titlebar, рамкой из темы и опциональным resize."""

    CHROME_OBJECT_NAME = "dialogChromeWidget"
    CONTENT_OBJECT_NAME = "dialogContentWidget"
    # Hit-test resize по краям resizable-диалогов (px); шире, чем у главного окна (4 px).
    _RESIZE_EDGE_SIZE_PX = 8

    @classmethod
    def chrome_extra_height_px(cls):
        """Доп. высота окна относительно контента: titlebar + separator + рамка."""
        return int(DialogTitleBar.TITLEBAR_HEIGHT_PX) + 1 + 2

    @classmethod
    def chrome_extra_width_px(cls):
        """Доп. ширина окна относительно контента: margins chrome + рамка."""
        return 4

    def __init__(self, parent=None, *, resizable=False, content_margins=(8, 8, 8, 8)):
        super().__init__(parent)
        if resizable == "horizontal":
            self._frameless_resizable = True
            self._frameless_resize_horizontal_only = True
        else:
            self._frameless_resizable = bool(resizable)
            self._frameless_resize_horizontal_only = False
        if self._frameless_resizable:
            self._resize_edge_size = int(self._RESIZE_EDGE_SIZE_PX)
        self._border_color = self._theme_value("dialog_border", "#A2A4A6")
        self._init_frameless_shell(content_margins)
        try:
            ThemeManager.instance().register_refresh_callback(self._refresh_frameless_dialog_theme)
        except Exception:
            pass
        try:
            self.destroyed.connect(self._unregister_frameless_dialog_theme_callback)
        except Exception:
            pass
        try:
            self.destroyed.connect(self._unregister_resizable_cursor_tracking)
        except Exception:
            pass

    @staticmethod
    def _theme_value(key, default):
        try:
            return ThemeManager.instance().color(key)
        except Exception:
            pass
        try:
            return LIGHT_THEME[key]
        except Exception:
            return default

    @staticmethod
    def _theme_dict():
        try:
            return ThemeManager.instance().theme()
        except Exception:
            pass
        try:
            return LIGHT_THEME
        except NameError:
            return {}

    def _init_frameless_shell(self, content_margins):
        self.setWindowFlags(Qt.Dialog | Qt.FramelessWindowHint)
        self.setAttribute(Qt.WA_TranslucentBackground, True)
        self.setMouseTracking(True)

        root_layout = QVBoxLayout(self)
        root_layout.setContentsMargins(0, 0, 0, 0)
        root_layout.setSpacing(0)

        self._chrome_widget = QWidget(self)
        self._chrome_widget.setObjectName(self.CHROME_OBJECT_NAME)
        self._chrome_widget.setAttribute(Qt.WA_StyledBackground, True)
        self._chrome_widget.setAutoFillBackground(True)
        self._chrome_widget.setMouseTracking(True)
        self._chrome_widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        root_layout.addWidget(self._chrome_widget, 1)

        chrome_layout = QVBoxLayout(self._chrome_widget)
        chrome_layout.setContentsMargins(1, 1, 1, 1)
        chrome_layout.setSpacing(0)

        self._title_bar = DialogTitleBar(self)
        chrome_layout.addWidget(self._title_bar)

        self._title_bar_separator = QWidget(self._chrome_widget)
        self._title_bar_separator.setFixedHeight(1)
        self._title_bar_separator.setAttribute(Qt.WA_StyledBackground, True)
        chrome_layout.addWidget(self._title_bar_separator)

        self._content_widget = QWidget(self._chrome_widget)
        self._content_widget.setObjectName(self.CONTENT_OBJECT_NAME)
        self._content_widget.setAttribute(Qt.WA_StyledBackground, True)
        self._content_widget.setAutoFillBackground(True)
        self._content_widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        chrome_layout.addWidget(self._content_widget, 1)

        l, t, r, b = content_margins
        self._content_layout = QVBoxLayout(self._content_widget)
        self._content_layout.setContentsMargins(int(l), int(t), int(r), int(b))

        self._inherit_window_icon()
        self._apply_chrome_styles()

    def _inherit_window_icon(self):
        try:
            parent = self.parent()
            if parent is not None:
                icon = parent.windowIcon()
                if not icon.isNull():
                    self.setWindowIcon(icon)
                    return
            app = QApplication.instance()
            if app is not None:
                icon = app.windowIcon()
                if not icon.isNull():
                    self.setWindowIcon(icon)
        except Exception:
            pass

    def content_widget(self):
        return self._content_widget

    def content_layout(self):
        return self._content_layout

    def setWindowTitle(self, title):
        super().setWindowTitle(title)
        tb = getattr(self, "_title_bar", None)
        if tb is not None:
            tb.set_title_text(title)

    def resize_for_content(self, width, height):
        """Задать размер клиентской области (без учёта titlebar и рамки)."""
        self.resize(int(width), int(height) + self.chrome_extra_height_px())

    def fit_to_content_size(self, *, min_content_width=None, lock_height=False):
        """Подогнать размер окна под sizeHint контента (без фиксированных px).

        min_content_width — нижняя граница ширины контента (напр. ~30 символов × 2 колонки).
        lock_height — зафиксировать высоту (resize только по ширине).
        """
        cw = self.content_widget()
        layout = self.content_layout()
        prev_constraint = None
        try:
            if min_content_width is not None:
                cw.setMinimumWidth(max(int(cw.minimumWidth()), int(min_content_width)))
            if layout is not None:
                prev_constraint = layout.sizeConstraint()
                layout.setSizeConstraint(QtWidgets.QLayout.SetFixedSize)
                layout.activate()
            cw.adjustSize()
            content_w = max(
                int(cw.sizeHint().width()),
                int(cw.minimumSizeHint().width()),
                int(cw.minimumWidth()),
            )
            content_h = max(
                int(cw.sizeHint().height()),
                int(cw.minimumSizeHint().height()),
                int(cw.minimumHeight()),
            )
        except Exception:
            content_w, content_h = 400, 300
        finally:
            try:
                if layout is not None:
                    layout.setSizeConstraint(
                        prev_constraint
                        if prev_constraint is not None
                        else QtWidgets.QLayout.SetDefaultConstraint
                    )
            except Exception:
                pass
        try:
            cw.setMinimumWidth(int(content_w))
            cw.setMinimumHeight(int(content_h))
            cw.setMaximumWidth(int(QtWidgets.QWIDGETSIZE_MAX))
            if lock_height:
                cw.setMaximumHeight(int(content_h))
            else:
                cw.setMaximumHeight(int(QtWidgets.QWIDGETSIZE_MAX))
            if layout is not None:
                layout.setSizeConstraint(QtWidgets.QLayout.SetNoConstraint)
                layout.activate()
            w = int(content_w) + self.chrome_extra_width_px()
            h = int(content_h) + self.chrome_extra_height_px()
            self.setMinimumWidth(w)
            if lock_height:
                self.setMinimumHeight(h)
                self.setMaximumHeight(h)
            else:
                self.setMinimumHeight(h)
            self.resize(w, h)
            self._sync_frameless_shell_geometry()
        except Exception:
            pass
        self._refresh_frameless_dialog_theme()

    def _sync_frameless_shell_geometry(self):
        """Frameless + WA_TranslucentBackground: принудительно растянуть chrome на весь диалог."""
        try:
            chrome = getattr(self, "_chrome_widget", None)
            if chrome is None:
                return
            target = self.rect().size()
            if target.width() <= 0 or target.height() <= 0:
                return
            if chrome.size() != target:
                chrome.resize(target)
            chrome_layout = chrome.layout()
            if chrome_layout is not None:
                chrome_layout.activate()
            content_layout = self.content_layout()
            if content_layout is not None:
                content_layout.activate()
        except Exception:
            pass

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._sync_frameless_shell_geometry()

    def _apply_chrome_styles(self):
        self._apply_dialog_palette()
        theme = self._theme_dict()
        border = theme.get("dialog_border", self._border_color)
        self._border_color = border
        self._chrome_widget.setStyleSheet(
            f"QWidget#{self.CHROME_OBJECT_NAME} {{"
            f" background-color: palette(window);"
            f" border: 1px solid {border};"
            f" }}"
        )
        self._content_widget.setStyleSheet(
            f"QWidget#{self.CONTENT_OBJECT_NAME} {{"
            f" background-color: palette(window);"
            f" border: none;"
            f" }}"
        )
        sep = theme.get("separator", "#cccccc")
        self._title_bar_separator.setStyleSheet(
            f"QWidget {{ background-color: {sep}; border: none; }}"
        )
        tb = getattr(self, "_title_bar", None)
        if tb is not None:
            tb.apply_theme_styles(theme)

    def _apply_dialog_palette(self):
        """Палитра диалоговых окон из ThemeManager — как у нативных QDialog через app.setPalette."""
        try:
            palette = ThemeManager.instance().palette()
        except Exception:
            try:
                palette = build_palette(self._theme_dict())
            except Exception:
                return
        self.setPalette(palette)
        for widget in (getattr(self, "_chrome_widget", None), getattr(self, "_content_widget", None)):
            if widget is not None:
                widget.setPalette(palette)
        content = getattr(self, "_content_widget", None)
        if content is not None:
            theme = self._theme_dict()
            for child in content.findChildren(QWidget):
                try:
                    if isinstance(child, TextEditor):
                        child.apply_theme_styles(theme)
                        continue
                    child.setPalette(palette)
                    child.style().unpolish(child)
                    child.style().polish(child)
                except Exception:
                    pass

    def _refresh_frameless_dialog_theme(self):
        self._apply_chrome_styles()

    def _unregister_frameless_dialog_theme_callback(self, *_args):
        try:
            ThemeManager.instance().unregister_refresh_callback(self._refresh_frameless_dialog_theme)
        except Exception:
            pass

    def showEvent(self, event):
        super().showEvent(event)
        self._attach_combo_popup_resize_guards()
        self._ensure_frameless_resize_filters()
        if self._frameless_resizable:
            _ResizableDialogCursorAppFilter.instance().register_dialog(self)
        self._refresh_frameless_dialog_theme()
        self._sync_frameless_shell_geometry()
        focus_widget = self._initial_focus_widget()
        if focus_widget is not None:
            try:
                focus_widget.setFocus(Qt.ActiveWindowFocusReason)
            except Exception:
                pass

    def hideEvent(self, event):
        if self._frameless_resizable:
            self._unregister_resizable_cursor_tracking()
            self.clear_application_override_cursor()
        super().hideEvent(event)

    def leaveEvent(self, event):
        if self._frameless_resizable:
            self.clear_application_override_cursor()
        super().leaveEvent(event)

    def _unregister_resizable_cursor_tracking(self, *_args):
        try:
            _ResizableDialogCursorAppFilter.instance().unregister_dialog(self)
        except Exception:
            pass

    def _initial_focus_widget(self):
        """Виджет для начального фокуса при показе; переопределяется в наследниках."""
        return None

    def _frameless_modal_or_popup_blocks_resize(self):
        """Модальный frameless-диалог: блокировать resize при popup этого диалога."""
        try:
            active_modal = QApplication.activeModalWidget()
            if active_modal is not None and active_modal is not self:
                return True
            popup = QApplication.activePopupWidget()
            if popup is not None:
                if FramelessWindowMixin._popup_belongs_to_widget(popup, self):
                    return True
                if active_modal is self:
                    return True
        except Exception:
            pass
        return False

    def _attach_combo_popup_resize_guards(self):
        """QComboBox dropdown: сброс resize-курсора; на Wayland — фикс геометрии popup."""
        roots = [self]
        content = getattr(self, "_content_widget", None)
        if content is not None:
            roots.append(content)
        seen_combos = set()
        for root in roots:
            try:
                combos = root.findChildren(QComboBox)
            except Exception:
                combos = []
            for combo in combos:
                wid = id(combo)
                if wid in seen_combos:
                    continue
                seen_combos.add(wid)
                if getattr(combo, "_jbp_show_popup_guarded", False):
                    continue
                try:
                    combo._jbp_show_popup_guarded = True
                    orig_show_popup = combo.showPopup

                    def _guarded_show_popup(_orig=orig_show_popup, _combo=combo):
                        FramelessWindowMixin.clear_application_override_cursor()
                        _prepare_combo_popup_wayland(_combo)
                        _orig()
                        _fix_combo_popup_geometry_wayland(_combo)

                    combo.showPopup = _guarded_show_popup
                except Exception:
                    pass

    def _ensure_frameless_resize_filters(self):
        """Проброс событий мыши с дочерних виджетов для resize по краям (resizable=True)."""
        if not self._frameless_resizable:
            return
        if getattr(self, "_frameless_resize_filters_ready", False):
            return
        targets = [self]
        for attr in ("_chrome_widget", "_content_widget", "_title_bar"):
            w = getattr(self, attr, None)
            if w is not None:
                targets.append(w)
        content = getattr(self, "_content_widget", None)
        if content is not None:
            targets.extend(content.findChildren(QWidget))
        title_bar = getattr(self, "_title_bar", None)
        if title_bar is not None:
            targets.extend(title_bar.findChildren(QWidget))
        seen = set()
        for widget in targets:
            if widget is None:
                continue
            if isinstance(widget, QComboBox):
                continue
            try:
                parent = widget.parentWidget()
                while parent is not None:
                    if isinstance(parent, QComboBox):
                        break
                    parent = parent.parentWidget()
                else:
                    parent = None
                if parent is not None:
                    continue
            except Exception:
                pass
            wid = id(widget)
            if wid in seen:
                continue
            seen.add(wid)
            try:
                widget.setMouseTracking(True)
                widget.installEventFilter(self)
            except Exception:
                pass
        self._frameless_resize_filters_ready = True

    def eventFilter(self, obj, event):
        if self._frameless_resizable and isinstance(event, QMouseEvent):
            try:
                popup = QApplication.activePopupWidget()
                if popup is not None and FramelessWindowMixin._popup_belongs_to_widget(popup, self):
                    if event.type() in (
                        QEvent.MouseButtonPress,
                        QEvent.MouseButtonRelease,
                    ):
                        if FramelessWindowMixin._popup_contains_global_point(
                            popup, event.globalPos()
                        ):
                            return True
                    return False
            except Exception:
                pass
            if isinstance(obj, QComboBox):
                return False
            try:
                parent = obj.parentWidget()
                while parent is not None:
                    if isinstance(parent, QComboBox):
                        return False
                    parent = parent.parentWidget()
            except Exception:
                pass
            et = event.type()
            if et in (QEvent.MouseMove, QEvent.MouseButtonPress, QEvent.MouseButtonRelease):
                local_pos = self.mapFromGlobal(event.globalPos())
                if et == QEvent.MouseMove:
                    mapped = QMouseEvent(
                        QEvent.MouseMove,
                        local_pos,
                        event.globalPos(),
                        event.button(),
                        event.buttons(),
                        event.modifiers(),
                    )
                    self.frameless_handle_mouse_move(mapped)
                elif et == QEvent.MouseButtonPress and event.button() == Qt.LeftButton:
                    mapped = QMouseEvent(
                        QEvent.MouseButtonPress,
                        local_pos,
                        event.globalPos(),
                        event.button(),
                        event.buttons(),
                        event.modifiers(),
                    )
                    if self.frameless_handle_mouse_press(mapped):
                        return True
                elif et == QEvent.MouseButtonRelease and event.button() == Qt.LeftButton:
                    self.clear_application_override_cursor()
        return super().eventFilter(obj, event)

    def _is_titlebar_chrome_at(self, pos):
        try:
            tb = self._title_bar
            global_pos = self.mapToGlobal(pos)
            local = tb.mapFromGlobal(global_pos)
            return tb.rect().contains(local)
        except Exception:
            return False

    def _frameless_is_titlebar_drag_at(self, local_pos):
        try:
            tb = getattr(self, "_title_bar", None)
            if tb is None or not tb.isVisible():
                return False
            global_pos = self.mapToGlobal(local_pos)
            tb_local = tb.mapFromGlobal(global_pos)
            if not tb.rect().contains(tb_local):
                return False
            return bool(tb._is_drag_region(tb_local))
        except Exception:
            return False

    def _frameless_resize_blocked_at(self, pos):
        return self._is_titlebar_chrome_at(pos)

    def _get_resize_edge(self, pos):
        if not self._frameless_resizable:
            return None
        try:
            if self.isMaximized():
                return None
        except Exception:
            pass
        if self._frameless_resize_blocked_at(pos):
            return None

        rect = self.rect()
        x, y = pos.x(), pos.y()
        edge_size = int(getattr(self, "_resize_edge_size", 4))
        inset = int(self._frameless_resize_inset_px())
        width = rect.width()
        height = rect.height()

        if getattr(self, "_frameless_resize_horizontal_only", False):
            if x <= edge_size + inset:
                return "left"
            if x >= width - edge_size - inset:
                return "right"
            return None

        # Только стороны (без углов): достаточно ← → ↑ ↓
        if x <= edge_size + inset:
            return "left"
        if x >= width - edge_size - inset:
            return "right"
        if y <= edge_size + inset:
            return "top"
        if y >= height - edge_size - inset:
            return "bottom"
        return None

    def mouseMoveEvent(self, event):
        if self.frameless_handle_mouse_move(event):
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mousePressEvent(self, event):
        if self.frameless_handle_mouse_press(event):
            return
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event):
        if self.frameless_handle_mouse_release(event):
            if self._frameless_resizable:
                self.clear_application_override_cursor()
            else:
                self.frameless_restore_resize_cursor()
            return
        if event.button() == Qt.LeftButton and self._frameless_resizable:
            self.clear_application_override_cursor()
        elif event.button() == Qt.LeftButton:
            self.frameless_restore_resize_cursor()
        super().mouseReleaseEvent(event)

    def nativeEvent(self, eventType, message):
        return self.frameless_dispatch_native_event(eventType, message)


class ThemedMessageDialog(ThemedFramelessDialog):
    """Themed-замена QMessageBox: одно- и двухкнопочные сообщения, confirm-диалоги.

    Возвращает коды QMessageBox.* для совместимости с существующими проверками reply.
    Файловые диалоги (QFileDialog) сюда не входят — остаются нативными.
    """

    _ICON_STD_ROLE = {
        QMessageBox.Question: QStyle.SP_MessageBoxQuestion,
        QMessageBox.Warning: QStyle.SP_MessageBoxWarning,
        QMessageBox.Information: QStyle.SP_MessageBoxInformation,
        QMessageBox.Critical: QStyle.SP_MessageBoxCritical,
    }
    _BUTTON_LABEL_KEYS = {
        QMessageBox.Ok: ("dialog.button_ok", "ОК"),
        QMessageBox.Cancel: ("dialog.button_cancel", "Отмена"),
        QMessageBox.Yes: ("dialog.button_yes", "Да"),
        QMessageBox.No: ("dialog.button_no", "Нет"),
    }
    # Порядок кнопок в строке (как NewNotebookDialog: справа, слева направо Ok → Cancel).
    _BUTTON_ROW_ORDER = (
        QMessageBox.Ok,
        QMessageBox.Cancel,
        QMessageBox.Yes,
        QMessageBox.No,
    )
    # Минимальная ширина текстовой колонки (~как _fix_form_label в Ui_Dialog / Настройки).
    _TEXT_WRAP_CHARS = 50

    def __init__(
        self,
        parent=None,
        *,
        title="",
        text="",
        icon=QMessageBox.NoIcon,
        buttons=QMessageBox.Ok,
        default_button=None,
        button_labels=None,
        button_order=None,
    ):
        super().__init__(parent, resizable=False, content_margins=(16, 16, 16, 12))
        self.setWindowTitle(title)
        self.setModal(True)
        self._result = QMessageBox.Cancel
        self._result_from_button = False
        self._default_button_widget = None
        self._button_widgets = {}

        layout = self.content_layout()

        body_layout = QHBoxLayout()
        body_layout.setSpacing(12)

        self._icon_label = QLabel()
        self._icon_label.setAlignment(Qt.AlignTop | Qt.AlignLeft)
        icon_pixmap = self._icon_pixmap(icon)
        if icon_pixmap is not None and not icon_pixmap.isNull():
            self._icon_label.setPixmap(icon_pixmap)
            body_layout.addWidget(self._icon_label, 0, Qt.AlignTop)
        else:
            self._icon_label.hide()

        self._text_label = QLabel(text)
        self._text_label.setWordWrap(True)
        self._text_label.setSizePolicy(QSizePolicy.MinimumExpanding, QSizePolicy.Preferred)
        self._text_label.setTextInteractionFlags(Qt.TextSelectableByMouse)
        try:
            fm = self._text_label.fontMetrics()
            text_min_px = int(fm.averageCharWidth() * self._TEXT_WRAP_CHARS)
            self._text_label.setMinimumWidth(text_min_px)
        except Exception:
            text_min_px = 0
        body_layout.addWidget(self._text_label, 1)
        layout.addLayout(body_layout)

        buttons_layout = QHBoxLayout()
        buttons_layout.addStretch()
        labels = dict(button_labels or {})
        row_order = button_order if button_order is not None else self._BUTTON_ROW_ORDER
        for role in row_order:
            if not (int(buttons) & int(role)):
                continue
            if role in labels:
                btn_text = labels[role]
            else:
                key, fallback = self._BUTTON_LABEL_KEYS.get(role, ("", str(role)))
                btn_text = tr(key, fallback) if key else fallback
            btn = QPushButton(btn_text)
            btn.clicked.connect(lambda _checked=False, r=role: self._on_button_clicked(r))
            buttons_layout.addWidget(btn)
            self._button_widgets[role] = btn

        if default_button is not None and default_button in self._button_widgets:
            self._button_widgets[default_button].setDefault(True)
            self._default_button_widget = self._button_widgets[default_button]
        elif int(buttons) == int(QMessageBox.Ok):
            ok_btn = self._button_widgets.get(QMessageBox.Ok)
            if ok_btn is not None:
                ok_btn.setDefault(True)
                self._default_button_widget = ok_btn

        layout.addLayout(buttons_layout)
        icon_extra = (48 + 12) if icon_pixmap is not None and not icon_pixmap.isNull() else 0
        content_margins_h = 16 + 16
        min_content_w = icon_extra + text_min_px + content_margins_h
        if min_content_w > 0:
            self.fit_to_content_size(min_content_width=min_content_w)
        else:
            self.fit_to_content_size()

    @classmethod
    def _icon_pixmap(cls, icon):
        std_role = cls._ICON_STD_ROLE.get(icon)
        if std_role is None:
            return None
        try:
            app = QApplication.instance()
            if app is not None:
                return app.style().standardIcon(std_role).pixmap(48, 48)
        except Exception:
            pass
        return None

    def _default_reject_role(self):
        for role in (QMessageBox.Cancel, QMessageBox.No, QMessageBox.Ok):
            if role in self._button_widgets:
                return role
        return QMessageBox.Cancel

    def _on_button_clicked(self, role):
        self._result_from_button = True
        self._result = role
        if role in (QMessageBox.Ok, QMessageBox.Yes):
            self.accept()
        else:
            self.reject()

    def reject(self):
        if not self._result_from_button:
            self._result = self._default_reject_role()
        super().reject()

    def closeEvent(self, event):
        if not self._result_from_button:
            self._result = self._default_reject_role()
        super().closeEvent(event)

    def exec_(self):
        self._result_from_button = False
        self._result = self._default_reject_role()
        super().exec_()
        return self._result

    def _initial_focus_widget(self):
        return self._default_button_widget

    @classmethod
    def single_ok(cls, parent, title, text, *, icon=QMessageBox.Information):
        """Однокнопочное сообщение (эталон миграции _qmessagebox_single_ok)."""
        dlg = cls(
            parent,
            title=title,
            text=text,
            icon=icon,
            buttons=QMessageBox.Ok,
            default_button=QMessageBox.Ok,
        )
        dlg.exec_()
        return dlg._result

    @classmethod
    def question_ok_cancel(cls, parent, title, text, *, default_button=None):
        """Подтверждение Ok/Cancel (эталон миграции delete_item и аналогов)."""
        dlg = cls(
            parent,
            title=title,
            text=text,
            icon=QMessageBox.Question,
            buttons=QMessageBox.Ok | QMessageBox.Cancel,
            default_button=default_button,
        )
        return dlg.exec_()

    @classmethod
    def warning_ok_cancel(cls, parent, title, text, *, default_button=QMessageBox.Cancel):
        """Предупреждение Ok/Cancel (потеря несохранённых изменений и аналоги)."""
        dlg = cls(
            parent,
            title=title,
            text=text,
            icon=QMessageBox.Warning,
            buttons=QMessageBox.Ok | QMessageBox.Cancel,
            default_button=default_button,
        )
        return dlg.exec_()

    @classmethod
    def question_yes_no(cls, parent, title, text, *, default_button=QMessageBox.No, button_labels=None):
        """Подтверждение Yes/No (подписи кнопок — через button_labels, напр. ОК/Отмена)."""
        dlg = cls(
            parent,
            title=title,
            text=text,
            icon=QMessageBox.Question,
            buttons=QMessageBox.Yes | QMessageBox.No,
            default_button=default_button,
            button_labels=button_labels,
        )
        return dlg.exec_()

    @classmethod
    def question_yes_no_cancel(cls, parent, title, text, *, default_button=QMessageBox.Cancel, button_labels=None):
        """Подтверждение Yes/No/Cancel (Escape/крестик → Cancel)."""
        dlg = cls(
            parent,
            title=title,
            text=text,
            icon=QMessageBox.Question,
            buttons=QMessageBox.Yes | QMessageBox.No | QMessageBox.Cancel,
            default_button=default_button,
            button_labels=button_labels,
            button_order=(QMessageBox.Yes, QMessageBox.No, QMessageBox.Cancel),
        )
        return dlg.exec_()


# --- About dialog (English only; edit text and URLs here) ---
_ABOUT_DIALOG_LINES = (
    "JBPad 1.0",
    "",
    "Free and open-source software.",
    "License: GNU GPLv3",
    "",    
    "Copyright © 2026 Олег Любошенко (somuser)",
    "",
    "Platforms:",
    "",    
    "Windows • macOS • Linux",
)

# (heading, link_text, url). Empty url → plain selectable text (not clickable yet).
_ABOUT_DIALOG_LINK_SECTIONS = (
    ("Website:", "somuser.org", "https://somuser.org"),
    ("Source code:", "GitHub", "https://github.com/somusersoft/JBPad"),
)


def _build_about_dialog_html(theme=None):
    """Собирает HTML для окна «О программе» из констант выше."""
    try:
        theme = theme or ThemeManager.instance().theme()
    except Exception:
        try:
            theme = LIGHT_THEME
        except NameError:
            theme = {}
    text_color = theme.get("palette_window_text", "#000000")
    window_color = theme.get("palette_window", "#f0f0f0")
    link_color = theme.get("link_color", "#2b6cb0")
    parts = [
        f'<div style="color:{html.escape(str(text_color))};'
        f' background-color:{html.escape(str(window_color))};">',
    ]
    for line in _ABOUT_DIALOG_LINES:
        if line == "":
            parts.append("<br/>")
        else:
            parts.append(f"<p style='margin:0;'>{html.escape(line)}</p>")
    parts.append("<br/>")
    for heading, link_text, url in _ABOUT_DIALOG_LINK_SECTIONS:
        parts.append(f"<p style='margin:0;'>{html.escape(heading)}</p>")
        url = str(url or "").strip()
        if url:
            safe_url = html.escape(url, quote=True)
            safe_text = html.escape(link_text)
            parts.append(
                f'<p style="margin:0;">'
                f'<a href="{safe_url}" style="color:{html.escape(str(link_color))}; text-decoration:none;">'
                f"{safe_text}</a></p>"
            )
        else:
            parts.append(f"<p style='margin:0;'>{html.escape(link_text)}</p>")
        parts.append("<br/>")
    parts.append("</div>")
    return "".join(parts)


class AboutJBPadDialog(ThemedFramelessDialog):
    """Окно «О программе» (English only, без локализации)."""

    _TEXT_WRAP_CHARS = 50

    def __init__(self, parent=None):
        super().__init__(parent, resizable=False, content_margins=(16, 16, 16, 12))
        self.setWindowTitle("")
        self.setModal(True)

        layout = self.content_layout()

        self._text_browser = QTextBrowser()
        self._text_browser.setOpenExternalLinks(True)
        self._text_browser.setReadOnly(True)
        self._text_browser.setFrameShape(QtWidgets.QFrame.NoFrame)
        self._text_browser.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self._text_browser.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self._text_browser.setTextInteractionFlags(
            Qt.TextSelectableByMouse | Qt.TextBrowserInteraction
        )
        self._text_browser.setSizePolicy(QSizePolicy.MinimumExpanding, QSizePolicy.Fixed)
        try:
            fm = self._text_browser.fontMetrics()
            text_min_px = int(fm.averageCharWidth() * self._TEXT_WRAP_CHARS)
            self._text_browser.setMinimumWidth(text_min_px)
        except Exception:
            text_min_px = 0
        layout.addWidget(self._text_browser)
        try:
            wire_copy_paste_context_menu_for_text_edit(self._text_browser, paste_enabled=False)
        except Exception:
            pass

        buttons_layout = QHBoxLayout()
        buttons_layout.addStretch()
        self.ok_button = QPushButton("OK")
        self.ok_button.setDefault(True)
        self.ok_button.clicked.connect(self.accept)
        buttons_layout.addWidget(self.ok_button)
        buttons_layout.addStretch()
        layout.addLayout(buttons_layout)

        self._update_about_html()
        content_margins_h = 16 + 16
        min_content_w = text_min_px + content_margins_h if text_min_px > 0 else None
        if min_content_w:
            self.fit_to_content_size(min_content_width=min_content_w)
        else:
            self.fit_to_content_size()

    def _apply_text_browser_background(self):
        """Фон QTextBrowser = фон диалогового окна (только для этого окна)."""
        try:
            browser = self._text_browser
            window_color = self.palette().color(QPalette.Window)
            pal = browser.palette()
            pal.setColor(QPalette.Base, window_color)
            browser.setPalette(pal)
            browser.setAutoFillBackground(True)
            viewport = browser.viewport()
            if viewport is not None:
                vp_pal = viewport.palette()
                vp_pal.setColor(QPalette.Window, window_color)
                vp_pal.setColor(QPalette.Base, window_color)
                viewport.setPalette(vp_pal)
                viewport.setAutoFillBackground(True)
            browser.setStyleSheet(
                "QTextBrowser, QTextBrowser QAbstractScrollArea::viewport {"
                " background-color: palette(window); border: none; }"
            )
        except Exception:
            pass

    def _update_about_html(self):
        try:
            theme = self._theme_dict()
        except Exception:
            theme = {}
        self._apply_text_browser_background()
        self._text_browser.setHtml(_build_about_dialog_html(theme))
        self._sync_about_browser_height()

    def _sync_about_browser_height(self):
        try:
            viewport_w = max(
                int(self._text_browser.viewport().width()),
                int(self._text_browser.minimumWidth()),
                200,
            )
            doc = self._text_browser.document()
            doc.setTextWidth(float(viewport_w))
            height = int(math.ceil(doc.size().height())) + 4
            self._text_browser.setFixedHeight(max(height, 1))
        except Exception:
            pass

    def _refresh_frameless_dialog_theme(self):
        super()._refresh_frameless_dialog_theme()
        self._update_about_html()

    def showEvent(self, event):
        super().showEvent(event)
        self._sync_about_browser_height()

    def _initial_focus_widget(self):
        return getattr(self, "ok_button", None)


class CustomTitleBar(QWidget):
    """Кастомная панель заголовка для frameless окна"""

    # Высота полосы titlebar (px). Все кнопки titlebar подстраиваются под это значение.
    TITLEBAR_HEIGHT_PX = 28
    # Размер PNG-иконок (px). Кнопки TITLEBAR_HEIGHT_PX, иконка центрируется внутри.
    TITLE_BAR_ICON_SIZE = 24
    # Размер иконки приложения (px) — как в заголовках дочерних окон (16×16 из .ico).
    TITLEBAR_APP_ICON_SIZE = 16
    # --- Расположение иконок в titlebar (все отступы в px) ---
    # 1. Иконка приложения → первая иконка левого блока (Создать файл … Настройки).
    TITLEBAR_LEFT_NAV_FIRST_ICON_OFFSET_PX = 0
    # 2. Правый блок (избранное, тема) → блок кнопок окна (свернуть, развернуть, закрыть).
    TITLEBAR_RIGHT_TOOL_TO_WINDOW_CONTROLS_GAP_PX = 18
    # 3. Между иконками в правом блоке: поверх всех окон ↔ избранное ↔ тема.
    TITLEBAR_RIGHT_TOOL_ICON_GAP_PX = 0
    # 4. Промежутки в левом блоке (6 иконок): (n1, n2, n3, n4, n5) — px между соседними парами.
    # n1: 1→2, n2: 2→3, n3: 3→4, n4: 4→5, n5: 5→6 (Создать файл … Настройки).
    TITLEBAR_LEFT_NAV_ICON_GAPS_PX = (0, 0, 0, 0, 0)

    @staticmethod
    def _add_fixed_spacer(layout, parent_widget, width_px, alignment=Qt.AlignVCenter):
        """Невидимый горизонтальный отступ фиксированной ширины (px)."""
        w = int(width_px)
        if w > 0:
            spacer = QWidget(parent_widget)
            spacer.setFixedWidth(w)
            spacer.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
            layout.addWidget(spacer, 0, alignment)

    @classmethod
    def _normalize_gaps_px(cls, gaps_px, button_count):
        """Приводит gaps к кортежу длины button_count - 1 (int, допускает одно число)."""
        if button_count <= 1:
            return ()
        if isinstance(gaps_px, (tuple, list)):
            raw = tuple(gaps_px)
        elif gaps_px is None:
            raw = ()
        else:
            raw = (int(gaps_px),)
        gaps = tuple(int(g) for g in raw)
        need = button_count - 1
        if len(gaps) < need:
            gaps = gaps + (0,) * (need - len(gaps))
        return gaps[:need]

    @classmethod
    def _layout_icon_row_gaps(cls, layout, parent_widget, buttons, gaps_px):
        """Ряд QPushButton; зазоры только явные spacers (px) или отриц. margin-left."""
        gaps = cls._normalize_gaps_px(gaps_px, len(buttons))
        align = Qt.AlignVCenter
        for i, btn in enumerate(buttons):
            if i > 0:
                gap = gaps[i - 1] if (i - 1) < len(gaps) else 0
                if gap > 0:
                    cls._add_fixed_spacer(layout, parent_widget, gap, alignment=align)
                elif gap < 0:
                    base = (btn.styleSheet() or "").strip()
                    btn.setStyleSheet(
                        base + f" QPushButton {{ margin-left: {gap}px; }}"
                    )
            layout.addWidget(btn, 0, align)

    @classmethod
    def _make_icon_row_widget(cls, parent, buttons, gaps_px):
        """Контейнер с горизонтальным рядом иконок (левый/правый блок)."""
        row = QWidget(parent)
        row_layout = QHBoxLayout(row)
        row_layout.setContentsMargins(0, 0, 0, 0)
        row_layout.setSpacing(0)
        cls._layout_icon_row_gaps(row_layout, row, buttons, gaps_px)
        return row

    def __init__(self, parent=None):
        super().__init__(parent)
        self.main_window = parent
        self._drag_area_left_x = 0
        bar_h = int(self.TITLEBAR_HEIGHT_PX)
        icon_px = int(self.TITLE_BAR_ICON_SIZE)
        self.setFixedHeight(bar_h)
        
        self.setObjectName("CustomTitleBar")
        self.setAttribute(Qt.WA_StyledBackground, True)
        self.setCursor(Qt.ArrowCursor)

        layout = QHBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        tool_hover = LIGHT_THEME["titlebar_tool_button_hover_overlay"]
        window_hover = LIGHT_THEME["titlebar_button_hover_overlay"]
        close_hover = LIGHT_THEME["titlebar_close_button_hover_background"]
        self._tool_btn_style = (
            "QPushButton { border: none; background: transparent; padding: 0px; margin: 0px; }"
            f"QPushButton:hover {{ background-color: {tool_hover}; }}"
        )
        self._window_btn_style = (
            "QPushButton { border: none; background: transparent; padding: 0px; margin: 0px; }"
            f"QPushButton:hover {{ background-color: {window_hover}; }}"
        )
        self._close_btn_style = (
            "QPushButton { border: none; background: transparent; padding: 0px; margin: 0px; }"
            f"QPushButton:hover {{ background-color: {close_hover}; }}"
        )
        icon_sz = QSize(icon_px, icon_px)

        def _make_icon_button(tooltip, style_sheet):
            btn = _TitleBarIconButton(self)
            btn.setFixedSize(bar_h, bar_h)
            btn.setIconSize(icon_sz)
            btn.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
            btn.setCursor(Qt.ArrowCursor)
            btn.setStyleSheet(style_sheet)
            btn.setToolTip(tooltip)
            return btn

        self.app_icon_label = QLabel(self)
        self.app_icon_label.setFixedSize(bar_h, bar_h)
        self.app_icon_label.setAlignment(Qt.AlignCenter)
        self.app_icon_label.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        self.app_icon_label.setCursor(Qt.ArrowCursor)
        layout.addWidget(self.app_icon_label, 0, Qt.AlignVCenter)

        self._add_fixed_spacer(layout, self, self.TITLEBAR_LEFT_NAV_FIRST_ICON_OFFSET_PX)

        self.nav_new_file_button = _make_icon_button(
            tr("tooltip.new_file", "Создать файл"), self._tool_btn_style
        )
        self.nav_new_folder_button = _make_icon_button(
            tr("tooltip.new_folder", "Создать папку"), self._tool_btn_style
        )
        self.nav_open_notepad_button = _make_icon_button(
            tr("tooltip.open_notepad", "Открыть блокнот"), self._tool_btn_style
        )
        self.nav_new_notepad_button = _make_icon_button(
            tr("tooltip.new_notepad", "Создать блокнот"), self._tool_btn_style
        )
        self.nav_file_management_button = _make_icon_button(
            tr("tooltip.file_management", "Управление файлами..."), self._tool_btn_style
        )
        self.nav_find_button = _make_icon_button(
            tr("dialog.search", "Поиск"), self._tool_btn_style
        )
        self.nav_settings_button = _make_icon_button(
            tr("tooltip.setting", "Настройки"), self._tool_btn_style
        )
        self.nav_tool_buttons = (
            self.nav_new_file_button,
            self.nav_new_folder_button,
            self.nav_open_notepad_button,
            self.nav_new_notepad_button,
            self.nav_file_management_button,
            self.nav_find_button,
            self.nav_settings_button,
        )
        self._left_nav_row = self._make_icon_row_widget(
            self, self.nav_tool_buttons, self.TITLEBAR_LEFT_NAV_ICON_GAPS_PX
        )
        layout.addWidget(self._left_nav_row, 0, Qt.AlignVCenter)

        # Зона перетаскивания: постоянный контейнер (stretch) + индикатор по центру.
        self._drag_area = QWidget(self)
        self._drag_area.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
        self._drag_area.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        drag_layout = QHBoxLayout(self._drag_area)
        drag_layout.setContentsMargins(10, 0, 10, 0)
        drag_layout.setSpacing(0)
        self.autosave_status_label = QLabel(self._drag_area)
        self.autosave_status_label.setObjectName("titlebarAutosaveStatus")
        self.autosave_status_label.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.autosave_status_label.setAlignment(Qt.AlignVCenter | Qt.AlignCenter)
        drag_layout.addWidget(self.autosave_status_label, 0, Qt.AlignCenter)
        self.autosave_status_label.hide()
        layout.addWidget(self._drag_area, 1)

        self.always_on_top_button = _make_icon_button(
            tr("tooltip.always_on_top", "Поверх всех окон"), self._tool_btn_style
        )
        if self.main_window:
            self.always_on_top_button.clicked.connect(
                self.main_window._toggle_always_on_top_from_favorites
            )

        self.favorites_toggle_button = _make_icon_button(
            tr("tooltip.favorites", "Избранное"), self._tool_btn_style
        )
        if self.main_window:
            self.favorites_toggle_button.clicked.connect(self.main_window.toggle_favorites_panel)

        self.theme_button = _make_icon_button(
            tr("tooltip.toggle_theme", "Переключить тему"), self._tool_btn_style
        )

        self.titlebar_right_tool_buttons = (
            self.always_on_top_button,
            self.favorites_toggle_button,
            self.theme_button,
        )
        self.titlebar_tool_buttons = self.nav_tool_buttons + (
            self.always_on_top_button,
            self.favorites_toggle_button,
            self.theme_button,
        )
        self._right_tool_row = self._make_icon_row_widget(
            self, self.titlebar_right_tool_buttons, self.TITLEBAR_RIGHT_TOOL_ICON_GAP_PX
        )
        layout.addWidget(self._right_tool_row, 0, Qt.AlignVCenter)
        self._add_fixed_spacer(layout, self, self.TITLEBAR_RIGHT_TOOL_TO_WINDOW_CONTROLS_GAP_PX)

        self.minimize_button = _make_icon_button("", self._window_btn_style)
        self.minimize_button.clicked.connect(self.minimize_window)
        self.maximize_button = _make_icon_button("", self._window_btn_style)
        self.maximize_button.clicked.connect(self.toggle_maximize)
        self.close_button = _TitleBarCloseButton(self)
        self.close_button.setFixedSize(bar_h, bar_h)
        self.close_button.setIconSize(icon_sz)
        self.close_button.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        self.close_button.setCursor(Qt.ArrowCursor)
        self.close_button.setStyleSheet(self._close_btn_style)
        self.close_button.clicked.connect(self.close_window)
        self.titlebar_window_buttons = (
            self.minimize_button,
            self.maximize_button,
            self.close_button,
        )
        self._window_controls_row = self._make_icon_row_widget(
            self, self.titlebar_window_buttons, (0, 0)
        )
        layout.addWidget(self._window_controls_row, 0, Qt.AlignVCenter)

        self.update_icons()
        self._update_autosave_status_label_style()
        self._titlebar_status_autosave_disabled = False
        self._titlebar_status_saving = False

    def set_autosave_disabled_indicator(self, disabled: bool):
        """Показывает/скрывает текст в зоне drag titlebar при отключённой записи на диск."""
        self._titlebar_status_autosave_disabled = bool(disabled)
        self._refresh_titlebar_status_label()

    def set_saving_indicator(self, active: bool):
        """Индикатор «Сохранение…» в titlebar (ниже приоритетом, чем autosave_disabled)."""
        self._titlebar_status_saving = bool(active)
        self._refresh_titlebar_status_label()

    def _refresh_titlebar_status_label(self):
        label = getattr(self, "autosave_status_label", None)
        if label is None:
            return
        if getattr(self, "_titlebar_status_autosave_disabled", False):
            label.setText(
                tr("titlebar.autosave_disabled", "Автосохранение отключено")
            )
            label.show()
        elif getattr(self, "_titlebar_status_saving", False):
            label.setText(tr("titlebar.saving", "Сохранение…"))
            label.show()
        else:
            label.clear()
            label.hide()

    def _update_autosave_status_label_style(self, theme=None):
        label = getattr(self, "autosave_status_label", None)
        if label is None:
            return
        try:
            if theme is None:
                theme = ThemeManager.instance().theme()
            color = theme.get("titlebar_icons", "#87929E")
        except Exception:
            color = "#87929E"
        label.setStyleSheet(
            f"QLabel#titlebarAutosaveStatus {{ color: {color}; background: transparent; border: none; }}"
        )

    def _update_drag_region_bounds(self):
        """Правая граница зоны перетаскивания — правый край левого ряда навигационных иконок."""
        try:
            row = getattr(self, "_left_nav_row", None)
            if row is not None:
                self._drag_area_left_x = row.geometry().right()
                return
            last_nav = getattr(self, "nav_settings_button", None)
            if last_nav is not None:
                self._drag_area_left_x = last_nav.geometry().right()
                return
        except Exception:
            pass
        self._drag_area_left_x = 0

    def _is_drag_region(self, pos):
        """Пустая область titlebar между навигационными кнопками и избранным."""
        self._update_drag_region_bounds()
        try:
            right_row = getattr(self, "_right_tool_row", None)
            if right_row is not None:
                right = right_row.x()
            else:
                right = self.favorites_toggle_button.mapTo(self, QPoint(0, 0)).x()
        except Exception:
            return False
        return (
            self._drag_area_left_x <= pos.x() < right
            and 0 <= pos.y() < self.height()
        )

    def resizeEvent(self, event):
        self._update_drag_region_bounds()
        super().resizeEvent(event)
    
    def mousePressEvent(self, event):
        """Перетаскивание окна через QWindow.startSystemMove (Qt 5.15+)."""
        if event.button() == Qt.LeftButton and self.main_window:
            try:
                if self.main_window.isMaximized():
                    super().mousePressEvent(event)
                    return
            except Exception:
                pass
            if self._is_drag_region(event.pos()):
                if getattr(self.main_window, "frameless_start_system_move", None):
                    if self.main_window.frameless_start_system_move():
                        event.accept()
                        return
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event):
        """Двойной клик по заголовку: развернуть/восстановить (как в обычном окне)."""
        try:
            if event.button() == Qt.LeftButton and self.main_window:
                if self._is_drag_region(event.pos()):
                    self.toggle_maximize()
                    event.accept()
                    return
        except Exception:
            pass
        super().mouseDoubleClickEvent(event)
    
    def minimize_window(self):
        """Минимизация окна"""
        if self.main_window:
            self.main_window.showMinimized()
    
    def toggle_maximize(self):
        """Переключение между максимизацией и восстановлением"""
        if self.main_window:
            if self.main_window.isMaximized():
                self.main_window.showNormal()
            else:
                self.main_window.showMaximized()
    
    def close_window(self):
        """Закрытие окна"""
        if self.main_window:
            self.main_window.close()
    
    def update_icons(self):
        """Обновляет иконки панели заголовка"""
        if not self.main_window:
            return

        im = IconManager.instance()

        app_icon_px = int(self.TITLEBAR_APP_ICON_SIZE)
        app_icon = self.main_window.windowIcon()
        if app_icon.isNull():
            app_icon = QIcon(resource_path("resources/icons/JBPad_windowicon.ico"))
        self.app_icon_label.setPixmap(app_icon.pixmap(app_icon_px, app_icon_px))

        self.nav_new_file_button.setIcon(im.icon("file_plus"))
        self.nav_new_folder_button.setIcon(im.icon("folder_plus"))
        self.nav_open_notepad_button.setIcon(im.icon("open_notebook"))
        self.nav_new_notepad_button.setIcon(im.icon("add_notebook"))
        self.nav_file_management_button.setIcon(im.icon("file_management"))
        self.nav_find_button.setIcon(im.icon("find"))
        self.nav_settings_button.setIcon(im.icon("settings"))
        self.theme_button.setIcon(im.icon("theme_toggle"))
        self.favorites_toggle_button.setIcon(im.icon("favorites_toggle"))
        self.minimize_button.setIcon(im.icon("minimize"))
        
        # Обновляем иконку максимизации/восстановления в зависимости от состояния окна
        if self.main_window and self.main_window.isMaximized():
            self.maximize_button.setIcon(im.icon("restore"))
        else:
            self.maximize_button.setIcon(im.icon("maximize"))
        
        self.close_button.set_close_icons(im.icon("close_window"), im.icon("close_window_hover"))
        
        # Обновляем иконку кнопки добавления временного файла (если доступна)
        if self.main_window and hasattr(self.main_window, '_update_add_temp_file_button_icon'):
            self.main_window._update_add_temp_file_button_icon()
    
    def update_style(self, background_color, update_icons: bool = True):
        """Обновляет стиль панели заголовка"""
        # Убеждаемся, что атрибут WA_StyledBackground установлен для применения фона через StyleSheet
        if not self.testAttribute(Qt.WA_StyledBackground):
            self.setAttribute(Qt.WA_StyledBackground, True)
        
        # Сбрасываем палитру и autoFillBackground, чтобы избежать конфликтов с StyleSheet
        self.setAutoFillBackground(False)
        palette = self.style().standardPalette()
        self.setPalette(palette)
        
        # Используем селектор по имени объекта для более точного применения стилей
        # Если background_color содержит "palette", используем специальный синтаксис
        if "palette" in background_color:
            style_sheet = f"QWidget#CustomTitleBar {{ background: {background_color}; border: none; }}"
        else:
            style_sheet = f"QWidget#CustomTitleBar {{ background-color: {background_color}; border: none; }}"
        
        # Устанавливаем стиль (без processEvents: избегаем реентранса и нестабильного старта)
        self.setStyleSheet(style_sheet)
            
        # Обновляем иконки (можно отложить для ускорения первого кадра)
        if update_icons:
            self.update_icons()
        
        # Принудительно обновляем стили через unpolish/polish
        self.style().unpolish(self)
        self.style().polish(self)
        
        # Принудительно обновляем виджет (без processEvents)
        self.update()
        if update_icons:
            self.repaint()

        for btn in (
            *getattr(self, "titlebar_tool_buttons", ()),
            self.minimize_button,
            self.maximize_button,
            self.close_button,
        ):
            if btn:
                btn.update()
                if update_icons:
                    btn.repaint()
        self._update_autosave_status_label_style()

    def apply_theme_styles(self, theme):
        """Обновляет stylesheet-части title bar из theme registry (live theme switch)."""
        self.update_style(theme["titlebar_background"], update_icons=False)
        tool_hover = theme["titlebar_tool_button_hover_overlay"]
        window_hover = theme["titlebar_button_hover_overlay"]
        close_hover = theme["titlebar_close_button_hover_background"]
        _btn_base = (
            "QPushButton { border: none; background: transparent; padding: 0px; margin: 0px; }"
        )
        self._tool_btn_style = _btn_base + f"QPushButton:hover {{ background-color: {tool_hover}; }}"
        self._window_btn_style = _btn_base + f"QPushButton:hover {{ background-color: {window_hover}; }}"
        self._close_btn_style = _btn_base + f"QPushButton:hover {{ background-color: {close_hover}; }}"
        for btn in getattr(self, "titlebar_tool_buttons", ()):
            if btn:
                btn.setStyleSheet(self._tool_btn_style)
        for btn in (self.minimize_button, self.maximize_button):
            if btn:
                btn.setStyleSheet(self._window_btn_style)
        if self.close_button:
            self.close_button.setStyleSheet(self._close_btn_style)
        self._update_autosave_status_label_style(theme)


class TabCloseIndicatorMixin(object):
    """Кнопка закрытия вкладки: PM_TabCloseIndicator* + PE_IndicatorTabClose.

    Иконка — та же из ресурсов, что и у избранного; hover-подложка — из tabs theme.
    Это MIXIN для единственного application-стиля (см. AppFusionStyle), а НЕ
    самостоятельный QProxyStyle для QWidget.setStyle(): widget-level python-стиль
    даёт access violation при завершении процесса на Windows (пояснение — в AppFusionStyle).
    """

    def pixelMetric(self, metric, option=None, widget=None):
        if metric == QStyle.PM_TabCloseIndicatorWidth:
            return 16
        if metric == QStyle.PM_TabCloseIndicatorHeight:
            return 16
        return super().pixelMetric(metric, option, widget)

    def drawPrimitive(self, element, option, painter, widget=None):
        if element == QStyle.PE_IndicatorTabClose:
            painter.save()
            rect = option.rect
            is_hover = bool(option.state & QStyle.State_MouseOver)

            if is_hover:
                painter.setRenderHint(QPainter.Antialiasing)
                bg_rect = rect.adjusted(1, 1, -1, -1)
                painter.setPen(Qt.NoPen)
                painter.setBrush(ThemeManager.instance().qcolor("small_close_button_hover_overlay"))
                radius = 4
                painter.drawRoundedRect(bg_rect, radius, radius)

            close_icon = IconManager.instance().icon("close_tab")
            if not close_icon.isNull():
                close_icon.paint(painter, rect, Qt.AlignCenter)

            painter.restore()
            return

        super().drawPrimitive(element, option, painter, widget)


class FlatTreeSelectionMixin(object):
    """Подавляет полнострочный фон выделения QTreeWidget; узкая полоска — в CustomItemDelegate."""

    def drawPrimitive(self, element, option, painter, widget=None):
        if isinstance(widget, QTreeWidget) and (option.state & QStyle.State_Selected):
            # Fusion рисует фон выделения на branch/indent через drawPrimitive,
            # не только через PE_PanelItemViewItem.
            opt = QStyleOption(option)
            opt.state &= ~QStyle.State_Selected
            return super().drawPrimitive(element, opt, painter, widget)
        return super().drawPrimitive(element, option, painter, widget)

    def drawControl(self, element, option, painter, widget=None):
        if isinstance(widget, QTreeWidget) and (option.state & QStyle.State_Selected):
            if element == QStyle.CE_ItemViewItem:
                opt = QStyleOptionViewItem(option)
                opt.state &= ~QStyle.State_Selected
                return super().drawControl(element, opt, painter, widget)
        return super().drawControl(element, option, painter, widget)


class AppFusionStyle(TabCloseIndicatorMixin, FlatTreeSelectionMixin, QProxyStyle):
    """Единый application-стиль JBPad — все правки Qt-стиля живут только здесь.

    Содержит:
    • плоский disabled-текст в QMenu (без emboss SH_EtchDisabledText);
    • кнопку закрытия вкладок (TabCloseIndicatorMixin);
    • подавление полнострочного фона выделения в QTreeWidget (FlatTreeSelectionMixin).

    КРИТИЧНО (Windows), почему стиль нельзя ставить на виджеты:
    QStyle, созданный в Python и установленный через QWidget.setStyle(), НЕ передаёт владение
    Qt (документация QWidget::setStyle: ownership не передаётся), а PyQt уничтожает python-объект
    в произвольный момент — при сборке мусора или на teardown интерпретатора, — при этом виджет
    продолжает держать указатель на стиль. Итог: обращение к освобождённому объекту стиля и
    `Windows fatal exception: access violation` (<no Python frame>, c0000005 / BEX64) при закрытии
    приложения. QApplication.setStyle(), наоборот, передаёт владение C++ (QApplication), поэтому
    стиль уничтожается в предсказуемом месте и процесс завершается штатно.

    Воспроизведено на Qt 5.15.2 + PyQt 5.15.11 (Python 3.8.10) — Windows 7 SP1 x64 и Windows 10 x64:
    любой widget-level QProxyStyle (даже без python-оверрайдов и даже если держать на него
    python-ссылку) даёт exit code 0xC0000005, app-level — чистый выход с кодом 0.
    Поэтому все оверрайды обязаны находиться именно здесь.
    """

    def styleHint(self, hint, option=None, widget=None, returnData=None):
        if hint == QStyle.SH_EtchDisabledText:
            return 0
        return super().styleHint(hint, option, widget, returnData)


# Ширина вертикальной полосы прокрутки (дерево и редактор), px.
SCROLLBAR_WIDTH_PX = 18

_SCROLLBAR_ARROW_HANDLE_SUFFIX = {
    "disabled": "handle_background",
    "active": "handle_hover_background",
    "pressed": "handle_pressed_background",
}


def _scrollbar_context_prefix(context):
    """Префикс ключей темы: tree_scrollbar_ / editor_scrollbar_."""
    return "tree_scrollbar_" if str(context) == "tree" else "editor_scrollbar_"


def _scrollbar_theme_color_keys(context):
    """Имена ключей темы для track/handle/hover/pressed по контексту дерева или редактора."""
    prefix = _scrollbar_context_prefix(context)
    return {
        "track": f"{prefix}track_background",
        "handle": f"{prefix}handle_background",
        "hover": f"{prefix}handle_hover_background",
        "pressed": f"{prefix}handle_pressed_background",
    }


class ScrollBarStyle:
    """Отрисовка треугольных стрелок вертикальной полосы прокрутки (track/handle — QSS на QScrollBar)."""

    @staticmethod
    def _arrow_color(state, scrollbar=None):
        suffix = _SCROLLBAR_ARROW_HANDLE_SUFFIX.get(state, "handle_background")
        context = getattr(scrollbar, "_scrollbar_context", "editor") if scrollbar is not None else "editor"
        key = f"{_scrollbar_context_prefix(context)}{suffix}"
        try:
            return ThemeManager.instance().qcolor(key)
        except Exception:
            return theme_qcolor(key)

    @staticmethod
    def arrow_state(scrollbar, which):
        """which: 'up' | 'down' → 'disabled' | 'active' | 'pressed'."""
        try:
            pos = int(scrollbar.value())
            mn = int(scrollbar.minimum())
            mx = int(scrollbar.maximum())
        except Exception:
            return "disabled"
        clickable = (which == "up" and pos > mn) or (which == "down" and pos < mx)
        if not clickable:
            return "disabled"
        if getattr(scrollbar, "_arrow_pressed", None) == which:
            return "pressed"
        return "active"

    @staticmethod
    def _draw_v_arrow(painter, rect, pointing_up, *, state="disabled", scrollbar=None):
        if not rect.isValid() or int(rect.width()) <= 0 or int(rect.height()) <= 0:
            return
        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, False)
        color = QColor(ScrollBarStyle._arrow_color(state, scrollbar))
        painter.setPen(Qt.NoPen)
        painter.setBrush(color)
        cx = int(rect.x() + rect.width() / 2)
        cy = int(rect.y() + rect.height() / 2)
        aw = max(4, min(int(rect.width()), int(rect.height())) // 3)
        ah = max(3, aw - 1)
        if pointing_up:
            tri = QPolygon([
                QPoint(cx, cy - ah),
                QPoint(cx - aw, cy + ah),
                QPoint(cx + aw, cy + ah),
            ])
        else:
            tri = QPolygon([
                QPoint(cx - aw, cy - ah),
                QPoint(cx + aw, cy - ah),
                QPoint(cx, cy + ah),
            ])
        painter.drawPolygon(tri)
        painter.restore()

    @staticmethod
    def _vertical_button_rects(scrollbar):
        """Области sub-line / add-line без subControlRect (в paintEvent он небезоперен на Windows)."""
        r = scrollbar.rect()
        btn = int(SCROLLBAR_WIDTH_PX)
        if r.width() <= 0 or r.height() <= btn:
            return None, None
        sub_rect = QRect(r.left(), r.top(), r.width(), btn)
        add_rect = QRect(r.left(), r.bottom() - btn + 1, r.width(), btn)
        return sub_rect, add_rect

    @staticmethod
    def paint_vertical_arrows(painter, scrollbar):
        """Стрелки поверх QSS-полосы (sub-line / add-line)."""
        if scrollbar is None or scrollbar.orientation() != Qt.Vertical:
            return
        sub_rect, add_rect = ScrollBarStyle._vertical_button_rects(scrollbar)
        if sub_rect is not None and sub_rect.isValid():
            ScrollBarStyle._draw_v_arrow(
                painter, sub_rect, True,
                state=ScrollBarStyle.arrow_state(scrollbar, "up"),
                scrollbar=scrollbar,
            )
        if add_rect is not None and add_rect.isValid():
            ScrollBarStyle._draw_v_arrow(
                painter, add_rect, False,
                state=ScrollBarStyle.arrow_state(scrollbar, "down"),
                scrollbar=scrollbar,
            )


class ThemedVerticalScrollBar(QScrollBar):
    """QScrollBar с QSS-темой и треугольными стрелками через ScrollBarStyle."""

    def __init__(self, parent=None):
        super().__init__(Qt.Vertical, parent)
        self._arrow_pressed = None  # None | 'up' | 'down'
        try:
            self.valueChanged.connect(self._on_arrow_value_changed)
        except Exception:
            pass

    def _button_at(self, pos):
        sub_rect, add_rect = ScrollBarStyle._vertical_button_rects(self)
        if sub_rect is not None and sub_rect.contains(pos):
            return "up"
        if add_rect is not None and add_rect.contains(pos):
            return "down"
        return None

    def _on_arrow_value_changed(self, value):
        changed = False
        if value <= self.minimum() and self._arrow_pressed == "up":
            self._arrow_pressed = None
            changed = True
        if value >= self.maximum() and self._arrow_pressed == "down":
            self._arrow_pressed = None
            changed = True
        if changed:
            self.update()

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            btn = self._button_at(event.pos())
            if btn == "up" and self.value() > self.minimum():
                self._arrow_pressed = "up"
                self.update()
            elif btn == "down" and self.value() < self.maximum():
                self._arrow_pressed = "down"
                self.update()
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event):
        super().mouseReleaseEvent(event)
        if self._arrow_pressed is not None:
            self._arrow_pressed = None
            self.update()

    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QPainter()
        if not painter.begin(self):
            return
        try:
            ScrollBarStyle.paint_vertical_arrows(painter, self)
        finally:
            painter.end()


def setup_themed_vertical_scrollbar(area, theme=None, *, context="editor"):
    """QSS на сам QScrollBar + ThemedVerticalScrollBar (QSS родителя не перехватывает стрелки)."""
    if area is None:
        return None
    if theme is None:
        try:
            theme = ThemeManager.instance().theme()
        except Exception:
            theme = LIGHT_THEME
    sb = area.verticalScrollBar()
    if not isinstance(sb, ThemedVerticalScrollBar):
        sb = ThemedVerticalScrollBar(area)
        area.setVerticalScrollBar(sb)
    try:
        sb._scrollbar_context = "tree" if str(context) == "tree" else "editor"
        sb.setStyleSheet(build_scrollbar_widget_stylesheet(theme, context=sb._scrollbar_context))
        sb.setCursor(Qt.ArrowCursor)
    except Exception:
        pass
    return sb


def _tree_item_icon_width(widget, style=None, option=None):
    """Ширина иконки элемента дерева (iconSize или PM_SmallIconSize стиля)."""
    if widget is None:
        return 16
    try:
        w = int(widget.iconSize().width())
    except Exception:
        w = 0
    if w <= 0:
        if style is None:
            style = widget.style()
        try:
            w = int(style.pixelMetric(QStyle.PM_SmallIconSize, option, widget))
        except Exception:
            w = 16
    return max(1, int(w))


class SmartTreeView(QTreeView):
    """QTreeView с tooltip только для визуально обрезанного текста."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMouseTracking(True)
        # Полностью исключаем из глобальной политики обычных tooltip'ов в Settings.
        self._jbpad_skip_global_tooltip_policy = True
        self._last_tooltip_index = None
        self._last_tooltip_text = None
        _truncation_tooltip_clear_shown(self)

    def _hide_truncation_tooltip(self):
        QToolTip.hideText()
        self._last_tooltip_index = None
        self._last_tooltip_text = None
        _truncation_tooltip_clear_shown(self)

    def _show_truncation_tooltip(self, index, text, global_pos):
        rect = self.visualRect(index)
        if not rect.isValid():
            self._hide_truncation_tooltip()
            return
        show_key = (_truncation_tooltip_index_key(index), text)
        if not _truncation_tooltip_should_show(self, show_key):
            return
        QToolTip.showText(global_pos, text, self, rect, 300000)
        self._last_tooltip_index = index
        self._last_tooltip_text = text
        _truncation_tooltip_mark_shown(self, show_key)

    def mouseMoveEvent(self, event):
        super().mouseMoveEvent(event)
        if event.buttons() & Qt.LeftButton:
            self._hide_truncation_tooltip()
            return
        index = self.indexAt(event.pos())
        if not index.isValid():
            self._hide_truncation_tooltip()
            return

        text = index.data(Qt.DisplayRole)
        if text is None:
            self._hide_truncation_tooltip()
            return

        text = str(text)
        rect = self.visualRect(index)
        fm = self.fontMetrics()
        available_width = max(0, int(rect.width()))
        if rect.isValid() and text and _fm_is_elided(fm, text, available_width):
            self._show_truncation_tooltip(index, text, event.globalPos())
        else:
            self._hide_truncation_tooltip()

    def leaveEvent(self, event):
        self._hide_truncation_tooltip()
        super().leaveEvent(event)


class SmartListView(QListView):
    """QListView с tooltip только для визуально обрезанного текста."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMouseTracking(True)
        # Полностью исключаем из глобальной политики обычных tooltip'ов в Settings.
        self._jbpad_skip_global_tooltip_policy = True
        self._last_tooltip_index = None
        self._last_tooltip_text = None
        _truncation_tooltip_clear_shown(self)

    def _hide_truncation_tooltip(self):
        QToolTip.hideText()
        self._last_tooltip_index = None
        self._last_tooltip_text = None
        _truncation_tooltip_clear_shown(self)

    def _display_text_for_tooltip(self, raw_text):
        """Для избранного показываем только имя файла без расширения."""
        text = "" if raw_text is None else str(raw_text)
        file_name = os.path.basename(text)
        stem, _ext = os.path.splitext(file_name)
        return stem if stem else text

    def _text_available_width(self, rect):
        """Оценка реальной ширины зоны текста с учётом отступов делегата."""
        width = int(rect.width())
        try:
            delegate = self.itemDelegate()
            left = int(getattr(delegate, "left_padding", 0))
            right = int(getattr(delegate, "right_padding", 0))
            close_size = int(getattr(delegate, "close_size", 0))
            close_margin = int(getattr(delegate, "close_margin", 0))
            width -= (left + right + close_size + close_margin)
        except Exception:
            pass
        return max(0, width)

    def _show_truncation_tooltip(self, index, text, global_pos):
        rect = self.visualRect(index)
        if not rect.isValid():
            self._hide_truncation_tooltip()
            return
        show_key = (_truncation_tooltip_index_key(index), text)
        if not _truncation_tooltip_should_show(self, show_key):
            return
        QToolTip.showText(global_pos, text, self, rect, 300000)
        self._last_tooltip_index = index
        self._last_tooltip_text = text
        _truncation_tooltip_mark_shown(self, show_key)

    def mouseMoveEvent(self, event):
        super().mouseMoveEvent(event)
        if event.buttons() & Qt.LeftButton:
            self._hide_truncation_tooltip()
            return
        index = self.indexAt(event.pos())
        if not index.isValid():
            self._hide_truncation_tooltip()
            return

        raw_text = index.data(Qt.DisplayRole)
        if raw_text is None:
            self._hide_truncation_tooltip()
            return

        text = self._display_text_for_tooltip(raw_text)
        rect = self.visualRect(index)
        fm = self.fontMetrics()
        available_width = self._text_available_width(rect)
        if rect.isValid() and text and _fm_is_elided(fm, text, available_width):
            self._show_truncation_tooltip(index, text, event.globalPos())
        else:
            self._hide_truncation_tooltip()

    def leaveEvent(self, event):
        self._hide_truncation_tooltip()
        super().leaveEvent(event)


class SmartTabBar(QTabBar):
    """QTabBar с tooltip только для визуально обрезанных заголовков вкладок."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMouseTracking(True)
        # Полностью исключаем из глобальной политики обычных tooltip'ов в Settings.
        self._jbpad_skip_global_tooltip_policy = True
        self._last_hover_tab_index = -1
        self._tooltip_keepalive_enabled = str(os.environ.get("JBPAD_TOOLTIP_KEEPALIVE", "1")).lower() not in ("0", "false", "no")
        self._tooltip_keepalive_tab_index = -1
        self._tooltip_keepalive_timer = QTimer(self)
        self._tooltip_keepalive_timer.setInterval(350)
        self._tooltip_keepalive_timer.timeout.connect(self._on_tooltip_keepalive_tick)
        _truncation_tooltip_clear_shown(self)

    def _updateAllTabTooltips(self):
        for i in range(self.count()):
            self.updateTabTooltip(i)

    def updateTabTooltip(self, index):
        """Отключает встроенные tooltip'ы QTabBar — показ только через QToolTip.showText()."""
        if index < 0 or index >= self.count():
            return
        self.setTabToolTip(index, "")

    def tabInserted(self, index):
        super().tabInserted(index)
        self._updateAllTabTooltips()

    def tabRemoved(self, index):
        super().tabRemoved(index)
        self._updateAllTabTooltips()

    def setTabText(self, index, text):
        super().setTabText(index, text)
        self.updateTabTooltip(index)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._updateAllTabTooltips()

    def tabLayoutChange(self):
        super().tabLayoutChange()
        self._updateAllTabTooltips()

    def mouseMoveEvent(self, event):
        hovered_index = self.tabAt(event.pos())
        self._last_hover_tab_index = hovered_index
        super().mouseMoveEvent(event)
        self._show_hover_tab_tooltip(hovered_index, event.globalPos())

    def _hide_hover_tab_tooltip(self):
        self._tooltip_keepalive_tab_index = -1
        self._tooltip_keepalive_timer.stop()
        QToolTip.hideText()
        _truncation_tooltip_clear_shown(self)

    def _show_hover_tab_tooltip(self, tab_index, global_pos):
        if tab_index < 0 or tab_index >= self.count():
            self._hide_hover_tab_tooltip()
            return False

        text = self.tabText(tab_index) or ""
        fm = self.fontMetrics()
        rect = self.tabRect(tab_index)
        tab_width = int(rect.width()) if rect.isValid() else -1
        available_width = tab_width
        # Учитываем реальную зону текста: кнопка закрытия + служебные отступы.
        try:
            right_btn = self.tabButton(tab_index, QTabBar.RightSide)
            if right_btn is not None and right_btn.isVisible():
                available_width -= int(right_btn.sizeHint().width())
        except Exception:
            pass
        try:
            left_btn = self.tabButton(tab_index, QTabBar.LeftSide)
            if left_btn is not None and left_btn.isVisible():
                available_width -= int(left_btn.sizeHint().width())
        except Exception:
            pass
        try:
            available_width -= int(EDITOR_TAB_LEFT_PAD_PX)
        except Exception:
            pass
        # Небольшой резерв под внутренние отступы стиля/иконки.
        available_width = max(0, int(available_width) - 10)
        truncated = bool(text and rect.isValid() and _fm_is_elided(fm, text, available_width))
        if truncated:
            show_key = (int(tab_index), text)
            if not _truncation_tooltip_should_show(self, show_key):
                if self._tooltip_keepalive_enabled and not self._tooltip_keepalive_timer.isActive():
                    self._tooltip_keepalive_tab_index = tab_index
                    self._tooltip_keepalive_timer.start()
                return True
            # Мгновенный показ без ожидания системного delay tooltip'ов.
            QToolTip.showText(global_pos, text, self, rect, 300000)
            _truncation_tooltip_mark_shown(self, show_key)
            if self._tooltip_keepalive_enabled:
                self._tooltip_keepalive_tab_index = tab_index
                if not self._tooltip_keepalive_timer.isActive():
                    self._tooltip_keepalive_timer.start()
            return True

        self._hide_hover_tab_tooltip()
        return False

    def _on_tooltip_keepalive_tick(self):
        if not self._tooltip_keepalive_enabled:
            self._tooltip_keepalive_timer.stop()
            return
        if not _truncation_tooltip_keepalive_should_restore(self):
            return
        pos = self.mapFromGlobal(QCursor.pos())
        tab_index = self.tabAt(pos)
        if tab_index < 0:
            self._hide_hover_tab_tooltip()
            return
        self._show_hover_tab_tooltip(tab_index, QCursor.pos())

    def leaveEvent(self, event):
        self._hide_hover_tab_tooltip()
        self._last_hover_tab_index = -1
        super().leaveEvent(event)


class CustomTabBar(SmartTabBar):
    """
    TabBar с:
    • кнопкой закрытия — иконка из resources/icons/close_tab.png (как у избранного)
    • возможностью визуально прижать кнопку к правому краю вкладки
      через расширение ширины вкладки
    """

    def __init__(self, parent=None):
        super().__init__(parent)

        self.setTabsClosable(True)
        self.setMouseTracking(True)  # нужно для hover-состояния кнопки

        # Сколько "пустого" места добавить справа ко ВСЕЙ вкладке.
        # Чем больше число — тем ближе кнопка к правому краю.
        self.extra_right_space = 30

        # ВАЖНО: widget-level стиль здесь НЕ ставится (раньше было self.setStyle(TabCloseStyle(...))).
        # Такой стиль даёт access violation при закрытии приложения на Windows — пояснение
        # в комментарии к AppFusionStyle. Иконка и размер кнопки закрытия вкладки приходят
        # из application-стиля AppFusionStyle (pixelMetric PM_TabCloseIndicator* +
        # drawPrimitive PE_IndicatorTabClose), поэтому внешний вид и поведение вкладок те же.

        # КРИТИЧНО: убираем системную подсказку "Close Tab" на кнопке закрытия вкладки.
        # Это должен быть жёсткий запрет во всех режимах (включая включённые общие подсказки),
        # при этом "умные подсказки" на обрезанный текст вкладки остаются (они реализованы через QToolTip.showText()).
        try:
            QTimer.singleShot(0, self._suppress_close_tab_button_tooltips)
        except Exception:
            pass

    def _suppress_close_tab_button_tooltips(self):
        """Полностью запрещает tooltip на кнопках закрытия вкладок (Qt иногда ставит "Close Tab")."""
        try:
            n = int(self.count())
        except Exception:
            n = 0
        for i in range(max(0, n)):
            for side in (QTabBar.LeftSide, QTabBar.RightSide):
                try:
                    btn = self.tabButton(i, side)
                except Exception:
                    btn = None
                if btn is None:
                    continue
                # У кнопки закрытия это обычно QToolButton, но нам достаточно QWidget.setToolTip("")
                try:
                    if hasattr(btn, "setToolTip"):
                        btn.setToolTip("")
                except Exception:
                    pass
                # Не даём глобальной политике подсказок восстановить "Close Tab" из кеша.
                try:
                    setattr(btn, "_jbpad_tooltip_original", "")
                except Exception:
                    pass

    # Держим запрет устойчивым к пересозданию кнопок/ре-лейауту внутри Qt.
    def tabInserted(self, index):
        super().tabInserted(index)
        try:
            self._suppress_close_tab_button_tooltips()
        except Exception:
            pass
        try:
            QTimer.singleShot(0, self._suppress_close_tab_button_tooltips)
        except Exception:
            pass

    def tabRemoved(self, index):
        super().tabRemoved(index)
        try:
            self._suppress_close_tab_button_tooltips()
        except Exception:
            pass

    def tabLayoutChange(self):
        super().tabLayoutChange()
        try:
            self._suppress_close_tab_button_tooltips()
        except Exception:
            pass

    def tabSizeHint(self, index):
        size = super().tabSizeHint(index)

        # Чуть выше вкладка
        size.setHeight(size.height() + 6)

        # Главное: расширяем вкладку вправо
        size.setWidth(size.width() + self.extra_right_space)

        return size

    def _click_on_tab_close_button(self, tab_index, pos):
        """True, если pos попадает в кнопку закрытия (×) вкладки."""
        try:
            if tab_index < 0:
                return False
            for side in (QTabBar.LeftSide, QTabBar.RightSide):
                try:
                    btn = self.tabButton(tab_index, side)
                except Exception:
                    btn = None
                if btn is None or not btn.isVisible():
                    continue
                if btn.geometry().contains(pos):
                    return True
        except Exception:
            pass
        return False

    def mouseDoubleClickEvent(self, event):
        """Двойной клик по вкладке переключает отметку «* » (не по кнопке ×)."""
        try:
            if event.button() == Qt.LeftButton:
                tab_index = self.tabAt(event.pos())
                if tab_index >= 0:
                    if self._click_on_tab_close_button(tab_index, event.pos()):
                        event.accept()
                        return
                    main_window = getattr(self, "_jbpad_main_window", None)
                    if main_window is not None and hasattr(main_window, "toggle_tab_mark_at_index"):
                        try:
                            main_window.toggle_tab_mark_at_index(tab_index)
                            event.accept()
                            return
                        except Exception:
                            pass
        except Exception:
            pass

        super().mouseDoubleClickEvent(event)


class _FixedCornerContainer(QWidget):
    """Контейнер для cornerWidget с фиксированным sizeHint()."""

    def __init__(self, fixed_size: QSize, parent=None):
        super().__init__(parent)
        self._fixed_size = QSize(fixed_size)
        self.setFixedSize(self._fixed_size)
        self.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)

    def sizeHint(self):
        return QSize(self._fixed_size)

    def minimumSizeHint(self):
        return QSize(self._fixed_size)

    def setFixedSizeValue(self, w, h):
        """Обновляет фиксированный размер и sizeHint (для подгонки под фактическую высоту tab bar)."""
        self._fixed_size = QSize(w, h)
        self.setFixedSize(self._fixed_size)

    def _align_y_to_tab_bar_row(self):
        """Fusion/QTabWidget ставит cornerWidget на y=-1; выравниваем по tabBar.y()."""
        tw = self.parent()
        if not isinstance(tw, QTabWidget):
            return
        try:
            ty = int(tw.tabBar().geometry().y())
        except Exception:
            return
        if int(self.y()) != ty:
            self.move(int(self.x()), ty)

    def moveEvent(self, event):
        super().moveEvent(event)
        self._align_y_to_tab_bar_row()

    def showEvent(self, event):
        super().showEvent(event)
        self._align_y_to_tab_bar_row()


def tab_row_tool_button_content_height(host_height_px, tab_widget=None):
    """Высота QToolButton в corner: нижний 1px строки — для линии-разделителя."""
    h = max(1, int(host_height_px))
    if tab_widget is not None and str(tab_widget.property("paneTopLine") or "") == "1":
        return max(1, h - 1)
    return h


class _TabBarBottomLine(QWidget):
    """1px линия на всю ширину строки вкладок (родитель — _tab_container, поверх QTabWidget)."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setAttribute(Qt.WA_StyledBackground, True)
        self.setAutoFillBackground(True)
        self.setFixedHeight(1)
        self._line_color = QColor(LIGHT_THEME["separator"])

    def apply_theme(self):
        try:
            c = ThemeManager.instance().color("separator")
        except Exception:
            c = LIGHT_THEME["separator"]
        self._line_color = QColor(c)
        self.setStyleSheet(f"background-color: {c}; border: none; margin: 0; padding: 0;")
        self.update()

    def paintEvent(self, event):
        p = QPainter(self)
        try:
            p.fillRect(self.rect(), self._line_color)
        except Exception:
            super().paintEvent(event)
        finally:
            p.end()

    def showEvent(self, event):
        super().showEvent(event)
        self.raise_()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.raise_()


def editor_tab_bar_row_height_px(tab_bar):
    """Фактическая высота строки QTabBar (px) для corner-кнопок."""
    if tab_bar is None:
        return 24
    try:
        h = int(tab_bar.height())
        if h > 0:
            return h
    except Exception:
        pass
    try:
        if tab_bar.count() > 0:
            return int(tab_bar.tabRect(0).height())
    except Exception:
        pass
    try:
        return max(24, int(tab_bar.sizeHint().height()))
    except Exception:
        return 24


class _TabBarCornerButtonHost(_FixedCornerContainer):
    """Правый cornerWidget: прозрачный host (как левый), фон только на QToolButton."""

    def __init__(self, tool_button, fixed_size: QSize, parent=None):
        super().__init__(fixed_size, parent)
        self._tool_button = tool_button
        tool_button.setParent(self)
        tool_button.setAutoRaise(False)
        tool_button.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Ignored)

    def _sync_tool_button_geometry(self):
        btn = self._tool_button
        if btn is not None:
            tw = self.parent()
            btn_h = tab_row_tool_button_content_height(self.height(), tw if isinstance(tw, QTabWidget) else None)
            btn.setGeometry(0, 0, self.width(), btn_h)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._sync_tool_button_geometry()


