THEME_EDITABLE_KEYS = {
    key: tr(i18n_key, default)
    for key, (i18n_key, default) in _THEME_EDITABLE_KEY_I18N.items()
}

# Зависимые ключи: target <- source (редактируется только source в UI).
_THEME_MIRROR_KEYS = {
    "palette_mid": "separator",
    "palette_highlight_inactive": "palette_highlight",
    "palette_highlighted_text_inactive": "palette_highlighted_text",
}

THEME_REGISTRY = {
    "light": LIGHT_THEME,
}


def validate_theme_registry(registry):
    """Проверяет, что все темы в registry содержат одинаковый набор semantic keys."""
    if not registry:
        raise ValueError("Theme registry validation failed: registry is empty")
    names = list(registry.keys())
    ref_name = names[0]
    ref_keys = frozenset(registry[ref_name].keys())
    errors = []
    for name in names[1:]:
        keys = frozenset(registry[name].keys())
        missing = sorted(ref_keys - keys)
        extra = sorted(keys - ref_keys)
        if missing:
            errors.append(
                f"  theme '{name}': missing keys {missing} (reference theme: '{ref_name}')"
            )
        if extra:
            errors.append(
                f"  theme '{name}': extra keys {extra} (reference theme: '{ref_name}')"
            )
    if errors:
        raise ValueError(
            "Theme registry validation failed: theme key sets are out of sync.\n"
            + "\n".join(errors)
        )


validate_theme_registry(THEME_REGISTRY)


def validate_theme_editable_keys():
    """Проверяет, что все редактируемые ключи присутствуют во встроенной теме."""
    for key in THEME_EDITABLE_KEYS:
        if key not in LIGHT_THEME:
            print(f"Warning: editable theme key '{key}' is missing from LIGHT_THEME")


validate_theme_editable_keys()


def resolve_theme_file_path(filename):
    """Путь к файлу темы в Data/theme или None."""
    filename = os.path.basename(str(filename or "").strip())
    if not filename:
        return None
    if not filename.lower().endswith(".json"):
        filename = f"{filename}.json"
    path = data_themes_dir() / filename
    if path.is_file():
        return str(path)
    # Case-insensitive fallback (для case-sensitive ФС); на промахе — один scandir().
    matched = _resolve_dir_entry_case_insensitive(data_themes_dir(), filename)
    if matched:
        alt = data_themes_dir() / matched
        if alt.is_file():
            return str(alt)
    return None


def iter_custom_theme_filenames():
    """Имена *.json из Data/theme (без создания каталога)."""
    themes_dir = data_themes_dir()
    if not themes_dir.is_dir():
        return ()
    names = []
    try:
        for entry in os.listdir(str(themes_dir)):
            if not entry.lower().endswith(".json"):
                continue
            path = themes_dir / entry
            if path.is_file() and jbp_is_valid(str(path), JBP_KIND_THEME):
                names.append(entry)
    except Exception:
        pass
    return tuple(sorted(names))


def _theme_file_stem(filename):
    """Имя файла темы без расширения .json."""
    return os.path.splitext(os.path.basename(str(filename or "")))[0]


def _is_reserved_custom_theme_filename(filename):
    """Default.json зарезервировано под встроенную тему (отображается как Default)."""
    return _theme_file_stem(filename).lower() == "default"


def build_custom_theme_combo_entries():
    """Список (подпись, data) для кастомных тем в combobox (без встроенной Default)."""
    filenames = [
        f for f in iter_custom_theme_filenames()
        if not _is_reserved_custom_theme_filename(f)
    ]
    stem_counts = {}
    for filename in filenames:
        key = _theme_file_stem(filename).lower()
        stem_counts[key] = stem_counts.get(key, 0) + 1
    entries = []
    for filename in filenames:
        stem = _theme_file_stem(filename)
        if stem_counts.get(stem.lower(), 0) > 1:
            label = f"{stem} ({filename})"
        else:
            label = stem
        entries.append((label, filename))
    return entries


def populate_theme_combo(combo, *, include_default=False, select_data=None):
    """Заполняет QComboBox темами; select_data — 'light' или имя файла *.json."""
    combo.blockSignals(True)
    combo.clear()
    if include_default:
        combo.addItem("Default", "light")
    for label, data in build_custom_theme_combo_entries():
        combo.addItem(label, data)

    resolved = str(select_data or "light").strip() or "light"
    if resolved != "light":
        resolved = _legacy_custom_theme_filename(resolved) or resolved

    selected_index = 0 if include_default else (0 if combo.count() > 0 else -1)
    found = False
    for index in range(combo.count()):
        if combo.itemData(index) == resolved:
            selected_index = index
            found = True
            break
    if not found and include_default:
        selected_index = 0

    combo.setCurrentIndex(selected_index)
    combo.blockSignals(False)


def theme_color_from_registry(theme, key):
    """Semantic-цвет из theme registry (#hex или rgba(...))."""
    return theme[key]


def _qcolor_from_theme_value(value):
    if isinstance(value, str) and value.lower().startswith("rgba("):
        inner = value[value.index("(") + 1 : value.rindex(")")]
        parts = [p.strip() for p in inner.split(",")]
        if len(parts) == 4:
            r, g, b = (int(parts[i]) for i in range(3))
            alpha = max(0, min(255, int(round(float(parts[3]) * 255))))
            return QColor(r, g, b, alpha)
    return QColor(value)


def _color_for_luminance(color):
    """Непрозрачный RGB для расчёта яркости (полупрозрачный — смешение с белым)."""
    if not color.isValid():
        return QColor(255, 255, 255)
    if color.alpha() >= 255:
        return QColor(color.red(), color.green(), color.blue())
    a = color.alphaF()
    return QColor(
        int(round(color.red() * a + 255 * (1.0 - a))),
        int(round(color.green() * a + 255 * (1.0 - a))),
        int(round(color.blue() * a + 255 * (1.0 - a))),
    )


def _relative_luminance(color):
    """Относительная яркость sRGB (WCAG 2.x), 0..1."""
    c = _color_for_luminance(color)

    def _linear(channel):
        x = channel / 255.0
        return x / 12.92 if x <= 0.03928 else ((x + 0.055) / 1.055) ** 2.4

    return 0.2126 * _linear(c.red()) + 0.7152 * _linear(c.green()) + 0.0722 * _linear(c.blue())


def _contrast_icon_color_for_background(background):
    """Чёрная иконка на светлом фоне, белая на тёмном."""
    if _relative_luminance(background) > 0.179:
        return QColor(0, 0, 0)
    return QColor(255, 255, 255)


_AUTO_ICON_TINT_PREFIX = "auto:"


def _resolve_icon_tint_color(theme, color_key):
    """theme color key, None или auto:<фон> — контрастный ч/б по яркости фона."""
    if color_key is None:
        return None
    if not isinstance(theme, dict):
        return None
    if color_key.startswith(_AUTO_ICON_TINT_PREFIX):
        bg_key = color_key[len(_AUTO_ICON_TINT_PREFIX):]
        bg_value = theme.get(bg_key)
        if bg_value is None:
            return QColor(0, 0, 0)
        return _contrast_icon_color_for_background(_qcolor_from_theme_value(bg_value))
    value = theme.get(color_key)
    if value is None:
        return None
    return _qcolor_from_theme_value(value)


def _is_valid_theme_color(value):
    """Проверяет, что значение — корректный цвет темы (#hex или rgba(...))."""
    if not isinstance(value, str):
        return False
    value = value.strip()
    if not value:
        return False
    return _qcolor_from_theme_value(value).isValid()


def _sync_mirrored_theme_keys(theme):
    """Копирует значения source-ключей в привязанные target-ключи (in-place)."""
    if not isinstance(theme, dict):
        return theme
    for target_key, source_key in _THEME_MIRROR_KEYS.items():
        if source_key in theme and _is_valid_theme_color(theme[source_key]):
            theme[target_key] = str(theme[source_key]).strip()
    return theme


_SCROLLBAR_LEGACY_KEY_MIGRATION = (
    ("scrollbar_track_background", "tree_scrollbar_track_background", "editor_scrollbar_track_background"),
    ("scrollbar_handle_background", "tree_scrollbar_handle_background", "editor_scrollbar_handle_background"),
    ("scrollbar_handle_hover_background", "tree_scrollbar_handle_hover_background", "editor_scrollbar_handle_hover_background"),
    ("scrollbar_handle_pressed_background", "tree_scrollbar_handle_pressed_background", "editor_scrollbar_handle_pressed_background"),
)


def _apply_legacy_scrollbar_key_migration(overrides):
    """Копирует устаревшие scrollbar_* в tree_/editor_ при отсутствии новых ключей."""
    if not isinstance(overrides, dict):
        return overrides
    merged = dict(overrides)
    for old_key, tree_key, editor_key in _SCROLLBAR_LEGACY_KEY_MIGRATION:
        if old_key not in merged:
            continue
        val = merged[old_key]
        if not _is_valid_theme_color(val):
            continue
        val = str(val).strip()
        merged.setdefault(tree_key, val)
        merged.setdefault(editor_key, val)
    if "dialog_border" not in merged and "window_border" in merged:
        val = merged["window_border"]
        if _is_valid_theme_color(val):
            merged["dialog_border"] = str(val).strip()
    return merged


def _merge_custom_theme(overrides):
    """Собирает полную тему: LIGHT_THEME + переопределения из пользовательского json."""
    result = dict(LIGHT_THEME)
    if not isinstance(overrides, dict):
        return _sync_mirrored_theme_keys(result)
    overrides = _apply_legacy_scrollbar_key_migration(overrides)
    for key, value in overrides.items():
        if key not in THEME_KEYS:
            continue
        if _is_valid_theme_color(value):
            result[key] = value.strip()
    return _sync_mirrored_theme_keys(result)


def _load_custom_theme_overrides_from_file(path):
    """Читает json пользовательской темы; при ошибке возвращает пустой dict."""
    data = jbp_load_json(path, JBP_KIND_THEME)
    if isinstance(data, dict):
        return data
    return {}


def _serialize_theme_dict_for_json(theme_dict):
    """Оставляет только известные ключи темы с корректными цветами."""
    output = {}
    if not isinstance(theme_dict, dict):
        return output
    for key, value in theme_dict.items():
        if key in THEME_KEYS and _is_valid_theme_color(value):
            output[key] = str(value).strip()
    return output


def _set_palette_role(palette, theme, key, role, *, disabled_key=None, inactive_key=None):
    color = _qcolor_from_theme_value(theme[key])
    palette.setColor(QPalette.Active, role, color)
    if inactive_key and inactive_key in theme:
        inactive_color = _qcolor_from_theme_value(theme[inactive_key])
    else:
        inactive_color = color
    palette.setColor(QPalette.Inactive, role, inactive_color)
    if disabled_key and disabled_key in theme:
        disabled_color = _qcolor_from_theme_value(theme[disabled_key])
    else:
        disabled_color = color
    palette.setColor(QPalette.Disabled, role, disabled_color)


def build_palette(theme):
    """Создаёт QPalette из semantic-цветов theme registry (не из standardPalette)."""
    palette = QPalette()
    _set_palette_role(palette, theme, "palette_window", QPalette.Window)
    _set_palette_role(palette, theme, "palette_window_text", QPalette.WindowText, disabled_key="palette_disabled_text")
    _set_palette_role(palette, theme, "palette_base", QPalette.Base)
    _set_palette_role(palette, theme, "palette_alternate_base", QPalette.AlternateBase)
    _set_palette_role(palette, theme, "palette_text", QPalette.Text, disabled_key="palette_disabled_text")
    _set_palette_role(palette, theme, "palette_button", QPalette.Button)
    _set_palette_role(palette, theme, "palette_button_text", QPalette.ButtonText, disabled_key="palette_disabled_button_text")
    _set_palette_role(palette, theme, "palette_bright_text", QPalette.BrightText)
    _set_palette_role(palette, theme, "palette_highlight", QPalette.Highlight, inactive_key="palette_highlight_inactive")
    _set_palette_role(
        palette, theme, "palette_highlighted_text", QPalette.HighlightedText,
        inactive_key="palette_highlighted_text_inactive",
    )
    _set_palette_role(palette, theme, "palette_tool_tip_base", QPalette.ToolTipBase)
    _set_palette_role(palette, theme, "palette_tool_tip_text", QPalette.ToolTipText)
    _set_palette_role(palette, theme, "palette_light", QPalette.Light)
    _set_palette_role(palette, theme, "palette_mid", QPalette.Mid)
    _set_palette_role(palette, theme, "palette_dark", QPalette.Dark)
    _set_palette_role(palette, theme, "palette_shadow", QPalette.Shadow)
    link_color = _qcolor_from_theme_value(theme["palette_link"])
    palette.setColor(QPalette.Link, link_color)
    palette.setColor(QPalette.LinkVisited, link_color)
    # Emboss disabled-пунктов QMenu (Fusion): Light/Dark = фон меню → без «двойного» текста.
    menu_base = _qcolor_from_theme_value(theme["palette_base"])
    palette.setColor(QPalette.Disabled, QPalette.Light, menu_base)
    palette.setColor(QPalette.Disabled, QPalette.Dark, menu_base)
    return palette


def build_app_menu_stylesheet(theme):
    """QSS уровня приложения: плоский цвет disabled-пунктов QMenu."""
    disabled = theme.get("palette_disabled_text", LIGHT_THEME["palette_disabled_text"])
    return (
        f"QMenu::item:disabled {{ color: {disabled}; background-color: transparent; }}"
    )


def build_tab_widget_stylesheet(tab_bar_tab_padding=1):
    """Stylesheet QTabWidget из semantic-цветов tabs subsystem (ThemeManager)."""
    tm = ThemeManager.instance()
    c = tm.color
    _tp = tab_bar_tab_padding
    # Цвет текста вкладок — только через setTabTextColor / EditorTabBar.paintEvent (tab_text / link_color).
    # QSS color перекрывает per-tab setTabTextColor и ломает цвет вкладки-ссылки.
    tab_bar_tab_styles = (
        f"QTabBar::tab {{ border: none; border-right: 1px solid {c('separator')}; background-color: {c('tab_unselected_background')}; padding-top: %dpx; padding-bottom: %dpx; }}"
        f"QTabBar::tab:selected {{ background-color: {c('tab_selected_background')}; border-right: 1px solid {c('separator')}; padding-top: %dpx; padding-bottom: %dpx; }}"
        f"QTabBar::tab:!selected {{ background-color: {c('tab_unselected_background')}; border-right: 1px solid {c('separator')}; padding-top: %dpx; padding-bottom: %dpx; }}"
        f"QTabBar::tab:!selected:hover {{ background-color: {c('tab_unselected_hover_background')}; }}"
    ) % (_tp, _tp, _tp, _tp, _tp, _tp)
    return (
        "QTabWidget { margin: 0; padding: 0; }"
        "QTabWidget::pane { margin: 0; padding: 0; border: none; }"
        # Линия под строкой вкладок — виджет _TabBarBottomLine на всю ширину QTabWidget (не border QTabBar).
        "QTabWidget QTextEdit { border: none; outline: none; margin: 0; padding: 0; }"
        "QTabWidget QTextEdit:focus { border: none; outline: none; margin: 0; padding: 0; }"
        "QTabWidget::pane QTextEdit { border: none; outline: none; margin: 0; padding: 0; }"
        "QTabWidget::pane QTextEdit:focus { border: none; outline: none; margin: 0; padding: 0; }"
        f"QTabBar {{ background-color: {c('tab_bar_trailing_background')}; }}"
        + tab_bar_tab_styles
        + (
            f"QTabBar::scroller {{ background-color: {c('tab_bar_trailing_background')}; }}"
            f"QTabBar QToolButton {{ border: none; background-color: {c('tab_bar_trailing_background')}; background: {c('tab_bar_trailing_background')}; }}"
            f"QTabBar QToolButton:hover {{ border: none; background-color: {c('tab_bar_trailing_background')}; background: {c('tab_bar_trailing_background')}; }}"
            f"QTabBar QToolButton:disabled {{ border: none; background-color: {c('tab_bar_trailing_background')}; background: {c('tab_bar_trailing_background')}; }}"
        )
    )


def build_tab_side_button_style():
    tm = ThemeManager.instance()
    return (
        f"QToolButton {{ border: none; padding: 0px; margin: 0px; background-color: {tm.color('tab_bar_trailing_background')}; }}"
        f"QToolButton:hover {{ background-color: {tm.color('hover_blue')}; }}"
    )


def apply_tab_corner_container_background(corner_container, theme=None):
    """Фон cornerWidget «Добавить временный файл» (= фон QToolButton)."""
    if corner_container is None:
        return
    try:
        if theme is None:
            theme = ThemeManager.instance().theme()
        bg = theme["tab_bar_trailing_background"]
        obj_name = "jbpadTabCornerContainer"
        corner_container.setObjectName(obj_name)
        corner_container.setAttribute(Qt.WA_StyledBackground, True)
        corner_container.setStyleSheet(
            f"#{obj_name} {{ background-color: {bg}; border: none; outline: none; }}"
        )
    except Exception:
        pass


