def _build_vertical_scrollbar_qss(theme, parent_selector="", *, context="editor"):
    """QSS вертикальной полосы прокрутки. parent_selector пустой — правила для самого QScrollBar."""
    keys = _scrollbar_theme_color_keys(context)
    track = theme[keys["track"]]
    handle = theme[keys["handle"]]
    hover = theme[keys["hover"]]
    pressed = theme[keys["pressed"]]
    w = int(SCROLLBAR_WIDTH_PX)
    btn_h = w
    ps = f"{parent_selector} " if parent_selector else ""
    return (
        # margin сверху/снизу резервирует место под кнопки — иначе бегунок перекрывает sub/add-line
        f"{ps}QScrollBar:vertical {{"
        f" background: {track}; width: {w}px;"
        f" margin: {btn_h}px 0px {btn_h}px 0px; border: none; padding: 0px;"
        f"}}"
        f"{ps}QScrollBar::handle:vertical {{"
        f" background: {handle}; min-height: {btn_h}px; border-radius: 0px; margin: 0px 2px;"
        f"}}"
        f"{ps}QScrollBar::handle:vertical:hover {{"
        f" background: {hover};"
        f"}}"
        f"{ps}QScrollBar::handle:vertical:pressed {{"
        f" background: {pressed};"
        f"}}"
        f"{ps}QScrollBar::sub-line:vertical {{"
        f" height: {btn_h}px; width: {w}px;"
        f" subcontrol-origin: margin; subcontrol-position: top;"
        f" background: {track}; border: none;"
        f"}}"
        f"{ps}QScrollBar::add-line:vertical {{"
        f" height: {btn_h}px; width: {w}px;"
        f" subcontrol-origin: margin; subcontrol-position: bottom;"
        f" background: {track}; border: none;"
        f"}}"
        f"{ps}QScrollBar::up-arrow:vertical, "
        f"{ps}QScrollBar::down-arrow:vertical {{"
        f" height: 0px; width: 0px; border: none; background: none;"
        f"}}"
        f"{ps}QScrollBar::add-page:vertical, "
        f"{ps}QScrollBar::sub-page:vertical {{"
        f" background: {track};"
        f"}}"
    )


def build_scrollbar_widget_stylesheet(theme, *, context="editor"):
    """QSS для ThemedVerticalScrollBar (без префикса родителя)."""
    return _build_vertical_scrollbar_qss(theme, "", context=context)


def apply_tree_text_palette(tree, theme):
    """QPalette.Text/Base дерева и inline-редакторов из ключей tree_text / tree_background."""
    if tree is None:
        return
    try:
        text_color = theme_qcolor("tree_text", theme)
        bg_color = theme_qcolor("tree_background", theme)
        palette = tree.palette()
        palette.setColor(QPalette.Active, QPalette.Text, text_color)
        palette.setColor(QPalette.Inactive, QPalette.Text, text_color)
        palette.setColor(QPalette.Active, QPalette.Base, bg_color)
        palette.setColor(QPalette.Inactive, QPalette.Base, bg_color)
        tree.setPalette(palette)
        editor = getattr(tree, "_inline_create_editor", None)
        if editor is not None:
            ed_palette = editor.palette()
            ed_palette.setColor(QPalette.Active, QPalette.Text, text_color)
            ed_palette.setColor(QPalette.Inactive, QPalette.Text, text_color)
            ed_palette.setColor(QPalette.Active, QPalette.Base, bg_color)
            ed_palette.setColor(QPalette.Inactive, QPalette.Base, bg_color)
            editor.setPalette(ed_palette)
    except Exception:
        pass


