class TranslationEditorDialog(ThemedFramelessDialog, Ui_TranslationEditorDialog):
    """Диалог «Редактор перевода»."""
    ROLE_TR_TOUCHED = Qt.UserRole + 2000

    def __init__(self, parent=None):
        super().__init__(parent, resizable=True, content_margins=(0, 0, 0, 0))
        self.setupUi(self.content_widget())
        QtCore.QMetaObject.connectSlotsByName(self)

        self.setWindowTitle(tr("tr_dialog.title", "Редактор перевода"))
        self.setModal(True)
        self.resize_for_content(651, 780)
        self.setMinimumSize(
            651 + self.chrome_extra_width_px(),
            480 + self.chrome_extra_height_px(),
        )

        try:
            wire_copy_paste_context_menu_for_line_edit(getattr(self, "tr_file_name_lineEdit", None))
        except Exception:
            pass
        try:
            wire_copy_paste_context_menu_for_table_view(getattr(self, "tr_edit_tableView", None))
        except Exception:
            pass

        self.model = QStandardItemModel(0, 3, self)
        self._translation_header_text = tr("tr_dialog.column_translation", "Перевод")
        self.model.setHorizontalHeaderLabels([
            tr("tr_dialog.column_key", "key"),
            tr("tr_dialog.column_original", "Оригинал"),
            self._translation_header_text,
        ])

        self.tr_edit_tableView.setModel(self.model)
        self.tr_edit_tableView.setColumnHidden(0, True)

        # Многострочный текст в ячейках: перенос + авто-высота строк (без "...")
        try:
            self.tr_edit_tableView.setWordWrap(True)
        except Exception:
            pass
        try:
            self.tr_edit_tableView.setTextElideMode(Qt.ElideNone)
        except Exception:
            pass
        try:
            self.tr_edit_tableView.setUniformRowHeights(False)
        except Exception:
            pass
        try:
            vheader = self.tr_edit_tableView.verticalHeader()
            vheader.setSectionResizeMode(QtWidgets.QHeaderView.ResizeToContents)
        except Exception:
            pass

        header = self.tr_edit_tableView.horizontalHeader()
        try:
            header.setSectionResizeMode(0, QtWidgets.QHeaderView.ResizeToContents)
            header.setSectionResizeMode(1, QtWidgets.QHeaderView.Stretch)
            header.setSectionResizeMode(2, QtWidgets.QHeaderView.Stretch)
        except Exception:
            pass

        # При изменении ширин колонок пересчитываем высоту строк (с debounce)
        try:
            header.sectionResized.connect(lambda *_a: self._schedule_resize_rows_to_contents())
        except Exception:
            pass

        self.current_translation_path = None
        self._set_translation_dirty(False)
        self._pending_resize_rows = False
        self._translation_edit_enabled = False
        self._apply_translation_column_state()
        self._suppress_item_changed = False
        self._suppress_original_combo_change = False

        try:
            self.model.itemChanged.connect(self._on_model_item_changed)
        except Exception:
            pass

        try:
            self.tr_new_button.clicked.connect(self.on_new_translation)
        except Exception:
            pass
        try:
            self.tr_open_button.clicked.connect(self.on_open_translation)
        except Exception:
            pass
        try:
            self.tr_save_button.clicked.connect(self.on_save)
        except Exception:
            pass
        try:
            self.tr_cancel_button.clicked.connect(self.reject)
        except Exception:
            pass

        # Делегат колонки «Перевод»
        try:
            self._translation_delegate = TranslationItemDelegate(self)
            self.tr_edit_tableView.setItemDelegateForColumn(2, self._translation_delegate)
        except Exception:
            self._translation_delegate = None

        # Один клик по колонке "Перевод" -> сразу редактирование (без промежуточного клика на выделение)
        try:
            self.tr_edit_tableView.clicked.connect(self._on_tr_table_clicked)
        except Exception:
            pass

        # Комбо "Исходный язык": список файлов из \languages (без расширения),
        # текущий выбор = текущий загруженный json языка интерфейса (Setting.ini [languages] translation)
        try:
            self._original_language_name = self._get_original_language_name_from_ini()
            if not str(self._original_language_name or "").strip():
                self._original_language_name = self._default_original_language_name()
            self._populate_original_language_combo(selected_name=str(self._original_language_name))
        except Exception:
            self._original_language_name = self._default_original_language_name()
        try:
            if hasattr(self, "tr_original_comboBox") and self.tr_original_comboBox:
                self.tr_original_comboBox.currentIndexChanged.connect(self._on_original_language_combo_changed)
        except Exception:
            pass

        # При открытии — загружаем исходный язык из Setting.ini и заполняем таблицу
        try:
            self._load_original_language_into_table()
        except Exception:
            pass

        try:
            self._populate_full_date_locale_combo(selected_code=None)
            self._set_full_date_locale_combo_enabled(False)
        except Exception:
            pass

        self._tr_close_confirming = False

    def _initial_focus_widget(self):
        return getattr(self, "tr_edit_tableView", None)

    def _sync_tr_save_button_enabled(self):
        try:
            btn = getattr(self, "tr_save_button", None)
            if btn is not None:
                btn.setEnabled(bool(getattr(self, "is_dirty", False)))
        except Exception:
            pass

    def _set_translation_dirty(self, dirty: bool):
        self.is_dirty = bool(dirty)
        self._sync_tr_save_button_enabled()

    def event(self, event):
        """Крестик в заголовке шлёт QEvent.Close; перехват здесь надёжнее, чем только closeEvent у QDialog."""
        if event.type() == QEvent.Close:
            try:
                if getattr(self, "_tr_close_confirming", False):
                    return super().event(event)
                if not self._confirm_discard_if_dirty():
                    event.ignore()
                    return True
                self._tr_close_confirming = True
                try:
                    return super().event(event)
                finally:
                    self._tr_close_confirming = False
            except Exception:
                try:
                    self._tr_close_confirming = False
                except Exception:
                    pass
                try:
                    event.ignore()
                except Exception:
                    pass
                return True
        return super().event(event)

    def reject(self):
        """Esc и кнопка «Отмена»: то же подтверждение, что и при закрытии крестиком."""
        try:
            if getattr(self, "_tr_close_confirming", False):
                super().reject()
                return
            if not self._confirm_discard_if_dirty():
                return
            self._tr_close_confirming = True
            try:
                super().reject()
            finally:
                self._tr_close_confirming = False
        except Exception:
            try:
                self._tr_close_confirming = False
            except Exception:
                pass

    def _on_tr_table_clicked(self, index):
        """Запускает редактирование по одному клику в колонке 'Перевод'."""
        try:
            if not bool(getattr(self, "_translation_edit_enabled", False)):
                return
        except Exception:
            return
        try:
            if index is None or (hasattr(index, "isValid") and (not index.isValid())):
                return
        except Exception:
            pass
        try:
            if hasattr(index, "column") and int(index.column()) != 2:
                return
        except Exception:
            return

        # Даем view выставить current/selection, затем открываем редактор
        try:
            QTimer.singleShot(0, lambda idx=index: self.tr_edit_tableView.edit(idx))
        except Exception:
            try:
                self.tr_edit_tableView.edit(index)
            except Exception:
                pass

    def _on_model_item_changed(self, item=None, *_args):
        try:
            if bool(getattr(self, "_suppress_item_changed", False)):
                return
        except Exception:
            pass
        # dirty считаем только по изменениям в колонке "Перевод"
        try:
            if item is not None and hasattr(item, "column") and int(item.column()) != 2:
                return
        except Exception:
            pass
        self._set_translation_dirty(True)
        try:
            if item is not None and hasattr(item, "row"):
                # Пользователь изменил перевод -> считаем строку активированной
                try:
                    item.setData(True, self.ROLE_TR_TOUCHED)
                except Exception:
                    pass
        except Exception:
            pass
        self._schedule_resize_rows_to_contents()

    def _apply_translation_column_state(self):
        """Скрывает/показывает колонку 'Перевод' и включает/выключает редактирование."""
        enabled = bool(getattr(self, "_translation_edit_enabled", False))
        try:
            # При disabled скрываем колонку целиком, чтобы не было заголовка
            self.tr_edit_tableView.setColumnHidden(2, not enabled)
        except Exception:
            pass
        try:
            self.tr_edit_tableView.setEditTriggers(
                QtWidgets.QAbstractItemView.DoubleClicked
                | QtWidgets.QAbstractItemView.EditKeyPressed
                | QtWidgets.QAbstractItemView.AnyKeyPressed
                | QtWidgets.QAbstractItemView.SelectedClicked
            ) if enabled else self.tr_edit_tableView.setEditTriggers(QtWidgets.QAbstractItemView.NoEditTriggers)
        except Exception:
            pass
        try:
            # Заголовок колонки 2: на всякий случай держим корректным
            self.model.setHeaderData(2, QtCore.Qt.Horizontal, self._translation_header_text if enabled else self._translation_header_text)
        except Exception:
            pass
        self._schedule_resize_rows_to_contents()

    def _schedule_resize_rows_to_contents(self):
        """Debounce пересчета высоты строк (иначе дергается на каждую правку символа)."""
        try:
            if getattr(self, "_pending_resize_rows", False):
                return
            self._pending_resize_rows = True
            QTimer.singleShot(0, self._resize_rows_to_contents)
        except Exception:
            pass

    def _resize_rows_to_contents(self):
        try:
            self._pending_resize_rows = False
        except Exception:
            pass
        try:
            if hasattr(self, "tr_edit_tableView") and self.tr_edit_tableView:
                self.tr_edit_tableView.resizeRowsToContents()
        except Exception:
            pass

    def _get_settings_file_path(self) -> str:
        """Путь к Setting.ini (через get_settings_file_path() главного окна, если доступно)."""
        # parent может быть NewSettingsDialog, у которого есть parent_window (MainWindow)
        try:
            parent = self.parent()
        except Exception:
            parent = None

        try:
            mw = getattr(parent, "parent_window", None) if parent is not None else None
        except Exception:
            mw = None
        if mw is None:
            mw = parent

        try:
            if mw is not None and hasattr(mw, "get_settings_file_path"):
                return str(mw.get_settings_file_path())
        except Exception:
            pass
        return str(APP_DIR / "Setting.ini")

    def _get_original_language_name_from_ini(self) -> str:
        """Имя исходного языка из Setting.ini (секция [languages], ключ translation)."""
        settings_file = self._get_settings_file_path()
        lang_name = ""
        if _io_exists(settings_file):
            cfg = _read_settings_ini(settings_file)
            try:
                lang_name = str(cfg.get("languages", "translation", fallback="") or "").strip()
            except Exception:
                lang_name = ""

        if not lang_name:
            return ""

        # В ini может быть либо "Name", либо "Name.json"
        try:
            if lang_name.lower().endswith(".json"):
                lang_name = os.path.splitext(lang_name)[0]
        except Exception:
            pass
        return str(lang_name)

    def _default_original_language_name(self) -> str:
        """Имя исходного языка по умолчанию для редактора (если в ini не задано)."""
        names = []
        try:
            for fn in iter_language_filenames():
                base, _ext = os.path.splitext(str(fn))
                if base:
                    names.append(str(base))
        except Exception:
            names = []
        for _name in names:
            if _locale_names_equal(_name, _BASE_RU_LOCALE_NAME):
                # Возвращаем фактическое имя из папки languages (на macOS — в NFD)
                return str(_name)
        if names:
            try:
                return sorted(names, key=lambda s: str(s).lower())[0]
            except Exception:
                return str(names[0])
        return ""

    def _get_languages_dir(self) -> str:
        return str(data_languages_dir())

    def _get_current_original_language_json_path(self) -> str:
        """Путь к JSON исходного языка (тот же, что для колонки «Оригинал»)."""
        try:
            lang_name = str(getattr(self, "_original_language_name", "") or "").strip()
        except Exception:
            lang_name = ""
        if not lang_name:
            try:
                lang_name = str(self._get_original_language_name_from_ini() or "").strip()
            except Exception:
                lang_name = ""
        if not lang_name:
            return ""
        try:
            resolved = language_json_path(lang_name)
        except Exception:
            resolved = None
        return str(resolved or "")

    @staticmethod
    def _canonical_path_for_comparison(p: str) -> str:
        """Абсолютный путь в каноническом виде для сравнения на разных ОС (регистр, symlinks)."""
        try:
            s = os.path.expandvars(os.path.expanduser(str(p)))
        except Exception:
            s = str(p)
        return _canonical_file_path(s)

    @staticmethod
    def _same_json_file_path(a: str, b: str) -> bool:
        """Тот же файл на диске: samefile (жёсткие ссылки, symlink), иначе сравнение канонических путей."""
        if not a or not b:
            return False
        try:
            ea = os.path.expandvars(os.path.expanduser(str(a)))
            eb = os.path.expandvars(os.path.expanduser(str(b)))
        except Exception:
            ea, eb = str(a), str(b)
        try:
            if os.path.exists(ea) and os.path.exists(eb) and os.path.samefile(ea, eb):
                return True
        except (OSError, ValueError):
            pass
        ca = TranslationEditorDialog._canonical_path_for_comparison(ea)
        cb = TranslationEditorDialog._canonical_path_for_comparison(eb)
        return bool(ca and cb and ca == cb)

    def _populate_original_language_combo(self, selected_name: str = ""):
        """Заполняет tr_original_comboBox именами json-файлов из папки languages (без расширения)."""
        combo = getattr(self, "tr_original_comboBox", None)
        if combo is None:
            return

        names = []
        try:
            for fn in iter_language_filenames():
                base, _ext = os.path.splitext(str(fn))
                if base:
                    names.append(str(base))
        except Exception:
            names = []

        try:
            names = sorted(set(names), key=lambda s: str(s).lower())
        except Exception:
            pass

        selected = str(selected_name or "").strip()
        try:
            combo.blockSignals(True)
            combo.clear()
            if names:
                combo.addItems(list(names))
            if selected:
                idx = _combo_index_by_locale_name(combo, selected)
                if idx >= 0:
                    combo.setCurrentIndex(idx)
                else:
                    # Если файла нет, всё равно показываем текущий выбор (чтобы соответствовал загруженному json)
                    combo.addItem(selected)
                    combo.setCurrentIndex(combo.count() - 1)
        finally:
            try:
                combo.blockSignals(False)
            except Exception:
                pass

    def _populate_full_date_locale_combo(self, selected_code=None):
        """Заполняет combobox языка полной даты; selected_code — код из заголовка locale."""
        combo = getattr(self, "tr_full_date_locale_comboBox", None)
        if combo is None:
            return
        try:
            combo.blockSignals(True)
            combo.clear()
            combo.addItem("None", None)
            for code, display_name in full_date_locale_store.iter_for_combobox():
                combo.addItem(str(display_name), str(code))
            if selected_code is not None:
                for i in range(int(combo.count())):
                    try:
                        if combo.itemData(i) == selected_code:
                            combo.setCurrentIndex(i)
                            return
                    except Exception:
                        continue
                if selected_code:
                    combo.addItem(str(selected_code), str(selected_code))
                    combo.setCurrentIndex(combo.count() - 1)
                    return
            combo.setCurrentIndex(0)
        finally:
            try:
                combo.blockSignals(False)
            except Exception:
                pass

    def _set_full_date_locale_combo_enabled(self, enabled: bool):
        combo = getattr(self, "tr_full_date_locale_comboBox", None)
        if combo is not None:
            try:
                combo.setEnabled(bool(enabled))
            except Exception:
                pass

    def _get_selected_full_date_locale_code(self):
        combo = getattr(self, "tr_full_date_locale_comboBox", None)
        if combo is None:
            return None
        try:
            return combo.currentData()
        except Exception:
            return None

    def _escape_newlines_for_table(self, text: str) -> str:
        """Показываем переносы строк как литералы '\\n', чтобы они не ломали строку в ячейке."""
        try:
            s = str(text)
        except Exception:
            s = ""
        # Приводим сначала CRLF/CR к LF, затем экранируем
        try:
            s = s.replace("\r\n", "\n").replace("\r", "\n")
        except Exception:
            pass
        try:
            s = s.replace("\n", "\\n")
        except Exception:
            pass
        return s

    def _has_visible_user_input(self) -> bool:
        """Есть ли в таблице введённый текст перевода."""
        try:
            row_count = int(self.model.rowCount())
        except Exception:
            return False
        for row in range(row_count):
            try:
                tr_item = self.model.item(row, 2)
                tr_text = "" if tr_item is None else str(tr_item.text() or "")
                if str(tr_text).strip():
                    return True
            except Exception:
                continue
        return False

    def _flush_open_translation_cell_editor(self):
        """Записать открытый редактор ячейки в модель до проверки is_dirty.

        Закрытие по крестику и иные пути без смены фокуса на другое поле могут не вызвать
        setModelData у делегата, поэтому правки остаются только в QTextEdit и is_dirty не ставится.
        При клике по заголовку окна фокус может уже не быть в редакторе — ищем видимый QTextEdit в таблице.
        """
        try:
            view = getattr(self, "tr_edit_tableView", None)
            if view is None:
                return
            to_commit = []
            try:
                fw = QApplication.focusWidget()
                if fw is not None and view.isAncestorOf(fw):
                    to_commit.append(fw)
            except Exception:
                pass
            try:
                for ed in view.findChildren(QTextEdit):
                    try:
                        if ed.isVisible():
                            to_commit.append(ed)
                    except Exception:
                        continue
            except Exception:
                pass
            seen = set()
            for w in to_commit:
                if w is None:
                    continue
                try:
                    wid = int(id(w))
                    if wid in seen:
                        continue
                    seen.add(wid)
                    view.commitData(w)
                except Exception:
                    pass
        except Exception:
            pass

    def _on_original_language_combo_changed(self, _index: int):
        """Смена исходного языка (перезагрузка таблицы как при первом открытии)."""
        try:
            if bool(getattr(self, "_suppress_original_combo_change", False)):
                return
        except Exception:
            pass

        try:
            combo = getattr(self, "tr_original_comboBox", None)
            selected = "" if combo is None else str(combo.currentText() or "").strip()
        except Exception:
            selected = ""

        if not selected:
            return

        try:
            current = str(getattr(self, "_original_language_name", "") or "").strip()
        except Exception:
            current = ""

        if selected == current:
            return

        try:
            self._flush_open_translation_cell_editor()
        except Exception:
            pass

        # Если есть несохранённые изменения в текущем переводе — предупреждаем.
        try:
            dirty = bool(getattr(self, "is_dirty", False))
        except Exception:
            dirty = False

        if dirty:
            res = ThemedMessageDialog.warning_ok_cancel(
                self,
                tr("dialog.confirmation", "Подтверждение"),
                tr("tr_dialog.lose_changes_text", "Все несохраненные изменения будут потеряны. Продолжить?"),
            )
            if res != QMessageBox.Ok:
                # Откатываем выбор в комбобоксе
                try:
                    self._suppress_original_combo_change = True
                    idx = _combo_index_by_locale_name(combo, current)
                    if idx >= 0:
                        combo.setCurrentIndex(idx)
                except Exception:
                    pass
                finally:
                    self._suppress_original_combo_change = False
                return

        # Переключаем язык "как при новом открытии": сбрасываем режим редактирования перевода
        self._original_language_name = str(selected)
        self._translation_edit_enabled = False
        self._apply_translation_column_state()
        try:
            if hasattr(self, "tr_file_name_lineEdit") and self.tr_file_name_lineEdit:
                self.tr_file_name_lineEdit.clear()
        except Exception:
            pass
        self.current_translation_path = None
        self._set_translation_dirty(False)

        try:
            self._populate_full_date_locale_combo(selected_code=None)
            self._set_full_date_locale_combo_enabled(False)
        except Exception:
            pass

        try:
            self._load_original_language_into_table()
        except Exception:
            pass

    def _confirm_discard_if_dirty(self) -> bool:
        """Если есть несохранённые изменения — спросить, можно ли их отбросить."""
        try:
            self._flush_open_translation_cell_editor()
        except Exception:
            pass
        try:
            dirty = bool(getattr(self, "is_dirty", False))
        except Exception:
            dirty = False
        if not dirty:
            return True

        res = ThemedMessageDialog.warning_ok_cancel(
            self,
            tr("dialog.confirmation", "Подтверждение"),
            tr("tr_dialog.lose_changes_text", "Все несохраненные изменения будут потеряны. Продолжить?"),
        )
        return res == QMessageBox.Ok

    def _load_original_language_into_table(self):
        """Загружает JSON исходного языка и заполняет модель: key/original/''."""
        try:
            lang_name = str(getattr(self, "_original_language_name", "") or "").strip()
        except Exception:
            lang_name = ""
        if not lang_name:
            lang_name = self._get_original_language_name_from_ini()
            if not str(lang_name or "").strip():
                lang_name = self._default_original_language_name()
            try:
                self._original_language_name = str(lang_name)
            except Exception:
                pass

        # Путь: \languages\<language>.json
        json_path = os.path.join(str(self._get_languages_dir()), f"{lang_name}.json")

        if not os.path.exists(json_path):
            _qmessagebox_single_ok(
                QMessageBox.Critical,
                self,
                APP_BRAND,
                tr("tr_dialog.load_error_text", "Не найден файл исходного языка:") + f"\n{json_path}",
            )
            return

        try:
            data = jbp_load_json(json_path, JBP_KIND_LOCALE)
        except Exception as e:
            data = None
            _qmessagebox_single_ok(
                QMessageBox.Critical,
                self,
                APP_BRAND,
                tr("tr_dialog.load_error_parse", "Не удалось прочитать JSON исходного языка:") + f"\n{json_path}\n\n{e}",
            )
            return

        if not isinstance(data, dict):
            _qmessagebox_single_ok(
                QMessageBox.Critical,
                self,
                APP_BRAND,
                tr("tr_dialog.load_error_format", "Некорректный формат файла языка (ожидается объект JSON):") + f"\n{json_path}",
            )
            return

        # Показать текущий исходный язык в комбобоксе
        try:
            combo = getattr(self, "tr_original_comboBox", None)
            if combo is not None:
                combo.blockSignals(True)
                try:
                    idx = _combo_index_by_locale_name(combo, str(lang_name))
                    if idx >= 0:
                        combo.setCurrentIndex(idx)
                    else:
                        combo.addItem(str(lang_name))
                        combo.setCurrentIndex(combo.count() - 1)
                finally:
                    combo.blockSignals(False)
        except Exception:
            pass

        # Заполнение таблицы
        try:
            # Не блокируем сигналы модели целиком — иначе QTableView не обновится до следующего события (клика).
            # Вместо этого подавляем только реакцию на itemChanged.
            try:
                self._suppress_item_changed = True
            except Exception:
                pass

            self.model.removeRows(0, self.model.rowCount())

            for k, v in data.items():
                key_item = QStandardItem(str(k))
                orig_item = QStandardItem(self._escape_newlines_for_table(v))
                tr_item = QStandardItem("")
                try:
                    tr_item.setData(False, self.ROLE_TR_TOUCHED)
                except Exception:
                    pass

                # key (скрыта) — не редактируется
                try:
                    key_item.setFlags(key_item.flags() & ~QtCore.Qt.ItemIsEditable)
                except Exception:
                    key_item.setEditable(False)

                # original — не редактируется
                try:
                    orig_item.setFlags(orig_item.flags() & ~QtCore.Qt.ItemIsEditable)
                except Exception:
                    orig_item.setEditable(False)

                # translation — editable только если включен режим редактирования
                if bool(getattr(self, "_translation_edit_enabled", False)):
                    try:
                        if not (tr_item.flags() & QtCore.Qt.ItemIsEditable):
                            tr_item.setFlags(tr_item.flags() | QtCore.Qt.ItemIsEditable)
                    except Exception:
                        pass
                else:
                    try:
                        tr_item.setFlags(tr_item.flags() & ~QtCore.Qt.ItemIsEditable)
                    except Exception:
                        try:
                            tr_item.setEditable(False)
                        except Exception:
                            pass
                try:
                    tr_item.setFlags(tr_item.flags() | QtCore.Qt.ItemIsEnabled | QtCore.Qt.ItemIsSelectable)
                except Exception:
                    pass

                self.model.appendRow([key_item, orig_item, tr_item])
        finally:
            try:
                self._suppress_item_changed = False
            except Exception:
                pass

        self._set_translation_dirty(False)
        self._schedule_resize_rows_to_contents()
        try:
            if not bool(getattr(self, "_translation_edit_enabled", False)):
                self._populate_full_date_locale_combo(selected_code=None)
                self._set_full_date_locale_combo_enabled(False)
        except Exception:
            pass

    def on_new_translation(self):
        if not self._confirm_discard_if_dirty():
            return

        # По кнопке "Новый..." включаем ввод перевода и показываем колонку "Перевод"
        self._translation_edit_enabled = True
        self._apply_translation_column_state()

        # Режим "Новый": колонка перевода начинается пустой.
        try:
            try:
                self._suppress_item_changed = True
            except Exception:
                pass
            for row in range(int(self.model.rowCount())):
                try:
                    tr_item = self.model.item(row, 2)
                    if tr_item is None:
                        tr_item = QStandardItem("")
                        self.model.setItem(row, 2, tr_item)
                    # Очищаем, чтобы новый перевод начинался "с нуля"
                    tr_item.setText("")
                    try:
                        tr_item.setData(False, self.ROLE_TR_TOUCHED)
                    except Exception:
                        pass

                    try:
                        if not (tr_item.flags() & QtCore.Qt.ItemIsEditable):
                            tr_item.setFlags(tr_item.flags() | QtCore.Qt.ItemIsEditable)
                    except Exception:
                        try:
                            tr_item.setEditable(True)
                        except Exception:
                            pass
                except Exception:
                    continue
        except Exception:
            pass
        finally:
            try:
                self._suppress_item_changed = False
            except Exception:
                pass

        self.current_translation_path = None
        self._set_translation_dirty(False)
        try:
            if hasattr(self, "tr_file_name_lineEdit") and self.tr_file_name_lineEdit:
                self.tr_file_name_lineEdit.clear()
        except Exception:
            pass
        try:
            self._populate_full_date_locale_combo(selected_code=None)
            self._set_full_date_locale_combo_enabled(True)
        except Exception:
            pass
        self._schedule_resize_rows_to_contents()

    def on_open_translation(self):
        if not self._confirm_discard_if_dirty():
            return

        # Открываем JSON из Data/languages
        lang_dir = str(data_languages_dir())

        try:
            selected_path, _selected_filter = QFileDialog.getOpenFileName(
                self,
                tr("tr_dialog.open_title", "Открыть перевод"),
                lang_dir,
                "JSON (*.json)",
            )
        except Exception:
            return

        if not selected_path:
            return

        try:
            orig_json = self._get_current_original_language_json_path()
        except Exception:
            orig_json = ""
        if orig_json and self._same_json_file_path(str(selected_path), str(orig_json)):
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                self,
                APP_BRAND,
                tr("tr_dialog.open_same_as_original", "Этот файл уже открыт для перевода"),
            )
            return

        # Загружаем JSON
        data, full_date_locale_meta = jbp_load_locale(selected_path)
        if data is None:
            _qmessagebox_single_ok(
                QMessageBox.Critical,
                self,
                APP_BRAND,
                tr("tr_dialog.load_error_parse", "Не удалось прочитать файл перевода:") + f"\n{selected_path}",
            )
            return

        if not isinstance(data, dict):
            _qmessagebox_single_ok(
                QMessageBox.Critical,
                self,
                APP_BRAND,
                tr("tr_dialog.load_error_format", "Некорректный формат файла перевода (ожидается объект JSON)") + f"\n{selected_path}",
            )
            return

        # При открытии существующего перевода — показываем колонку "Перевод" и разрешаем ввод
        self._translation_edit_enabled = True
        self._apply_translation_column_state()

        # Заполняем колонку "Перевод" по ключам из таблицы; лишние ключи из файла игнорируем
        try:
            try:
                self._suppress_item_changed = True
            except Exception:
                pass
            for row in range(int(self.model.rowCount())):
                try:
                    key_item = self.model.item(row, 0)
                    key = "" if key_item is None else str(key_item.text())
                    value = data.get(key, "")

                    tr_item = self.model.item(row, 2)
                    if tr_item is None:
                        tr_item = QStandardItem("")
                        self.model.setItem(row, 2, tr_item)

                    tr_item.setText(self._escape_newlines_for_table(value))
                    try:
                        if not (tr_item.flags() & QtCore.Qt.ItemIsEditable):
                            tr_item.setFlags(tr_item.flags() | QtCore.Qt.ItemIsEditable)
                    except Exception:
                        try:
                            tr_item.setEditable(True)
                        except Exception:
                            pass
                except Exception:
                    continue
        finally:
            try:
                self._suppress_item_changed = False
            except Exception:
                pass

        self.current_translation_path = str(selected_path)
        try:
            if hasattr(self, "tr_file_name_lineEdit") and self.tr_file_name_lineEdit:
                self.tr_file_name_lineEdit.setText(os.path.basename(str(selected_path)))
        except Exception:
            pass

        self._set_translation_dirty(False)
        try:
            self._populate_full_date_locale_combo(selected_code=full_date_locale_meta)
            self._set_full_date_locale_combo_enabled(True)
        except Exception:
            pass
        self._schedule_resize_rows_to_contents()

    def on_save(self):
        try:
            self._flush_open_translation_cell_editor()
        except Exception:
            pass

        try:
            current_path = str(getattr(self, "current_translation_path", None) or "").strip()
        except Exception:
            current_path = ""

        try:
            raw_name = ""
            if hasattr(self, "tr_file_name_lineEdit") and self.tr_file_name_lineEdit:
                raw_name = str(self.tr_file_name_lineEdit.text() or "")
        except Exception:
            raw_name = ""

        if not str(raw_name).strip():
            if current_path:
                try:
                    raw_name = os.path.basename(str(current_path))
                except Exception:
                    raw_name = ""
            if not str(raw_name).strip():
                _qmessagebox_single_ok(
                    QMessageBox.Warning,
                    self,
                    APP_BRAND,
                    tr("tr_dialog.save_error_empty_name", "Введите имя файла"),
                )
                return

        sanitized = sanitize_filename(str(raw_name), default_stem="translation", extension=".json")
        try:
            if sanitized != str(raw_name):
                if hasattr(self, "tr_file_name_lineEdit") and self.tr_file_name_lineEdit:
                    self.tr_file_name_lineEdit.setText(str(sanitized))
        except Exception:
            pass

        if not sanitized:
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                self,
                APP_BRAND,
                tr("tr_dialog.save_error_empty_name", "Введите имя файла"),
            )
            return

        ensure_data_languages_dir()
        lang_dir = str(data_languages_dir())

        try:
            target_path = os.path.join(str(lang_dir), str(sanitized))
        except Exception:
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                self,
                APP_BRAND,
                tr("tr_dialog.save_error_empty_name", "Введите имя файла"),
            )
            return

        existing_name = find_filename_in_dir_case_insensitive(lang_dir, sanitized)
        existing_path = (
            os.path.join(str(lang_dir), str(existing_name)) if existing_name else None
        )

        save_as = bool(current_path) and (not self._same_json_file_path(current_path, target_path))

        if save_as and existing_path and not self._same_json_file_path(current_path, existing_path):
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                self,
                APP_BRAND,
                tr("message.file_duplicate", "Файл с таким именем уже существует"),
            )
            return

        if (not current_path) and existing_path:
            res = ThemedMessageDialog.question_yes_no(
                self,
                tr("dialog.confirmation", "Подтверждение"),
                tr("tr_dialog.overwrite_text", "Файл уже существует. Перезаписать?"),
                default_button=QMessageBox.No,
                button_labels={
                    QMessageBox.Yes: tr("dialog.button_ok", "ОК"),
                    QMessageBox.No: tr("dialog.button_cancel", "Отмена"),
                },
            )
            if res != QMessageBox.Yes:
                return
            target_path = existing_path
        elif (
            current_path
            and existing_path
            and self._same_json_file_path(current_path, existing_path)
        ):
            target_path = existing_path

        # Собираем JSON: только непустые строки
        out = {}
        try:
            row_count = int(self.model.rowCount())
        except Exception:
            row_count = 0

        for row in range(row_count):
            try:
                key_item = self.model.item(row, 0)
                tr_item = self.model.item(row, 2)
                key = "" if key_item is None else str(key_item.text() or "")
                tr_text = "" if tr_item is None else str(tr_item.text() or "")

                if not str(tr_text).strip():
                    continue

                # В файл пишем с реальными переводами строки
                try:
                    value_to_save = str(tr_text).replace("\\n", "\n")
                except Exception:
                    value_to_save = str(tr_text)

                if key:
                    out[str(key)] = value_to_save
            except Exception:
                continue

        try:
            jbp_dump_locale(
                str(target_path),
                out,
                full_date_locale=self._get_selected_full_date_locale_code(),
            )
        except Exception as e:
            _qmessagebox_single_ok(
                QMessageBox.Critical,
                self,
                APP_BRAND,
                tr("tr_dialog.save_error_write", "Не удалось сохранить файл перевода") + f"\n{target_path}\n\n{e}",
            )
            return

        self._set_translation_dirty(False)
        self.current_translation_path = str(target_path)
        try:
            if hasattr(self, "tr_file_name_lineEdit") and self.tr_file_name_lineEdit:
                self.tr_file_name_lineEdit.setText(os.path.basename(str(target_path)))
        except Exception:
            pass


_FORBIDDEN_FILENAME_CHARS = frozenset('<>:"/\\|?*')
_WINDOWS_RESERVED_STEMS = {"CON", "PRN", "AUX", "NUL"}
for _reserved_i in range(1, 10):
    _WINDOWS_RESERVED_STEMS.add(f"COM{_reserved_i}")
    _WINDOWS_RESERVED_STEMS.add(f"LPT{_reserved_i}")


def _fix_windows_reserved_stem(stem: str) -> str:
    if not stem:
        return stem
    try:
        stem_upper = stem.upper()
    except Exception:
        stem_upper = stem
    if stem_upper in _WINDOWS_RESERVED_STEMS:
        return stem + "_file"
    return stem


def _collapse_whitespace_in_filename(s: str) -> str:
    s = re.sub(r"[ \t]{2,}", " ", s)
    s = re.sub(r"_{2,}", "_", s)
    s = re.sub(r"(?=[ _\t]*_)(?=[ _\t]*[ \t])[ _\t]+", "_", s)
    return s


def sanitize_path_component(name, *, max_length: int = 120) -> str:
    """Санитизация одного сегмента пути (stem или имя папки без каталога)."""
    try:
        s = "" if name is None else str(name)
    except Exception:
        s = ""

    s = s.strip(" \t")

    cleaned_chars = []
    for ch in s:
        try:
            if ord(ch) == 0x7F:
                continue
            if unicodedata.category(ch) == "Cc":
                continue
        except Exception:
            continue
        cleaned_chars.append(ch)
    s = "".join(cleaned_chars)

    if any(ch in _FORBIDDEN_FILENAME_CHARS for ch in s):
        out = []
        for ch in s:
            out.append(" " if ch in _FORBIDDEN_FILENAME_CHARS else ch)
        s = "".join(out)

    s = _collapse_whitespace_in_filename(s)
    s = s.rstrip(" .")

    if s in (".", ".."):
        s = ""

    s = _fix_windows_reserved_stem(s)

    if max_length and len(s) > max_length:
        s = s[:max_length].rstrip(" .")
        s = _fix_windows_reserved_stem(s)

    return s


def find_filename_in_dir_case_insensitive(directory: str, filename: str):
    """Имя файла на диске при совпадении без учёта регистра, иначе None."""
    if not directory or not filename:
        return None
    try:
        target = _filename_compare_key(filename, directory=directory)
    except Exception:
        return None
    try:
        entries = _io_listdir(str(directory))
    except OSError:
        return None
    for entry in entries:
        try:
            if _filename_compare_key(entry, directory=directory) == target:
                return str(entry)
        except Exception:
            continue
    return None


def filename_exists_in_dir_case_insensitive(directory: str, filename: str) -> bool:
    return find_filename_in_dir_case_insensitive(directory, filename) is not None


def sanitize_filename(
    name: str,
    *,
    default_stem=None,
    extension: str = ".json",
    max_length: int = 120,
) -> str:
    """Санитизация имени создаваемого файла (stem + extension)."""
    ext = str(extension or "")
    if ext and not ext.startswith("."):
        ext = "." + ext

    try:
        raw = "" if name is None else str(name)
    except Exception:
        raw = ""

    stem_input = raw
    if ext:
        try:
            if raw.lower().endswith(ext.lower()):
                stem_input = raw[: -len(ext)]
        except Exception:
            pass

    max_stem = max(1, int(max_length) - len(ext)) if max_length else 120
    stem = sanitize_path_component(stem_input, max_length=max_stem)
    if not stem:
        if default_stem is not None:
            stem = sanitize_path_component(str(default_stem), max_length=max_stem)
        else:
            return ""
    if not stem:
        return ""

    stem = _fix_windows_reserved_stem(stem)
    full = stem + ext
    if max_length and len(full) > max_length:
        stem = stem[: max(1, max_length - len(ext))].rstrip(" .")
        stem = _fix_windows_reserved_stem(stem)
        if not stem:
            return ""
        full = stem + ext
    return full


def sanitize_path_from_dialog(
    full_path,
    *,
    default_stem=None,
    extension: str = ".json",
    max_length: int = 120,
) -> str:
    """QFileDialog.getSaveFileName: sanitize basename, каталог сохраняем."""
    try:
        full = "" if full_path is None else str(full_path)
    except Exception:
        full = ""
    if not full.strip():
        return ""
    directory, basename = os.path.split(full)
    sanitized = sanitize_filename(
        basename,
        default_stem=default_stem,
        extension=extension,
        max_length=max_length,
    )
    if not sanitized:
        return ""
    if directory:
        return os.path.join(directory, sanitized)
    return sanitized


def _same_directory(a: str, b: str) -> bool:
    try:
        na = os.path.normcase(os.path.normpath(os.path.abspath(str(a or ""))))
        nb = os.path.normcase(os.path.normpath(os.path.abspath(str(b or ""))))
        return bool(na and nb and na == nb)
    except Exception:
        return False


def prepare_theme_json_save_path(raw_path, *, parent=None, current_path=None):
    """Санитизация Save As для темы; duplicate guard в Data/theme/.

    Returns:
        (resolved_path, ok)
    """
    path = sanitize_path_from_dialog(raw_path, default_stem="MyTheme", extension=".json")
    if not path:
        if parent is not None:
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                parent,
                APP_BRAND,
                tr("tr_dialog.save_error_empty_name", "Введите имя файла"),
            )
        return None, False

    try:
        directory = os.path.dirname(os.path.abspath(path))
        themes_dir = os.path.abspath(str(data_themes_dir()))
    except Exception:
        directory = ""
        themes_dir = ""

    if _same_directory(directory, themes_dir):
        basename = os.path.basename(path)
        existing_name = find_filename_in_dir_case_insensitive(themes_dir, basename)
        if existing_name:
            existing_path = os.path.join(themes_dir, existing_name)
            if current_path and TranslationEditorDialog._same_json_file_path(
                current_path, existing_path
            ):
                return existing_path, True
            if parent is not None:
                _qmessagebox_single_ok(
                    QMessageBox.Warning,
                    parent,
                    APP_BRAND,
                    tr("message.file_duplicate", "Файл с таким именем уже существует"),
                )
            return None, False

    return path, True


def sanitize_export_top_level_stem(item_name: str, current_date: str) -> str:
    """Top-level export: name_date; пустой stem → dd.mm.yyyy (см. документацию)."""
    try:
        raw = f"{item_name}_{current_date}"
    except Exception:
        raw = str(current_date or "")
    stem = sanitize_path_component(raw)
    if not stem:
        stem = sanitize_path_component(str(current_date or "")) or str(current_date or "")
    return stem


def sanitize_export_recursive_stem(name: str) -> str:
    """Рекурсивный export: stem файла/папки; пустой → unnamed."""
    return sanitize_path_component(name) or "unnamed"


def sanitize_export_cover_stem(item_name: str) -> str:
    """Cover-файл export; пустое имя узла → cover."""
    try:
        raw = f"cover_{item_name}"
    except Exception:
        raw = "cover_"
    return sanitize_path_component(raw) or "cover"


def _export_coerce_text(content) -> str:
    if isinstance(content, list):
        try:
            return "".join(content)
        except Exception:
            return ""
    if content is None:
        return ""
    return str(content)


def _export_iter_unique_candidates(path: str):
    """Кандидаты имён экспорта: path, path (2), path (3), ..."""
    if not path:
        return
    try:
        parent, name = os.path.split(path)
        if not parent:
            parent = "."
    except Exception:
        yield path
        return
    base, ext = os.path.splitext(name)
    yield os.path.join(parent, name)
    for n in range(2, 1000):
        yield os.path.join(parent, f"{base} ({n}){ext}")


def _export_make_unique_path(path: str) -> str:
    """Если путь занят (без учёта регистра), добавляет суффикс ' (n)'."""
    if not path:
        return path
    try:
        parent, name = os.path.split(path)
        if not parent:
            parent = "."
        if not find_filename_in_dir_case_insensitive(parent, name):
            return path
    except Exception:
        return path

    base, ext = os.path.splitext(name)
    for n in range(2, 1000):
        candidate_name = f"{base} ({n}){ext}"
        try:
            if not find_filename_in_dir_case_insensitive(parent, candidate_name):
                return os.path.join(parent, candidate_name)
        except Exception:
            return os.path.join(parent, candidate_name)
    return path


def _export_write_text_file_exclusive_once(file_path: str, content: str) -> bool:
    """Записывает txt через O_EXCL; False если файл уже существует."""
    if _is_windows_extended_path_too_long(file_path):
        return False
    directory = os.path.dirname(str(file_path or "")) or "."
    try:
        _io_makedirs(directory, exist_ok=True)
    except OSError:
        return False
    io_path = _win_io_path(str(file_path))
    text = "" if content is None else str(content)
    fd = None
    try:
        fd = os.open(io_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, _default_file_mode())
    except FileExistsError:
        return False
    except OSError as exc:
        if getattr(exc, "errno", None) == errno.EEXIST:
            return False
        return False
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as f:
            fd = None
            f.write(text)
            f.flush()
            _io_fsync_file_fd(f.fileno())
        _io_fsync_directory(directory)
        return True
    except OSError:
        try:
            if fd is not None:
                os.close(fd)
        except OSError:
            pass
        try:
            _io_remove(file_path)
        except OSError:
            pass
        return False


def _export_write_text_file(file_path: str, content: str) -> bool:
    """Записывает txt с O_EXCL; при занятом имени пробует суффиксы ' (n)'."""
    for candidate in _export_iter_unique_candidates(file_path):
        if _export_write_text_file_exclusive_once(candidate, content):
            return True
    return False


def _export_count_snapshot_writes(node) -> int:
    if not isinstance(node, dict):
        return 0
    item_type = node.get("type")
    if item_type == "file":
        return 1
    if item_type == "folder":
        total = 1
        for child in node.get("children") or ():
            total += _export_count_snapshot_writes(child)
        return total
    return 0


def _export_snapshot_children(children, parent_dir, cancelled_check, progress_step) -> bool:
    for child in (children or ()):
        if cancelled_check():
            return False
        if not isinstance(child, dict):
            continue
        child_type = child.get("type")
        child_name = child.get("name") or ""
        if child_type == "file":
            stem = sanitize_export_recursive_stem(child_name)
            file_path = os.path.join(parent_dir, f"{stem}.txt")
            if not _export_write_text_file(file_path, child.get("text", "")):
                return False
            progress_step(child_name)
        elif child_type == "folder":
            stem = sanitize_export_recursive_stem(child_name)
            folder_path = os.path.join(parent_dir, stem)
            folder_path = _export_make_unique_path(folder_path)
            if _is_windows_extended_path_too_long(folder_path):
                return False
            try:
                _io_makedirs(folder_path, exist_ok=True)
            except OSError:
                return False

            cover_stem = sanitize_export_cover_stem(child_name)
            cover_file_path = os.path.join(folder_path, f"{cover_stem}.txt")
            if not _export_write_text_file(cover_file_path, child.get("text", "")):
                return False
            progress_step(child_name)

            if not _export_snapshot_children(child.get("children"), folder_path, cancelled_check, progress_step):
                return False
    return True


def _export_snapshot_top_level(node, export_dir, current_date, cancelled_check, progress_step):
    if cancelled_check() or not isinstance(node, dict):
        return None
    item_name = node.get("name") or ""
    item_type = node.get("type")
    if item_type == "file":
        stem = sanitize_export_top_level_stem(item_name, current_date)
        file_path = os.path.join(export_dir, f"{stem}.txt")
        if not _export_write_text_file(file_path, node.get("text", "")):
            return None
        progress_step(item_name)
        return file_path

    if item_type == "folder":
        stem = sanitize_export_top_level_stem(item_name, current_date)
        folder_path = os.path.join(export_dir, stem)
        folder_path = _export_make_unique_path(folder_path)

        cover_stem = sanitize_export_cover_stem(item_name)
        staging_root = None
        try:
            staging_root = tempfile.mkdtemp(
                prefix=".jbpad_export_",
                dir=_win_io_path(export_dir),
            )
            _io_chmod_mode(staging_root, _default_dir_mode())
            cover_file_path = os.path.join(staging_root, f"{cover_stem}.txt")
            if not _export_write_text_file(cover_file_path, node.get("text", "")):
                return None
            progress_step(item_name)
            if not _export_snapshot_children(
                node.get("children"),
                staging_root,
                cancelled_check,
                progress_step,
            ):
                return None
            if cancelled_check():
                return None
            shutil.move(_win_io_path(staging_root), _win_io_path(folder_path))
            staging_root = None
            return folder_path
        except OSError:
            return None
        finally:
            if staging_root and _io_isdir(staging_root):
                try:
                    shutil.rmtree(_win_io_path(staging_root), ignore_errors=True)
                except Exception:
                    pass
    return None


class ExportTxtWorker(QObject):
    """Фоновый экспорт дерева блокнота в txt (disk I/O без блокировки GUI)."""

    progress = pyqtSignal(int, int, str)
    export_finished = pyqtSignal(object, object, bool)

    def __init__(self):
        super().__init__()
        self._cancelled = False

    @pyqtSlot()
    def cancel(self):
        self._cancelled = True

    @pyqtSlot(object)
    def run_export(self, job):
        self._cancelled = False
        successful_names = []
        failed_names = []
        export_dir = ""
        current_date = ""
        entries = []

        if isinstance(job, dict):
            export_dir = str(job.get("export_dir") or "")
            current_date = str(job.get("current_date") or "")
            raw_entries = job.get("entries") or []
            if isinstance(raw_entries, list):
                entries = raw_entries

        total_writes = 0
        for entry in entries:
            if isinstance(entry, dict):
                total_writes += _export_count_snapshot_writes(entry.get("snapshot"))
        total_writes = max(1, int(total_writes))
        done_writes = 0

        def cancelled_check():
            return bool(self._cancelled)

        def progress_step(label):
            nonlocal done_writes
            done_writes += 1
            try:
                self.progress.emit(int(done_writes), int(total_writes), str(label or ""))
            except Exception:
                pass

        if export_dir and entries:
            for entry in entries:
                if cancelled_check():
                    break
                if not isinstance(entry, dict):
                    continue
                name = str(entry.get("name") or "").strip()
                snapshot = entry.get("snapshot")
                if not isinstance(snapshot, dict):
                    failed_names.append(name or "—")
                    continue
                result = _export_snapshot_top_level(
                    snapshot,
                    export_dir,
                    current_date,
                    cancelled_check,
                    progress_step,
                )
                if result:
                    successful_names.append(name or "—")
                else:
                    failed_names.append(name or "—")

        self.export_finished.emit(successful_names, failed_names, bool(self._cancelled))


class TranslationItemDelegate(QStyledItemDelegate):
    """Делегат для колонки «Перевод» в редакторе перевода."""

    def __init__(self, dialog: TranslationEditorDialog):
        super().__init__(dialog)
        self._dlg = dialog

    def _on_translation_editor_text_changed(self):
        """Помечаем несохранённое сразу при вводе, не дожидаясь commit в модель."""
        try:
            dlg = getattr(self, "_dlg", None)
            if dlg is None:
                return
            if not bool(getattr(dlg, "_translation_edit_enabled", False)):
                return
            dlg._set_translation_dirty(True)
        except Exception:
            pass

    def createEditor(self, parent, option, index):
        editor = QTextEdit(parent)
        try:
            editor.setAcceptRichText(False)
            editor.setFrameStyle(QtWidgets.QFrame.NoFrame)
            editor.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            editor.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            editor.setLineWrapMode(QTextEdit.WidgetWidth)
            editor.setWordWrapMode(QTextOption.WrapAtWordBoundaryOrAnywhere)
            editor.installEventFilter(self)
            editor.textChanged.connect(self._on_translation_editor_text_changed)
        except Exception:
            pass
        wire_copy_paste_context_menu_for_text_edit(editor)
        return editor

    def setEditorData(self, editor, index):
        try:
            current = "" if index.data(Qt.DisplayRole) is None else str(index.data(Qt.DisplayRole))
            editor.setPlainText(current)
        except Exception:
            super().setEditorData(editor, index)

    def setModelData(self, editor, model, index):
        try:
            txt = str(editor.toPlainText())
            if not str(txt).strip():
                txt = ""
            model.setData(index, txt, Qt.EditRole)
        except Exception:
            super().setModelData(editor, model, index)

    def eventFilter(self, editor, event):
        """Enter -> сохранить и закрыть редактор, без вставки перевода строки."""
        try:
            if event is not None and event.type() == QEvent.KeyPress:
                try:
                    key = int(event.key())
                except Exception:
                    key = None
                try:
                    mods = event.modifiers()
                except Exception:
                    mods = None
                if key in (Qt.Key_Return, Qt.Key_Enter) and (mods == Qt.NoModifier or mods == QtCore.Qt.NoModifier):
                    try:
                        self.commitData.emit(editor)
                        self.closeEditor.emit(editor, QAbstractItemDelegate.NoHint)
                    except Exception:
                        pass
                    return True
        except Exception:
            pass
        try:
            return super().eventFilter(editor, event)
        except Exception:
            return False


class _ColorSVSquare(QWidget):
    """Квадрат насыщенность/яркость при фиксированном Hue."""

    colorChanged = pyqtSignal(int, int, int)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._hue = 0
        self._sat = 255
        self._val = 255
        self._dragging = False
        self._cache = None
        self._cache_hue = -1
        self._cache_size = QSize()
        self.setMinimumSize(160, 160)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        self.setMouseTracking(True)

    def hsv(self):
        return self._hue, self._sat, self._val

    def set_hsv(self, h, s, v):
        h = int(h) % 360
        s = max(0, min(255, int(s)))
        v = max(0, min(255, int(v)))
        if self._cache_hue != h:
            self._cache = None
        self._hue, self._sat, self._val = h, s, v
        self.update()

    def _ensure_cache(self):
        if (
            self._cache is not None
            and self._cache_hue == self._hue
            and self._cache_size == self.size()
        ):
            return
        w = max(1, self.width())
        h = max(1, self.height())
        img = QImage(w, h, QImage.Format_RGB32)
        for y in range(h):
            val = int((h - 1 - y) * 255 / max(1, h - 1))
            for x in range(w):
                sat = int(x * 255 / max(1, w - 1))
                img.setPixel(x, y, QColor.fromHsv(self._hue, sat, val).rgb())
        self._cache = img
        self._cache_hue = self._hue
        self._cache_size = QSize(w, h)

    def paintEvent(self, event):
        painter = QPainter(self)
        self._ensure_cache()
        if self._cache is not None:
            painter.drawImage(0, 0, self._cache)
        if self.width() > 1 and self.height() > 1:
            cx = int(self._sat * (self.width() - 1) / 255)
            cy = int((255 - self._val) * (self.height() - 1) / 255)
            painter.setPen(QPen(Qt.black if self._val > 128 else Qt.white, 1))
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(QPoint(cx, cy), 5, 5)

    def _pos_to_sv(self, pos):
        w = max(1, self.width() - 1)
        h = max(1, self.height() - 1)
        s = max(0, min(255, int(pos.x() * 255 / w)))
        v = max(0, min(255, int((h - pos.y()) * 255 / h)))
        return s, v

    def _pick_at(self, pos):
        s, v = self._pos_to_sv(pos)
        self._sat, self._val = s, v
        self.update()
        self.colorChanged.emit(self._hue, self._sat, self._val)

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self._dragging = True
            self._pick_at(event.pos())

    def mouseMoveEvent(self, event):
        if self._dragging:
            self._pick_at(event.pos())

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.LeftButton:
            self._dragging = False

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._cache = None


class _HueSlider(QWidget):
    """Ползунок Hue с радужной дорожкой."""

    valueChanged = pyqtSignal(int)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._value = 0
        self._dragging = False
        self.setFixedHeight(18)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)

    def value(self):
        return self._value

    def set_value(self, value):
        value = max(0, min(359, int(value)))
        if value == self._value:
            return
        self._value = value
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        rect = self.rect().adjusted(1, 1, -1, -1)
        grad = QLinearGradient(rect.left(), 0, rect.right(), 0)
        for i in range(7):
            hue = int(i * 360 / 6) % 360
            grad.setColorAt(i / 6.0, QColor.fromHsv(hue, 255, 255))
        painter.setPen(QPen(self.palette().mid(), 1))
        painter.setBrush(grad)
        painter.drawRect(rect)
        if rect.width() > 1:
            x = rect.left() + int(self._value * (rect.width() - 1) / 359)
            painter.setPen(QPen(Qt.black, 1))
            painter.drawLine(x, rect.top(), x, rect.bottom())

    def _value_from_pos(self, x):
        rect = self.rect().adjusted(1, 1, -1, -1)
        if rect.width() <= 1:
            return self._value
        rel = max(0, min(rect.width() - 1, int(x) - rect.left()))
        return int(rel * 359 / max(1, rect.width() - 1))

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self._dragging = True
            value = self._value_from_pos(event.pos().x())
            self.set_value(value)
            self.valueChanged.emit(self._value)

    def mouseMoveEvent(self, event):
        if self._dragging:
            value = self._value_from_pos(event.pos().x())
            self.set_value(value)
            self.valueChanged.emit(self._value)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.LeftButton:
            self._dragging = False


class _SaturationSlider(QWidget):
    """Ползунок насыщенности: от серого до текущего оттенка при фиксированной яркости."""

    valueChanged = pyqtSignal(int)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._hue = 0
        self._val = 255
        self._value = 255
        self._dragging = False
        self.setFixedHeight(18)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)

    def value(self):
        return self._value

    def set_context(self, hue, val):
        hue = int(hue) % 360
        val = max(0, min(255, int(val)))
        changed = self._hue != hue or self._val != val
        self._hue, self._val = hue, val
        if changed:
            self.update()

    def set_value(self, value):
        value = max(0, min(255, int(value)))
