class ThemeEditorColorPicker(QWidget):
    """Локальный выбор цвета: RGB, SV-квадрат, Hue, Value, Saturation."""

    colorChanged = pyqtSignal(QColor)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._block = False
        self._color = QColor("#808080")

        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)

        rgb_layout = QVBoxLayout()
        rgb_layout.setContentsMargins(0, 0, 0, 0)
        rgb_layout.setSpacing(2)

        self.r_slider = QSlider(Qt.Horizontal)
        self.g_slider = QSlider(Qt.Horizontal)
        self.b_slider = QSlider(Qt.Horizontal)
        for label, slider in (
            ("R", self.r_slider),
            ("G", self.g_slider),
            ("B", self.b_slider),
        ):
            row = QHBoxLayout()
            row.setContentsMargins(0, 0, 0, 0)
            row.setSpacing(8)
            name = QLabel(label)
            name.setFixedWidth(14)
            slider.setRange(0, 255)
            row.addWidget(name)
            row.addWidget(slider, 1)
            row_widget = QWidget()
            row_widget.setLayout(row)
            rgb_layout.addWidget(row_widget)

        layout.addLayout(rgb_layout)

        self.sv_square = _ColorSVSquare()
        layout.addWidget(self.sv_square, 1)

        self.hue_slider = _HueSlider()
        layout.addWidget(self.hue_slider)

        self.val_slider = _ValueSlider()
        layout.addWidget(self.val_slider)

        self.sat_slider = _SaturationSlider()
        layout.addWidget(self.sat_slider)

        self.sv_square.colorChanged.connect(self._on_sv_changed)
        self.hue_slider.valueChanged.connect(self._on_hue_changed)
        self.sat_slider.valueChanged.connect(self._on_sat_changed)
        self.val_slider.valueChanged.connect(self._on_val_changed)
        self.r_slider.valueChanged.connect(self._on_rgb_changed)
        self.g_slider.valueChanged.connect(self._on_rgb_changed)
        self.b_slider.valueChanged.connect(self._on_rgb_changed)

    def _sync_from_hsv(self, h, s, v):
        self.sv_square.set_hsv(h, s, v)
        self.hue_slider.set_value(h)
        self.sat_slider.set_context(h, v)
        self.sat_slider.set_value(s)
        self.val_slider.set_context(h, s)
        self.val_slider.set_value(v)
        c = QColor.fromHsv(h, s, v)
        self.r_slider.setValue(c.red())
        self.g_slider.setValue(c.green())
        self.b_slider.setValue(c.blue())
        return c

    def set_color(self, color):
        if self._block:
            return
        c = QColor(color)
        if not c.isValid():
            return
        self._block = True
        try:
            self._color = c
            h, s, v, _ = c.getHsv()
            if h < 0:
                h = 0
            if s < 0:
                s = 0
            if v < 0:
                v = 0
            self._sync_from_hsv(h, s, v)
        finally:
            self._block = False

    def _emit_color(self, color):
        if self._block:
            return
        c = QColor(color)
        if not c.isValid():
            return
        self._color = c
        self.colorChanged.emit(c)

    def _on_sv_changed(self, h, s, v):
        if self._block:
            return
        self._block = True
        try:
            c = self._sync_from_hsv(h, s, v)
        finally:
            self._block = False
        self._emit_color(c)

    def _on_hue_changed(self, h):
        if self._block:
            return
        _, s, v = self.sv_square.hsv()
        self._block = True
        try:
            c = self._sync_from_hsv(h, s, v)
        finally:
            self._block = False
        self._emit_color(c)

    def _on_sat_changed(self, s):
        if self._block:
            return
        h, _, v = self.sv_square.hsv()
        self._block = True
        try:
            c = self._sync_from_hsv(h, s, v)
        finally:
            self._block = False
        self._emit_color(c)

    def _on_val_changed(self, v):
        if self._block:
            return
        h, s, _ = self.sv_square.hsv()
        self._block = True
        try:
            c = self._sync_from_hsv(h, s, v)
        finally:
            self._block = False
        self._emit_color(c)

    def _on_rgb_changed(self, _value=None):
        if self._block:
            return
        self._block = True
        try:
            c = QColor(self.r_slider.value(), self.g_slider.value(), self.b_slider.value())
            h, s, v, _ = c.getHsv()
            if h < 0:
                h = 0
            if s < 0:
                s = 0
            if v < 0:
                v = 0
            self._sync_from_hsv(h, s, v)
        finally:
            self._block = False
        self._emit_color(c)


_SCREEN_PICKER_MAGNIFIER_PX = 150
_SCREEN_PICKER_ZOOM = 4
_SCREEN_PICKER_SAMPLE_LOGICAL_PX = _SCREEN_PICKER_MAGNIFIER_PX // _SCREEN_PICKER_ZOOM
_SCREEN_PICKER_CURSOR_OFFSET = QPoint(_MARGIN_ARROW_LOGICAL_PX - 1, -_SCREEN_PICKER_MAGNIFIER_PX - 16)


def _screen_picker_uses_fullscreen_input_layer():
    """macOS: кастомная пипетка заменена системным QColorDialog (см. _on_dropper_clicked)."""
    return sys.platform != "darwin"


_PORTAL_BUS = "org.freedesktop.portal.Desktop"
_PORTAL_PATH = "/org/freedesktop/portal/desktop"
_PORTAL_SCREENSHOT_IFACE = "org.freedesktop.portal.Screenshot"
_PORTAL_REQUEST_IFACE = "org.freedesktop.portal.Request"


def _is_linux_wayland_session():
    """True, если приложение запущено в Linux-сессии Wayland."""
    if not sys.platform.startswith("linux"):
        return False
    session_type = os.environ.get("XDG_SESSION_TYPE", "").strip().lower()
    if session_type == "wayland":
        return True
    if os.environ.get("WAYLAND_DISPLAY"):
        return True
    try:
        app = QGuiApplication.instance()
        if app is not None and app.platformName().lower() == "wayland":
            return True
    except Exception:
        pass
    return False


def _combo_global_points_wayland(combo):
    """Глобальные координаты combobox; на Wayland mapToGlobal иногда даёт origin окна."""
    try:
        win = combo.window()
        if win is not None and win is not combo:
            top_left = win.mapToGlobal(combo.mapTo(win, combo.rect().topLeft()))
            bottom_left = win.mapToGlobal(combo.mapTo(win, combo.rect().bottomLeft()))
        else:
            top_left = combo.mapToGlobal(combo.rect().topLeft())
            bottom_left = combo.mapToGlobal(combo.rect().bottomLeft())
        return top_left, bottom_left
    except Exception:
        return combo.mapToGlobal(QPoint(0, 0)), combo.mapToGlobal(QPoint(0, combo.height()))


def _combo_popup_screen_cap(combo, margin=6):
    """Максимальная высота списка QComboBox в пределах экрана (Wayland)."""
    try:
        global_top_left, global_bottom_left = _combo_global_points_wayland(combo)
        screen = (
            QGuiApplication.screenAt(global_bottom_left)
            or QGuiApplication.screenAt(global_top_left)
            or QGuiApplication.primaryScreen()
        )
        if screen is None:
            return 0, None
        avail = screen.availableGeometry()
        return int(max(80, avail.height() - 2 * margin)), avail
    except Exception:
        return 0, None


def _prepare_combo_popup_wayland(combo):
    """До showPopup: лимит высоты списка по экрану (Wayland)."""
    if not _is_linux_wayland_session():
        return
    try:
        view = combo.view()
        cap, _avail = _combo_popup_screen_cap(combo)
        if view is not None and cap > 0:
            view.setMinimumHeight(0)
            view.setMaximumHeight(int(cap))
    except Exception:
        pass


def _apply_combo_popup_wayland(combo):
    """После showPopup: только высота view, без popup.setGeometry (ломает ввод на Wayland)."""
    if not _is_linux_wayland_session():
        return False
    try:
        view = combo.view()
        if view is None:
            return False
        cap, _avail = _combo_popup_screen_cap(combo)
        if cap <= 0:
            return False
        view.setMinimumHeight(0)
        view.setMaximumHeight(int(cap))
        return True
    except Exception:
        return False


def _fix_combo_popup_geometry_wayland(combo):
    """Wayland: Qt может «схлопнуть» dropdown, если список не помещается на экране."""
    if not _is_linux_wayland_session():
        return
    _apply_combo_popup_wayland(combo)


def _qwindow_set_stays_on_top(widget, enable):
    """WindowStaysOnTopHint через QWindow.setFlag без пересоздания native-окна.

    Предпочтительный путь на Linux (X11 и Wayland): setWindowFlags() на Wayland
    пересоздаёт surface и часто игнорируется композитором.
    """
    try:
        wh = None
        if widget is not None and hasattr(widget, "_ensure_window_handle"):
            wh = widget._ensure_window_handle()
        elif widget is not None:
            wh = widget.windowHandle()
            if wh is None:
                try:
                    widget.winId()
                except Exception:
                    pass
                wh = widget.windowHandle()
        if wh is None or not hasattr(wh, "setFlag"):
            return False
        wh.setFlag(Qt.WindowStaysOnTopHint, bool(enable))
        if enable:
            if hasattr(widget, "raise_"):
                widget.raise_()
            if hasattr(widget, "activateWindow"):
                try:
                    widget.activateWindow()
                except Exception:
                    pass
        return True
    except Exception:
        return False


def _theme_editor_independent_window():
    """True — редактор тем как отдельное немодальное окно (parent=main); нужно на Wayland."""
    return _is_linux_wayland_session()


def _portal_parent_window_handle(widget):
    """Идентификатор окна для xdg-desktop-portal (parent_window)."""
    try:
        platform = QGuiApplication.platformName().lower()
        if platform == "wayland":
            # winId() на native Wayland в Qt5 ненадёжен; пустой handle безопаснее.
            return ""
        win = widget.windowHandle() if widget is not None else None
        if win is None and widget is not None:
            win = widget.window().windowHandle() if widget.window() is not None else None
        if win is None:
            return "x11:" if platform == "xcb" else ""
        wid = win.winId()
        if platform == "xcb":
            if wid:
                return f"x11:{int(wid):x}"
            return "x11:"
    except Exception:
        pass
    return ""


def _unwrap_dbus_value(value):
    if value is None:
        return None
    if isinstance(value, (str, int, float, bool, list, tuple, dict)):
        return value
    try:
        if hasattr(value, "variant"):
            return _unwrap_dbus_value(value.variant())
    except Exception:
        pass
    try:
        if isinstance(value, QtCore.QVariant):
            return _unwrap_dbus_value(value.value())
    except Exception:
        pass
    return value


def _portal_color_pick_available():
    """True, если xdg-desktop-portal Screenshot/PickColor доступен в сессии."""
    if not sys.platform.startswith("linux"):
        return False
    try:
        bus = QDBusConnection.sessionBus()
        if not bus.isConnected():
            return False
        portal = QDBusInterface(
            _PORTAL_BUS,
            _PORTAL_PATH,
            _PORTAL_SCREENSHOT_IFACE,
            bus,
        )
        return portal.isValid()
    except Exception:
        return False


def _parse_portal_color(results):
    """Разбирает results из org.freedesktop.portal.Request::Response (PickColor)."""
    data = _unwrap_dbus_value(results)
    if not isinstance(data, dict):
        try:
            data = dict(data)
        except Exception:
            return None
    raw = _unwrap_dbus_value(data.get("color"))
    if raw is None:
        return None
    if isinstance(raw, QColor):
        return raw if raw.isValid() else None
    if isinstance(raw, (list, tuple)) and len(raw) >= 3:
        try:
            return QColor.fromRgbF(float(raw[0]), float(raw[1]), float(raw[2]))
        except Exception:
            return None
    try:
        if hasattr(raw, "beginStructure"):
            raw.beginStructure()
            r = float(raw.next())
            g = float(raw.next())
            b = float(raw.next())
            raw.endStructure()
            return QColor.fromRgbF(r, g, b)
    except Exception:
        pass
    return None


def _screen_grab_likely_blocked(screen=None, global_pos=None):
    """True, если grabWindow, вероятно, не даёт реального содержимого (Wayland)."""
    if not _is_linux_wayland_session():
        return False
    if QGuiApplication.platformName().lower() == "xcb":
        return False
    pos = global_pos if global_pos is not None else QCursor.pos()
    screen = screen if screen is not None else _screen_at_global_pos(pos)
    pixmap, _color = _grab_magnifier_region(screen, pos)
    if pixmap is None or pixmap.isNull():
        return True
    img = pixmap.toImage()
    if img.isNull() or img.width() < 1 or img.height() < 1:
        return True
    sample_points = (
        (img.width() // 2, img.height() // 2),
        (0, 0),
        (max(0, img.width() - 1), max(0, img.height() - 1)),
    )
    first_rgb = None
    for x, y in sample_points:
        c = QColor(img.pixel(x, y))
        rgb = (c.red(), c.green(), c.blue())
        if first_rgb is None:
            first_rgb = rgb
        elif rgb != first_rgb:
            return False
    return first_rgb == (0, 0, 0)


class PortalColorRequest(QObject):
    """Асинхронный PickColor через xdg-desktop-portal с явной отменой и очисткой D-Bus."""

    colorPicked = pyqtSignal(QColor)
    cancelled = pyqtSignal()

    _TIMEOUT_MS = 120000

    def __init__(self, parent_window="", parent=None):
        super().__init__(parent)
        self._parent_window = parent_window or ""
        self._request_path = None
        self._pickcolor_watcher = None
        self._response_connected = False
        self._cancelled_locally = False
        self._bus = QDBusConnection.sessionBus()
        self._timeout_timer = QTimer(self)
        self._timeout_timer.setSingleShot(True)
        self._timeout_timer.timeout.connect(self._on_timeout)

    def start(self):
        """Запускает portal PickColor асинхронно. Возвращает False при немедленной ошибке."""
        if self._request_path is not None or self._pickcolor_watcher is not None:
            return True
        if not self._bus.isConnected():
            return False
        portal = QDBusInterface(
            _PORTAL_BUS,
            _PORTAL_PATH,
            _PORTAL_SCREENSHOT_IFACE,
            self._bus,
        )
        if not portal.isValid():
            return False
        self._cancelled_locally = False
        pending = portal.asyncCall("PickColor", self._parent_window, {})
        self._pickcolor_watcher = QDBusPendingCallWatcher(pending, self)
        self._pickcolor_watcher.finished.connect(self._on_pickcolor_call_finished)
        return True

    @pyqtSlot()
    def _on_pickcolor_call_finished(self):
        watcher = self.sender()
        if watcher is not None:
            try:
                watcher.finished.disconnect(self._on_pickcolor_call_finished)
            except Exception:
                pass
            try:
                watcher.deleteLater()
            except Exception:
                pass
        if self._pickcolor_watcher is watcher:
            self._pickcolor_watcher = None
        if self._cancelled_locally:
            return
        if watcher is None:
            self.cancelled.emit()
            return
        try:
            pending_reply = QDBusPendingReply(watcher)
            if pending_reply.isError():
                self.cancelled.emit()
                return
            request_handle = pending_reply.value()
            if request_handle is None:
                args = pending_reply.arguments()
                request_handle = args[0] if args else None
        except Exception:
            self.cancelled.emit()
            return
        if request_handle is None:
            self.cancelled.emit()
            return
        self._request_path = str(request_handle)
        if not self._connect_response():
            self._request_path = None
            self.cancelled.emit()
            return
        self._timeout_timer.start(self._TIMEOUT_MS)

    def _connect_response(self):
        if not self._request_path or self._response_connected:
            return bool(self._response_connected)
        for service in ("", _PORTAL_BUS):
            try:
                if self._bus.connect(
                    service,
                    self._request_path,
                    _PORTAL_REQUEST_IFACE,
                    "Response",
                    self._on_response,
                ):
                    self._response_connected = True
                    return True
            except Exception:
                pass
        return False

    def _handle_portal_response(self, response_code, results):
        if self._cancelled_locally or self._request_path is None:
            self._disconnect_response()
            return
        self._timeout_timer.stop()
        request_path = self._request_path
        self._disconnect_response()
        self._request_path = None
        self._close_request_path(request_path)
        if int(response_code) != 0:
            self.cancelled.emit()
            return
        color = _parse_portal_color(results)
        if color is None or not color.isValid():
            self.cancelled.emit()
            return
        self.colorPicked.emit(color)

    @pyqtSlot(QDBusMessage)
    def _on_response(self, message):
        try:
            args = message.arguments() if message is not None else []
            response_code = int(args[0]) if len(args) > 0 else -1
            results = args[1] if len(args) > 1 else {}
        except Exception:
            self.cancelled.emit()
            return
        self._handle_portal_response(response_code, results)

    def cancel(self):
        """Прерывает запрос без эмита сигналов (закрытие диалога / явная отмена)."""
        self._cancelled_locally = True
        self._timeout_timer.stop()
        watcher = self._pickcolor_watcher
        if watcher is not None:
            try:
                watcher.finished.disconnect(self._on_pickcolor_call_finished)
            except Exception:
                pass
            try:
                watcher.deleteLater()
            except Exception:
                pass
            self._pickcolor_watcher = None
        request_path = self._request_path
        self._disconnect_response()
        self._request_path = None
        if request_path:
            self._close_request_path(request_path)

    def _on_timeout(self):
        if self._request_path is None:
            return
        self.cancel()
        self.cancelled.emit()

    def _disconnect_response(self):
        if not self._response_connected or not self._request_path:
            self._response_connected = False
            return
        request_path = self._request_path
        for service in ("", _PORTAL_BUS):
            try:
                self._bus.disconnect(
                    service,
                    request_path,
                    _PORTAL_REQUEST_IFACE,
                    "Response",
                    self._on_response,
                )
            except Exception:
                pass
        self._response_connected = False

    def _close_request_path(self, request_path):
        if not request_path:
            return
        try:
            request_iface = QDBusInterface(
                _PORTAL_BUS,
                request_path,
                _PORTAL_REQUEST_IFACE,
                self._bus,
            )
            if request_iface.isValid():
                request_iface.call("Close")
        except Exception:
            pass


def _screen_at_global_pos(global_pos):
    """Возвращает QScreen под глобальной позицией курсора (поддержка отрицательных координат)."""
    try:
        if hasattr(QGuiApplication, "screenAt"):
            screen = QGuiApplication.screenAt(global_pos)
            if screen is not None:
                return screen
    except Exception:
        pass
    for screen in QGuiApplication.screens():
        try:
            if screen.geometry().contains(global_pos):
                return screen
        except Exception:
            continue
    try:
        return QGuiApplication.primaryScreen()
    except Exception:
        return None


def _grab_magnifier_region(screen, global_pos, *, hide_windows=()):
    """Локальный захват области вокруг курсора; центр — выбираемый пиксель (HiDPI-aware).

    hide_windows — временно скрыть top-level окна пипетки перед grab (macOS: иначе в кадр
    попадает полноэкранный input-layer вместо рабочего стола).
    """
    if screen is None:
        return None, QColor()

    hidden = []
    for widget in hide_windows or ():
        try:
            if widget is not None and widget.isVisible():
                widget.hide()
                hidden.append(widget)
        except Exception:
            pass
    if hidden:
        try:
            QApplication.processEvents(QEventLoop.AllEvents, 50)
        except Exception:
            pass

    try:
        geometry = screen.geometry()
        dpr = float(screen.devicePixelRatio() or 1.0)
        sample_logical = _SCREEN_PICKER_SAMPLE_LOGICAL_PX
        half = sample_logical // 2

        local_x = global_pos.x() - geometry.x()
        local_y = global_pos.y() - geometry.y()
        grab_left = local_x - half
        grab_top = local_y - half

        full_w = max(1, int(sample_logical * dpr))
        full_h = max(1, int(sample_logical * dpr))
        canvas = QImage(full_w, full_h, QImage.Format_ARGB32)
        canvas.fill(QColor(0, 0, 0, 255))

        src_left = max(0.0, grab_left)
        src_top = max(0.0, grab_top)
        src_right = min(float(geometry.width()), grab_left + sample_logical)
        src_bottom = min(float(geometry.height()), grab_top + sample_logical)

        if src_right > src_left and src_bottom > src_top:
            sw = max(1, int((src_right - src_left) * dpr))
            sh = max(1, int((src_bottom - src_top) * dpr))
            grabbed = screen.grabWindow(0, int(src_left * dpr), int(src_top * dpr), sw, sh)
            if grabbed.isNull():
                grabbed = screen.grabWindow(
                    0,
                    int(src_left),
                    int(src_top),
                    max(1, int(src_right - src_left)),
                    max(1, int(src_bottom - src_top)),
                )
            if not grabbed.isNull():
                dest_x = int((src_left - grab_left) * dpr)
                dest_y = int((src_top - grab_top) * dpr)
                painter = QPainter(canvas)
                try:
                    painter.drawImage(dest_x, dest_y, grabbed.toImage())
                finally:
                    painter.end()

        pick_x = max(0, min(canvas.width() - 1, int(half * dpr)))
        pick_y = max(0, min(canvas.height() - 1, int(half * dpr)))
        color = QColor(canvas.pixel(pick_x, pick_y))

        pixmap = QPixmap.fromImage(canvas)
        pixmap.setDevicePixelRatio(dpr)
        return pixmap, color
    finally:
        for widget in hidden:
            try:
                widget.show()
            except Exception:
                pass


def _clamp_picker_overlay_global_pos(global_pos, cursor_offset, overlay_size):
    """Держит лупу на экране (macOS: иначе y<0 → «outside any known screen» и сбои ввода)."""
    try:
        pos = QPoint(global_pos) + cursor_offset
    except Exception:
        return global_pos
    screen = _screen_at_global_pos(global_pos)
    if screen is None:
        return pos
    try:
        geo = screen.geometry()
        w = max(1, int(overlay_size.width()))
        h = max(1, int(overlay_size.height()))
        x = max(int(geo.left()), min(int(pos.x()), int(geo.right()) - w + 1))
        y = max(int(geo.top()), min(int(pos.y()), int(geo.bottom()) - h + 1))
        return QPoint(x, y)
    except Exception:
        return pos


def _virtual_desktop_geometry():
    """Объединённая геометрия всех экранов (включая отрицательные координаты)."""
    rect = QRect()
    for screen in QGuiApplication.screens():
        try:
            rect = rect.united(screen.geometry())
        except Exception:
            continue
    if rect.isNull():
        try:
            screen = QGuiApplication.primaryScreen()
            if screen is not None:
                return screen.geometry()
        except Exception:
            pass
        return QRect(0, 0, 1920, 1080)
    return rect


class _ScreenPickerInputLayer(QWidget):
    """Почти невидимый слой на весь виртуальный рабочий стол — глобальный перехват мыши и ESC."""

    pickRequested = pyqtSignal()
    cancelRequested = pyqtSignal()
    cursorMoved = pyqtSignal(QPoint)

    def __init__(self):
        super().__init__(
            None,
            Qt.Window
            | Qt.FramelessWindowHint
            | Qt.WindowStaysOnTopHint
            | Qt.Tool,
        )
        self.setAttribute(Qt.WA_TranslucentBackground, True)
        self.setMouseTracking(True)
        self.setFocusPolicy(Qt.StrongFocus)

    def show_global(self):
        self.setGeometry(_virtual_desktop_geometry())
        self.show()
        self.raise_()
        self.activateWindow()
        self.setFocus(Qt.ActiveWindowFocusReason)
        try:
            self.grabMouse()
        except Exception:
            pass
        # macOS: grabKeyboard() часто блокирует Esc и закрытие приложения; клавиши — через eventFilter.
        if sys.platform != "darwin":
            try:
                self.grabKeyboard()
            except Exception:
                pass

    def hide_global(self):
        try:
            if self.mouseGrabber() is self:
                self.releaseMouse()
        except Exception:
            pass
        try:
            if sys.platform != "darwin":
                self.releaseKeyboard()
        except Exception:
            pass
        self.hide()

    def paintEvent(self, event):
        # alpha=1: на Windows иначе клики проходят «сквозь» окно к окнам ниже
        painter = QPainter(self)
        painter.fillRect(self.rect(), QColor(0, 0, 0, 1))

    def mouseMoveEvent(self, event):
        self.cursorMoved.emit(event.globalPos())
        event.accept()

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.pickRequested.emit()
            event.accept()
            return
        if event.button() == Qt.RightButton:
            self.cancelRequested.emit()
            event.accept()
            return
        super().mousePressEvent(event)

    def keyPressEvent(self, event):
        if event.key() == Qt.Key_Escape:
            self.cancelRequested.emit()
            event.accept()
            return
        super().keyPressEvent(event)


class ScreenColorPickerOverlay(QWidget):
    """Окно экранной лупы 150×150 с перекрестием в центре."""

    def __init__(self):
        super().__init__(
            None,
            Qt.Window
            | Qt.Tool
            | Qt.FramelessWindowHint
            | Qt.WindowStaysOnTopHint
            | Qt.WindowDoesNotAcceptFocus,
        )
        self.setAttribute(Qt.WA_ShowWithoutActivating, True)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setFixedSize(_SCREEN_PICKER_MAGNIFIER_PX, _SCREEN_PICKER_MAGNIFIER_PX)
        self._magnified = QPixmap()
        self.setWindowOpacity(0.94)

    def set_magnified_pixmap(self, pixmap):
        self._magnified = pixmap if pixmap is not None else QPixmap()
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.fillRect(self.rect(), QColor(24, 24, 24, 235))
        if not self._magnified.isNull():
            painter.drawPixmap(
                0,
                0,
                self._magnified.scaled(
                    self.size(),
                    Qt.IgnoreAspectRatio,
                    Qt.FastTransformation,
                ),
            )
        cx = self.width() // 2
        cy = self.height() // 2
        painter.setPen(QPen(QColor(0, 0, 0), 1))
        painter.drawLine(cx, 0, cx, self.height())
        painter.drawLine(0, cy, self.width(), cy)
        painter.setPen(QPen(QColor(255, 255, 255), 1))
        painter.drawLine(cx + 1, 0, cx + 1, self.height())
        painter.drawLine(0, cy + 1, self.width(), cy + 1)


class ScreenColorPicker(QObject):
    """Экранная пипетка с лупой (кроссплатформенный захват через QScreen.grabWindow)."""

    colorPicked = pyqtSignal(QColor)
    cancelled = pyqtSignal()

    def __init__(self, parent=None):
        super().__init__(parent)
        # Top-level окна без QWidget-родителя (PyQt5); lifecycle — через _teardown().
        self._overlay = ScreenColorPickerOverlay()
        self._input_layer = _ScreenPickerInputLayer()
        self._input_layer.cursorMoved.connect(self._update_at)
        self._input_layer.pickRequested.connect(self._finish_pick)
        self._input_layer.cancelRequested.connect(self._cancel_pick)
        self._poll_timer = QTimer(self)
        self._poll_timer.setInterval(16)
        self._poll_timer.timeout.connect(self._poll_cursor)
        self._active = False
        self._teardown_done = False
        self._cursor_offset = QPoint(_SCREEN_PICKER_CURSOR_OFFSET)
        self._current_color = QColor()
        self._last_global_pos = None
        self._capture_warned = False
        self._cursor_applied = False
        self._saved_dialog_modality = None
        self._left_button_was_down = False
        self._right_button_was_down = False
        self._esc_shortcut = None
        self._saved_modalities = []
        self._parent_esc_block_until = 0.0
        if parent is not None:
            try:
                parent.destroyed.connect(self._on_owner_destroyed)
            except Exception:
                pass

    def is_active(self):
        return bool(self._active)

    def cancel(self):
        """Отмена режима пипетки (Esc / ПКМ)."""
        self._cancel_pick()

    def start(self):
        """Запускает режим пипетки. Возвращает False, если захват экрана недоступен."""
        if self._active:
            return True
        if _screen_grab_likely_blocked():
            if not self._capture_warned:
                print(
                    "Warning: Screen color picker unavailable — screen capture blocked "
                    "(typical on Linux Wayland). Use the portal color picker or QColorDialog."
                )
                self._capture_warned = True
            return False
        test_pos = QCursor.pos()
        screen = _screen_at_global_pos(test_pos)
        pixmap, _color = _grab_magnifier_region(screen, test_pos)
        if pixmap is None or pixmap.isNull():
            if not self._capture_warned:
                print(
                    "Warning: Screen color picker unavailable — QScreen.grabWindow() returned empty pixmap. "
                    "On Linux Wayland screen capture is often restricted by the compositor; use X11 session if needed."
                )
                self._capture_warned = True
            return False

        self._active = True
        self._last_global_pos = None
        self._left_button_was_down = bool(QApplication.mouseButtons() & Qt.LeftButton)
        self._right_button_was_down = bool(QApplication.mouseButtons() & Qt.RightButton)
        self._release_dialog_modal_block()
        self._install_esc_cancel_shortcut()
        app = QApplication.instance()
        if app is not None:
            app.installEventFilter(self)
            if sys.platform == "darwin" and not getattr(self, "_about_to_quit_connected", False):
                try:
                    app.aboutToQuit.connect(self._on_app_about_to_quit)
                    self._about_to_quit_connected = True
                except Exception:
                    pass
        input_layer = getattr(self, "_input_layer", None)
        overlay = getattr(self, "_overlay", None)
        if input_layer is None or overlay is None:
            self.stop()
            return False
        if _screen_picker_uses_fullscreen_input_layer():
            input_layer.show_global()
        self._apply_picker_cursor()
        self._update_at(test_pos)
        overlay.show()
        self._raise_picker_windows()
        self._poll_timer.start()
        return True

    def stop(self):
        """Выход из активного режима; идемпотентно снимает grab/filter/cursor."""
        self._active = False
        try:
            self._poll_timer.stop()
        except Exception:
            pass
        input_layer = getattr(self, "_input_layer", None)
        if input_layer is not None:
            try:
                input_layer.hide_global()
            except Exception:
                pass
        overlay = getattr(self, "_overlay", None)
        if overlay is not None:
            try:
                overlay.hide()
            except Exception:
                pass
        app = QApplication.instance()
        if app is not None:
            try:
                app.removeEventFilter(self)
            except Exception:
                pass
        self._remove_esc_cancel_shortcut()
        self._restore_dialog_modal_block()
        self._restore_cursor()

    def _on_app_about_to_quit(self):
        try:
            if self._active:
                self.stop()
        except Exception:
            pass

    def _teardown(self):
        """Гарантированная очистка при закрытии владельца (диалога редактора тем)."""
        if getattr(self, "_teardown_done", False):
            return
        self._teardown_done = True
        self.stop()
        for attr in ("_input_layer", "_overlay"):
            widget = getattr(self, attr, None)
            if widget is None:
                continue
            try:
                widget.deleteLater()
            except Exception:
                pass
            setattr(self, attr, None)

    def _on_owner_destroyed(self, _obj=None):
        try:
            self._teardown()
        except Exception:
            pass

    def parent_should_ignore_esc(self):
        return time.monotonic() < float(getattr(self, "_parent_esc_block_until", 0.0))

    def _install_esc_cancel_shortcut(self):
        # macOS: Esc через eventFilter; QShortcut дублирует и закрывает редактор тем.
        if sys.platform == "darwin":
            return
        self._remove_esc_cancel_shortcut()
        parent = self.parent()
        if not isinstance(parent, QWidget):
            parent = QApplication.activeWindow()
        if not isinstance(parent, QWidget):
            return
        shortcut = QShortcut(QKeySequence(Qt.Key_Escape), parent)
        if sys.platform == "darwin":
            shortcut.setContext(Qt.ApplicationShortcut)
        else:
            shortcut.setContext(Qt.WidgetWithChildrenShortcut)
        shortcut.activated.connect(self._cancel_pick)
        self._esc_shortcut = shortcut

    def _remove_esc_cancel_shortcut(self):
        shortcut = self._esc_shortcut
        self._esc_shortcut = None
        if shortcut is None:
            return
        try:
            shortcut.activated.disconnect(self._cancel_pick)
        except Exception:
            pass
        try:
            shortcut.deleteLater()
        except Exception:
            pass

    def _release_dialog_modal_block(self):
        """Снимает модальность цепочки QDialog (редактор тем ← настройки) на время кастомной пипетки."""
        self._saved_modalities = []
        widget = self.parent()
        while widget is not None:
            if isinstance(widget, QDialog):
                try:
                    self._saved_modalities.append((widget, widget.windowModality()))
                    widget.setWindowModality(Qt.NonModal)
                except Exception:
                    pass
            widget = widget.parentWidget()

    def _restore_dialog_modal_block(self):
        for widget, modality in list(getattr(self, "_saved_modalities", []) or []):
            try:
                widget.setWindowModality(modality)
            except Exception:
                pass
        self._saved_modalities = []

    def _raise_picker_windows(self):
        if _screen_picker_uses_fullscreen_input_layer():
            input_layer = getattr(self, "_input_layer", None)
            if input_layer is not None:
                input_layer.raise_()
        overlay = getattr(self, "_overlay", None)
        if overlay is not None:
            overlay.raise_()

    def _poll_cursor(self):
        if not self._active:
            return
        self._raise_picker_windows()
        global_pos = QCursor.pos()
        self._update_at(global_pos)

        buttons = QApplication.mouseButtons()
        left_down = bool(buttons & Qt.LeftButton)
        right_down = bool(buttons & Qt.RightButton)

        if right_down and not self._right_button_was_down:
            self._cancel_pick()
            return

        if left_down and not self._left_button_was_down:
            self._finish_pick()
            return

        self._left_button_was_down = left_down
        self._right_button_was_down = right_down

    def _apply_picker_cursor(self):
        if self._cursor_applied:
            return
        try:
            cursor = get_picker_margin_arrow_cursor()
        except Exception:
            cursor = QCursor(Qt.CrossCursor)
        if _screen_picker_uses_fullscreen_input_layer():
            input_layer = getattr(self, "_input_layer", None)
            if input_layer is not None:
                try:
                    input_layer.setCursor(cursor)
                except Exception:
                    pass
        else:
            try:
                QApplication.setOverrideCursor(cursor)
            except Exception:
                pass
        self._cursor_applied = True

    def _restore_cursor(self):
        if not self._cursor_applied:
            return
        if _screen_picker_uses_fullscreen_input_layer():
            input_layer = getattr(self, "_input_layer", None)
            if input_layer is not None:
                try:
                    input_layer.unsetCursor()
                except Exception:
                    pass
        else:
            try:
                while QApplication.overrideCursor() is not None:
                    QApplication.restoreOverrideCursor()
            except Exception:
                pass
        self._cursor_applied = False

    def _picker_windows_to_hide_for_grab(self):
        # Лупа смещена от hotspot; на macOS input-layer не показывается — hide не нужен.
        return ()

    def _update_at(self, global_pos):
        if global_pos is None:
            return
        if self._last_global_pos is not None and self._last_global_pos == global_pos:
            return
        self._last_global_pos = QPoint(global_pos)

        pick_pos = _picker_pick_global_pos(global_pos)
        screen = _screen_at_global_pos(pick_pos)
        pixmap, color = _grab_magnifier_region(
            screen,
            pick_pos,
            hide_windows=self._picker_windows_to_hide_for_grab(),
        )
        if pixmap is None or pixmap.isNull():
            return

        self._current_color = color
        overlay = getattr(self, "_overlay", None)
        if overlay is None:
            return
        overlay.set_magnified_pixmap(pixmap)
        # Лупа привязана к QCursor.pos(), не к pick_pos — иначе уезжает от курсора.
        overlay.move(
            _clamp_picker_overlay_global_pos(
                global_pos,
                self._cursor_offset,
                overlay.size(),
            )
        )

    def _finish_pick(self):
        if not self._active:
            return
        self._last_global_pos = None
        self._update_at(QCursor.pos())
        color = QColor(self._current_color)
        self.stop()
        if color.isValid():
            self.colorPicked.emit(color)

    def _cancel_pick(self):
        if not self._active:
            return
        self._parent_esc_block_until = time.monotonic() + 0.35
        self.stop()
        self.cancelled.emit()

    def _event_target_in_parent_dialog(self, obj):
        parent = self.parent()
        if not isinstance(parent, QWidget):
            return True
        if obj is parent:
            return True
        try:
            return parent.isAncestorOf(obj)
        except Exception:
            return False

    @staticmethod
    def _is_escape_key_event(event):
        if event.type() not in (QEvent.KeyPress, QEvent.ShortcutOverride):
            return False
        try:
            return event.key() == Qt.Key_Escape
        except Exception:
            return False

    def eventFilter(self, obj, event):
        if not self._active:
            return False

        if self._is_escape_key_event(event):
            self._cancel_pick()
            try:
                event.accept()
            except Exception:
                pass
            if event.type() == QEvent.ShortcutOverride:
                event.accept()
            return True

        if isinstance(event, QMouseEvent):
            et = event.type()
            if et == QEvent.MouseButtonPress:
                if event.button() == Qt.RightButton:
                    self._cancel_pick()
                    event.accept()
                    return True
                if event.button() == Qt.LeftButton:
                    if not self._left_button_was_down:
                        self._finish_pick()
                    self._left_button_was_down = True
                    event.accept()
                    return True
            if et == QEvent.MouseButtonRelease:
                if event.button() == Qt.LeftButton:
                    self._left_button_was_down = False
                elif event.button() == Qt.RightButton:
                    self._right_button_was_down = False

        return False


class ThemeEditorDialog(ThemedFramelessDialog):
    """Редактор тем: working_theme_name (ComboBox) — единственный источник истины для preview/apply/save."""

    parameterSelected = pyqtSignal(str)
    colorChanged = pyqtSignal(QColor)

    def __init__(self, parent=None, *, independent_window=None):
        super().__init__(parent, resizable=True, content_margins=(10, 10, 10, 10))
        self.setWindowTitle(tr("theme_editor.title", "Редактор тем"))
        if independent_window is None:
            independent_window = _theme_editor_independent_window()
        self._independent_window = bool(independent_window)
        # На Wayland модальный QDialog с parent «прилипает» к главному окну;
        # на остальных платформах модальный режим (parent=настройки) работает корректно.
        self.setModal(not self._independent_window)
        self.resize_for_content(760, 520)
        self.setMinimumSize(480, 360 + self.chrome_extra_height_px())

        self._theme_manager = ThemeManager.instance()
        if self._theme_manager.is_session_dirty():
            self.working_theme_name = self._theme_manager.session_theme_name()
            self.working_theme = self._theme_manager.session_working_dict()
            self.is_modified = True
            self._selected_parameter_key = self._theme_manager.session_selected_parameter_key()
        else:
            self.working_theme_name = self._theme_manager.current_theme_name()
            self.working_theme = self._theme_manager.create_working_copy(self.working_theme_name)
            self.is_modified = False
            self._selected_parameter_key = None
        self._modified_keys = set()
        self.has_applied_changes = False

        self.current_color = QColor("#808080")
        self._syncing_color = False
        self._screen_color_picker = ScreenColorPicker(self)
        self._portal_request = None
        self._portal_saved_modality = None
        self._close_confirming = False

        content_layout = self.content_layout()
        columns_layout = QHBoxLayout()
        columns_layout.setSpacing(12)

        # --- Левая колонка (2/3): тема и список параметров ---
        left_layout = QVBoxLayout()
        left_layout.setSpacing(8)

        self.theme_combo = QComboBox()
        self._populate_theme_combo(self.working_theme_name)
        self.theme_combo.currentIndexChanged.connect(self._on_theme_combo_changed)
        left_layout.addWidget(self.theme_combo)

        self.param_list = QListView()
        self.param_list.setSelectionMode(QAbstractItemView.SingleSelection)
        self.param_list.setEditTriggers(QAbstractItemView.NoEditTriggers)
        self._param_model = QStandardItemModel(self)
        self.param_list.setModel(self._param_model)
        self.param_list.selectionModel().currentChanged.connect(self._on_parameter_changed)
        left_layout.addWidget(self.param_list, 1)

        save_row = QHBoxLayout()
        save_row.addStretch()
        self.save_button = QPushButton(tr("tr_dialog.save", "Сохранить"))
        self.save_button.setEnabled(False)
        self.save_button.clicked.connect(self._on_save_clicked)
        self.save_as_button = QPushButton(tr("theme_editor.save_as", "Сохранить как..."))
        self.save_as_button.setEnabled(True)
        self.save_as_button.clicked.connect(self._on_save_as_clicked)
        save_row.addWidget(self.save_button)
        save_row.addWidget(self.save_as_button)
        left_layout.addLayout(save_row)

        left_widget = QWidget()
        left_widget.setLayout(left_layout)
        left_widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        columns_layout.addWidget(left_widget, 2)

        # --- Правая колонка (1/3): инструменты цвета ---
        right_layout = QVBoxLayout()
        right_layout.setSpacing(8)

        color_row = QHBoxLayout()
        color_row.setSpacing(8)

        self.dropper_button = QToolButton()
        self.dropper_button.setIcon(IconManager.instance().icon("dropper"))
        self.dropper_button.setToolTip(tr("theme_editor.dropper", "Пипетка"))
        self.dropper_button.setAutoRaise(True)
        self.dropper_button.clicked.connect(self._on_dropper_clicked)
        self._screen_color_picker.colorPicked.connect(self._on_screen_color_picked)
        color_row.addWidget(self.dropper_button)

        self.color_swatch = QLabel()
        self.color_swatch.setFixedSize(28, 28)
        self.color_swatch.setFrameStyle(QtWidgets.QFrame.Panel | QtWidgets.QFrame.Sunken)
        color_row.addWidget(self.color_swatch)

        self.hex_edit = QLineEdit()
        self.hex_edit.setMaxLength(7)
        try:
            self.hex_edit.setContextMenuPolicy(Qt.CustomContextMenu)
            self.hex_edit.customContextMenuRequested.connect(
                lambda pos, e=self.hex_edit: show_copy_paste_context_menu_for_line_edit(e, pos)
            )
        except Exception:
            pass
        color_row.addWidget(self.hex_edit, 1)

        self.apply_button = QPushButton(tr("theme_editor.apply", "Применить"))
        self.apply_button.setEnabled(False)
        self.apply_button.clicked.connect(self._on_apply_clicked)
        color_row.addWidget(self.apply_button)

        right_layout.addLayout(color_row)

        self.color_picker = ThemeEditorColorPicker()
        self.color_picker.colorChanged.connect(self._on_picker_color_changed)
        right_layout.addWidget(self.color_picker, 1)

        action_row = QHBoxLayout()
        action_row.addStretch()
        self.ok_button = QPushButton(tr("dialog.button_ok", "ОК"))
        self.ok_button.clicked.connect(self._on_ok_clicked)
        self.cancel_button = QPushButton(tr("dialog.button_cancel", "Отмена"))
        self.cancel_button.clicked.connect(self._on_cancel_clicked)
        action_row.addWidget(self.ok_button)
        action_row.addWidget(self.cancel_button)
        right_layout.addLayout(action_row)

        right_widget = QWidget()
        right_widget.setLayout(right_layout)
        right_widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        columns_layout.addWidget(right_widget, 1)
        content_layout.addLayout(columns_layout, 1)

        self.hex_edit.textChanged.connect(self._on_hex_text_changed)
        self.hex_edit.editingFinished.connect(self._on_hex_editing_finished)

        self._rebuild_param_list(select_first=not self._selected_parameter_key)
        self._load_color_for_selected_parameter()
        if self.is_modified:
            self.apply_button.setEnabled(True)
            self.save_button.setEnabled(True)

    def _initial_focus_widget(self):
        return getattr(self, "save_as_button", None)

    @staticmethod
    def _format_hex(color):
        return f"#{color.red():02X}{color.green():02X}{color.blue():02X}"

    @staticmethod
    def _parse_hex(text):
        raw = str(text or "").strip().lstrip("#")
        if len(raw) == 6 and all(ch in "0123456789abcdefABCDEF" for ch in raw):
            return QColor(f"#{raw}")
        if len(raw) == 3 and all(ch in "0123456789abcdefABCDEF" for ch in raw):
            return QColor(f"#{raw[0] * 2}{raw[1] * 2}{raw[2] * 2}")
        return QColor()

    _HEX_EDIT_ERROR_TEXT_COLOR = "#FF0000"

    @classmethod
    def _is_complete_hex_field_text(cls, text):
        """True для завершённого ввода #RGB (4) или #RRGGBB (7)."""
        stripped = str(text or "").strip()
        if len(stripped) not in (4, 7):
            return False
        return stripped.startswith("#")

    def _set_hex_edit_error_highlight(self, invalid):
        if invalid:
            color = self._HEX_EDIT_ERROR_TEXT_COLOR
            self.hex_edit.setStyleSheet(f"QLineEdit {{ color: {color}; }}")
        else:
            self.hex_edit.setStyleSheet("")

    @staticmethod
    def _is_builtin_theme(theme_name):
        return str(theme_name) in ThemeManager.instance().builtin_themes()

    def _theme_combo_value(self, index=None):
        if index is None:
            index = self.theme_combo.currentIndex()
        if index < 0:
            return None
        return self.theme_combo.itemData(index)

    def _populate_theme_combo(self, select_name=None):
        select_name = select_name or self._theme_manager.current_theme_name()
        if select_name != "light":
            select_name = self._theme_manager._normalize_custom_theme_filename(select_name) or select_name
        self.theme_combo.blockSignals(True)
        self.theme_combo.clear()
        self.theme_combo.addItem(
            tr("theme_editor.new_theme", "Новая тема"),
            "light",
        )
        for label, data in build_custom_theme_combo_entries():
            self.theme_combo.addItem(label, data)
        for index in range(self.theme_combo.count()):
            if self.theme_combo.itemData(index) == select_name:
                self.theme_combo.setCurrentIndex(index)
                break
        self.theme_combo.blockSignals(False)

    def _rebuild_param_list(self, select_first=False, select_key=None):
        selected_key = select_key or self._selected_parameter_key
        self._param_model.clear()
        for row_index, key in enumerate(self._theme_manager.available_theme_keys(), start=1):
            label = self._theme_manager.theme_label(key)
            item = QStandardItem(f"{row_index}. {label}")
            item.setData(key, Qt.UserRole)
            self._param_model.appendRow(item)
        if select_first and self._param_model.rowCount() > 0:
            self.param_list.setCurrentIndex(self._param_model.index(0, 0))
            self._selected_parameter_key = self._param_model.item(0).data(Qt.UserRole)
        elif selected_key:
            for row in range(self._param_model.rowCount()):
                item = self._param_model.item(row)
                if item and item.data(Qt.UserRole) == selected_key:
                    self.param_list.setCurrentIndex(self._param_model.index(row, 0))
                    self._selected_parameter_key = selected_key
                    break

    def _mark_modified(self):
        self.is_modified = True
        if self._selected_parameter_key:
            self._modified_keys.add(self._selected_parameter_key)
        self.apply_button.setEnabled(True)
        self.save_button.setEnabled(True)

    def _clear_modified_state(self):
        self.is_modified = False
        self.apply_button.setEnabled(False)
        self.save_button.setEnabled(False)

    def _load_working_theme(self, theme_name):
        self.working_theme_name = str(theme_name)
        self.working_theme = self._theme_manager.create_working_copy(self.working_theme_name)
        self._modified_keys.clear()
        self._clear_modified_state()
        self._rebuild_param_list(select_first=not self._selected_parameter_key)
        self._load_color_for_selected_parameter()

    def _theme_base_for_editor(self, theme_name=None):
        theme_name = theme_name or self.working_theme_name
        return self._theme_manager.build_full_theme(theme_name)

    def _editor_theme_dict(self):
        """Полная тема выбранная в ComboBox + правки из working_theme."""
        return self._theme_manager.build_full_theme(self.working_theme_name, self.working_theme)

    def _has_unsaved_session(self):
        return bool(self._theme_manager.is_session_dirty())

    def _commit_color_changes_to_session(self):
        self._theme_manager.set_session_dirty(
            self.working_theme_name,
            dict(self.working_theme),
            selected_parameter_key=self._selected_parameter_key,
        )

    def _revert_to_last_saved_and_resync(self):
        """Откат к последнему сохранённому (ini/файл на диске) и синхронизация UI редактора."""
        app = QApplication.instance()
        self._theme_manager.revert_to_ini_active(app)
        ini_name = self._theme_manager.ini_active_theme_name()
        self.working_theme_name = str(ini_name or "light")
        self.working_theme = self._theme_manager.create_working_copy(self.working_theme_name)
        self._modified_keys.clear()
        self._clear_modified_state()
        self.has_applied_changes = False
        self._populate_theme_combo(self.working_theme_name)
        self._rebuild_param_list(select_first=not self._selected_parameter_key)
        self._load_color_for_selected_parameter()
        self._update_dropper_button_icon()

    def _apply_editor_theme_to_app(self, *, preview_only=False):
        """Применяет тему редактора (ComboBox + правки) к приложению без записи в Setting.ini."""
        app = QApplication.instance()
        self._theme_manager.apply_theme_dict(
            self.working_theme_name,
            self._editor_theme_dict(),
            app,
        )
        self._update_dropper_button_icon()
        if not preview_only:
            self.has_applied_changes = True

    def _update_dropper_button_icon(self):
        try:
            self.dropper_button.setIcon(IconManager.instance().icon("dropper"))
        except Exception:
            pass

    def _load_color_for_selected_parameter(self):
        key = self._selected_parameter_key
        if not key:
            return
        value = self.working_theme.get(key)
        if value is None:
            value = self._theme_base_for_editor().get(key, "#808080")
        color = _qcolor_from_theme_value(value)
        if not color.isValid():
            color = QColor("#808080")
        self._set_current_color(color, source="parameter", update_working=False)

    def _set_current_color(self, color, source=None, update_working=True):
        c = QColor(color)
        if not c.isValid():
            return
        self.current_color = c
        self._sync_color_widgets(source=source)
        if update_working and self._selected_parameter_key:
            new_hex = self._format_hex(self.current_color)
            if self.working_theme.get(self._selected_parameter_key) != new_hex:
                self.working_theme[self._selected_parameter_key] = new_hex
                _sync_mirrored_theme_keys(self.working_theme)
                self._mark_modified()
        self.colorChanged.emit(self.current_color)

    def _sync_color_widgets(self, source=None):
        if self._syncing_color:
            return
        self._syncing_color = True
        try:
            if source != "swatch":
                self.color_swatch.setStyleSheet(
                    f"background-color: {self._format_hex(self.current_color)};"
                )
            if source != "hex":
                self.hex_edit.blockSignals(True)
                self.hex_edit.setText(self._format_hex(self.current_color))
                self._set_hex_edit_error_highlight(False)
                self.hex_edit.blockSignals(False)
            if source != "color_picker":
                self.color_picker.set_color(self.current_color)
        finally:
            self._syncing_color = False

    def _on_picker_color_changed(self, color):
        self._set_current_color(color, source="color_picker")

    def _on_hex_text_changed(self, text):
        if self._syncing_color:
            return
        if not self._is_complete_hex_field_text(text):
            self._set_hex_edit_error_highlight(False)
            return
        parsed = self._parse_hex(text)
        if parsed.isValid():
            self._set_hex_edit_error_highlight(False)
            self._set_current_color(parsed, source="hex")
        else:
            self._set_hex_edit_error_highlight(True)

    def _on_hex_editing_finished(self):
        if self._syncing_color:
            return
        text = self.hex_edit.text()
        parsed = self._parse_hex(text)
        if parsed.isValid():
            self._set_hex_edit_error_highlight(False)
            formatted = self._format_hex(parsed)
            if formatted != self._format_hex(self.current_color):
                self._set_current_color(parsed, source="hex")
            return
        self._set_hex_edit_error_highlight(False)
        self.hex_edit.blockSignals(True)
        self.hex_edit.setText(self._format_hex(self.current_color))
        self.hex_edit.blockSignals(False)

    def _on_parameter_changed(self, current, _previous):
        if current is None or not current.isValid():
            self._selected_parameter_key = None
            return
        item = self._param_model.itemFromIndex(current)
        if item is None:
            return
        self._selected_parameter_key = item.data(Qt.UserRole)
        self.parameterSelected.emit(str(self._selected_parameter_key))
        self._load_color_for_selected_parameter()

    def _preview_loaded_theme(self):
        """Сразу перекрашивает приложение в тему, выбранную в ComboBox (не session-dirty)."""
        self._apply_editor_theme_to_app(preview_only=True)

    def _on_theme_combo_changed(self, index):
        theme_name = self._theme_combo_value(index)
        if not theme_name or theme_name == self.working_theme_name:
            return
        self._load_working_theme(theme_name)
        self._preview_loaded_theme()

    def _on_apply_clicked(self):
        if not self.is_modified:
            return
        self._apply_editor_theme_to_app(preview_only=False)
        self._commit_color_changes_to_session()

    def _on_save_clicked(self):
        if not self.is_modified:
            return
        theme_to_save = self._editor_theme_dict()
        if self._is_builtin_theme(self.working_theme_name):
            self._on_save_as_clicked(theme_to_save)
            return
        if self._theme_manager.save_theme(self.working_theme_name, theme_to_save):
            self.working_theme = dict(theme_to_save)
            self._modified_keys.clear()
            self._clear_modified_state()
            if (
                self._theme_manager.is_session_dirty()
                and self._theme_manager.session_theme_name() == self.working_theme_name
            ):
                self._theme_manager.clear_session_dirty()

    def _on_save_as_clicked(self, theme_to_save=None):
        """Сохраняет тему в новый .json; возвращает True при успехе."""
        theme_to_save = theme_to_save if isinstance(theme_to_save, dict) else self._editor_theme_dict()
        default_dir = str(data_themes_dir())
        default_name = "MyTheme.json"
        if not self._is_builtin_theme(self.working_theme_name):
            default_name = str(self.working_theme_name)
        default_path = os.path.join(default_dir, default_name)
        path, _ = QFileDialog.getSaveFileName(
            self,
            tr("theme_editor.save_as", "Сохранить как..."),
            default_path,
            FILE_FILTER_JSON,
        )
        if not path:
            return False
        current_path = None
        if not self._is_builtin_theme(self.working_theme_name):
            try:
                current_path = os.path.join(
                    str(data_themes_dir()), str(self.working_theme_name)
                )
            except Exception:
                current_path = None
        path, save_ok = prepare_theme_json_save_path(
            path, parent=self, current_path=current_path
        )
        if not save_ok or not path:
            return False
        if not self._theme_manager.save_theme_as(path, theme_to_save):
            return False
        filename = os.path.basename(path)
        self._populate_theme_combo(filename)
        self.working_theme_name = filename
        self.working_theme = self._theme_manager.create_working_copy(filename)
        self._modified_keys.clear()
        self._clear_modified_state()
        self._theme_manager.clear_session_dirty()
        return True

    def _get_main_window(self):
        parent = self.parent()
        if parent is not None and hasattr(parent, "parent_window"):
            return parent.parent_window
        if parent is not None and hasattr(parent, "get_settings_file_path"):
            return parent
        return None

    def _on_ok_clicked(self):
        """Применяет тему; при правке цвета — session-dirty; иначе commit active в ini."""
        app = QApplication.instance()
        if self.is_modified:
            self._apply_editor_theme_to_app(preview_only=False)
            self._commit_color_changes_to_session()
        else:
            self._theme_manager.clear_session_dirty()
            self._theme_manager.commit_active(self.working_theme_name, app)

        self.has_applied_changes = False
        self.accept()

    def _finish_close_editor(self):
        try:
            self._screen_color_picker.cancel()
            self._screen_color_picker._teardown()
        except Exception:
            pass
        self._cancel_portal_color_pick()
        self._close_confirming = True
        try:
            super().reject()
        finally:
            self._close_confirming = False

    def _on_cancel_clicked(self):
        if self._has_unsaved_session():
            self._revert_to_last_saved_and_resync()
            return
        self._finish_close_editor()

    def _confirm_close_with_unsaved_session(self):
        """Крестик/Esc: диалог сохранения; True — закрыть редактор, False — остаться."""
        main = self._get_main_window()
        if main is None or not hasattr(main, "_prompt_unsaved_theme_session_action"):
            return True
        action = main._prompt_unsaved_theme_session_action()
        if action == "cancelled":
            return False
        self._finish_close_editor()
        return True

    def event(self, event):
        if event.type() == QEvent.Close:
            try:
                if getattr(self, "_close_confirming", False):
                    return super().event(event)
                if self._has_unsaved_session():
                    if not self._confirm_close_with_unsaved_session():
                        event.ignore()
                        return True
                self._finish_close_editor()
                return True
            except Exception:
                try:
                    event.ignore()
                except Exception:
                    pass
                return True
        return super().event(event)

    def keyPressEvent(self, event):
        picker = self._screen_color_picker
        if event.key() == Qt.Key_Escape:
            if picker.is_active():
                picker.cancel()
                event.accept()
                return
            if picker.parent_should_ignore_esc():
                event.accept()
                return
        if event.key() == Qt.Key_Escape and getattr(self, "_portal_request", None) is not None:
            self._cancel_portal_color_pick()
            event.accept()
            return
        if event.key() == Qt.Key_Escape:
            try:
                if getattr(self, "_close_confirming", False):
                    event.accept()
                    return
                if self._has_unsaved_session():
                    if not self._confirm_close_with_unsaved_session():
                        event.accept()
                        return
                self._finish_close_editor()
                event.accept()
                return
            except Exception:
                event.accept()
                return
        super().keyPressEvent(event)

    def closeEvent(self, event):
        try:
            self._screen_color_picker.cancel()
            self._screen_color_picker._teardown()
        except Exception:
            pass
        self._cancel_portal_color_pick()
        super().closeEvent(event)

    def accept(self):
        try:
            self._screen_color_picker.cancel()
            self._screen_color_picker._teardown()
        except Exception:
            pass
        self._cancel_portal_color_pick()
        super().accept()

    def reject(self):
        if getattr(self, "_close_confirming", False):
            try:
                self._screen_color_picker.cancel()
                self._screen_color_picker._teardown()
            except Exception:
                pass
            self._cancel_portal_color_pick()
            super().reject()
            return
        if self._has_unsaved_session():
            if not self._confirm_close_with_unsaved_session():
                return
            return
        self._finish_close_editor()

    def _restore_portal_modality(self):
        if self._portal_saved_modality is not None:
            try:
                self.setWindowModality(self._portal_saved_modality)
            except Exception:
                pass
            self._portal_saved_modality = None

    def _cancel_portal_color_pick(self):
        req = getattr(self, "_portal_request", None)
        if req is not None:
            try:
                req.colorPicked.disconnect(self._on_portal_color_picked)
            except Exception:
                pass
            try:
                req.cancelled.disconnect(self._on_portal_color_cancelled)
            except Exception:
                pass
            try:
                req.cancel()
                req.deleteLater()
            except Exception:
                pass
            self._portal_request = None
        self._restore_portal_modality()

    def _start_wayland_portal_color_pick(self):
        if self._portal_request is not None:
            return True
        if not _portal_color_pick_available():
            return False
        self._portal_saved_modality = self.windowModality()
        self.setWindowModality(Qt.NonModal)
        req = PortalColorRequest(_portal_parent_window_handle(self), self)
        req.colorPicked.connect(self._on_portal_color_picked, Qt.QueuedConnection)
        req.cancelled.connect(self._on_portal_color_cancelled, Qt.QueuedConnection)
        self._portal_request = req
        if not req.start():
            self._portal_request = None
            self._restore_portal_modality()
            return False
        return True

    def _on_portal_color_picked(self, color):
        self._portal_request = None
        self._restore_portal_modality()
        if color is not None and color.isValid():
            self._on_screen_color_picked(color)

    def _on_portal_color_cancelled(self):
        self._portal_request = None
        self._restore_portal_modality()

    def _pick_color_via_dialog(self, *, native_on_macos=False):
        if native_on_macos and sys.platform == "darwin":
            color = QColorDialog.getColor(
                self.current_color,
                self,
                tr("theme_editor.dropper", "Пипетка"),
            )
        else:
            color = QColorDialog.getColor(
                self.current_color,
                self,
                tr("theme_editor.dropper", "Пипетка"),
                QColorDialog.DontUseNativeDialog,
            )
        if color.isValid():
            self._on_screen_color_picked(color)

    def _on_dropper_clicked(self):
        if _is_linux_wayland_session():
            if self._start_wayland_portal_color_pick():
                return
            self._pick_color_via_dialog()
            return
        # macOS: модальные «Настройки → редактор тем» + grabWindow конфликтуют с кастомной лупой;
        # системная панель цвета (иконка лупы) работает по всему экрану без сбоев ввода.
        if sys.platform == "darwin":
            self._pick_color_via_dialog(native_on_macos=True)
            return
        if self._screen_color_picker.start():
            return
        self._pick_color_via_dialog()

    def _on_screen_color_picked(self, color):
        self._set_current_color(color, source="dropper")
        self.activateWindow()
        self.raise_()


class NewSettingsDialog(ThemedFramelessDialog, Ui_Dialog):
    """Диалог настроек программы."""

    def __init__(self, parent=None):
        super().__init__(parent, resizable="horizontal", content_margins=(0, 0, 0, 0))
        self.parent_window = parent

        self.setupUi(self.content_widget())
        QtCore.QMetaObject.connectSlotsByName(self)

        self.setWindowTitle(tr("tooltip.setting", "Настройки"))
        self.setModal(True)

        try:
            wire_copy_paste_context_menu_for_line_edit(getattr(self, "separator_line", None))
        except Exception:
            pass
        for _spin_name in (
            "max_editor_tab_width_spin",
            "max_favorites_item_width_spin",
            "margin_spin",
            "line_spacing_spin",
            "newlines_spin",
            "right_indent_spin",
            "slow_double_click_min_spin",
            "slow_double_click_max_spin",
        ):
            try:
                disable_spinbox_context_menu(getattr(self, _spin_name, None))
            except Exception:
                pass

        # Заполняем список переводов из папки languages
        try:
            self._populate_language_combo()
        except Exception:
            pass
        # Если явный выбор не задан — предпочитаем Русский (если есть в списке)
        try:
            if hasattr(self, "language_combo") and self.language_combo:
                wanted = ""
                try:
                    wanted = str(getattr(self.parent_window, "ui_translation_saved", getattr(self.parent_window, "ui_translation", "")) or "").strip()
                except Exception:
                    wanted = ""
                if not wanted:
                    idx_ru = _combo_index_by_locale_name(self.language_combo, _BASE_RU_LOCALE_NAME)
                    if idx_ru >= 0:
                        # Берём фактическое имя пункта: на macOS оно приходит в NFD
                        wanted = str(self.language_combo.itemText(int(idx_ru)))
                idx = _combo_index_by_locale_name(self.language_combo, str(wanted))
                if idx >= 0:
                    self.language_combo.setCurrentIndex(idx)
        except Exception:
            pass

        # Переменные для хранения настроек (как в SettingsDialog)
        self.text_font = self._get_system_proportional_font()
        self.ui_font = self._get_system_proportional_font()

        # ------------------------------------------------------------
        # Инициализация диапазонов виджетов
        # ------------------------------------------------------------
        try:
            if hasattr(self, "margin_spin") and self.margin_spin:
                self.margin_spin.setRange(0, 1000)
                self.margin_spin.setValue(27)
        except Exception:
            pass
        try:
            if hasattr(self, "line_spacing_spin") and self.line_spacing_spin:
                self.line_spacing_spin.setRange(50, 200)
                self.line_spacing_spin.setValue(100)
        except Exception:
            pass
        try:
            if hasattr(self, "newlines_spin") and self.newlines_spin:
                self.newlines_spin.setRange(0, 1000)
                self.newlines_spin.setValue(50)
        except Exception:
            pass
        try:
            if hasattr(self, "right_indent_spin") and self.right_indent_spin:
                # Правый "safe" отступ при выравнивании по правому краю (px)
                self.right_indent_spin.setRange(0, 500)
                self.right_indent_spin.setValue(int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10)))
        except Exception:
            pass

        # Настраиваемые ограничения ширины
        try:
            if hasattr(self, "max_editor_tab_width_spin") and self.max_editor_tab_width_spin:
                self.max_editor_tab_width_spin.setRange(int(VIEW_WIDTH_MIN_PX), int(VIEW_WIDTH_MAX_PX))
                self.max_editor_tab_width_spin.setSingleStep(5)
                # суффикс убран — показываем только число
        except Exception:
            pass
        try:
            if hasattr(self, "max_favorites_item_width_spin") and self.max_favorites_item_width_spin:
                self.max_favorites_item_width_spin.setRange(int(VIEW_WIDTH_MIN_PX), int(VIEW_WIDTH_MAX_PX))
                self.max_favorites_item_width_spin.setSingleStep(5)
                # суффикс убран — показываем только число
        except Exception:
            pass

        # Медленный "двойной" клик
        try:
            if hasattr(self, "slow_double_click_min_spin") and self.slow_double_click_min_spin:
                self.slow_double_click_min_spin.setRange(0, 59999)
                self.slow_double_click_min_spin.setSingleStep(50)
                # суффикс убран — показываем только число
        except Exception:
            pass
        try:
            if hasattr(self, "slow_double_click_max_spin") and self.slow_double_click_max_spin:
                self.slow_double_click_max_spin.setRange(1, 60000)
                self.slow_double_click_max_spin.setSingleStep(50)
                # суффикс убран — показываем только число
        except Exception:
            pass

        # Подключаем выбор шрифта
        try:
            if hasattr(self, "text_font_button") and self.text_font_button:
                self.text_font_button.clicked.connect(self.choose_text_font)
        except Exception:
            pass
        try:
            if hasattr(self, "ui_font_button") and self.ui_font_button:
                self.ui_font_button.clicked.connect(self.choose_ui_font)
        except Exception:
            pass

        # Кнопка "Редактор перевода..."
        try:
            if hasattr(self, "create_translation_button") and self.create_translation_button:
                self.create_translation_button.clicked.connect(self._open_translation_editor_dialog)
        except Exception:
            pass
        # Кнопка "Редактор тем..." — открывает редактор тем
        try:
            if hasattr(self, "theme_button") and self.theme_button:
                self.theme_button.clicked.connect(self._open_theme_editor_dialog)
        except Exception:
            pass
        # Кнопка "О программе..."
        try:
            if hasattr(self, "about_JBPad_button") and self.about_JBPad_button:
                self.about_JBPad_button.clicked.connect(self._open_about_dialog)
        except Exception:
            pass
        # Группа радиокнопок формата даты
        try:
            self.date_format_button_group = QButtonGroup()
            if hasattr(self, "date_format_short_ISO_radio") and self.date_format_short_ISO_radio:
                self.date_format_button_group.addButton(self.date_format_short_ISO_radio, 0)
            if hasattr(self, "date_format_short_us_radio") and self.date_format_short_us_radio:
                self.date_format_button_group.addButton(self.date_format_short_us_radio, 1)
            if hasattr(self, "date_format_short_radio") and self.date_format_short_radio:
                self.date_format_button_group.addButton(self.date_format_short_radio, 2)
            if hasattr(self, "date_format_long_radio") and self.date_format_long_radio:
                self.date_format_button_group.addButton(self.date_format_long_radio, 3)
            self.date_format_button_group.buttonClicked.connect(self._update_date_format_examples)
        except Exception:
            # Если чего-то не хватает в UI, просто не подключаем
            pass
        try:
            if hasattr(self, "date_include_time_checkbox") and self.date_include_time_checkbox:
                self.date_include_time_checkbox.toggled.connect(self._update_date_format_examples)
        except Exception:
            pass

        if hasattr(self, "ok_button") and self.ok_button:
            try:
                self.ok_button.setDefault(True)
                self.ok_button.clicked.connect(self.accept)
            except Exception:
                pass
        if hasattr(self, "cancel_button") and self.cancel_button:
            try:
                self.cancel_button.clicked.connect(self.reject)
            except Exception:
                pass

        # Зависимые элементы: "Отступ справа" активен только при включенном выравнивании справа
        try:
            if hasattr(self, "alignRight_checkbox") and self.alignRight_checkbox:
                self.alignRight_checkbox.toggled.connect(self._update_right_indent_controls)
        except Exception:
            pass

        # Загружаем текущие настройки
        self.load_current_settings()
        self._update_right_indent_controls()

        # Live preview: правый отступ (имеет эффект только если в этом запуске включено выравнивание справа)
        try:
            self._initial_right_indent_px = int(self.right_indent_spin.value()) if hasattr(self, "right_indent_spin") and self.right_indent_spin else int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))
        except Exception:
            self._initial_right_indent_px = int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))
        try:
            if hasattr(self, "right_indent_spin") and self.right_indent_spin:
                self.right_indent_spin.valueChanged.connect(self._preview_right_indent)
        except Exception:
            pass

        # Live preview: применяем подсказки сразу при переключении чекбокса,
        # а при "Отмена" откатываем к исходному состоянию.
        self._initial_show_tooltips = bool(getattr(self, "show_tooltips_checkbox", None) and self.show_tooltips_checkbox.isChecked())
        self._initial_highlight_links = bool(getattr(self, "highlight_links_checkbox", None) and self.highlight_links_checkbox.isChecked())
        try:
            if hasattr(self, "show_tooltips_checkbox") and self.show_tooltips_checkbox:
                self.show_tooltips_checkbox.toggled.connect(self._preview_show_tooltips)
        except Exception:
            pass
        try:
            if hasattr(self, "highlight_links_checkbox") and self.highlight_links_checkbox:
                self.highlight_links_checkbox.toggled.connect(self._preview_highlight_links)
        except Exception:
            pass

        fm = self.fontMetrics()
        min_content_w = max(460, int(fm.averageCharWidth() * 30 * 2 + 24))
        self.fit_to_content_size(
            min_content_width=min_content_w,
            lock_height=True,
        )
        self._ensure_settings_horizontal_stretch()

    def _ensure_settings_horizontal_stretch(self):
        """После fit: контент может расти по ширине вместе с окном."""
        try:
            cw = self.content_widget()
            cw.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
            cw.setMaximumWidth(int(QtWidgets.QWIDGETSIZE_MAX))
            layout = self.content_layout()
            if layout is not None:
                layout.setSizeConstraint(QtWidgets.QLayout.SetNoConstraint)
            for oid in ("settingsColumnsWrapper", "settingsColumnsWidget"):
                wrapper = cw.findChild(QWidget, oid)
                if wrapper is not None:
                    wrapper.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
                    wrapper.setMaximumWidth(int(QtWidgets.QWIDGETSIZE_MAX))
            for group in cw.findChildren(QtWidgets.QGroupBox):
                group.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
                group.setMaximumWidth(int(QtWidgets.QWIDGETSIZE_MAX))
            self._sync_frameless_shell_geometry()
        except Exception:
            pass

    def _initial_focus_widget(self):
        return getattr(self, "ok_button", None)

    def _update_right_indent_controls(self, checked: bool = None):
        """Включает/выключает элементы отступа справа в зависимости от alignRight_checkbox."""
        try:
            if checked is None:
                checked = bool(self.alignRight_checkbox.isChecked()) if hasattr(self, "alignRight_checkbox") and self.alignRight_checkbox else False
        except Exception:
            checked = False

        try:
            if hasattr(self, "right_indent_spin") and self.right_indent_spin:
                self.right_indent_spin.setEnabled(bool(checked))
        except Exception:
            pass
        try:
            if hasattr(self, "right_indent_label") and self.right_indent_label:
                self.right_indent_label.setEnabled(bool(checked))
        except Exception:
            pass

    def _populate_language_combo(self):
        """Заполняет language_combo именами переводов из Data/languages (без расширения)."""
        try:
            combo = getattr(self, "language_combo", None)
            if combo is None:
                return
            try:
                combo.clear()
            except Exception:
                pass

            names = []
            try:
                for fn in iter_language_filenames():
                    base, _ = os.path.splitext(str(fn))
                    if base:
                        names.append(base)
            except Exception:
                names = []

            # Стабильная сортировка без учёта регистра
            try:
                names = sorted(set(names), key=lambda s: str(s).lower())
            except Exception:
                pass

            try:
                combo.addItems(list(names))
            except Exception:
                for n in names:
                    try:
                        combo.addItem(str(n))
                    except Exception:
                        pass
        except Exception:
            pass
        finally:
            self._update_translation_editor_button_enabled()

    def _update_translation_editor_button_enabled(self):
        """Кнопка «Редактор перевода...» активна только при наличии файлов локализации."""
        try:
            btn = getattr(self, "create_translation_button", None)
            if btn is None:
                return
            has_locale_files = False
            try:
                has_locale_files = bool(iter_language_filenames())
            except Exception:
                has_locale_files = False
            btn.setEnabled(bool(has_locale_files))
        except Exception:
            pass

    def _preview_right_indent(self, value):
        """Live preview изменения правого отступа (эффект виден только при активном right_alignment этого запуска)."""
        try:
            # Если выравнивание справа выключено — ничего не применяем
            if hasattr(self, "alignRight_checkbox") and self.alignRight_checkbox and (not bool(self.alignRight_checkbox.isChecked())):
                return
            if self.parent_window and hasattr(self.parent_window, "apply_editor_right_indent_px"):
                self.parent_window.apply_editor_right_indent_px(int(value))
        except Exception:
            pass

    def _preview_show_tooltips(self, checked: bool):
        """Live preview для настройки 'Показывать подсказки'."""
        try:
            if self.parent_window:
                self.parent_window.set_show_tooltips(bool(checked))
        except Exception:
            pass

    def _preview_highlight_links(self, checked: bool):
        """Live preview для настройки 'Подсветка ссылок внутри текста'."""
        try:
            if self.parent_window:
                self.parent_window.set_link_highlight_enabled(bool(checked))
        except Exception:
            pass

    def reject(self):
        """Откат live-preview при нажатии 'Отмена'."""
        if getattr(self, "_skip_live_preview_rollback", False):
            super().reject()
            return
        try:
            if self.parent_window:
                self.parent_window.set_show_tooltips(bool(getattr(self, "_initial_show_tooltips", True)))
                self.parent_window.set_link_highlight_enabled(bool(getattr(self, "_initial_highlight_links", True)))
                try:
                    if hasattr(self.parent_window, "apply_editor_right_indent_px"):
                        self.parent_window.apply_editor_right_indent_px(int(getattr(self, "_initial_right_indent_px", getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))))
                except Exception:
                    pass
        except Exception:
            pass
        super().reject()

    def dismiss_without_commit(self):
        """Закрывает диалог без accept()/reject()-rollback (live-preview сохраняется)."""
        self._skip_live_preview_rollback = True
        try:
            super().reject()
        finally:
            self._skip_live_preview_rollback = False

    def _get_system_proportional_font(self) -> 'QFont':
        """Системный пропорциональный шрифт (кроссплатформенно через Qt)."""
        try:
            app = QApplication.instance()
            if app is not None:
                return QFont(app.font())
        except Exception:
            pass
        return QFont()

    def _font_from_config_or_system(
        self,
        config: 'configparser.ConfigParser',
        *,
        family_key: str,
        size_key: str,
        bold_key: str,
        italic_key: str,
    ) -> 'QFont':
        """Возвращает пользовательский шрифт из секции шрифтов текущей ОС или системный.

        Секция зависит от ОС ([Font_Win]/[Font_Linux]/[Font_macOS]); общая [Font]
        используется как fallback для конфигов прежних версий.
        """
        base = self._get_system_proportional_font()
        f = QFont(base)

        _font_section = _settings_section_name(config, "Font")
        if not _font_section:
            return f

        try:
            family = config.get(_font_section, family_key, fallback='').strip()
        except Exception:
            family = ''
        try:
            size = config.getint(_font_section, size_key, fallback=-1)
        except Exception:
            size = -1
        try:
            bold = config.getboolean(_font_section, bold_key, fallback=bool(base.bold()))
        except Exception:
            bold = bool(base.bold())
        try:
            italic = config.getboolean(_font_section, italic_key, fallback=bool(base.italic()))
        except Exception:
            italic = bool(base.italic())

        if family:
            try:
                _qfont_apply_family_if_available(f, family)
            except Exception:
                pass
        if size and int(size) > 0:
            try:
                f.setPointSize(int(size))
            except Exception:
                pass
        try:
            f.setBold(bool(bold))
        except Exception:
            pass
        try:
            f.setItalic(bool(italic))
        except Exception:
            pass
        return f

    def choose_text_font(self):
        """Открывает диалог выбора шрифта для текстового поля"""
        font, ok = RussianFontDialog.get_font_dialog(self.text_font, self, APP_BRAND)
        if ok:
            self.text_font = font

    def choose_ui_font(self):
        """Открывает диалог выбора шрифта для интерфейса"""
        font, ok = RussianFontDialog.get_font_dialog(self.ui_font, self, APP_BRAND)
        if ok:
            self.ui_font = font

    def _update_date_format_examples(self):
        """Обновляет примеры формата даты динамически"""
        include_time = False
        try:
            include_time = bool(self.date_include_time_checkbox.isChecked())
        except Exception:
            include_time = False

        iso_example = format_date('iso', include_time)
        us_example = format_date('us', include_time)
        short_example = format_date('short', include_time)
        long_available = is_long_date_format_available()
        long_example = (
            format_date('long', include_time, for_preview=True)
            if long_available
            else "None"
        )

        try:
            if hasattr(self, "date_format_short_ISO_label") and self.date_format_short_ISO_label:
                self.date_format_short_ISO_label.setText(iso_example)
        except Exception:
            pass
        try:
            if hasattr(self, "date_format_short_us_label") and self.date_format_short_us_label:
                self.date_format_short_us_label.setText(us_example)
        except Exception:
            pass
        try:
            if hasattr(self, "date_format_short_label") and self.date_format_short_label:
                self.date_format_short_label.setText(short_example)
        except Exception:
            pass
        try:
            long_radio = getattr(self, "date_format_long_radio", None)
            long_label = getattr(self, "date_format_long_label", None)
            if long_radio is not None:
                long_radio.setEnabled(bool(long_available))
                if not long_available and long_radio.isChecked():
                    try:
                        short_radio = getattr(self, "date_format_short_radio", None)
                        if short_radio is not None:
                            short_radio.setChecked(True)
                    except Exception:
                        pass
            if long_label is not None:
                long_label.setText(long_example)
        except Exception:
            pass

    def _open_translation_editor_dialog(self):
        try:
            dlg = TranslationEditorDialog(self)
            dlg.exec_()
            self._update_translation_editor_button_enabled()
        except Exception:
            return

    def _open_theme_editor_dialog(self):
        main = self.parent_window
        if main is None:
            return

        if _theme_editor_independent_window():
            # Wayland: вложенный QEventLoop внутри exec_() настроек не доставляет ввод
            # в немодальный редактор. Закрываем настройки, открываем редактор на уровне main.
            main._reopen_settings_after_theme_editor = True
            self.dismiss_without_commit()
            return

        # Windows / X11 / macOS: parent=настройки, модально (проверенная схема до рефакторинга).
        dlg = ThemeEditorDialog(self, independent_window=False)
        dlg.setWindowModality(Qt.ApplicationModal)
        saved_opacity = 1.0
        saved_mouse_transparent = False
        loop = QEventLoop()
        try:
            def _on_theme_finished(_code):
                loop.quit()

            dlg.finished.connect(_on_theme_finished)
            try:
                saved_mouse_transparent = bool(self.testAttribute(Qt.WA_TransparentForMouseEvents))
                self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
            except Exception:
                pass
            saved_opacity = float(self.windowOpacity())
            self.setWindowOpacity(0.0)
            dlg.show()
            dlg.raise_()
            dlg.activateWindow()
            loop.exec_()
        except Exception:
            return
        finally:
            try:
                dlg.finished.disconnect()
            except Exception:
                pass
            if ThemeManager.instance().is_session_dirty():
                self.dismiss_without_commit()
            else:
                try:
                    self.setAttribute(Qt.WA_TransparentForMouseEvents, saved_mouse_transparent)
                except Exception:
                    pass
                self.setWindowOpacity(saved_opacity)
                self.raise_()
                self.activateWindow()

    def _open_about_dialog(self):
        try:
            dlg = AboutJBPadDialog(self)
            dlg.exec_()
        except Exception:
            return

    def load_current_settings(self):
        """Загружает текущие настройки из главного окна"""
        if not self.parent_window:
            return

        # Загружаем настройку показа подсказок
        settings_file = self.parent_window.get_settings_file_path()
        show_tooltips = True  # По умолчанию включено
        highlight_links = bool(getattr(self.parent_window, 'highlight_links_in_text', True))
        separator_text = str(getattr(self.parent_window, "separator_text", "") or "")

        # Настраиваемые ограничения ширины
        try:
            max_editor_tab_width_px = int(getattr(self.parent_window, "max_editor_tab_width_px_saved", getattr(self.parent_window, "max_editor_tab_width_px", DEFAULT_EDITOR_TAB_MAX_WIDTH_PX)))
        except Exception:
            max_editor_tab_width_px = int(DEFAULT_EDITOR_TAB_MAX_WIDTH_PX)
        try:
            max_favorites_item_width_px = int(getattr(self.parent_window, "max_favorites_item_width_px_saved", getattr(self.parent_window, "max_favorites_item_width_px", DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX)))
        except Exception:
            max_favorites_item_width_px = int(DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX)
        max_editor_tab_width_px = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(max_editor_tab_width_px)))
        max_favorites_item_width_px = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(max_favorites_item_width_px)))

        # Переименование по клику (Tree)
        try:
            slow_min_ms = int(getattr(self.parent_window, "slow_double_click_min_interval_ms", SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT))
        except Exception:
            slow_min_ms = SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT
        try:
            slow_max_ms = int(getattr(self.parent_window, "slow_double_click_max_interval_ms", SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT))
        except Exception:
            slow_max_ms = SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT

        config = _read_settings_ini(settings_file)
        try:
            # Текущий перевод (если задан) — выбираем в комбобоксе
            try:
                lang_name = str(config.get('languages', 'translation', fallback='') or '').strip()
            except Exception:
                lang_name = ''
            if not lang_name:
                lang_name = str(getattr(self.parent_window, "ui_translation_saved", getattr(self.parent_window, "ui_translation", "")) or "").strip()
            try:
                if hasattr(self, "language_combo") and self.language_combo:
                    idx = _combo_index_by_locale_name(self.language_combo, lang_name)
                    if idx >= 0:
                        self.language_combo.setCurrentIndex(idx)
                    else:
                        idx_ru = _combo_index_by_locale_name(self.language_combo, _BASE_RU_LOCALE_NAME)
                        if idx_ru >= 0:
                            self.language_combo.setCurrentIndex(idx_ru)
                        elif self.language_combo.count() > 0:
                            self.language_combo.setCurrentIndex(0)
            except Exception:
                pass

            if config.has_section('Toolbar'):
                show_tooltips = config.getboolean('Toolbar', 'show_tooltips', fallback=True)
            if config.has_section('View'):
                highlight_links = config.getboolean('View', 'highlight_links_in_text', fallback=highlight_links)
                try:
                    max_editor_tab_width_px = config.getint('View', 'max_editor_tab_width_px', fallback=max_editor_tab_width_px)
                except Exception:
                    pass
                try:
                    max_favorites_item_width_px = config.getint('View', 'max_favorites_item_width_px', fallback=max_favorites_item_width_px)
                except Exception:
                    pass
            if config.has_section('Separator'):
                try:
                    separator_text = config.get('Separator', 'text', fallback=separator_text)
                except Exception:
                    pass
            try:
                if config.has_section('Tree'):
                    slow_min_ms = config.getint('Tree', 'slow_double_click_min_interval_ms', fallback=slow_min_ms)
                    slow_max_ms = config.getint('Tree', 'slow_double_click_max_interval_ms', fallback=slow_max_ms)
            except Exception:
                pass
        except Exception:
            pass

        if hasattr(self, "show_tooltips_checkbox") and self.show_tooltips_checkbox:
            self.show_tooltips_checkbox.setChecked(show_tooltips)
        if hasattr(self, 'highlight_links_checkbox') and self.highlight_links_checkbox:
            self.highlight_links_checkbox.setChecked(bool(highlight_links))
        try:
            if hasattr(self, "separator_line") and self.separator_line:
                self.separator_line.setText(str(separator_text or ""))
        except Exception:
            pass

        # Клампим и проставляем спинбоксы ширины
        try:
            max_editor_tab_width_px = int(max_editor_tab_width_px)
        except Exception:
            max_editor_tab_width_px = int(DEFAULT_EDITOR_TAB_MAX_WIDTH_PX)
        try:
            max_favorites_item_width_px = int(max_favorites_item_width_px)
        except Exception:
            max_favorites_item_width_px = int(DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX)
        max_editor_tab_width_px = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(max_editor_tab_width_px)))
        max_favorites_item_width_px = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(max_favorites_item_width_px)))
        try:
            if hasattr(self, "max_editor_tab_width_spin") and self.max_editor_tab_width_spin:
                self.max_editor_tab_width_spin.setValue(int(max_editor_tab_width_px))
        except Exception:
            pass
        try:
            if hasattr(self, "max_favorites_item_width_spin") and self.max_favorites_item_width_spin:
                self.max_favorites_item_width_spin.setValue(int(max_favorites_item_width_px))
        except Exception:
            pass

        # Медленный "двойной" клик (Tree)
        slow_min_ms = max(0, min(59999, int(slow_min_ms)))
        slow_max_ms = max(1, min(60000, int(slow_max_ms)))
        if slow_max_ms <= slow_min_ms:
            slow_max_ms = min(60000, slow_min_ms + 1)
            if slow_max_ms <= slow_min_ms:
                slow_min_ms = max(0, slow_max_ms - 1)
        try:
            if hasattr(self, "slow_double_click_min_spin") and self.slow_double_click_min_spin:
                self.slow_double_click_min_spin.setValue(int(slow_min_ms))
            if hasattr(self, "slow_double_click_max_spin") and self.slow_double_click_max_spin:
                self.slow_double_click_max_spin.setValue(int(slow_max_ms))
        except Exception:
            pass

        # Загружаем настройки шрифта из файла настроек
        settings_file = self.parent_window.get_settings_file_path()
        config = _read_settings_ini(settings_file)
        try:

            # Шрифты: секция текущей ОС ([Font_Win]/[Font_Linux]/[Font_macOS]) или общая [Font]
            _font_section = _settings_section_name(config, "Font")

            # Шрифт текстового поля
            if _font_section:
                self.text_font = self._font_from_config_or_system(
                    config,
                    family_key='text_family',
                    size_key='text_size',
                    bold_key='text_bold',
                    italic_key='text_italic',
                )

            # Шрифт интерфейса
            if _font_section:
                self.ui_font = self._font_from_config_or_system(
                    config,
                    family_key='ui_family',
                    size_key='ui_size',
                    bold_key='ui_bold',
                    italic_key='ui_italic',
                )

            # Отступ редактора
            if config.has_section('Editor'):
                margin = config.getint('Editor', 'left_margin', fallback=27)
            else:
                margin = getattr(self.parent_window, 'editor_left_margin', 27)
            if hasattr(self, "margin_spin") and self.margin_spin:
                self.margin_spin.setValue(int(margin))

            # Количество переводов каретки
            if config.has_section('Editor'):
                newlines_count = config.getint('Editor', 'newlines_count', fallback=50)
            else:
                newlines_count = getattr(self.parent_window, 'newlines_count', 50)
            if hasattr(self, "newlines_spin") and self.newlines_spin:
                self.newlines_spin.setValue(int(newlines_count))

            # Межстрочный интервал (проценты от высоты шрифта)
            if config.has_section('Editor'):
                line_spacing = config.getint('Editor', 'line_spacing', fallback=getattr(self.parent_window, 'editor_line_spacing_saved', 100))
            else:
                line_spacing = getattr(self.parent_window, 'editor_line_spacing_saved', 100)
            try:
                line_spacing = int(line_spacing)
            except Exception:
                line_spacing = 100
            line_spacing = max(50, min(200, line_spacing))
            if hasattr(self, 'line_spacing_spin') and self.line_spacing_spin:
                self.line_spacing_spin.setValue(line_spacing)

            # Выравнивание (trailing/leading) — показываем сохранённое значение
            if config.has_section('Editor'):
                try:
                    right_alignment = config.getboolean('Editor', 'right_alignment', fallback=getattr(self.parent_window, 'editor_right_alignment_saved', False))
                except Exception:
                    try:
                        right_alignment = str(config.get('Editor', 'right_alignment', fallback=str(getattr(self.parent_window, 'editor_right_alignment_saved', False)))).strip().lower() in ("1", "true", "yes", "y", "on")
                    except Exception:
                        right_alignment = bool(getattr(self.parent_window, 'editor_right_alignment_saved', False))
            else:
                right_alignment = bool(getattr(self.parent_window, 'editor_right_alignment_saved', False))
            try:
                if hasattr(self, "alignRight_checkbox") and self.alignRight_checkbox:
                    self.alignRight_checkbox.setChecked(bool(right_alignment))
            except Exception:
                pass

            # Правый отступ (px), используемый при выравнивании по правому краю
            try:
                if config.has_section('Editor'):
                    try:
                        right_indent = config.getint('Editor', 'right_indent', fallback=int(getattr(self.parent_window, 'editor_right_indent_px_saved', getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))))
                    except Exception:
                        try:
                            right_indent = int(str(config.get('Editor', 'right_indent', fallback=str(getattr(self.parent_window, 'editor_right_indent_px_saved', getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))))).strip())
                        except Exception:
                            right_indent = int(getattr(self.parent_window, 'editor_right_indent_px_saved', getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10)))
                else:
                    right_indent = int(getattr(self.parent_window, 'editor_right_indent_px_saved', getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10)))
            except Exception:
                right_indent = int(getattr(self.parent_window, 'editor_right_indent_px_saved', getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10)))
            right_indent = max(0, min(500, int(right_indent)))
            try:
                if hasattr(self, "right_indent_spin") and self.right_indent_spin:
                    self.right_indent_spin.setValue(int(right_indent))
            except Exception:
                pass

            # Настройки формата даты
            if config.has_section('General'):
                settings_path = self.parent_window.get_settings_file_path() if self.parent_window else str(APP_DIR / "Setting.ini")
                date_format, include_time = normalize_date_settings(settings_path)

                # Устанавливаем радиокнопку
                try:
                    if date_format == 'iso' and hasattr(self, "date_format_short_ISO_radio") and self.date_format_short_ISO_radio:
                        self.date_format_short_ISO_radio.setChecked(True)
                    elif date_format == 'us' and hasattr(self, "date_format_short_us_radio") and self.date_format_short_us_radio:
                        self.date_format_short_us_radio.setChecked(True)
                    elif date_format == 'short' and hasattr(self, "date_format_short_radio") and self.date_format_short_radio:
                        self.date_format_short_radio.setChecked(True)
                    elif hasattr(self, "date_format_long_radio") and self.date_format_long_radio:
                        self.date_format_long_radio.setChecked(True)
                except Exception:
                    # Fallback
                    if hasattr(self, "date_format_short_radio") and self.date_format_short_radio:
                        self.date_format_short_radio.setChecked(True)

                # Устанавливаем чекбокс времени
                if hasattr(self, "date_include_time_checkbox") and self.date_include_time_checkbox:
                    self.date_include_time_checkbox.setChecked(include_time)

                # Обновляем примеры
                self._update_date_format_examples()
            else:
                # Если секции 'General' нет, используем значения по умолчанию
                if hasattr(self, "date_format_short_radio") and self.date_format_short_radio:
                    self.date_format_short_radio.setChecked(True)
                if hasattr(self, "date_include_time_checkbox") and self.date_include_time_checkbox:
                    self.date_include_time_checkbox.setChecked(False)
                self._update_date_format_examples()
        except Exception:
            # При ошибке загрузки используем значения из parent_window или значения по умолчанию
            margin = getattr(self.parent_window, 'editor_left_margin', 27)
            newlines_count = getattr(self.parent_window, 'newlines_count', 50)
            if hasattr(self, "margin_spin") and self.margin_spin:
                self.margin_spin.setValue(int(margin))
            if hasattr(self, "newlines_spin") and self.newlines_spin:
                self.newlines_spin.setValue(int(newlines_count))

            line_spacing = getattr(self.parent_window, 'editor_line_spacing_saved', 100)
            try:
                line_spacing = int(line_spacing)
            except Exception:
                line_spacing = 100
            line_spacing = max(50, min(200, line_spacing))
            if hasattr(self, 'line_spacing_spin') and self.line_spacing_spin:
                self.line_spacing_spin.setValue(line_spacing)

            try:
                if hasattr(self, "alignRight_checkbox") and self.alignRight_checkbox:
                    self.alignRight_checkbox.setChecked(bool(getattr(self.parent_window, 'editor_right_alignment_saved', False)))
            except Exception:
                pass

            try:
                right_indent = int(getattr(self.parent_window, 'editor_right_indent_px_saved', getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10)))
            except Exception:
                right_indent = int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))
            right_indent = max(0, min(500, int(right_indent)))
            try:
                if hasattr(self, "right_indent_spin") and self.right_indent_spin:
                    self.right_indent_spin.setValue(int(right_indent))
            except Exception:
                pass

            # Настройки формата даты по умолчанию
            if hasattr(self, "date_format_short_radio") and self.date_format_short_radio:
                self.date_format_short_radio.setChecked(True)
            if hasattr(self, "date_include_time_checkbox") and self.date_include_time_checkbox:
                self.date_include_time_checkbox.setChecked(False)
            self._update_date_format_examples()

    def accept(self):
        """Применяет настройки при нажатии OK"""
        if not self.parent_window:
            super().accept()
            return

        # Межстрочный интервал: сохраняем в INI, но НЕ применяем в текущей сессии (только после перезапуска)
        old_line_spacing_active = getattr(self.parent_window, 'editor_line_spacing', 100)
        new_line_spacing = old_line_spacing_active
        if hasattr(self, 'line_spacing_spin') and self.line_spacing_spin:
            new_line_spacing = int(self.line_spacing_spin.value())
        new_line_spacing = max(50, min(200, new_line_spacing))
        self.parent_window.editor_line_spacing_saved = new_line_spacing
        line_spacing_requires_restart = (new_line_spacing != old_line_spacing_active)

        # Выравнивание по правому краю: сохраняем в INI, но НЕ применяем в текущей сессии (только после перезапуска)
        old_right_alignment_active = bool(getattr(self.parent_window, 'editor_right_alignment', False))
        new_right_alignment = old_right_alignment_active
        try:
            if hasattr(self, "alignRight_checkbox") and self.alignRight_checkbox:
                new_right_alignment = bool(self.alignRight_checkbox.isChecked())
        except Exception:
            new_right_alignment = old_right_alignment_active
        self.parent_window.editor_right_alignment_saved = bool(new_right_alignment)
        right_alignment_requires_restart = (bool(new_right_alignment) != bool(old_right_alignment_active))

        # Перевод интерфейса: сохраняем в INI, применяем после перезапуска
        old_translation_active = str(getattr(self.parent_window, 'ui_translation', '') or '').strip()
        new_translation = old_translation_active
        try:
            if hasattr(self, "language_combo") and self.language_combo:
                new_translation = str(self.language_combo.currentText() or '').strip()
        except Exception:
            new_translation = old_translation_active
        self.parent_window.ui_translation_saved = str(new_translation or '')
        # Имя локали на macOS приходит с ФС в NFD, а из ini — в NFC:
        # сравниваем с нормализацией (иначе окно «после перезапуска» появляется всегда).
        translation_requires_restart = not _locale_names_equal(new_translation, old_translation_active)

        # Правый отступ (px) при выравнивании справа: применяем сразу и сохраняем в INI
        try:
            new_right_indent_px = int(self.right_indent_spin.value()) if hasattr(self, "right_indent_spin") and self.right_indent_spin else int(getattr(self.parent_window, 'editor_right_indent_px_saved', getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10)))
        except Exception:
            new_right_indent_px = int(getattr(self.parent_window, 'editor_right_indent_px_saved', getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10)))
        new_right_indent_px = max(0, min(500, int(new_right_indent_px)))
        try:
            self.parent_window.editor_right_indent_px_saved = int(new_right_indent_px)
        except Exception:
            pass
        try:
            if hasattr(self.parent_window, "apply_editor_right_indent_px"):
                if hasattr(self, "alignRight_checkbox") and self.alignRight_checkbox and bool(self.alignRight_checkbox.isChecked()):
                    self.parent_window.apply_editor_right_indent_px(int(new_right_indent_px))
        except Exception:
            pass

        # Применяем настройку показа подсказок
        show_tooltips = self.show_tooltips_checkbox.isChecked() if hasattr(self, "show_tooltips_checkbox") and self.show_tooltips_checkbox else True
        self.parent_window.set_show_tooltips(show_tooltips)
        # Применяем подсветку ссылок внутри текста
        highlight_links = self.highlight_links_checkbox.isChecked() if hasattr(self, "highlight_links_checkbox") and self.highlight_links_checkbox else True
        self.parent_window.set_link_highlight_enabled(highlight_links)

        # ------------------------------------------------------------
        # Разделитель
        # ------------------------------------------------------------
        try:
            sep = self.separator_line.text() if hasattr(self, "separator_line") and self.separator_line else ""
        except Exception:
            sep = ""
        try:
            self.parent_window.separator_text = str(sep)
        except Exception:
            pass

        # ------------------------------------------------------------
        # Ограничения ширины
        # ------------------------------------------------------------
        try:
            new_max_favorites_item_width_px = int(self.max_favorites_item_width_spin.value()) if hasattr(self, "max_favorites_item_width_spin") and self.max_favorites_item_width_spin else int(DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX)
        except Exception:
            new_max_favorites_item_width_px = int(DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX)
        new_max_favorites_item_width_px = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(new_max_favorites_item_width_px)))
        try:
            # Избранное применяется сразу
            if hasattr(self.parent_window, "set_max_favorites_item_width_px"):
                self.parent_window.set_max_favorites_item_width_px(int(new_max_favorites_item_width_px))
            else:
                self.parent_window.max_favorites_item_width_px = int(new_max_favorites_item_width_px)
                self.parent_window.max_favorites_item_width_px_saved = int(new_max_favorites_item_width_px)
        except Exception:
            pass

        try:
            new_editor_tab_width_px = int(self.max_editor_tab_width_spin.value()) if hasattr(self, "max_editor_tab_width_spin") and self.max_editor_tab_width_spin else int(DEFAULT_EDITOR_TAB_MAX_WIDTH_PX)
        except Exception:
            new_editor_tab_width_px = int(DEFAULT_EDITOR_TAB_MAX_WIDTH_PX)
        new_editor_tab_width_px = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(new_editor_tab_width_px)))
        # Применяем и сохраняем только по OK.
        try:
            self.parent_window.apply_max_editor_tab_width_px(int(new_editor_tab_width_px))
            self.parent_window.max_editor_tab_width_px_saved = int(new_editor_tab_width_px)
        except Exception:
            pass

        # ------------------------------------------------------------
        # Переименование по клику (медленный "двойной" клик)
        # ------------------------------------------------------------
        try:
            min_ms = int(self.slow_double_click_min_spin.value()) if hasattr(self, "slow_double_click_min_spin") and self.slow_double_click_min_spin else int(getattr(self.parent_window, 'slow_double_click_min_interval_ms', SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT))
        except Exception:
            min_ms = SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT
        try:
            max_ms = int(self.slow_double_click_max_spin.value()) if hasattr(self, "slow_double_click_max_spin") and self.slow_double_click_max_spin else int(getattr(self.parent_window, 'slow_double_click_max_interval_ms', SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT))
        except Exception:
            max_ms = SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT
        min_ms = max(0, min(59999, int(min_ms)))
        max_ms = max(1, min(60000, int(max_ms)))
        if max_ms <= min_ms:
            max_ms = min(60000, min_ms + 1)
            if max_ms <= min_ms:
                min_ms = max(0, max_ms - 1)
        try:
            self.parent_window.slow_double_click_min_interval_ms = int(min_ms)
            self.parent_window.slow_double_click_max_interval_ms = int(max_ms)
        except Exception:
            pass
        # Применяем сразу к дереву (без перезапуска)
        try:
            if hasattr(self.parent_window, "tree") and self.parent_window.tree:
                self.parent_window.tree.slow_double_click_min_interval_ms = int(min_ms)
                self.parent_window.tree.slow_double_click_max_interval_ms = int(max_ms)
        except Exception:
            pass

        # Применяем настройки шрифта
        self.apply_font_settings()

        # Применяем отступ редактора
        try:
            margin = int(self.margin_spin.value())
            margin = max(0, min(1000, margin))  # Ограничиваем от 0 до 1000
            self.parent_window.editor_left_margin = margin

            # Применяем отступ ко всем открытым редакторам
            for tab_index in range(self.parent_window.tab_widget.count()):
                text_editor = self.parent_window.tab_widget.widget(tab_index)
                if text_editor and isinstance(text_editor, TextEditor):
                    text_editor.set_left_margin(margin)
        except ValueError:
            pass

        # Применяем настройки быстрого доступа к строкам
        try:
            newlines_count = int(self.newlines_spin.value())
            newlines_count = max(0, min(1000, newlines_count))  # Ограничиваем от 0 до 1000
            self.parent_window.newlines_count = newlines_count
        except ValueError:
            self.parent_window.newlines_count = 50

        # Сохраняем настройки
        self.parent_window.save_settings()

        if line_spacing_requires_restart or right_alignment_requires_restart or translation_requires_restart:
            _qmessagebox_single_ok(
                QMessageBox.Information,
                self,
                APP_BRAND,
                tr("message.the_line_spacing_change", "Изменения вступят в силу после перезапуска программы"),
            )

        super().accept()

    def apply_font_settings(self):
        """Применяет настройки шрифта"""
        # Применяем шрифт к текстовым полям
        for tab_index in range(self.parent_window.tab_widget.count()):
            text_editor = self.parent_window.tab_widget.widget(tab_index)
            if text_editor and isinstance(text_editor, QTextEdit):
                text_editor.setFont(self.text_font)

        # Применяем шрифт к интерфейсу
        # Применяем к дереву (имена файлов и папок)
        if hasattr(self.parent_window, 'tree'):
            self.parent_window.tree.setFont(self.ui_font)

        # Сохраняем шрифт интерфейса в MainWindow и применяем к вкладкам
        self.parent_window.ui_font = self.ui_font
        try:
            self.parent_window.editor_text_font = QFont(self.text_font)
            self.parent_window._editor_text_font_loaded = True
        except Exception:
            pass
        self.parent_window.apply_ui_font_to_tabs()

        # Сохраняем настройки шрифта в файл
        settings_file = self.parent_window.get_settings_file_path()
        config = _read_settings_ini(settings_file)

        # Пишем в секцию текущей ОС ([Font_Win]/[Font_Linux]/[Font_macOS]);
        # общую [Font] намеренно не изменяем (совместимость прежних версий).
        _font_section = _ensure_settings_section(config, "Font")

        # Сохраняем шрифт текстового поля
        config.set(_font_section, 'text_family', self.text_font.family())
        config.set(_font_section, 'text_size', str(self.text_font.pointSize()))
        config.set(_font_section, 'text_bold', str(self.text_font.bold()))
        config.set(_font_section, 'text_italic', str(self.text_font.italic()))

        # Сохраняем настройки интерфейса
        config.set(_font_section, 'ui_family', self.ui_font.family())
        config.set(_font_section, 'ui_size', str(self.ui_font.pointSize()))
        config.set(_font_section, 'ui_bold', str(self.ui_font.bold()))
        config.set(_font_section, 'ui_italic', str(self.ui_font.italic()))

        # Сохраняем отступ редактора и настройки быстрого доступа
        if not config.has_section('Editor'):
            config.add_section('Editor')
        try:
            margin = int(self.margin_spin.value())
            margin = max(0, min(1000, margin))  # Ограничиваем от 0 до 1000
            config.set('Editor', 'left_margin', str(margin))
        except ValueError:
            config.set('Editor', 'left_margin', '27')

        # Сохраняем количество переводов каретки
        try:
            newlines_count = int(self.newlines_spin.value())
            newlines_count = max(0, min(1000, newlines_count))  # Ограничиваем от 0 до 1000
            config.set('Editor', 'newlines_count', str(newlines_count))
        except ValueError:
            config.set('Editor', 'newlines_count', '50')
        # Удаляем устаревшую настройку (могла остаться в старых ini)
        try:
            if config.has_option('Editor', 'cursor_line'):
                config.remove_option('Editor', 'cursor_line')
        except Exception:
            pass

        # Сохраняем межстрочный интервал (проценты от высоты шрифта)
        try:
            line_spacing = int(self.line_spacing_spin.value()) if hasattr(self, 'line_spacing_spin') and self.line_spacing_spin else 100
            line_spacing = max(50, min(200, line_spacing))
            config.set('Editor', 'line_spacing', str(line_spacing))
        except Exception:
            config.set('Editor', 'line_spacing', '100')

        # Сохраняем выравнивание (trailing/leading)
        try:
            right_alignment = bool(self.alignRight_checkbox.isChecked()) if hasattr(self, "alignRight_checkbox") and self.alignRight_checkbox else False
        except Exception:
            right_alignment = False
        try:
            config.set('Editor', 'right_alignment', str(bool(right_alignment)))
        except Exception:
            pass

        # Сохраняем правый отступ (px) при выравнивании справа
        try:
            right_indent_px = int(self.right_indent_spin.value()) if hasattr(self, "right_indent_spin") and self.right_indent_spin else int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))
        except Exception:
            right_indent_px = int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))
        right_indent_px = max(0, min(500, int(right_indent_px)))
        try:
            config.set('Editor', 'right_indent', str(int(right_indent_px)))
        except Exception:
            pass

        # Сохраняем настройки формата даты
        if not config.has_section('General'):
            config.add_section('General')

        # Определяем выбранный формат
        checked_button = self.date_format_button_group.checkedButton() if hasattr(self, "date_format_button_group") else None
        if checked_button == getattr(self, "date_format_short_ISO_radio", None):
            date_format = 'iso'
        elif checked_button == getattr(self, "date_format_short_us_radio", None):
            date_format = 'us'
        elif checked_button == getattr(self, "date_format_short_radio", None):
            date_format = 'short'
        else:
            date_format = 'long'

        include_time_checked = False
        try:
            include_time_checked = bool(self.date_include_time_checkbox.isChecked())
        except Exception:
            include_time_checked = False
        config.set('General', 'date_format', date_format)
        config.set('General', 'date_include_time', str(include_time_checked))

        try:
            _write_settings_ini_atomic(settings_file, config)
        except Exception:
            pass


class ResizeEventFilter(QObject):
    """Фильтр событий для перехвата событий мыши на уровне приложения"""
    
    def __init__(self, main_window):
        super().__init__()
        self.main_window = main_window
    
    def eventFilter(self, obj, event):
        """Перехватываем события мыши для обработки изменения размера"""
        # Проверяем события мыши
        if isinstance(event, QMouseEvent):
            # Если открыт модальный диалог/попап, не даём глобальному override-курсору "залипать" поверх него
            # и не прокидываем события в логику ресайза главного окна.
            try:
                if QApplication.activeModalWidget() is not None or QApplication.activePopupWidget() is not None:
                    if QApplication.overrideCursor() is not None:
                        QApplication.restoreOverrideCursor()
                    return False
            except Exception:
                pass

            # Игнорируем события от дочерних окон (диалогов)
            if isinstance(obj, QDialog) or (hasattr(obj, 'window') and isinstance(obj.window(), QDialog)):
                return False
            
            # Оптимизация: сначала проверяем, является ли объект главным окном
            if obj == self.main_window:
                widget = self.main_window
            else:
                # Получаем главное окно из объекта события (только если нужно)
                widget = obj
                while widget and not isinstance(widget, MainWindow):
                    parent = widget.parent()
                    # Если родитель - диалог, прекращаем поиск
                    if isinstance(parent, QDialog):
                        return False
                    widget = parent
            
            if widget == self.main_window:
                # КРИТИЧНО: Проверяем, не находится ли курсор над открытым контекстным меню
                global_pos = event.globalPos()
                if self.main_window._is_menu_open_at_position(global_pos):
                    # Если курсор над меню, не обрабатываем события ресайза
                    # Сбрасываем курсор ресайза, если он был установлен
                    if QApplication.overrideCursor() is not None:
                        QApplication.restoreOverrideCursor()
                    return False
                
                # Преобразуем координаты в координаты главного окна
                local_pos = self.main_window.mapFromGlobal(global_pos)
                
                # Создаем новое событие с правильными координатами
                if event.type() == QEvent.MouseMove:
                    new_event = QMouseEvent(
                        QEvent.MouseMove,
                        local_pos,
                        global_pos,
                        event.button(),
                        event.buttons(),
                        event.modifiers()
                    )
                    self.main_window.mouseMoveEvent(new_event)
                elif event.type() == QEvent.MouseButtonPress:
                    new_event = QMouseEvent(
                        QEvent.MouseButtonPress,
                        local_pos,
                        global_pos,
                        event.button(),
                        event.buttons(),
                        event.modifiers()
                    )
                    self.main_window.mousePressEvent(new_event)
                    edge = self.main_window._get_resize_edge(local_pos)
                    if edge:
                        return True
                elif event.type() == QEvent.MouseButtonRelease:
                    new_event = QMouseEvent(
                        QEvent.MouseButtonRelease,
                        local_pos,
                        global_pos,
                        event.button(),
                        event.buttons(),
                        event.modifiers()
                    )
                    self.main_window.mouseReleaseEvent(new_event)
        
        return False


class FocusAllowEventFilter(QObject):
    """Фильтр событий уровня приложения: разрешает фокус в TextEditor по клику ЛКМ.

    Это нужно, потому что Qt может менять фокус ДО вызова TextEditor.mousePressEvent(),
    и FocusGuard успевает вернуть фокус в дерево.
    """

    def __init__(self, main_window):
        super().__init__()
        self.main_window = main_window

    def _find_text_editor_ancestor(self, obj):
        try:
            w = obj
            while w is not None:
                if isinstance(w, TextEditor):
                    return w
                try:
                    w = w.parent()
                except Exception:
                    break
        except Exception:
            return None
        return None

    def _click_in_main_window(self, obj):
        mw = self.main_window
        if mw is None:
            return False
        try:
            w = obj
            while w is not None:
                if w is mw:
                    return True
                if isinstance(w, QDialog):
                    return False
                w = w.parent()
        except Exception:
            return False
        return False

    def eventFilter(self, obj, event):
        try:
            if isinstance(event, QMouseEvent) and event.type() == QEvent.MouseButtonPress:
                if event.button() == Qt.LeftButton and self._click_in_main_window(obj):
                    activate = getattr(self.main_window, "frameless_activate_if_inactive", None)
                    if callable(activate):
                        activate()
        except Exception:
            pass

        try:
            if not isinstance(event, QMouseEvent):
                return False
            if event.type() != QEvent.MouseButtonPress:
                return False
            if event.button() != Qt.LeftButton:
                return False

            # Игнорируем клики в диалогах/дочерних окнах
            try:
                if isinstance(obj, QDialog) or (hasattr(obj, 'window') and isinstance(obj.window(), QDialog)):
                    return False
            except Exception:
                pass

            te = self._find_text_editor_ancestor(obj)
            if te is None:
                return False

            if hasattr(self.main_window, "_allow_editor_focus"):
                self.main_window._allow_editor_focus(350)
        except Exception:
            return False

        return False




class JsonDocument:
    """Владелец in-memory данных одного JSON-файла.

    Инвариант владения:
    - Ровно один объект `JsonDocument` владеет ссылкой на dict данных конкретного файла.
    - UI держит последнюю strong-ссылку на активный документ (`MainWindow.current_document`).
    - Кэш не продлевает жизнь документа (weak refs), поэтому закрытие файла — O(1):
      достаточно потерять последнюю strong-ссылку.

    Важно: никакой deepcopy/очисток — только замена ссылки на dict (O(1)).
    """

    __slots__ = (
        "filepath", "_data", "_item_data_cache",
        "_ui_tree_root", "_ui_tree_ui_dirty",
        "_node_editor_doc_cache", "_node_editor_doc_lru",
        "__weakref__",
    )

    def __init__(self, filepath, data):
        self.filepath = filepath
        self._data = data if isinstance(data, dict) else {}
        # Пер-документный кеш больших данных элементов дерева:
        # изоляция между файлами + O(1) переключение (смена ссылки на кеш).
        self._item_data_cache = {}
        # Кэш UI-дерева при переключении между блокнотами в RAM (фаза 2).
        self._ui_tree_root = None
        self._ui_tree_ui_dirty = False
        # LRU-кэш готовых QTextDocument per node_id (фаза B, пункт 6).
        self._node_editor_doc_cache = {}
        self._node_editor_doc_lru = []

    @property
    def data(self):
        return self._data

    def replace_data(self, new_data):
        """O(1) замена данных документа (без копирования/очистки)."""
        self._data = new_data if isinstance(new_data, dict) else {}
        cache = getattr(self, "_node_editor_doc_cache", None)
        if isinstance(cache, dict):
            for entry in cache.values():
                try:
                    del entry["doc"]
                except Exception:
                    pass
            cache.clear()
        lru = getattr(self, "_node_editor_doc_lru", None)
        if isinstance(lru, list):
            lru.clear()

    @property
    def item_cache(self):
        """Пер-документный кеш содержимого элементов дерева."""
        return self._item_data_cache

class JsonMemoryCache:
    """Singleton-кэш документов.

    Ключевое требование: НЕ продлевать жизнь данных закрытого файла.
    Поэтому храним weak-ссылки на `JsonDocument` (WeakValueDictionary).
    """
    _instance = None
    _initialized = False
    
    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(JsonMemoryCache, cls).__new__(cls)
        return cls._instance
    
    def __init__(self):
        if not self._initialized:
            # Словарь: нормализованный путь -> JsonDocument (weak)
            self._docs = weakref.WeakValueDictionary()
            self._initialized = True

    def _key(self, filepath):
        """Нормализованный ключ пути (важно для Windows и CI-ФС на Linux)."""
        key = _filesystem_path_key(filepath)
        if key:
            return key
        try:
            abs_path = os.path.abspath(filepath)
        except Exception:
            abs_path = filepath
        return os.path.normcase(os.path.normpath(abs_path))

    def get_document(self, filepath):
        """Возвращает документ из кэша без I/O (или None)."""
        return self._docs.get(self._key(filepath))

    def open_document(self, filepath):
        """Возвращает JsonDocument, загружая с диска, если нужно.

        ВНИМАНИЕ: чтение с диска синхронное (как и раньше) — сохраняем текущее поведение.
        """
        key = self._key(filepath)
        doc = self._docs.get(key)
        if doc is not None:
            return doc

        if not _io_exists(filepath):
            return None

        if not jbp_is_valid(filepath, JBP_KIND_NOTEBOOK):
            return None

        try:
            data = jbp_load_json(filepath, JBP_KIND_NOTEBOOK)
            if not isinstance(data, dict):
                return None
            if notebook_schema_validate(data) is not None:
                return None
        except Exception:
            return None

        filepath_norm = _win_qt_path(filepath)
        doc = JsonDocument(filepath_norm, data)
        self._docs[key] = doc
        return doc

    def create_document(self, filepath, initial_data):
        """Создает новый документ в памяти (без I/O)."""
        key = self._key(filepath)
        filepath_norm = _win_qt_path(filepath)
        doc = JsonDocument(filepath_norm, initial_data)
        self._docs[key] = doc
        return doc

    def set_document_data(self, filepath, data):
        """Устанавливает данные документа (создавая документ при необходимости)."""
        if not isinstance(data, dict) or notebook_schema_validate(data) is not None:
            return None
        key = self._key(filepath)
        doc = self._docs.get(key)
        if doc is None:
            doc = self.create_document(filepath, data)
        else:
            doc.replace_data(data)
            doc._ui_tree_ui_dirty = True
        return doc
    
    def load(self, filepath):
        """Back-compat: возвращает dict данных (или None)."""
        doc = self.open_document(filepath)
        return doc.data if doc is not None else None
    
    def get(self, filepath):
        """Back-compat: получает dict данных без I/O (или None)."""
        doc = self.get_document(filepath)
        return doc.data if doc is not None else None
    
    def set(self, filepath, data):
        """Back-compat: сохраняет dict данных в документ (создавая его при необходимости)."""
        self.set_document_data(filepath, data)
    
    def save_to_disk(self, filepath):
        """Сохраняет данные из кэша на диск"""
        filepath = _win_qt_path(filepath)
        doc = self.get_document(filepath)
        if doc is None:
            return False
        
        try:
            data = doc.data
            jbp_dump_json(filepath, data, JBP_KIND_NOTEBOOK)
            return True
        except Exception:
            return False
    
    def remove(self, filepath):
        """Back-compat: явное удаление ключа из weak-кэша (обычно не нужно)."""
        try:
            key = self._key(filepath)
            if key in self._docs:
                del self._docs[key]
        except Exception:
            pass
    
    def has(self, filepath):
        """Проверяет, загружен ли файл в кэш"""
        return self.get_document(filepath) is not None


class SaveWorker(QObject):
    """Worker для сохранения JSON-файлов в отдельном потоке"""
    
    # Сигнал о завершении сохранения (success: bool, error_message: str)
    save_finished = pyqtSignal(bool, str)
    # Сигнал о завершении фоновой загрузки избранного (filepath_norm, data_or_None)
    favorite_loaded = pyqtSignal(str, object)
    # Сигнал о завершении фоновой загрузки блокнота для открытия (filepath_norm, data_or_None, request_id)
    notebook_loaded = pyqtSignal(str, object, int)
    
    @pyqtSlot(str, object)
    def save(self, filepath: str, payload):
        """Сохраняет JSON-данные в файл атомарно (temp+replace / QSaveFile) в отдельном потоке.
        
        Args:
            filepath: Путь к целевому файлу
            payload: либо bytes/bytearray/QByteArray (уже сериализовано),
                     либо python-объект (dict/list) для сериализации в worker thread.
        """
        success = False
        err = ""
        try:
            json_bytes = jbp_prepare_notebook_save_bytes(payload)
            jbp_write_bytes_atomic(filepath, json_bytes)
            success = True
        except Exception:
            success = False
            try:
                err = str(sys.exc_info()[1] or "")
            except Exception:
                err = ""
        
        # Отправляем сигнал о завершении (в GUI-поток через Qt event loop)
        self.save_finished.emit(bool(success), err)

    @pyqtSlot(object)
    def release_document(self, _doc):
        """Освобождение документа в потоке save_thread.

        В CPython освобождение больших dict/list может быть дорогим (decref всех элементов).
        Переносим момент последнего decref с UI-потока в уже существующий save_thread,
        чтобы не было фризов при переключении файлов.
        """
        return

    @pyqtSlot(str)
    def load_favorite(self, filepath: str):
        """Фоновая загрузка JSON для избранного (без блокировки UI)."""
        filepath_norm = _win_qt_path(filepath) if filepath else filepath
        data = _load_notebook_data_from_disk(filepath_norm)
        self.favorite_loaded.emit(filepath_norm, data)

    @pyqtSlot(str, int)
    def load_notebook(self, filepath: str, request_id: int):
        """Фоновая загрузка JSON для открытия блокнота (без блокировки UI)."""
        filepath_norm = _win_qt_path(filepath) if filepath else filepath
        data = _load_notebook_data_from_disk(filepath_norm)
        self.notebook_loaded.emit(filepath_norm, data, int(request_id))


class ImportTxtWorker(QObject):
    """Фоновое сканирование и чтение txt для импорта (без блокировки GUI)."""

    scan_done = pyqtSignal(int)
    file_ready = pyqtSignal(str, object, object, str)
    import_finished = pyqtSignal(bool)

    def __init__(self):
        super().__init__()
        self._cancelled = False

    @pyqtSlot()
    def cancel(self):
        self._cancelled = True

    @pyqtSlot(object)
    def run_import(self, job):
        self._cancelled = False
        entries = []
        try:
            if isinstance(job, dict):
                if job.get("type") == "folder":
                    root = job.get("root")
                    if root:
                        entries = _scan_txt_import_folder_entries(str(root))
                elif job.get("type") == "files":
                    entries = _scan_txt_import_file_entries(job.get("paths") or [])
        except Exception:
            entries = []

        total = len(entries)
        self.scan_done.emit(int(total))
        if self._cancelled:
            self.import_finished.emit(True)
            return

        for file_path, rel_parts, fail_label in entries:
            if self._cancelled:
                break
            rel_tuple = tuple(rel_parts or ())
            try:
                size = _io_getsize(file_path)
            except OSError:
                self.file_ready.emit(str(file_path), rel_tuple, None, str(fail_label or ""))
                continue
            if size > _TXT_SIZE_MAX_BYTES:
                self.file_ready.emit(str(file_path), rel_tuple, None, str(fail_label or ""))
                continue
            content = _read_txt_file_for_import(file_path)
            if content is None:
                self.file_ready.emit(str(file_path), rel_tuple, None, str(fail_label or ""))
            else:
                self.file_ready.emit(str(file_path), rel_tuple, content, "")
        self.import_finished.emit(bool(self._cancelled))


def _main_window_uses_dwm_shadow():
    """Windows: системная DWM-тень вместо QGraphicsDropShadowEffect + margin."""
    return sys.platform == "win32"


def _win32_widget_hwnd_int(widget):
    """HWND top-level окна как int (PyQt5 sip.voidptr → ctypes)."""
    if widget is None or sys.platform != "win32":
        return None
    try:
        hwnd = widget.winId()
        if hasattr(hwnd, "__int__"):
            return int(hwnd.__int__())
        if hasattr(hwnd, "value"):
            return int(hwnd.value)
        if isinstance(hwnd, int):
            return int(hwnd)
        return int(hwnd)
    except Exception:
        return None


class _Win32DwmMargins(ctypes.Structure):
    _fields_ = [
        ("cxLeftWidth", ctypes.c_int),
        ("cxRightWidth", ctypes.c_int),
        ("cyTopHeight", ctypes.c_int),
        ("cyBottomHeight", ctypes.c_int),
    ]


def _apply_win32_dwm_window_shadow(widget, *, enable=True):
    """Вкл/выкл системную тень DWM для frameless HWND (Windows only)."""
    if sys.platform != "win32" or widget is None:
        return False
    hwnd_int = _win32_widget_hwnd_int(widget)
    if not hwnd_int:
        return False
    try:
        dwmapi = ctypes.windll.dwmapi
    except Exception:
        return False

    DWMWA_NCRENDERING_POLICY = 2
    DWMNCRP_DISABLED = 1
    DWMNCRP_ENABLED = 2
    DWMWA_WINDOW_CORNER_PREFERENCE = 33
    DWMWCP_DONOTROUND = 1

    try:
        policy = ctypes.c_int(DWMNCRP_ENABLED if enable else DWMNCRP_DISABLED)
        dwmapi.DwmSetWindowAttribute(
            ctypes.c_void_p(hwnd_int),
            ctypes.c_uint(DWMWA_NCRENDERING_POLICY),
            ctypes.byref(policy),
            ctypes.sizeof(policy),
        )
        if enable:
            margins = _Win32DwmMargins(1, 1, 1, 1)
            donot_round = ctypes.c_int(DWMWCP_DONOTROUND)
            try:
                dwmapi.DwmSetWindowAttribute(
                    ctypes.c_void_p(hwnd_int),
                    ctypes.c_uint(DWMWA_WINDOW_CORNER_PREFERENCE),
                    ctypes.byref(donot_round),
                    ctypes.sizeof(donot_round),
                )
            except Exception:
                pass
        else:
            margins = _Win32DwmMargins(0, 0, 0, 0)
        dwmapi.DwmExtendFrameIntoClientArea(
            ctypes.c_void_p(hwnd_int),
            ctypes.byref(margins),
        )
        return True
    except Exception:
        return False


class MainWindow(FramelessWindowMixin, QMainWindow):
    """Главное окно приложения"""

    _resize_edge_size_top_extra = 15

    @staticmethod
    def _uses_dwm_window_shadow():
        return _main_window_uses_dwm_shadow()

    @staticmethod
    def _clear_application_override_cursor():
        """Снимает стек QApplication.setOverrideCursor (стрелки resize с краёв окна не должны залипать на диалогах)."""
        FramelessWindowMixin.clear_application_override_cursor()

    # Сигнал для безопасного освобождения документов в фоне (queued -> save_thread)
    release_document_signal = pyqtSignal(object)
    # Сигнал-запрос на сохранение (queued -> save_thread).
    # payload: dict/list (будет сериализовано в worker) или bytes (уже сериализовано).
    save_request_signal = pyqtSignal(str, object)
    # Сигнал для фоновой подгрузки избранного (queued -> save_thread)
    preload_favorite_signal = pyqtSignal(str)
    # Сигнал для фоновой загрузки блокнота при открытии (queued -> save_thread)
    load_notebook_signal = pyqtSignal(str, int)
    import_txt_request_signal = pyqtSignal(object)
    import_txt_cancel_signal = pyqtSignal()
    export_txt_request_signal = pyqtSignal(object)
    export_txt_cancel_signal = pyqtSignal()

    def __init__(self):
        super().__init__()
        
        # Инициализируем логирование геометрии
        self.current_file = None
        self.current_document = None  # JsonDocument (владелец данных активного json-файла)
        self.current_item = None
        # Словарь для отслеживания открытых файлов в каждой вкладке
        self.tab_items = {}  # Виджет вкладки -> элемент дерева
        # Отмеченные вкладки редактора (сессия текущего .json); отображение — префикс TAB_MARK_PREFIX.
        self._marked_tab_editors = set()
        # O(1) индекс: node_id -> editor вкладки, где открыт элемент.
        self._open_tab_by_node_id = {}
        self.previous_tab_index = -1  # Индекс предыдущей вкладки для сохранения изменений
        # Словарь для хранения состояния вкладок (позиция курсора, прокрутка, выделение)
        self.tab_states = {}  # Виджет вкладки -> dict с состоянием

        # ------------------------------------------------------------
        # FocusGuard: защита от НЕявного перевода фокуса из дерева в редактор
        # Разрешённые случаи: явные команды пользователя (Tab/Ctrl+Tab или F2 на macOS) и клик мышью в редакторе.
        # ------------------------------------------------------------
        self._focus_guard_enabled = True
        self._focus_guard_in_progress = False
        self._allow_editor_focus_until = 0.0  # time.monotonic()
        self._focus_guard_connected = False
        self._focus_allow_filter = None

        # Единственная вкладка для файлов-ссылок (общая для всех ссылок).
        # Держим прямую ссылку на редактор для O(1) доступа; индекс получаем через tab_widget.indexOf().
        self._link_tab_editor = None
        self._link_tab_text_color = theme_qcolor("link_color")
        # Кеш больших данных элементов — теперь ПЕР-ДОКУМЕНТНЫЙ.
        # В init держим пустой, а при открытии файла привязываем к current_document.item_cache (O(1)).
        self._item_data_cache = {}
        # Strong-ссылки на документы избранного по пути (для O(1) переключения без I/O).
        # Список путей — в favorites_bar_sandbox.model.
        self.favorites_documents_by_path = {}  # norm_path -> JsonDocument
        self._adding_to_favorites = False  # Флаг для предотвращения повторных вызовов
        
        # ------------------------------------------------------------
        # Autosave: debounce после паузы в вводе + fallback-тик (без disk I/O в textChanged)
        # ------------------------------------------------------------
        self.autosave_debounce_ms = 2000
        self.autosave_fallback_ms = 5000
        self.autosave_debounce_timer = QTimer(self)
        self.autosave_debounce_timer.setSingleShot(True)
        self.autosave_debounce_timer.timeout.connect(self._autosave_debounce_fired)
        self.autosave_fallback_timer = QTimer(self)
        self.autosave_fallback_timer.setInterval(self.autosave_fallback_ms)
        self.autosave_fallback_timer.timeout.connect(self._autosave_fallback_tick)
        self.autosave_fallback_timer.start()

        # Накопители изменений (заполняются O(1) в on_text_changed / при изменениях дерева)
        self._dirty_node_ids = set()
        self._dirty_editors = set()
        self._autosave_job = None  # state-machine для построения снапшота без фризов
        self._autosave_snapshot_pending = False
        self._change_counter = 0
        self._last_dispatched_save_counter = 0
        self._document_ui_loaded = True

        # Генератор ID узлов дерева (в рамках текущего документа)
        self._next_node_id = 1
        
        # Флаг для отслеживания изменений данных дерева (для оптимизации)
        self._tree_data_changed = False
        
        # Поток для сохранения файлов (тяжёлая часть старта) — инициализируем отложенно в finish_init().
        self.save_thread = None
        self.save_worker = None
        # Флаг для контроля очереди сохранений (одновременно только одно сохранение)
        self._save_in_progress = False
        # Отложенные снапшоты per-file (коалесинг: последний снапшот wins для каждого пути).
        self._pending_saves = {}
        # Запись ушла в worker, но save_finished ещё не пришёл (dirty до ack на диск).
        self._disk_write_pending = False
        # Пути, для которых запись на диск запрещена после ошибки (normcase abspath).
        self._save_write_disabled_paths = set()
        self._save_in_progress_filepath = None
        # 0 = ещё не показывали; 1 = первый диалог; 2 = второй (больше не показывать).
        self._autosave_fail_dialog_count = 0
        self._autosave_fail_second_timer = QTimer(self)
        self._autosave_fail_second_timer.setSingleShot(True)
        self._autosave_fail_second_timer.timeout.connect(self._on_autosave_fail_second_timeout)
        self._shutdown_waiting_for_save = False
        self._shutting_down = False
        self._background_closing_started = False
        # True, если закрытие инициировано SIGTERM/SIGINT (без интерактивных диалогов).
        self._shutdown_from_signal = False
        self._shutdown_save_watchdog_timer = None
        self._notebook_load_request_id = 0
        self._notebook_load_busy = False
        self._notebook_load_block_tab_signals = False
        self._notebook_load_after_success = None
        self._notebook_load_pin_favorites = False

        self.import_txt_thread = None
        self.import_txt_worker = None
        self._txt_import_active = False
        self._txt_import_worker_finished = False
        self._txt_import_queue = []
        self._txt_import_ui_timer = QTimer(self)
        self._txt_import_ui_timer.setSingleShot(True)
        self._txt_import_ui_timer.timeout.connect(self._process_txt_import_ui_batch)
        self._txt_import_progress = None
        self._txt_import_mode = None
        self._txt_import_target_folder = None
        self._txt_import_wrapper_folder = None
        self._txt_import_folder_cache = {}

        self.export_txt_thread = None
        self.export_txt_worker = None
        self._export_active = False
        self._export_progress = None
        self._export_dir = None
        self._export_single_item = False
        self._txt_import_imported_count = 0
        self._txt_import_failed_names = []
        self._txt_import_total = 0
        self._txt_import_read_done = 0
        self._txt_import_selected_dir = None
        self._txt_import_folder_wrapper_name = None
        self._txt_import_insert_root = None

        self.ensure_data_directory()

        # Guard против реэнтрантности (вложенные QEventLoop при ожидании снапшота).
        self._snapshot_wait_in_progress = False
        self._close_requested_during_snapshot_wait = False
        self._titlebar_saving_arm_timer = None
        self._snapshot_dispatch_poll_timer = None
        self._snapshot_wait_loop = None
        self._snapshot_wait_started = None
        self._snapshot_wait_timeout_ms = 0
        
        # Инициализируем переменные для настроек (будут загружены в init_ui)
        self.saved_window_geometry = None
        self.saved_splitter_sizes = None
        self.last_file_path = None  # Путь к последнему открытому файлу
        self.ui_font = self.get_system_proportional_font()  # Шрифт интерфейса по умолчанию
        self.editor_left_margin = 27  # Отступ редактора по умолчанию в пикселях
        self.newlines_count = 50  # Количество переводов каретки для новых файлов/папок по умолчанию
        # Переименование по повторному одиночному клику ("медленный двойной клик"), мс
        self.slow_double_click_min_interval_ms = SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT
        self.slow_double_click_max_interval_ms = SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT
        # Межстрочный интервал (проценты от высоты шрифта).
        # editor_line_spacing — "активное" значение этого запуска (не меняется до перезапуска)
        # editor_line_spacing_saved — значение, которое пишется в Setting.ini
        self.editor_line_spacing = 100
        self.editor_line_spacing_saved = 100
        # Шрифт редактора — активное значение сессии (как editor_line_spacing)
        self.editor_text_font = self.get_system_proportional_font()
        self._editor_text_font_loaded = False
        # Выравнивание текста: trailing/leading (поддержка смешанных LTR/RTL).
        # editor_right_alignment — "активное" значение этого запуска (не меняется до перезапуска)
        # editor_right_alignment_saved — значение, которое пишется в Setting.ini
        self.editor_right_alignment = False
        self.editor_right_alignment_saved = False
        # Перевод интерфейса (имя файла в папке languages без расширения).
        # ui_translation — "активное" значение этого запуска (не меняется до перезапуска)
        # ui_translation_saved — значение, которое пишется в Setting.ini
        self.ui_translation = ""
        self.ui_translation_saved = ""
        # Правый "safe" отступ при выравнивании по правому краю (px).
        # editor_right_indent_px — активное значение этого запуска
        # editor_right_indent_px_saved — значение, которое пишется в Setting.ini
        try:
            _default_right_indent_px = int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))
        except Exception:
            _default_right_indent_px = 10
        self.editor_right_indent_px = int(_default_right_indent_px)
        self.editor_right_indent_px_saved = int(_default_right_indent_px)
        # Подсветка ссылок внутри текста (вкладка Настройки -> Вид)
        self.highlight_links_in_text = True
        # Настраиваемые ограничения ширины (вкладка Настройки -> Вид)
        try:
            self.max_editor_tab_width_px = int(DEFAULT_EDITOR_TAB_MAX_WIDTH_PX)  # активное значение этого запуска
        except Exception:
            self.max_editor_tab_width_px = 170
        self.max_editor_tab_width_px_saved = int(self.max_editor_tab_width_px)  # значение, которое пишется в Setting.ini
        try:
            self.max_favorites_item_width_px = int(DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX)
        except Exception:
            self.max_favorites_item_width_px = 170
        self.max_favorites_item_width_px_saved = int(self.max_favorites_item_width_px)

        # Глобальный источник истины для ширины вкладок редактора (см. EditorTabBar).
        try:
            app = QApplication.instance()
            if app is not None:
                app.setProperty("jbpad_max_editor_tab_width_px", int(self.max_editor_tab_width_px))
        except Exception:
            pass
        
        # Настройки темы
        self.custom_theme_active = False
        self.border_color = LIGHT_THEME["window_border"]  # Цвет рамки окна (по умолчанию для светлой темы)
        # Режим «поверх всех окон» (переключается правой кнопкой панели избранного)
        self._always_on_top_enabled = False
        
        # Диалог поиска
        self.search_dialog = None
        self.theme_editor_dialog = None
        self._reopen_settings_after_theme_editor = False

        # Инварианты старта: до первого MainWindow.show() не выполняем логику, зависящую от геометрии/layout,
        # не двигаем UI и не запускаем callback-и через таймеры/processEvents.
        self._startup_initialized = False
        self._startup_settings_loaded = False
        self._startup_settings_file_missing = False
        self._startup_window_geometry = None  # QRect или None
        self._startup_window_maximized = False
        self._startup_splitter_sizes = None
        self._startup_show_tooltips = True
        self._startup_highlight_links_in_text = True
        self._startup_max_editor_tab_width_px = int(self.max_editor_tab_width_px)
        self._startup_max_favorites_item_width_px = int(self.max_favorites_item_width_px)
        self._startup_favorites_visible = False
        self._startup_favorites_paths_list = []

        # Логическое (пользовательское) состояние видимости панели избранного.
        # Нельзя полагаться на QWidget.isVisible() при закрытии, т.к. closeEvent делает self.hide().
        self._favorites_panel_visible_state = False
        
        self.init_ui()
        self._setup_theme_manager()

        # Глобальный хук смены фокуса: подключаем один раз.
        # (дерево создаётся отложенно в finish_init — обработчик устойчив к tree=None)
        try:
            app = QApplication.instance()
            if app and not getattr(self, "_focus_guard_connected", False):
                app.focusChanged.connect(self._on_app_focus_changed)
                self._focus_guard_connected = True

            # Разрешаем фокус в редактор по ЛКМ клику (до смены фокуса).
            if app and getattr(self, "_focus_allow_filter", None) is None:
                self._focus_allow_filter = FocusAllowEventFilter(self)
                app.installEventFilter(self._focus_allow_filter)

            # Централизованный контроль подсказок: фильтр уровня приложения.
            # Подавляет QEvent.ToolTip глобально, поэтому подсказки применяются немедленно
            # и корректно работают для элементов, созданных позже.
            if app and not getattr(self, "_tooltips_event_filter_installed", False):
                app.installEventFilter(self)
                self._tooltips_event_filter_installed = True
        except Exception:
            pass
        
        # Устанавливаем фильтр событий для центрального виджета, чтобы перехватывать события мыши для изменения размера
        # Используем central_content_widget вместо centralWidget, так как теперь структура изменилась
        if hasattr(self, 'central_content_widget') and self.central_content_widget:
            self.central_content_widget.installEventFilter(self)
        
        # Устанавливаем фильтр событий для дерева, чтобы перехватывать Tab
        # (дерево может быть создано отложенно в finish_init)
        if getattr(self, 'tree', None):
            self.tree.installEventFilter(self)
        
        # ВАЖНО: load_settings и автозагрузка последнего файла выполняются один раз после первого show()

        # Достраиваем тяжёлые части UI/ресурсы после первого кадра (не меняя тип окна).
        QTimer.singleShot(0, self.finish_init)

    def init_ui(self):
        """Инициализация интерфейса"""
        self.setWindowTitle(APP_BRAND)
        
        # Делаем окно frameless, но с поддержкой сворачивания/разворачивания
        flags = Qt.FramelessWindowHint | Qt.Window | Qt.WindowMinimizeButtonHint | Qt.WindowMaximizeButtonHint
        self.setWindowFlags(flags)

        use_dwm_shadow = self._uses_dwm_window_shadow()
        if use_dwm_shadow:
            # Windows: opaque shell + DWM-тень (без margin и QGraphicsDropShadowEffect).
            self.setAttribute(Qt.WA_TranslucentBackground, False)
            self.setAutoFillBackground(False)
            self._shadow_container_margin_px = 0
        else:
            # Linux/macOS: прозрачный shell + Qt drop-shadow в margin (как до слоя 3).
            self.setAttribute(Qt.WA_TranslucentBackground, True)
            self._shadow_container_margin_px = 10

        # Включаем отслеживание мыши для изменения размера окна
        self.setMouseTracking(True)
        
        # Устанавливаем минимальные размеры окна
        self.setMinimumSize(400, 300)
        
        # Размер и позиция окна будут установлены после первого show() (см. showEvent/_startup_after_show)
        
        self._window_shadow_blur_px = 20
        self._window_shadow_y_offset_px = 2
        self._shadow_container = QWidget()
        self._shadow_container.setObjectName("shadowContainer")
        if not use_dwm_shadow:
            self._shadow_container.setAttribute(Qt.WA_TranslucentBackground, True)
        self._shadow_container.setAutoFillBackground(False)
        self._shadow_container.setMouseTracking(True)
        
        self.setCentralWidget(self._shadow_container)
        self._shadow_container.installEventFilter(self)
        
        # Layout: margin > 0 только на Linux/macOS (зона Qt drop-shadow).
        self._shadow_container_layout = QVBoxLayout(self._shadow_container)
        m = int(self._shadow_container_margin_px)
        self._shadow_container_layout.setContentsMargins(m, m, m, m)
        self._shadow_container_layout.setSpacing(0)
        
        # Центральный виджет (основное содержимое) - непрозрачный с рамкой
        self.central_content_widget = QWidget()
        self.central_content_widget.setObjectName("centralContentWidget")
        self.central_content_widget.setAttribute(Qt.WA_StyledBackground, True)
        self.central_content_widget.setAutoFillBackground(True)
        border_style = f"QWidget#centralContentWidget {{ background: palette(base); border: 1px solid {self.border_color}; }}"
        self.central_content_widget.setStyleSheet(border_style)
        self.central_content_widget.setMouseTracking(True)
        self._shadow_container_layout.addWidget(self.central_content_widget)

        # Qt-тень только на Linux/macOS; на Windows — DWM после show().
        self._window_shadow_effect = None
        if not use_dwm_shadow:
            self._window_shadow_effect = QGraphicsDropShadowEffect()
            self._window_shadow_effect.setBlurRadius(int(self._window_shadow_blur_px))
            self._window_shadow_effect.setXOffset(0)
            self._window_shadow_effect.setYOffset(int(self._window_shadow_y_offset_px))
            self._window_shadow_effect.setColor(theme_qcolor("window_shadow"))
            self.central_content_widget.setGraphicsEffect(self._window_shadow_effect)
        
        # Главный вертикальный layout для панели заголовка и содержимого
        main_layout = QVBoxLayout(self.central_content_widget)
        # Отступы 1px со всех сторон, чтобы виджеты не закрывали рамку
        main_layout.setContentsMargins(1, 1, 1, 1)
        main_layout.setSpacing(0)
        
        # Кастомная панель заголовка
        self.title_bar = CustomTitleBar(self)
        # Устанавливаем системный белый фон для панели заголовка
        self.title_bar.update_style(LIGHT_THEME["titlebar_background"], update_icons=True)
        self._connect_titlebar_nav_buttons()
        self._update_always_on_top_button_icon()
        main_layout.addWidget(self.title_bar)
        
        # Линия-разделитель под панелью заголовка
        self.title_bar_separator = QWidget(self)
        self.title_bar_separator.setFixedHeight(1)
        self.title_bar_separator.setAttribute(Qt.WA_StyledBackground, True)
        # Устанавливаем цвет разделителя для светлой темы (#cccccc)
        self.title_bar_separator.setStyleSheet(f"QWidget {{ background-color: {LIGHT_THEME['separator']}; }}")
        main_layout.addWidget(self.title_bar_separator)
        
        # Панель избранного (между toolbar и content_layout)
        self.favorites_container = QWidget()
        self.favorites_container.setStyleSheet("QWidget { border: none; outline: none; }")
        # Устанавливаем политику размера, чтобы контейнер не растягивался по вертикали
        self.favorites_container.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Fixed)
        favorites_layout = QVBoxLayout(self.favorites_container)
        favorites_layout.setContentsMargins(0, 0, 0, 0)
        favorites_layout.setSpacing(0)
        # Сохраняем layout как атрибут: панель избранного будет создана отложенно в finish_init()
        self._favorites_layout = favorites_layout

        # Новая панель избранного (QListView) создаётся отложенно.
        self.favorites_bar_sandbox = None
        self._favorites_bar_placeholder = QWidget(self.favorites_container)
        # Стартовая высота до синхронизации с высотой tabBar.
        self._favorites_bar_placeholder.setFixedHeight(24)
        self._favorites_bar_placeholder.setAttribute(Qt.WA_StyledBackground, True)
        self._favorites_bar_placeholder.setStyleSheet("QWidget { background: palette(base); border: none; }")
        favorites_layout.addWidget(self._favorites_bar_placeholder)
        
        # Разделитель под панелью избранного
        self.favorites_separator = QWidget()
        self.favorites_separator.setFixedHeight(1)
        self.favorites_separator.setAttribute(Qt.WA_StyledBackground, True)
        self.favorites_separator.setStyleSheet(f"QWidget {{ background-color: {LIGHT_THEME['separator']}; }}")
        favorites_layout.addWidget(self.favorites_separator)
        
        # Добавляем панель избранного в main_layout
        main_layout.addWidget(self.favorites_container)
        
        # Избранное хранится в модели новой панели (favorites_bar_sandbox.model)
        
        # Горизонтальный layout для содержимого
        content_layout = QHBoxLayout()
        content_layout.setContentsMargins(0, 0, 0, 0)
        content_layout.setSpacing(0)
        
        # Splitter для разделения дерева и редактора
        self.splitter = QSplitter(Qt.Horizontal)
        # Минимальные ширины панелей (пользователь не может "схлопнуть" их перетаскиванием).
        # Требование: дерево >= 76px, текстовое поле (правая панель) >= 144px.
        self._min_tree_width_px = 76
        self._min_editor_width_px = 144
        try:
            # Запрещаем пользовательское схлопывание секций до 0.
            # setCollapsible(i, ...) для конкретных индексов вызываем только когда секции уже созданы.
            self.splitter.setChildrenCollapsible(False)
        except Exception:
            pass
        # Устанавливаем ширину разделителя в 1 пиксель
        self.splitter.setHandleWidth(1)
        # Используем тот же цвет, что и рамка окна (#cccccc), чтобы визуально совпадали
        self.splitter.setStyleSheet(
            "QSplitter::handle { "
            f"background-color: {LIGHT_THEME['separator']}; "
            "width: 1px; "
            "border: none; "
            "margin: 0px; "
            "padding: 0px; "
            "min-width: 1px; "
            "max-width: 1px; "
            "}"
        )
        content_layout.addWidget(self.splitter)
        main_layout.addLayout(content_layout)
        
        # Дерево заметок (тяжёлая часть: QTreeWidget/модели) — создаём отложенно.
        self.tree = None
        self.tree_container = None
        self.spacer_label = None
        self._tree_placeholder = QWidget()
        self._tree_placeholder.setAttribute(Qt.WA_StyledBackground, True)
        self._tree_placeholder.setStyleSheet("QWidget { background: palette(base); border: none; }")
        try:
            self._tree_placeholder.setMinimumWidth(int(getattr(self, "_min_tree_width_px", 76)))
        except Exception:
            pass
        self.splitter.addWidget(self._tree_placeholder)
        
        # Вкладки/панель управления/иконки (тяжёлая часть) — создаём отложенно.
        self.tab_widget = None
        self.add_temp_file_button = None
        self.control_panel = None
        self._tab_bar_bottom_line = None
        self.on_icon_label = None
        self.off_icon_label = None
        self._tab_placeholder = QWidget()
        self._tab_placeholder.setAttribute(Qt.WA_StyledBackground, True)
        self._tab_placeholder.setStyleSheet("QWidget { background: palette(base); border: none; }")
        try:
            self._tab_placeholder.setMinimumWidth(int(getattr(self, "_min_editor_width_px", 144)))
        except Exception:
            pass
        self.splitter.addWidget(self._tab_placeholder)
        # Теперь в splitter гарантированно есть 2 секции: безопасно применяем ограничения collapsible.
        self._apply_splitter_collapsible_constraints()
        
        # Вкладки будут созданы только после открытия JSON-файла
        # Не создаем вкладку по умолчанию
        
        # Пропорции будут установлены после загрузки настроек
        # Временно устанавливаем значения по умолчанию
        self.splitter.setSizes([242, 602])

        # Сохранение размеров splitter при изменении пользователем (debounced).
        try:
            self.splitter.splitterMoved.connect(self._on_splitter_moved)
        except Exception:
            pass
        
        self._setup_shortcuts()

    def _setup_shortcuts(self):
        """Глобальные горячие клавиши главного окна (QAction + QKeySequence)."""

        def _register_shortcut(action):
            _configure_macos_qaction_shortcut(action)
            self.addAction(action)

        search_action = QAction(self)
        search_action.setShortcut(QKeySequence("Ctrl+F"))
        search_action.triggered.connect(self.show_search_dialog)
        _register_shortcut(search_action)

        toggle_focus_action = QAction(self)
        # macOS: Ctrl+Tab → ⌘+Tab (переключатель приложений); на darwin — F2.
        if sys.platform == "darwin":
            toggle_focus_action.setShortcut(QKeySequence("F2"))
        else:
            toggle_focus_action.setShortcut(QKeySequence("Ctrl+Tab"))
        toggle_focus_action.triggered.connect(self.toggle_tree_editor_focus)
        _register_shortcut(toggle_focus_action)

        always_on_top_action = QAction(self)
        always_on_top_action.setShortcut(QKeySequence("F6"))
        always_on_top_action.triggered.connect(self._toggle_always_on_top_from_favorites)
        _register_shortcut(always_on_top_action)

        favorites_action = QAction(self)
        favorites_action.setShortcut(QKeySequence("F7"))
        favorites_action.triggered.connect(self.toggle_favorites_panel)
        _register_shortcut(favorites_action)

        insert_date_action = QAction(self)
        insert_date_action.setShortcuts([
            QKeySequence("F8"),
            QKeySequence("Ctrl+D"),
        ])
        insert_date_action.triggered.connect(lambda: self.insert_date_at_cursor())
        _register_shortcut(insert_date_action)

        insert_separator_action = QAction(self)
        insert_separator_action.setShortcuts([
            QKeySequence("F9"),
            QKeySequence("Ctrl+J"),
        ])
        insert_separator_action.triggered.connect(lambda: self.insert_separator_at_cursor())
        _register_shortcut(insert_separator_action)

        new_file_action = QAction(self)
        if sys.platform != "darwin":
            new_file_action.setShortcut(QKeySequence("Ctrl+N"))
        new_file_action.triggered.connect(lambda: self.add_file(self._current_tree_item()))
        _register_shortcut(new_file_action)

        new_folder_action = QAction(self)
        if sys.platform != "darwin":
            new_folder_action.setShortcut(QKeySequence("Ctrl+Shift+N"))
        new_folder_action.triggered.connect(lambda: self.add_folder(self._current_tree_item()))
        _register_shortcut(new_folder_action)

        if sys.platform == "darwin":
            # ⌘+N может не дойти до Qt; F3/F4 — надёжный запасной вариант (как F2 для фокуса).
            sc_new_file = QShortcut(QKeySequence("F3"), self)
            sc_new_file.setContext(Qt.ApplicationShortcut)
            sc_new_file.activated.connect(lambda: self.add_file(self._current_tree_item()))
            self._macos_shortcut_new_file = sc_new_file

            sc_new_folder = QShortcut(QKeySequence("F4"), self)
            sc_new_folder.setContext(Qt.ApplicationShortcut)
            sc_new_folder.activated.connect(lambda: self.add_folder(self._current_tree_item()))
            self._macos_shortcut_new_folder = sc_new_folder

    def _apply_splitter_collapsible_constraints(self):
        """Безопасно применяет запрет схлопывания секций splitter без warning'ов Qt."""
        splitter = getattr(self, "splitter", None)
        if not splitter:
            return
        try:
            splitter.setChildrenCollapsible(False)
        except Exception:
            pass
        try:
            if splitter.count() > 0:
                splitter.setCollapsible(0, False)
            if splitter.count() > 1:
                splitter.setCollapsible(1, False)
        except Exception:
            pass

    def _setup_theme_manager(self):
        """Подключает MainWindow к ThemeManager (live theme switch)."""
        try:
            tm = ThemeManager.instance()
            tm.register_refresh_callback(self._refresh_theme_ui)
            if hasattr(self, "title_bar") and self.title_bar and self.title_bar.theme_button:
                try:
                    self.title_bar.theme_button.clicked.disconnect()
                except Exception:
                    pass
                self.title_bar.theme_button.clicked.connect(self._show_theme_select_dialog)
            # tm.apply() в main() выполняется до создания MainWindow — синхронизируем QSS сейчас.
            self._refresh_theme_ui()
        except Exception:
            pass

    def _show_theme_select_dialog(self):
        """Открывает диалог выбора темы."""
        try:
            if not self._resolve_unsaved_theme_session():
                return
            dialog = ThemeSelectDialog(self)
            if dialog.exec_() == QDialog.Accepted:
                self.custom_theme_active = ThemeManager.instance().is_custom_theme_active()
        except Exception:
            pass

    def _prompt_unsaved_theme_session_action(self):
        """Да/Нет/Отмена для session-dirty темы.

        Returns:
            'none' — session не dirty;
            'saved' — сохранено;
            'discarded' — откат к последнему сохранённому (ini/файл);
            'cancelled' — пользователь отменил диалог.
        """
        tm = ThemeManager.instance()
        if not tm.is_session_dirty():
            return "none"
        name = tm.session_display_filename()
        text = _tr_with_line(
            "theme_editor.save_changes_prompt",
            "Сохранить изменения в теме:",
            name,
        )
        res = ThemedMessageDialog.question_yes_no_cancel(
            self,
            tr("dialog.confirmation", "Подтверждение"),
            text,
            default_button=QMessageBox.Cancel,
        )
        if res == QMessageBox.Yes:
            outcome = tm.save_session_theme(parent=self, app=QApplication.instance())
            if outcome in ("cancelled", "failed"):
                return "cancelled"
            return "saved"
        if res == QMessageBox.No:
            tm.revert_to_ini_active(QApplication.instance())
            return "discarded"
        return "cancelled"

    def _resolve_unsaved_theme_session(self):
        """Да/Нет/Отмена: save/discard/abort session-dirty темы; True — продолжить действие."""
        if getattr(self, "_shutdown_from_signal", False):
            return self._resolve_unsaved_theme_session_quiet()
        action = self._prompt_unsaved_theme_session_action()
        return action in ("none", "saved", "discarded")

    def _resolve_unsaved_theme_session_quiet(self):
        """Signal-shutdown: best-effort save без диалогов; иначе discard. Всегда True."""
        tm = ThemeManager.instance()
        if not tm.is_session_dirty():
            return True
        app = QApplication.instance()
        try:
            theme_name = str(tm.session_theme_name() or "").strip()
            # Builtin / «новая тема» требуют Save As — при SIGTERM диалог недопустим.
            if (not theme_name) or theme_name in THEME_REGISTRY:
                tm.revert_to_ini_active(app)
                return True
            theme_dict = tm.build_full_theme(theme_name, tm.session_working_dict())
            if tm.save_theme(theme_name, theme_dict):
                tm.clear_session_dirty()
                try:
                    tm.commit_active(theme_name, app)
                except Exception:
                    pass
                return True
        except Exception:
            pass
        try:
            tm.revert_to_ini_active(app)
        except Exception:
            pass
        return True

    def _abort_shutdown(self):
        """Отмена закрытия (например, отменён Save As в диалоге сохранения темы)."""
        self._disarm_shutdown_save_watchdog()
        self._background_closing_started = False
        self._shutting_down = False
        self._shutdown_from_signal = False
        self._shutdown_waiting_for_save = False
        # Resume autosave только если запись на диск для текущего файла ещё разрешена.
        if not self._is_disk_write_disabled_for_current():
            try:
                self._resume_autosave_timers()
            except Exception:
                pass
            try:
                has_dirty_notebook = bool(
                    getattr(self, "_tree_data_changed", False)
                    or getattr(self, "_autosave_snapshot_pending", False)
                    or getattr(self, "_dirty_node_ids", None)
                )
                if has_dirty_notebook:
                    self._schedule_autosave_after_pause()
            except Exception:
                pass
        try:
            self.show()
            self.raise_()
            self.activateWindow()
        except Exception:
            pass

    def _refresh_theme_ui(self):
        """Повторно применяет stylesheet/custom UI из текущей темы (без перезапуска)."""
        try:
            tm = ThemeManager.instance()
            theme = tm.theme()
            self.custom_theme_active = tm.is_custom_theme_active()
            self.border_color = theme["window_border"]

            if hasattr(self, "central_content_widget") and self.central_content_widget:
                self.central_content_widget.setStyleSheet(
                    f"QWidget#centralContentWidget {{ background: palette(base); border: 1px solid {self.border_color}; }}"
                )

            effect = getattr(self, "_window_shadow_effect", None)
            if not self._uses_dwm_window_shadow():
                if not isinstance(effect, QGraphicsDropShadowEffect):
                    try:
                        target = self._get_window_shadow_target()
                        attached = target.graphicsEffect() if target is not None else None
                        if isinstance(attached, QGraphicsDropShadowEffect):
                            effect = attached
                    except Exception:
                        effect = None
                if isinstance(effect, QGraphicsDropShadowEffect):
                    try:
                        effect.setColor(theme_qcolor("window_shadow"))
                    except RuntimeError:
                        pass

            if hasattr(self, "title_bar") and self.title_bar:
                self.title_bar.apply_theme_styles(theme)
                if self._is_disk_write_disabled_for_current():
                    self.title_bar.set_autosave_disabled_indicator(True)

            self._apply_theme_icons()

            for sep_name in ("title_bar_separator", "favorites_separator"):
                sep = getattr(self, sep_name, None)
                if sep:
                    sep.setStyleSheet(f"QWidget {{ background-color: {theme['separator']}; }}")

            if hasattr(self, "splitter") and self.splitter:
                self.splitter.setStyleSheet(
                    "QSplitter::handle { "
                    f"background-color: {theme['separator']}; "
                    "width: 1px; "
                    "border: none; "
                    "margin: 0px; "
                    "padding: 0px; "
                    "min-width: 1px; "
                    "max-width: 1px; "
                    "}"
                )

            if hasattr(self, "tab_widget") and self.tab_widget:
                self._apply_tabs_theme_styles()

            fav = getattr(self, "favorites_bar_sandbox", None)
            if fav and hasattr(fav, "apply_theme_styles"):
                fav.apply_theme_styles(theme)

            self._apply_editors_theme(theme)

            self.update()
        except Exception:
            pass

    def _apply_editors_theme(self, theme):
        """Один проход: тема редакторов (stylesheet/palette), link overlay, scrollbar; плюс дерево."""
        try:
            self._link_tab_text_color = theme_qcolor("link_color", theme)
            self._apply_tab_text_colors_theme(theme)

            tree = getattr(self, "tree", None)
            if tree is not None:
                tree.setStyleSheet(build_tree_widget_stylesheet(theme))
                apply_tree_text_palette(tree, theme)
                setup_themed_vertical_scrollbar(tree, theme, context="tree")
            tree_container = getattr(self, "tree_container", None)
            if tree_container is not None:
                apply_tree_container_background(tree_container, theme)

            tw = getattr(self, "tab_widget", None)
            if tw is None:
                return
            for i in range(tw.count()):
                w = tw.widget(i)
                if not isinstance(w, TextEditor):
                    continue
                if hasattr(w, "apply_theme_styles"):
                    w.apply_theme_styles(theme)
                if hasattr(w, "apply_link_color"):
                    w.apply_link_color(theme)
                setup_themed_vertical_scrollbar(w, theme, context="editor")
        except Exception:
            pass

    def _apply_tabs_theme_styles(self):
        """Повторно применяет stylesheet/custom UI tabs subsystem из текущей темы."""
        try:
            tm = ThemeManager.instance()
            tab_side_style = build_tab_side_button_style()
            if hasattr(self, "tab_widget") and self.tab_widget:
                self.tab_widget.setStyleSheet(build_tab_widget_stylesheet(1))
                if getattr(self, "add_temp_file_button", None):
                    self.add_temp_file_button.setStyleSheet(tab_side_style)
                left_corner = getattr(self, "_tabwidget_left_corner", None)
                if left_corner is not None:
                    apply_tab_corner_container_background(left_corner, tm.theme())
                sep = getattr(self, "_tab_corner_separator", None)
                if sep:
                    sep.setStyleSheet(f"background-color: {tm.color('separator')};")
                tab_bar = self.tab_widget.tabBar()
                if tab_bar:
                    tab_bar.update()
            if getattr(self, "_close_all_tab_button", None):
                self._close_all_tab_button.setStyleSheet(build_tab_side_button_style())
            line = getattr(self, "_tab_bar_bottom_line", None)
            if line is not None:
                line.apply_theme()
            self._sync_tab_bar_bottom_line()
            panel = getattr(self, "control_panel", None)
            if panel is not None:
                if hasattr(panel, "_sync_tool_button_geometry"):
                    panel._sync_tool_button_geometry()
                panel.update()
            self._update_control_panel_size()
        except Exception:
            pass

    def finish_init(self):
        """Отложенная инициализация тяжёлых частей UI/ресурсов.

        ВАЖНО: этот метод не должен менять тип окна (flags/WA_TranslucentBackground/маски).
        Он выполняется после первого кадра через QTimer.singleShot(0, ...).
        """
        if getattr(self, "_finish_init_done", False):
            return
        self._finish_init_done = True

        # На случай асинхронной замены placeholder'ов/виджетов обновляем ограничения splitter повторно.
        self._apply_splitter_collapsible_constraints()

        # ------------------------------------------------------------
        # 1) Поток сохранения (отложенный старт)
        # import/export-потоки создаются лениво при первом использовании.
        # ------------------------------------------------------------
        self._ensure_save_thread()

        # ------------------------------------------------------------
        # 2) Панель избранного (QListView) + png-иконка
        # ------------------------------------------------------------
        try:
            if getattr(self, "favorites_bar_sandbox", None) is None and hasattr(self, "_favorites_layout"):
                self.favorites_bar_sandbox = FavoritesBarSandbox(self.favorites_container)
                # Подключаем обработчики сигналов
                self.favorites_bar_sandbox.favoriteActivated.connect(self._on_sandbox_favorite_activated)
                self.favorites_bar_sandbox.favoriteRemoved.connect(self._on_sandbox_favorite_removed)
                # Подключаем кнопку добавления
                self.favorites_bar_sandbox.add_button.clicked.connect(self.add_to_favorites)
                # Заменяем плейсхолдер на реальную панель
                placeholder = getattr(self, "_favorites_bar_placeholder", None)
                if placeholder is not None:
                    self._favorites_layout.removeWidget(placeholder)
                    placeholder.deleteLater()
                    self._favorites_bar_placeholder = None
                self._favorites_layout.insertWidget(0, self.favorites_bar_sandbox)
                # Ограничение максимальной ширины элементов панели избранного (px).
                try:
                    if hasattr(self.favorites_bar_sandbox, "set_max_item_width_px"):
                        w = int(getattr(self, "max_favorites_item_width_px", DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX))
                        w = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(w)))
                        self.favorites_bar_sandbox.set_max_item_width_px(int(w))
                except Exception:
                    pass
                # ВАЖНО: применяем видимость панели избранного после замены плейсхолдера
                self._apply_favorites_panel_visibility(bool(getattr(self, "_startup_favorites_visible", False)))
        except Exception:
            pass

        # ------------------------------------------------------------
        # 3) Дерево (QTreeWidget)
        # ------------------------------------------------------------
        try:
            if getattr(self, "tree", None) is None and hasattr(self, "splitter") and self.splitter:
                tree_container = QWidget()
                self.tree_container = tree_container
                try:
                    tree_container.setMinimumWidth(int(getattr(self, "_min_tree_width_px", 76)))
                except Exception:
                    pass
                tree_layout = QVBoxLayout(tree_container)
                tree_layout.setContentsMargins(0, 2, 0, 0)
                tree_layout.setSpacing(0)

                self.tree = JsonTreeWidget(self)
                self.tree.setItemDelegate(CustomItemDelegate(self.tree))
                # ВАЖНО: widget-level прокси-стиль (раньше: self.tree.setStyle(TreeItemViewStyle(...)))
                # больше не ставится — на Windows это даёт access violation при закрытии приложения
                # (пояснение в комментарии к AppFusionStyle). Подавление полнострочного фона
                # выделения обеспечивает application-стиль AppFusionStyle (FlatTreeSelectionMixin).
                try:
                    self.tree.setIconSize(QSize(16, 16))
                except Exception:
                    pass
                try:
                    tree_theme = ThemeManager.instance().theme()
                except Exception:
                    tree_theme = LIGHT_THEME
                self.tree.setStyleSheet(build_tree_widget_stylesheet(tree_theme))
                apply_tree_text_palette(self.tree, tree_theme)
                apply_tree_container_background(tree_container, tree_theme)
                setup_themed_vertical_scrollbar(self.tree, tree_theme, context="tree")

                tree_layout.addWidget(self.tree)

                # Заменяем плейсхолдер в splitter
                placeholder = getattr(self, "_tree_placeholder", None)
                if placeholder is not None:
                    idx = self.splitter.indexOf(placeholder)
                    if idx >= 0:
                        # replaceWidget есть в Qt5, но на всякий случай держим fallback
                        if hasattr(self.splitter, "replaceWidget"):
                            self.splitter.replaceWidget(idx, tree_container)
                        else:
                            self.splitter.insertWidget(idx, tree_container)
                            placeholder.setParent(None)
                    placeholder.deleteLater()
                    self._tree_placeholder = None
                else:
                    self.splitter.insertWidget(0, tree_container)

                # Фильтр событий для дерева (Tab и др.)
                try:
                    self.tree.installEventFilter(self)
                except Exception:
                    pass
        except Exception:
            pass

        # ------------------------------------------------------------
        # 4) Вкладки + оверлеи + иконки
        # ------------------------------------------------------------
        try:
            if getattr(self, "tab_widget", None) is None and hasattr(self, "splitter") and self.splitter:
                # Контейнер для вкладок и панели управления
                tab_container = QWidget()
                try:
                    tab_container.setMinimumWidth(int(getattr(self, "_min_editor_width_px", 144)))
                except Exception:
                    pass
                # Держим ссылку, чтобы можно было O(1) скрывать/показывать всю правую панель,
                # не пересоздавая UI и не трогая layout.
                self._tab_container = tab_container
                tab_container.installEventFilter(self)
                tab_container_layout = QVBoxLayout()
                tab_container_layout.setContentsMargins(0, 0, 0, 0)
                tab_container_layout.setSpacing(0)

                # Вкладки для текстовых редакторов
                self.tab_widget = QTabWidget()
                # Используем кастомный TabBar с немного увеличенной высотой вкладок
                custom_tab_bar = EditorTabBar()
                custom_tab_bar._jbpad_main_window = self
                self.tab_widget.setTabBar(custom_tab_bar)
                # Важно: QTabWidget может сбрасывать expanding на дефолт (True) внутри setTabBar().
                # Нам нужно НЕ растягивать вкладки на всю ширину, иначе скролл-стрелки никогда не появятся.
                try:
                    custom_tab_bar.setExpanding(False)
                except Exception:
                    pass
                # Убираем внутренние отступы панели вкладок, чтобы текстовое поле было прижато
                # к границам так же, как и дерево
                # Также убираем отступы у всех QTextEdit внутри tab_widget и у самого tab_widget
                # Отступы вкладок сверху/снизу (в пикселях) — меняйте здесь при необходимости:
                tab_bar_tab_padding = 1
                self.tab_widget.setStyleSheet(build_tab_widget_stylesheet(tab_bar_tab_padding))
                # Синхронизируем видимость верхней линии pane под текущее количество вкладок (на старте вкладок 0).
                try:
                    self._sync_tab_pane_top_line()
                except Exception:
                    pass
                self.tab_widget.setTabsClosable(True)
                self.tab_widget.tabCloseRequested.connect(self.close_tab)
                self.tab_widget.currentChanged.connect(self.on_tab_changed)
                # Жёстко подавляем tooltip "Close Tab" на кнопках закрытия вкладок.
                try:
                    tab_bar = self.tab_widget.tabBar()
                    if tab_bar and hasattr(tab_bar, "_suppress_close_tab_button_tooltips"):
                        tab_bar._suppress_close_tab_button_tooltips()
                except Exception:
                    pass

                # Включаем прокрутку вкладок, когда они не помещаются
                custom_tab_bar.setUsesScrollButtons(True)
                # Применяем активное ограничение ширины вкладок редактора (если уже задано)
                try:
                    w = int(getattr(self, "max_editor_tab_width_px", DEFAULT_EDITOR_TAB_MAX_WIDTH_PX))
                    w = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(w)))
                    if hasattr(custom_tab_bar, "set_max_tab_width_px"):
                        custom_tab_bar.set_max_tab_width_px(int(w))
                except Exception:
                    pass

                # Подключаем обработчик изменения размера tabBar для обновления панели управления
                tab_bar = self.tab_widget.tabBar()
                if tab_bar:
                    tab_bar.installEventFilter(self)

                tab_container_layout.addWidget(self.tab_widget)
                tab_container.setLayout(tab_container_layout)

                # Кнопка для добавления нового файла в папку Temp — как в панели избранного (QToolButton, тот же стиль)
                tab_bar_h = self.tab_widget.tabBar().sizeHint().height()
                btn_h = max(tab_bar_h, 24)
                _tab_side_button_style = build_tab_side_button_style()
                self.add_temp_file_button = QToolButton(tab_container)
                self.add_temp_file_button.setFixedSize(btn_h, btn_h)
                self.add_temp_file_button.setCursor(Qt.ArrowCursor)
                self.add_temp_file_button.setFocusPolicy(Qt.NoFocus)
                self.add_temp_file_button.setIconSize(QSize(16, 16))
                self.add_temp_file_button.setStyleSheet(_tab_side_button_style)
                self.add_temp_file_button.setToolTip(tr("tooltip.add_temp_file", "Добавить временный файл"))
                self.add_temp_file_button.clicked.connect(self.add_temp_file)
                # Видимость синхронизируется централизованно (см. _sync_editor_chrome_visibility).
                self.add_temp_file_button.setVisible(False)

                # Устанавливаем иконку для кнопки добавления
                self._update_add_temp_file_button_icon()

                # Статичная кнопка в строке TabBar (не overlay, без move/геометрии).
                # Так не сдвигается содержимое вкладки (текстовое поле) и кнопка не участвует в скролле вкладок.
                self._tabwidget_left_corner = _FixedCornerContainer(QSize(btn_h + 1, btn_h), self.tab_widget)
                corner_layout = QHBoxLayout(self._tabwidget_left_corner)
                corner_layout.setContentsMargins(0, 0, 0, 0)
                corner_layout.setSpacing(0)
                self.add_temp_file_button.setParent(self._tabwidget_left_corner)
                corner_layout.setAlignment(Qt.AlignTop)
                corner_layout.addWidget(self.add_temp_file_button, 0, Qt.AlignTop)
                # Полоска-разделитель между кнопкой и первой вкладкой (как между вкладками — #cccccc)
                self._tab_corner_separator = QWidget(self._tabwidget_left_corner)
                self._tab_corner_separator.setFixedWidth(1)
                self._tab_corner_separator.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
                self._tab_corner_separator.setStyleSheet(
                    f"background-color: {ThemeManager.instance().color('separator')};"
                )
                corner_layout.addWidget(self._tab_corner_separator)
                apply_tab_corner_container_background(self._tabwidget_left_corner)
                self.tab_widget.setCornerWidget(self._tabwidget_left_corner, Qt.TopLeftCorner)
                # Видимость синхронизируется централизованно (см. _sync_editor_chrome_visibility).
                self._tabwidget_left_corner.setVisible(False)

                # Панель управления (кнопка «Закрыть все вкладки») — cornerWidget справа.
                self._create_control_panel_icons()
                self.control_panel.setParent(self.tab_widget)
                self.control_panel.setVisible(False)
                self.tab_widget.setCornerWidget(self.control_panel, Qt.TopRightCorner)
                # Сохраняем ссылку на панель управления в tab_widget (на будущее/совместимость).
                self.tab_widget.setProperty("control_panel", self.control_panel)

                self._tab_bar_bottom_line = _TabBarBottomLine(tab_container)
                self._tab_bar_bottom_line.setVisible(False)
                self._tab_bar_bottom_line.apply_theme()
                try:
                    self._sync_tab_bar_bottom_line()
                except Exception:
                    pass

                # Заменяем плейсхолдер в splitter
                placeholder = getattr(self, "_tab_placeholder", None)
                if placeholder is not None:
                    idx = self.splitter.indexOf(placeholder)
                    if idx >= 0:
                        # replaceWidget есть в Qt5, но на всякий случай держим fallback
                        if hasattr(self.splitter, "replaceWidget"):
                            self.splitter.replaceWidget(idx, tab_container)
                        else:
                            self.splitter.insertWidget(idx, tab_container)
                            placeholder.setParent(None)
                    placeholder.deleteLater()
                    self._tab_placeholder = None
                else:
                    self.splitter.addWidget(tab_container)

                # ВАЖНО: не сбрасываем размеры splitter в дефолтные, чтобы не перетирать значения из Setting.ini.
                # Если настройки уже загружены — применим их повторно после замены плейсхолдеров.
                try:
                    desired = getattr(self, "_startup_splitter_sizes", None)
                    if desired and hasattr(self, "splitter") and self.splitter:
                        self.splitter.setSizes(list(desired))
                except Exception:
                    pass

                # Применяем стартовую видимость правой панели (если JSON не загружен — всё скрыто).
                try:
                    self._sync_editor_chrome_visibility()
                except Exception:
                    pass
        except Exception:
            pass

        # ------------------------------------------------------------
        # 5) Синхронизация темы для виджетов, созданных отложенно (дерево, избранное, вкладки)
        # ------------------------------------------------------------
        try:
            self._refresh_theme_ui()
        except Exception:
            pass

    def event(self, event):
        """Обработчик событий для перехвата событий мыши от центрального виджета"""
        # Перехватываем события мыши от центрального виджета
        if hasattr(self, 'centralWidget') and self.centralWidget():
            if isinstance(event, QMouseEvent):
                try:
                    if self.isMaximized():
                        return super().event(event)
                except Exception:
                    pass
            if isinstance(event, QMouseEvent) and event.type() == QEvent.MouseMove:
                # Преобразуем координаты события в координаты главного окна
                global_pos = self.centralWidget().mapToGlobal(event.pos())
                local_pos = self.mapFromGlobal(global_pos)
                
                # Создаем новое событие для главного окна с правильными координатами
                new_event = QMouseEvent(
                    QEvent.MouseMove,
                    local_pos,
                    global_pos,
                    event.button(),
                    event.buttons(),
                    event.modifiers()
                )
                self.mouseMoveEvent(new_event)
            elif isinstance(event, QMouseEvent) and event.type() == QEvent.MouseButtonPress:
                global_pos = self.centralWidget().mapToGlobal(event.pos())
                local_pos = self.mapFromGlobal(global_pos)
                
                new_event = QMouseEvent(
                    QEvent.MouseButtonPress,
                    local_pos,
                    global_pos,
                    event.button(),
                    event.buttons(),
                    event.modifiers()
                )
                if not self._is_titlebar_chrome_at(local_pos):
                    self.mousePressEvent(new_event)
                edge = self._get_resize_edge(local_pos)
                if edge:
                    return True
            elif isinstance(event, QMouseEvent) and event.type() == QEvent.MouseButtonRelease:
                global_pos = self.centralWidget().mapToGlobal(event.pos())
                local_pos = self.mapFromGlobal(global_pos)
                
                new_event = QMouseEvent(
                    QEvent.MouseButtonRelease,
                    local_pos,
                    global_pos,
                    event.button(),
                    event.buttons(),
                    event.modifiers()
                )
                self.mouseReleaseEvent(new_event)
        
        return super().event(event)

    def showEvent(self, event):
        super().showEvent(event)
        try:
            _MainWindowResizeCursorAppFilter.instance().register_main_window(self)
        except Exception:
            pass
        if self._uses_dwm_window_shadow():
            QTimer.singleShot(0, self._deferred_apply_dwm_window_shadow)
        if not getattr(self, "_startup_initialized", False):
            self._startup_initialized = True
            # Важно: не блокируем первый кадр — настройки/автозагрузку делаем отложенно.
            # Порядок гарантируется: finish_init() уже поставлен в очередь ещё в __init__.
            QTimer.singleShot(0, self._startup_after_show)

    def hideEvent(self, event):
        try:
            _MainWindowResizeCursorAppFilter.instance().unregister_main_window(self)
            self._clear_application_override_cursor()
        except Exception:
            pass
        super().hideEvent(event)

    def leaveEvent(self, event):
        try:
            self._clear_application_override_cursor()
        except Exception:
            pass
        super().leaveEvent(event)

    def _startup_after_show(self):
        """Однократная инициализация после первого show().

        Здесь разрешена геометрия/layout, т.к. окно уже находится в фазе отображения.
        """
        if not ensure_data_directory():
            _notify_data_directory_create_failed(self)

        try:
            self.load_settings()
        except Exception:
            pass

        # 1) Применяем геометрию окна/максимизацию
        try:
            if isinstance(getattr(self, "_startup_window_geometry", None), QRect):
                self.setGeometry(self._startup_window_geometry)
            else:
                screen = QApplication.primaryScreen().availableGeometry()
                width, height = 867, 725
                x = screen.x() + (screen.width() - width) // 2
                y = screen.y() + (screen.height() - height) // 2
                self.setGeometry(x, y, width, height)
            if getattr(self, "_startup_window_maximized", False):
                self.showMaximized()
            self._sync_window_shadow_layout()
        except Exception:
            pass

        # 2) Splitter/toolbar/tooltips
        try:
            if getattr(self, "_startup_splitter_sizes", None) and hasattr(self, "splitter") and self.splitter:
                self.splitter.setSizes(list(self._startup_splitter_sizes))
                # Критично для старта без открытого файла: finish_init может "запомнить" дефолтные размеры
                # до загрузки Setting.ini. Обновляем кэш последних валидных размеров значением из ini,
                # чтобы при первом открытии файла восстановилась именно сохранённая пользователем ширина.
                try:
                    self._last_splitter_sizes_editor_visible = list(self._startup_splitter_sizes)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            # ВАЖНО: фиксируем состояние в поле self.show_tooltips, т.к. часть UI (например, кнопки панели избранного)
            # читает его через getattr(self, 'show_tooltips', True).
            self.set_show_tooltips(bool(getattr(self, "_startup_show_tooltips", True)))
        except Exception:
            pass
        try:
            self.set_link_highlight_enabled(bool(getattr(self, "_startup_highlight_links_in_text", True)))
        except Exception:
            pass

        # 2.1) Ограничения ширины (вкладка "Вид")
        try:
            fav_w = int(getattr(self, "_startup_max_favorites_item_width_px", getattr(self, "max_favorites_item_width_px", DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX)))
            fav_w = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(fav_w)))
            self.set_max_favorites_item_width_px(int(fav_w))
        except Exception:
            pass
        try:
            tab_w = int(getattr(self, "_startup_max_editor_tab_width_px", getattr(self, "max_editor_tab_width_px", DEFAULT_EDITOR_TAB_MAX_WIDTH_PX)))
            tab_w = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(tab_w)))
            # В этом запуске применяем то, что было считано при старте
            self.apply_max_editor_tab_width_px(int(tab_w))
            # Синхронизируем saved (значение в ini) с применённым на старте
            self.max_editor_tab_width_px_saved = int(tab_w)
        except Exception:
            pass

        # 3) Применяем шрифт интерфейса
        try:
            if hasattr(self, "tree") and self.tree and getattr(self, "ui_font", None):
                self.tree.setFont(self.ui_font)
            self.apply_ui_font_to_tabs()
        except Exception:
            pass

        # 4) Избранное: панель QListView — единственный источник истины
        try:
            favorites_paths = list(getattr(self, "_startup_favorites_paths_list", []) or [])
            if hasattr(self, "favorites_bar_sandbox") and self.favorites_bar_sandbox:
                m = getattr(self.favorites_bar_sandbox, "model", None)
                if m is not None:
                    # ВАЖНО: не блокируем сигналы модели — иначе QListView не обновится (QStringListModel сообщает о изменениях сигналами).
                    m.setStringList(favorites_paths)
        except Exception:
            pass

        # 5) Видимость панели избранного
        try:
            self._apply_favorites_panel_visibility(bool(getattr(self, "_startup_favorites_visible", False)))
        except Exception:
            pass

        # 6) Синхронизация оверлеев (после show)
        try:
            self._update_control_panel_size()
        except Exception:
            pass

        # 6.1) Если на старте нет открытого документа — синхронизируем "схлопнутый" UI,
        # но запоминаем размеры из ini (см. логику в _sync_editor_chrome_visibility).
        try:
            if not getattr(self, "current_file", None):
                self._sync_editor_chrome_visibility()
        except Exception:
            pass

        # 7) Авто-открытие последнего файла (после show, без таймеров)
        try:
            last_fp = getattr(self, "last_file_path", None)
            if last_fp and _io_exists(last_fp) and jbp_is_valid(last_fp, JBP_KIND_NOTEBOOK):
                self._request_async_notebook_open(
                    last_fp,
                    block_tab_signals=True,
                    after_success="startup_tree_focus",
                )
        except Exception:
            pass

        # 7.1) Первый запуск: авто-добавление справки в избранное и её открытие.
        # Выполняется только если: ini существует и прочитан, translation непуст и
        # валиден (jbp_load_locale), избранное пусто, last_file не задан, файл справки
        # существует и структурно корректен (_load_notebook_data_from_disk).
        # save_settings() здесь намеренно НЕ вызывается: сохранение выполняет ветка
        # after_success == "startup_help_saved" после успешного открытия.
        try:
            _help_settings_file = self.get_settings_file_path()
            _help_translation = str(getattr(self, "ui_translation", "") or "").strip()
            if (
                _help_translation
                and _io_exists(_help_settings_file)
                and not bool(getattr(self, "_startup_settings_file_missing", False))
            ):
                _help_locale_path = language_json_path(_help_translation)
                _help_locale_data = None
                if _help_locale_path:
                    try:
                        _help_locale_data, _help_locale_meta = jbp_load_locale(_help_locale_path)
                    except Exception:
                        _help_locale_data = None
                if isinstance(_help_locale_data, dict):
                    _help_favorites_empty = (
                        not list(getattr(self, "_startup_favorites_paths_list", []) or [])
                        and not list(self.get_favorites() or [])
                    )
                    if _help_favorites_empty and not getattr(self, "last_file_path", None):
                        # Имя локали с ФС на macOS приходит в NFD — сравниваем через
                        # _locale_names_equal() (NFC + casefold), иначе берётся Help.json.
                        _help_name = (
                            "Справка.json"
                            if _locale_names_equal(_help_translation, _BASE_RU_LOCALE_NAME)
                            else "Help.json"
                        )
                        _help_path = str(data_directory() / _help_name)
                        if (
                            _io_exists(_help_path)
                            and _load_notebook_data_from_disk(_help_path) is not None
                        ):
                            # add_favorite() сам проверяет доступность панели избранного
                            # и отсутствие дубликата (is_favorite).
                            if self.add_favorite(_help_path):
                                # Панель избранного должна стать видимой и сохраниться
                                # как panel_visible = True: используем существующий
                                # механизм (см. save_settings -> _favorites_panel_visible_state).
                                try:
                                    self._apply_favorites_panel_visibility(True)
                                except Exception:
                                    pass
                                self._request_async_notebook_open(
                                    _help_path,
                                    block_tab_signals=True,
                                    after_success="startup_help_saved",
                                    pin_favorites_cache=True,
                                )
        except Exception:
            pass

        # 8) Если файла настроек не было — создаём его один раз после применения геометрии
        try:
            if getattr(self, "_startup_settings_file_missing", False):
                self.save_settings()
                self._startup_settings_file_missing = False
        except Exception:
            pass
    
    def _get_window_shadow_target(self):
        """Виджет, на котором рисуется тень (только opaque content, не внешний контейнер)."""
        return getattr(self, "central_content_widget", None)

    def _apply_dwm_window_shadow(self, enable=True):
        """Windows: системная DWM-тень для frameless HWND."""
        return _apply_win32_dwm_window_shadow(self, enable=bool(enable))

    def _deferred_apply_dwm_window_shadow(self):
        try:
            if not self._uses_dwm_window_shadow():
                return
            if bool(self.isMaximized()):
                self._apply_dwm_window_shadow(False)
            else:
                self._apply_dwm_window_shadow(True)
        except Exception:
            pass

    def _create_window_shadow_effect(self):
        """Создаёт новый QGraphicsDropShadowEffect (каждый restore — новый объект)."""
        shadow = QGraphicsDropShadowEffect()
        try:
            shadow.setBlurRadius(int(getattr(self, "_window_shadow_blur_px", 20)))
            shadow.setXOffset(0)
            shadow.setYOffset(int(getattr(self, "_window_shadow_y_offset_px", 2)))
            shadow.setColor(theme_qcolor("window_shadow"))
        except Exception:
            pass
        return shadow

    def _clear_graphics_effects_on_shadow_widgets(self):
        """Снимает effect с content и legacy-контейнера."""
        for widget in (self._get_window_shadow_target(), getattr(self, "_shadow_container", None)):
            if widget is None:
                continue
            try:
                widget.setGraphicsEffect(None)
            except Exception:
                pass

    def _attach_window_shadow_effect(self):
        """Прикрепляет свежий эффект тени к central_content_widget (Linux/macOS)."""
        if self._uses_dwm_window_shadow():
            return None
        target = self._get_window_shadow_target()
        if target is None:
            return None
        self._clear_graphics_effects_on_shadow_widgets()
        shadow = self._create_window_shadow_effect()
        self._window_shadow_effect = shadow
        target.setGraphicsEffect(shadow)
        return shadow

    def _detach_window_shadow_effect(self):
        """Снимает эффект тени. Qt уничтожает объект — ссылку обнуляем."""
        self._clear_graphics_effects_on_shadow_widgets()
        self._window_shadow_effect = None

    def _sync_window_shadow_layout(self, maximized=None):
        """Синхронизирует отступы и тень контейнера с состоянием окна (normal/maximized)."""
        if self._uses_dwm_window_shadow():
            self._sync_dwm_window_shadow_layout(maximized)
            return

        # Linux/macOS: QGraphicsDropShadowEffect + margin в _shadow_container.
        layout = getattr(self, "_shadow_container_layout", None)
        container = getattr(self, "_shadow_container", None)
        if layout is None or container is None:
            return

        if maximized is None:
            try:
                maximized = bool(self.isMaximized())
            except Exception:
                maximized = False

        try:
            self._shadow_sync_token = int(getattr(self, "_shadow_sync_token", 0)) + 1
        except Exception:
            self._shadow_sync_token = 1
        sync_token = int(getattr(self, "_shadow_sync_token", 0))

        try:
            if maximized:
                layout.setContentsMargins(0, 0, 0, 0)
                self._detach_window_shadow_effect()
            else:
                m = int(getattr(self, "_shadow_container_margin_px", 10))
                layout.setContentsMargins(m, m, m, m)
                container.update()
                target = self._get_window_shadow_target()
                if target is not None:
                    target.update()
                try:
                    self.repaint()
                except Exception:
                    pass

                def _deferred_attach_shadow(token=sync_token):
                    try:
                        if token != int(getattr(self, "_shadow_sync_token", 0)):
                            return
                        if bool(self.isMaximized()):
                            return
                        self._attach_window_shadow_effect()
                        t = self._get_window_shadow_target()
                        if t is not None:
                            t.update()
                    except Exception:
                        pass

                QTimer.singleShot(0, _deferred_attach_shadow)
        except Exception:
            pass

    def _sync_dwm_window_shadow_layout(self, maximized=None):
        """Windows: margin=0, без Qt-effect; DWM-тень вкл/выкл по maximized."""
        layout = getattr(self, "_shadow_container_layout", None)
        container = getattr(self, "_shadow_container", None)
        if layout is None or container is None:
            return

        if maximized is None:
            try:
                maximized = bool(self.isMaximized())
            except Exception:
                maximized = False

        try:
            self._shadow_sync_token = int(getattr(self, "_shadow_sync_token", 0)) + 1
        except Exception:
            self._shadow_sync_token = 1
        sync_token = int(getattr(self, "_shadow_sync_token", 0))

        try:
            layout.setContentsMargins(0, 0, 0, 0)
            self._detach_window_shadow_effect()
            container.update()
            target = self._get_window_shadow_target()
            if target is not None:
                target.update()

            def _deferred_dwm_shadow(token=sync_token):
                try:
                    if token != int(getattr(self, "_shadow_sync_token", 0)):
                        return
                    self._deferred_apply_dwm_window_shadow()
                except Exception:
                    pass

            QTimer.singleShot(0, _deferred_dwm_shadow)
        except Exception:
            pass

    def changeEvent(self, event):
        """Обработчик изменения состояния окна"""
        super().changeEvent(event)

        if event.type() == QEvent.WindowActivate:
            try:
                fav = getattr(self, "favorites_bar_sandbox", None)
                if fav is not None:
                    fav._refresh_favorite_exists_cache()
            except Exception:
                pass

        if event.type() == QEvent.WindowDeactivate:
            try:
                self.frameless_restore_resize_cursor()
                FramelessWindowMixin.clear_application_override_cursor()
            except Exception:
                pass
            try:
                for ed in self._iter_tab_text_editors():
                    ed._set_editor_mouse_cursor(Qt.ArrowCursor)
            except Exception:
                pass

        if event.type() == QEvent.WindowStateChange:
            # После super(): isMaximized() уже отражает новое состояние (иначе тень не восстановится).
            try:
                self._sync_window_shadow_layout()
            except Exception:
                pass
            try:
                self.frameless_restore_resize_cursor()
            except Exception:
                pass
            # Обновляем иконку кнопки максимизации/восстановления при изменении состояния окна
            if hasattr(self, "title_bar") and self.title_bar:
                self.title_bar.update_icons()
                try:
                    self.title_bar.raise_()
                    for btn in getattr(self.title_bar, "titlebar_window_buttons", ()):
                        if btn is not None:
                            btn.raise_()
                            btn.setEnabled(True)
                            btn.update()
                except Exception:
                    pass
                try:
                    if QApplication.overrideCursor() is not None:
                        QApplication.restoreOverrideCursor()
                except Exception:
                    pass
                # Обновляем иконки кнопок панели избранного (новая панель)
                try:
                    if hasattr(self, "favorites_bar_sandbox") and self.favorites_bar_sandbox:
                        self.favorites_bar_sandbox._update_add_button_icon()
                        self._update_always_on_top_button_icon()
                except Exception:
                    pass
    
    def paintEvent(self, event):
        """Отрисовка рамки больше не используется - рамка рисуется через CSS border на central_content_widget"""
        super().paintEvent(event)
        # Рамка теперь рисуется через CSS border на central_content_widget
        # Этот метод оставлен для совместимости, но не рисует рамку
    
    def _is_titlebar_chrome_at(self, pos):
        """True, если pos (координаты MainWindow) попадает в titlebar с кнопками окна."""
        try:
            tb = getattr(self, "title_bar", None)
            if tb is None or not tb.isVisible():
                return False
            global_pos = self.mapToGlobal(pos)
            local = tb.mapFromGlobal(global_pos)
            return tb.rect().contains(local)
        except Exception:
            return False

    def _frameless_is_titlebar_drag_at(self, local_pos):
        try:
            tb = getattr(self, "title_bar", None)
            if tb is None or not tb.isVisible():
                return False
            global_pos = self.mapToGlobal(local_pos)
            tb_local = tb.mapFromGlobal(global_pos)
            if not tb.rect().contains(tb_local):
                return False
            return bool(tb._is_drag_region(tb_local))
        except Exception:
            return False

    def _get_shadow_layout_margin_px(self):
        """Текущий margin layout тени (0 в maximized, иначе из layout/константы)."""
        try:
            if self.isMaximized():
                return 0
        except Exception:
            pass
        try:
            layout = getattr(self, "_shadow_container_layout", None)
            if layout is not None:
                l, t, r, b = layout.getContentsMargins()
                return max(int(l), int(t), int(r), int(b))
        except Exception:
            pass
        return int(getattr(self, "_shadow_container_margin_px", 10))

    def _frameless_resize_inset_px(self):
        return self._get_shadow_layout_margin_px()

    def _frameless_resize_blocked_at(self, pos):
        """В titlebar блокируем только верхний/центральный resize; боковые края — разрешены."""
        if not self._is_titlebar_chrome_at(pos):
            return False
        edge_size = int(getattr(self, "_resize_edge_size", 4))
        inset = int(self._frameless_resize_inset_px())
        try:
            x = int(pos.x())
            width = int(self.rect().width())
        except Exception:
            return True
        if x <= edge_size + inset or x >= width - edge_size - inset:
            return False
        return True

    def mouseMoveEvent(self, event):
        if self.frameless_handle_mouse_move(event):
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.frameless_activate_if_inactive()
        if self.frameless_handle_mouse_press(event):
            return
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event):
        if self.frameless_handle_mouse_release(event):
            self.frameless_restore_resize_cursor()
            return
        if event.button() == Qt.LeftButton:
            self.frameless_restore_resize_cursor()
        super().mouseReleaseEvent(event)

    def nativeEvent(self, eventType, message):
        return self.frameless_dispatch_native_event(eventType, message)

    def _set_tab_item_binding(self, text_editor, item):
        """Обновляет связь editor -> item и O(1) индекс node_id -> editor."""
        if not text_editor:
            return
        old_item = self.tab_items.get(text_editor)
        item_changed = old_item != item
        if item_changed:
            self._marked_tab_editors.discard(text_editor)
        if old_item:
            try:
                old_node_id = self._get_item_cache_key(old_item)
            except Exception:
                old_node_id = None
            if old_node_id is not None and self._open_tab_by_node_id.get(old_node_id) == text_editor:
                self._open_tab_by_node_id.pop(old_node_id, None)

        self.tab_items[text_editor] = item

        if item:
            try:
                node_id = self._get_item_cache_key(item)
            except Exception:
                node_id = None
            if node_id is not None:
                self._open_tab_by_node_id[node_id] = text_editor

        if item_changed:
            self._sync_tab_label(text_editor)

    def _bind_editor_document_signals(self, text_editor):
        """Подключает contentsChange к текущему документу editor (O(1)) и применяет настройки подсветки ссылок."""
        if not text_editor:
            return
        try:
            old_doc = getattr(text_editor, "_doc_for_link_tracking", None)
            old_handler = getattr(text_editor, "_doc_contents_change_handler", None)
            if old_doc is not None and old_handler is not None:
                try:
                    old_doc.contentsChange.disconnect(old_handler)
                except Exception:
                    pass

            doc = text_editor.document()
            def _contents_change_handler(position, chars_removed, chars_added, ed=text_editor):
                self._on_editor_contents_changed(ed, position, chars_removed, chars_added)

            handler = _contents_change_handler
            doc.contentsChange.connect(handler)
            text_editor._doc_for_link_tracking = doc
            text_editor._doc_contents_change_handler = handler

            # Применяем текущую настройку подсветки ссылок к editor (важно для новых вкладок и после setDocument()).
            try:
                if isinstance(text_editor, TextEditor):
                    desired = bool(getattr(self, "highlight_links_in_text", True))
                    try:
                        current = bool(getattr(text_editor, "_link_highlight_enabled", True))
                    except Exception:
                        current = True
                    if current != desired:
                        text_editor.set_link_highlight_enabled(desired)
            except Exception:
                pass
        except Exception:
            pass

    def _prime_editor_link_prefix_cache(self, text_editor):
        """Кеширует границу первого токена для быстрого guard в contentsChange."""
        if not text_editor:
            return
        try:
            _, token_end = extract_leading_url_from_document(text_editor.document())
            text_editor._leading_token_end_pos = int(token_end)
        except Exception:
            text_editor._leading_token_end_pos = 0

    def _begin_link_status_refresh_suppress(self, text_editor):
        """Подавляет live-refresh иконки ссылки во время setDocument/detach."""
        if not text_editor:
            return
        try:
            text_editor._link_status_refresh_suppress = int(
                getattr(text_editor, "_link_status_refresh_suppress", 0) or 0
            ) + 1
        except Exception:
            try:
                text_editor._link_status_refresh_suppress = 1
            except Exception:
                pass

    def _end_link_status_refresh_suppress(self, text_editor):
        if not text_editor:
            return
        try:
            n = int(getattr(text_editor, "_link_status_refresh_suppress", 0) or 0)
            text_editor._link_status_refresh_suppress = max(0, n - 1)
        except Exception:
            try:
                text_editor._link_status_refresh_suppress = 0
            except Exception:
                pass

    def _refresh_item_link_status_from_editor(
        self,
        text_editor,
        item=None,
        force: bool = False,
        from_programmatic_load: bool = False,
    ):
        """Обновляет ROLE_IS_LINK_FILE и иконку по editor; при загрузке — с fallback на кэш."""
        if not text_editor:
            return
        try:
            if int(getattr(text_editor, "_link_status_refresh_suppress", 0) or 0) > 0:
                return
        except Exception:
            pass
        if item is None:
            item = self.tab_items.get(text_editor)
        if not item:
            return
        try:
            if item.data(0, ROLE_NODE_TYPE) != "file":
                text_editor._cached_is_link_file = False
                text_editor._leading_token_end_pos = 0
                return
        except Exception:
            return

        url, token_end = extract_leading_url_from_document(text_editor.document())
        cache_url = self._get_item_link_url_from_cache(item)
        editor_is_link = bool(url)

        if from_programmatic_load or force:
            effective_url = url or cache_url
            new_is_link = bool(effective_url)
            if effective_url and not url:
                url = effective_url
        else:
            new_is_link = editor_is_link

        text_editor._cached_is_link_file = new_is_link
        text_editor._leading_token_end_pos = int(token_end)

        try:
            old_is_link = bool(item.data(0, ROLE_IS_LINK_FILE))
        except Exception:
            old_is_link = False

        if (not force) and (new_is_link == old_is_link):
            return

        if old_is_link and (not new_is_link):
            if (from_programmatic_load or force) and cache_url:
                new_is_link = True
                url = cache_url
                text_editor._cached_is_link_file = True
            else:
                icon = get_file_icon("", self.style())
                item.setIcon(0, icon)
                item.setData(0, ROLE_IS_LINK_FILE, False)
                try:
                    tab_index = self.tab_widget.indexOf(text_editor) if hasattr(self, "tab_widget") and self.tab_widget else -1
                except Exception:
                    tab_index = -1
                self._sync_link_tab_status_for_editor(text_editor, item, tab_index)
                return

        icon = get_file_icon(url or cache_url or "", self.style())
        item.setIcon(0, icon)
        item.setData(0, ROLE_IS_LINK_FILE, bool(new_is_link))

        if new_is_link and (not old_is_link):
            shared_editor = getattr(self, "_link_tab_editor", None)
            try:
                shared_index = self.tab_widget.indexOf(shared_editor) if (shared_editor and hasattr(self, "tab_widget") and self.tab_widget) else -1
            except Exception:
                shared_index = -1
            if (shared_editor is None) or (shared_index < 0) or (shared_editor == text_editor):
                try:
                    tab_index = self.tab_widget.indexOf(text_editor) if hasattr(self, "tab_widget") and self.tab_widget else -1
                except Exception:
                    tab_index = -1
                self._sync_link_tab_status_for_editor(text_editor, item, tab_index)
            self._schedule_migrate_link_item_to_shared_tab(item, source_editor=text_editor)

    def _schedule_migrate_link_item_to_shared_tab(self, item, source_editor):
        """Планирует перенос item в общую вкладку ссылок с закрытием старой вкладки."""
        if not item or not source_editor:
            return
        try:
            if source_editor == getattr(self, "_link_tab_editor", None) or bool(source_editor.property("is_link_tab")):
                return
        except Exception:
            return
        try:
            shared_editor = getattr(self, "_link_tab_editor", None)
            if not shared_editor:
                return
            if self.tab_widget.indexOf(shared_editor) < 0:
                return
            if self.tab_widget.indexOf(source_editor) < 0:
                return
            if getattr(source_editor, "_pending_link_migrate", False):
                return
            source_editor._pending_link_migrate = True
        except Exception:
            return

        def _do_migrate():
            try:
                source_editor._pending_link_migrate = False
            except Exception:
                pass
            try:
                if not item or not source_editor:
                    return
                try:
                    if not self._should_treat_as_link_file(item):
                        return
                except Exception:
                    return
                if source_editor == getattr(self, "_link_tab_editor", None) or bool(source_editor.property("is_link_tab")):
                    return
                old_index = self.tab_widget.indexOf(source_editor)
                if old_index < 0:
                    return
                shared_editor_local = getattr(self, "_link_tab_editor", None)
                if not shared_editor_local or self.tab_widget.indexOf(shared_editor_local) < 0:
                    return

                self.open_link_item_in_shared_tab(item, also_navigate=False)

                old_index = self.tab_widget.indexOf(source_editor)
                if old_index >= 0 and self.tab_widget.count() > 1:
                    self.close_tab(old_index)
            except Exception:
                pass

        QTimer.singleShot(0, _do_migrate)

    def _on_editor_contents_changed(self, text_editor, position: int, chars_removed: int, chars_added: int):
        """Быстрый live-апдейт статуса файл-ссылка: пересчёт только при изменении префикса."""
        if not text_editor:
            return
        item = self.tab_items.get(text_editor)
        if not item:
            return
        try:
            if item.data(0, ROLE_NODE_TYPE) != "file":
                return
        except Exception:
            return

        try:
            token_end = int(getattr(text_editor, "_leading_token_end_pos", 0) or 0)
        except Exception:
            token_end = 0
        try:
            pos = int(position)
            removed = int(chars_removed)
            change_end = pos + removed
        except Exception:
            pos = 0
            change_end = 0

        # Если изменение строго после первого токена — статус не меняется.
        # token_end <= 0: префикс ещё не primed — guard не применяем (иначе пропускаем все правки кроме pos 0).
        if token_end > 0 and pos > token_end and change_end > token_end:
            return

        self._refresh_item_link_status_from_editor(text_editor, item=item, force=False)

    def _remove_tab_item_binding(self, text_editor):
        """Удаляет связь editor -> item и соответствующий O(1) индекс."""
        if not text_editor:
            return
        old_item = self.tab_items.pop(text_editor, None)
        if not old_item:
            return
        try:
            node_id = self._get_item_cache_key(old_item)
        except Exception:
            node_id = None
        if node_id is not None and self._open_tab_by_node_id.get(node_id) == text_editor:
            self._open_tab_by_node_id.pop(node_id, None)

    def get_open_editor_for_item(self, item):
        """Возвращает editor, где открыт item, или None (быстрый путь O(1))."""
        if not item:
            return None
        try:
            node_id = self._get_item_cache_key(item)
        except Exception:
            node_id = None
        if node_id is None:
            return None

        editor = self._open_tab_by_node_id.get(node_id)
        if editor is None:
            return None

        try:
            if self.tab_widget.indexOf(editor) < 0:
                self._open_tab_by_node_id.pop(node_id, None)
                return None
        except Exception:
            self._open_tab_by_node_id.pop(node_id, None)
            return None

        if self.tab_items.get(editor) != item:
            # Индекс устарел (например, вкладка была переиспользована)
            if self._open_tab_by_node_id.get(node_id) == editor:
                self._open_tab_by_node_id.pop(node_id, None)
            return None
        return editor

    def is_item_open_in_other_tab(self, item, current_editor) -> bool:
        """True, если item открыт во вкладке, отличной от current_editor."""
        opened_editor = self.get_open_editor_for_item(item)
        return bool(opened_editor is not None and opened_editor != current_editor)

    def is_item_open_in_tab(self, item):
        """Проверяет, открыт ли элемент в какой-либо вкладке (O(1))."""
        return self.get_open_editor_for_item(item) is not None

    def is_link_file_item(self, item) -> bool:
        """True, если item — файл и помечен как файл-ссылка (O(1))."""
        if not item:
            return False
        try:
            if item.data(0, ROLE_NODE_TYPE) != "file":
                return False
            return bool(item.data(0, ROLE_IS_LINK_FILE))
        except Exception:
            return False

    def _get_item_link_url_from_cache(self, item):
        """URL из кэша содержимого (str/list chunks), без join всего текста."""
        if not item:
            return None
        try:
            content = self._get_item_content_from_cache(item)
            return extract_leading_url_from_content(content)
        except Exception:
            return None

    def _should_treat_as_link_file(self, item) -> bool:
        """Файл-ссылка: ROLE_IS_LINK_FILE; кэш — только если флаг ещё не вычислен."""
        if not item:
            return False
        try:
            if item.data(0, ROLE_NODE_TYPE) != "file":
                return False
        except Exception:
            return False
        try:
            flag = item.data(0, ROLE_IS_LINK_FILE)
        except Exception:
            flag = None
        if flag is True:
            return True
        if flag is False:
            # Редактор мог уже снять ссылку; item_cache/autosave иногда отстаёт.
            return False
        return bool(self._get_item_link_url_from_cache(item))

    def on_tree_mouse_single_click(self, item):
        """Открытие из дерева по одиночному клику ЛКМ (новые правила)."""
        if not item or not self.current_file:
            return
        try:
            item_type = item.data(0, ROLE_NODE_TYPE)
        except Exception:
            return

        if item_type == "file" and self._should_treat_as_link_file(item):
            self.open_link_item_in_shared_tab(
                item,
                also_navigate=False,
                close_source_if_existing_shared=False
            )
            return

        # Папки и обычные файлы — в новой вкладке (как в контекстном меню/Tab)
        self.open_item_in_new_tab(item)

    def _apply_link_tab_style(self, tab_index: int):
        """Подсвечивает вкладку ссылок синим цветом заголовка."""
        try:
            if tab_index is None or tab_index < 0:
                return
            tab_bar = self.tab_widget.tabBar() if hasattr(self, "tab_widget") and self.tab_widget else None
            if not tab_bar:
                return
            if tab_index >= tab_bar.count():
                return
            tab_bar.setTabTextColor(tab_index, self._link_tab_text_color)
            tab_bar.update()
        except Exception:
            pass

    def _reset_tab_text_color_to_default(self, tab_index: int):
        """Сбрасывает цвет заголовка вкладки на tab_text из текущей темы."""
        try:
            if tab_index is None or tab_index < 0:
                return
            tab_bar = self.tab_widget.tabBar() if hasattr(self, "tab_widget") and self.tab_widget else None
            if not tab_bar:
                return
            if tab_index >= tab_bar.count():
                return
            tab_bar.setTabTextColor(tab_index, theme_qcolor("tab_text"))
            tab_bar.update()
        except Exception:
            pass

    def _apply_tab_text_colors_theme(self, theme):
        """Обновляет tab_text на всех вкладках редактора; вкладка-ссылка остаётся link_color."""
        try:
            tw = getattr(self, "tab_widget", None)
            if tw is None:
                return
            tab_bar = tw.tabBar()
            if not tab_bar:
                return
            default_color = theme_qcolor("tab_text", theme)
            link_color = theme_qcolor("link_color", theme)
            link_ed = getattr(self, "_link_tab_editor", None)
            for i in range(tw.count()):
                w = tw.widget(i)
                if w is link_ed or bool(w and w.property("is_link_tab")):
                    tab_bar.setTabTextColor(i, link_color)
                else:
                    tab_bar.setTabTextColor(i, default_color)
            tab_bar.update()
        except Exception:
            pass

    def _sync_link_tab_status_for_editor(self, text_editor, item, tab_index: int):
        """O(1): синхронизирует статус/цвет общей вкладки ссылок для активного editor."""
        if not text_editor:
            return

        is_link_item = False
        try:
            is_link_item = bool(item and self._should_treat_as_link_file(item))
        except Exception:
            is_link_item = False

        if is_link_item:
            # Гарантируем единственность "синей" вкладки ссылок:
            # если ранее была другая общая вкладка, сначала снимаем её статус/цвет.
            prev_link_editor = getattr(self, "_link_tab_editor", None)
            if prev_link_editor is not None and prev_link_editor != text_editor:
                try:
                    prev_idx = self.tab_widget.indexOf(prev_link_editor) if hasattr(self, "tab_widget") and self.tab_widget else -1
                except Exception:
                    prev_idx = -1
                try:
                    prev_link_editor.setProperty("is_link_tab", False)
                except Exception:
                    pass
                if prev_idx >= 0:
                    self._reset_tab_text_color_to_default(prev_idx)

            self._link_tab_editor = text_editor
            try:
                text_editor.setProperty("is_link_tab", True)
            except Exception:
                pass
            self._apply_link_tab_style(tab_index)
            return

        # Если в этой вкладке теперь открыт НЕ файл-ссылка, снимаем статус общей вкладки ссылок.
        try:
            is_marked_link_tab = bool(text_editor.property("is_link_tab"))
        except Exception:
            is_marked_link_tab = False
        if text_editor == getattr(self, "_link_tab_editor", None) or is_marked_link_tab:
            if text_editor == getattr(self, "_link_tab_editor", None):
                self._link_tab_editor = None
            try:
                text_editor.setProperty("is_link_tab", False)
            except Exception:
                pass
        self._reset_tab_text_color_to_default(tab_index)

    def _ensure_link_tab(self):
        """Возвращает (text_editor, tab_index) для единственной вкладки ссылок, создавая/находя её при необходимости."""
        if not hasattr(self, "tab_widget") or not self.tab_widget:
            return None, -1

        # 1) Быстрый путь: вкладка уже известна
        if self._link_tab_editor is not None:
            try:
                idx = self.tab_widget.indexOf(self._link_tab_editor)
            except Exception:
                idx = -1
            if idx >= 0:
                self._apply_link_tab_style(idx)
                try:
                    self._link_tab_editor.setProperty("is_link_tab", True)
                except Exception:
                    pass
                return self._link_tab_editor, idx
            self._link_tab_editor = None

        # 1.5) O(1): если открыта единственная вкладка и это обложка корня,
        # используем её как общую вкладку ссылок (до тех пор, пока пользователь её не закроет).
        try:
            if self.tab_widget.count() == 1 and getattr(self, "tree", None) and self.tree:
                root_item = self.tree.topLevelItem(0)
                ed0 = self.tab_widget.widget(0)
                if root_item and ed0 and hasattr(self, "tab_items") and self.tab_items.get(ed0) == root_item:
                    self._link_tab_editor = ed0
                    try:
                        ed0.setProperty("is_link_tab", True)
                    except Exception:
                        pass
                    self._apply_link_tab_style(0)
                    return ed0, 0
        except Exception:
            pass

        # 1.75) Любая вкладка с property is_link_tab (даже если флаг в дереве слетел).
        try:
            for i in range(self.tab_widget.count()):
                ed = self.tab_widget.widget(i)
                if ed is None:
                    continue
                try:
                    if not bool(ed.property("is_link_tab")):
                        continue
                except Exception:
                    continue
                self._link_tab_editor = ed
                try:
                    ed.setProperty("is_link_tab", True)
                except Exception:
                    pass
                self._apply_link_tab_style(i)
                return ed, i
        except Exception:
            pass

        # 2) Если уже есть какой-то открытый файл-ссылка в любой вкладке — используем его вкладку как общую
        try:
            for ed, it in self.tab_items.items():
                if it and self._should_treat_as_link_file(it):
                    idx = self.tab_widget.indexOf(ed)
                    if idx >= 0:
                        self._link_tab_editor = ed
                        try:
                            ed.setProperty("is_link_tab", True)
                        except Exception:
                            pass
                        self._apply_link_tab_style(idx)
                        return ed, idx
        except Exception:
            pass

        # 3) Иначе создаём новую вкладку ссылок (без сканов/таймеров, всё O(1))
        text_editor = TextEditor()
        text_editor.setPlaceholderText("")
        text_editor.textChanged.connect(self.on_text_changed)
        self._bind_editor_document_signals(text_editor)
        text_editor.setContextMenuPolicy(Qt.CustomContextMenu)
        text_editor.customContextMenuRequested.connect(self.show_text_editor_context_menu)

        self._setup_scroll_tracking(text_editor)

        # Применяем отступ из настроек
        text_editor.set_left_margin(self.editor_left_margin)

        # Применяем шрифт из настроек
        text_font = self.get_text_font_from_settings()
        if text_font:
            text_editor.setFont(text_font)

        # Межстрочный интервал: применяем только значение, считанное при старте приложения
        text_editor.set_default_line_spacing(getattr(self, 'editor_line_spacing', 100))
        # Выравнивание (trailing/leading): применяем только значение, считанное при старте приложения
        text_editor.set_default_alignment(getattr(self, 'editor_right_alignment', False))

        tab_index = self.tab_widget.addTab(text_editor, "Link")
        self._set_tab_item_binding(text_editor, None)
        self._link_tab_editor = text_editor
        try:
            self._sync_tab_pane_top_line()
        except Exception:
            pass
        try:
            text_editor.setProperty("is_link_tab", True)
        except Exception:
            pass
        self._apply_link_tab_style(tab_index)
        return text_editor, tab_index

    def open_link_item_in_shared_tab(self, item, also_navigate: bool = False, close_source_if_existing_shared: bool = False):
        """Открывает файл-ссылку в единственной вкладке ссылок.

        Если also_navigate=True — сразу выполняет переход.
        Возвращает text_editor вкладки ссылок или None.
        """
        if not item or not self.current_file:
            return None

        existing_shared_editor = None
        try:
            candidate = getattr(self, "_link_tab_editor", None)
            if candidate and self.tab_widget.indexOf(candidate) >= 0:
                existing_shared_editor = candidate
        except Exception:
            existing_shared_editor = None

        text_editor, tab_index = self._ensure_link_tab()
        if not text_editor or tab_index < 0:
            return None

        # Переключаемся на вкладку ссылок
        current_text_editor = self.get_current_text_editor()
        if current_text_editor and current_text_editor != text_editor:
            try:
                self._save_tab_state(current_text_editor)
            except Exception:
                pass

        try:
            self.tab_widget.setCurrentIndex(tab_index)
            self.previous_tab_index = tab_index
        except Exception:
            pass

        self._apply_link_tab_style(tab_index)

        # Важно: не перекидываемся на "уже открытую" вкладку этого item — всегда открываем в общей вкладке ссылок
        self.on_tree_selection_changed(item, allow_switch_to_open_tab=False)

        # Синхронизируем выделение в дереве с активной общей вкладкой ссылок.
        # Это критично для сценария миграции: файл становится "файл-ссылка" во вкладке обычного файла,
        # переносится в общую вкладку ссылок, но выделение в дереве могло остаться на предыдущей ссылке.
        try:
            if getattr(self, "tree", None) is not None and self.tree and item:
                signals_were_blocked = self.tree.blockSignals(True)
                try:
                    try:
                        self.tree.clearSelection()
                    except Exception:
                        pass
                    try:
                        self.tree.setCurrentItem(item)
                    except Exception:
                        pass
                    try:
                        item.setSelected(True)
                    except Exception:
                        pass
                    try:
                        self.tree.scrollToItem(item)
                    except Exception:
                        pass
                finally:
                    self.tree.blockSignals(signals_were_blocked)
                self.current_item = item
        except Exception:
            pass

        if also_navigate:
            try:
                content = self._get_item_content_from_cache(item)
                if isinstance(content, list):
                    # Для навигации достаточно префикса первого чанка
                    content = content[0] if content else ""
                content_str = content if isinstance(content, str) else ("" if content is None else str(content))
                url = extract_url(content_str[:4096])
                if url:
                    open_url_in_browser(url)
            except Exception:
                pass

        # Если общая вкладка ссылок уже существовала ранее и пользователь
        # пришел на файл-ссылку из обычной вкладки — закрываем эту обычную вкладку.
        if close_source_if_existing_shared and existing_shared_editor is not None and current_text_editor and current_text_editor != text_editor:
            try:
                old_index = self.tab_widget.indexOf(current_text_editor)
            except Exception:
                old_index = -1
            if old_index >= 0 and self.tab_widget.count() > 1:
                self.close_tab(old_index)

        return text_editor
    
    def open_item_in_new_tab(self, item, force_new_tab: bool = False):
        """Открывает элемент (файл или папку) в новой вкладке"""
        if not item:
            return
        
        # Черновик inline-create: никогда не открываем как документ.
        try:
            if bool(item.data(0, ROLE_IS_INLINE_CREATE_DRAFT)):
                return
        except Exception:
            pass
        
        # Вкладки создаются только после открытия JSON-файла
        if not self.current_file:
            return

        # O(1): если открыта единственная вкладка и это обложка корневой директории,
        # открываем элемент в этой же вкладке (не создавая новую).
        # force_new_tab=True используется для явной команды "Открыть в новой вкладке" из контекстного меню.
        try:
            if (not force_new_tab) and self.tab_widget.count() == 1 and getattr(self, "tree", None) and self.tree:
                root_item = self.tree.topLevelItem(0)
                ed0 = self.tab_widget.widget(0)
                if root_item and ed0 and hasattr(self, "tab_items") and self.tab_items.get(ed0) == root_item:
                    self.tab_widget.setCurrentIndex(0)
                    self.on_tree_selection_changed(item)
                    return self.get_current_text_editor()
        except Exception:
            pass

        # Файл-ссылка: вкладка может быть только одна — используем общую вкладку ссылок.
        if self._should_treat_as_link_file(item):
            return self.open_link_item_in_shared_tab(
                item,
                also_navigate=False,
                close_source_if_existing_shared=False
            )
        
        # Проверяем, не открыт ли уже этот элемент в какой-либо вкладке
        if self.is_item_open_in_tab(item):
            # Если элемент уже открыт, переключаемся на его вкладку
            text_editor = self.get_open_editor_for_item(item)
            if text_editor:
                tab_index = self.tab_widget.indexOf(text_editor)
                if tab_index >= 0:
                    # Сохраняем состояние текущей вкладки перед переключением
                    current_text_editor = self.get_current_text_editor()
                    if current_text_editor and current_text_editor != text_editor:
                        self._save_tab_state(current_text_editor)
                    
                    self.tab_widget.setCurrentIndex(tab_index)
                    # on_tab_changed сохранит предыдущую вкладку и вызовет _restore_tab_state.

                    # Новое правило: вкладка, из которой пользователь пытался
                    # открыть уже открытый элемент, закрывается как дубликат.
                    return text_editor
        
        # Сохраняем изменения из текущей вкладки перед созданием новой.
        # ВАЖНО: reuse_editor=False — вкладка продолжает показывать этот item,
        # stash+detach здесь затёрли бы её документ пустым placeholder.
        current_text_editor = self.get_current_text_editor()
        if current_text_editor:
            current_item = self.tab_items.get(current_text_editor)
            if current_item:
                self._prepare_editor_leave_for_tree_item(
                    current_text_editor, current_item, reuse_editor=False
                )
        
        # Создаем новую вкладку
        text_editor = TextEditor()
        # Стили уже применены в конструкторе TextEditor
        text_editor.setPlaceholderText("")
        text_editor.textChanged.connect(self.on_text_changed)
        self._bind_editor_document_signals(text_editor)
        text_editor.setContextMenuPolicy(Qt.CustomContextMenu)
        text_editor.customContextMenuRequested.connect(self.show_text_editor_context_menu)
        
        # Настраиваем отслеживание прокрутки для сохранения состояния
        self._setup_scroll_tracking(text_editor)
        
        # Применяем отступ из настроек
        text_editor.set_left_margin(self.editor_left_margin)
        
        # Применяем шрифт из настроек (setFont в _load_item_into_editor / _populate)
        text_font = self.get_text_font_from_settings()

        # Межстрочный интервал: применяем только значение, считанное при старте приложения
        text_editor.set_default_line_spacing(getattr(self, 'editor_line_spacing', 100))
        
        # Определяем название вкладки и содержимое
        item_type = item.data(0, Qt.UserRole)
        if item_type == "file":
            text_editor.blockSignals(True)
            updates_were_enabled = False
            try:
                updates_were_enabled = self._load_item_into_editor(text_editor, item, text_font=text_font)
            finally:
                if updates_were_enabled:
                    text_editor.setUpdatesEnabled(True)
                text_editor.blockSignals(False)
            self._prime_editor_link_prefix_cache(text_editor)
            self._refresh_item_link_status_from_editor(
                text_editor, item=item, force=True, from_programmatic_load=True
            )
            tab_name = item.text(0)
        elif item_type == "folder":
            text_editor.blockSignals(True)
            updates_were_enabled_folder = False
            try:
                updates_were_enabled_folder = self._load_item_into_editor(text_editor, item, text_font=text_font)
            finally:
                if updates_were_enabled_folder:
                    text_editor.setUpdatesEnabled(True)
                text_editor.blockSignals(False)
            text_editor.setPlaceholderText("")
            self._prime_editor_link_prefix_cache(text_editor)
            tab_name = item.text(0)
        else:
            return None
        
        # Добавляем вкладку
        tab_index = self.tab_widget.addTab(text_editor, tab_name)
        self._sync_link_tab_status_for_editor(text_editor, item, tab_index)
        self._set_tab_item_binding(text_editor, item)
        self.tab_widget.setCurrentIndex(tab_index)
        self.previous_tab_index = tab_index

        # Линия pane должна появиться только когда вкладки реально есть.
        try:
            self._sync_tab_pane_top_line()
        except Exception:
            pass
        
        # Сохраняем начальное состояние вкладки (виджет уже на нужной позиции после загрузки).
        self._save_tab_state(text_editor)
        try:
            text_editor._tab_state_needs_restore = False
        except Exception:
            pass
        
        # Выделяем элемент в дереве
        self.tree.setCurrentItem(item)
        self.tree.scrollToItem(item)
        self.current_item = item

        # Синхронизируем оверлеи после добавления вкладки
        if getattr(self, "_startup_initialized", False) and self.isVisible():
            try:
                self._update_control_panel_size()
            except Exception:
                pass
        
        return text_editor
    
    def get_current_text_editor(self):
        """Возвращает текущий текстовый редактор из активной вкладки"""
        current_index = self.tab_widget.currentIndex()
        if current_index >= 0:
            return self.tab_widget.widget(current_index)
        return None
    
    def _move_cursor_to_3rd_line_start_if_any(self, editor) -> bool:
        """Ставит курсор в начало 3-й строки, если она есть. Возвращает True при успехе."""
        try:
            doc = editor.document()
            block = doc.findBlockByNumber(2)  # 0-based: 0=1-я строка, 2=3-я
            if not block.isValid():
                return False
            c = QTextCursor(block)
            c.movePosition(QTextCursor.StartOfLine, QTextCursor.MoveAnchor)
            editor.setTextCursor(c)
            return True
        except Exception:
            return False

    def _maybe_apply_new_item_cursor_rule(self, reason=None):
        """Одноразово применяет правило курсора для только что созданного item."""
        if reason == "focus_toggle":
            return
        item = getattr(self, "_pending_new_item_cursor_item", None)
        if item is None:
            return
        try:
            current_item = self.tree.currentItem() if getattr(self, "tree", None) else None
        except Exception:
            current_item = None
        if current_item is not item:
            # Пользователь успел сменить выделение — правило больше не актуально.
            try:
                self._pending_new_item_cursor_item = None
                self._pending_new_item_cursor_reason = None
            except Exception:
                pass
            try:
                item.setData(0, ROLE_JUST_CREATED, False)
            except Exception:
                pass
            return

        editor = self.get_current_text_editor()
        if not editor:
            return

        # Снимаем pending сразу, чтобы правило было строго одноразовым.
        try:
            self._pending_new_item_cursor_item = None
            self._pending_new_item_cursor_reason = None
        except Exception:
            pass
        try:
            item.setData(0, ROLE_JUST_CREATED, False)
        except Exception:
            pass

        # Даём UI/документу устаканиться после смены вкладки/фокуса.
        try:
            QTimer.singleShot(0, lambda ed=editor: self._move_cursor_to_3rd_line_start_if_any(ed))
        except Exception:
            pass

    def focus_text_editor(self, reason=None):
        """Переносит фокус в текущий текстовый редактор, при необходимости открывает вкладку из выбранного элемента дерева"""
        editor = self.get_current_text_editor()
        if editor:
            self._allow_editor_focus(350)
            editor.setFocus()
            self._maybe_apply_new_item_cursor_rule(reason=reason)
            return True

        # Если вкладка не открыта, пытаемся открыть текущий элемент дерева
        if self.tree:
            current_item = self.tree.currentItem()
            if current_item:
                self.open_item_in_new_tab(current_item)
                editor = self.get_current_text_editor()
                if editor:
                    self._allow_editor_focus(350)
                    editor.setFocus()
                    self._maybe_apply_new_item_cursor_rule(reason=reason)
                    return True
        return False

    def focus_tree(self):
        """Переносит фокус на дерево"""
        if self.tree:
            # Если нет текущего элемента, выбираем первый
            if not self.tree.currentItem() and self.tree.topLevelItemCount() > 0:
                self.tree.setCurrentItem(self.tree.topLevelItem(0))
            self.tree.setFocus()
            return True
        return False

    def _current_tree_item(self):
        """Текущий выделенный элемент дерева (или None)."""
        tree = getattr(self, "tree", None)
        if tree is None:
            return None
        try:
            return tree.currentItem()
        except Exception:
            return None

    def _is_focus_in_tree(self) -> bool:
        tree = getattr(self, "tree", None)
        if not tree:
            return False
        fw = QApplication.focusWidget()
        if fw is None:
            return False
        return fw is tree or self._widget_has_ancestor(fw, tree)

    def _is_focus_in_text_editor(self) -> bool:
        tab_widget = getattr(self, "tab_widget", None)
        if not tab_widget:
            return False
        fw = QApplication.focusWidget()
        if fw is None:
            return False
        try:
            for i in range(tab_widget.count()):
                w = tab_widget.widget(i)
                if w and (fw is w or self._widget_has_ancestor(fw, w)):
                    return True
        except Exception:
            pass
        return False

    def toggle_tree_editor_focus(self):
        """Переключение фокуса дерево ↔ редактор (Ctrl+Tab; macOS: F2)."""
        if self._is_focus_in_tree():
            self.focus_text_editor(reason="focus_toggle")
        elif self._is_focus_in_text_editor():
            self.focus_tree()
        elif not self.focus_text_editor(reason="focus_toggle"):
            self.focus_tree()

    def _focused_tree_name_line_edit(self):
        """QLineEdit inline-редактора имени в дереве (создание или переименование), если он в фокусе."""
        try:
            fw = QApplication.focusWidget()
        except Exception:
            fw = None
        if fw is None or not isinstance(fw, QLineEdit):
            return None
        tree = getattr(self, "tree", None)
        if not tree or not self._widget_has_ancestor(fw, tree):
            return None
        if (fw is getattr(tree, "_inline_create_editor", None)
                and getattr(tree, "_inline_create_active", False)):
            return fw
        try:
            if tree.state() == QAbstractItemView.EditingState:
                return fw
        except Exception:
            pass
        return None

    def _insert_date_into_line_edit(self, line_edit):
        """Вставляет текущую дату в позицию курсора QLineEdit (inline-редактор имени)."""
        if not line_edit:
            return
        date_format, include_time = self.get_date_settings()
        date_str = format_date(date_format, include_time)
        try:
            line_edit.insert(date_str)
        except Exception:
            pass

    def _editor_for_insert_command(self, text_editor=None):
        """Редактор для F8/F9/Ctrl+D/Ctrl+J без «слепой» вставки при фокусе в дереве."""
        # QAction.triggered передаёт checked: bool — не путать с виджетом редактора.
        if isinstance(text_editor, TextEditor):
            return text_editor
        if self._focused_tree_name_line_edit() is not None:
            return None
        if self._is_focus_in_text_editor():
            return self.get_current_text_editor()
        if self._is_focus_in_tree():
            current_item = self._current_tree_item()
            if current_item:
                self.open_item_in_new_tab(current_item)
            if self.focus_text_editor():
                return self.get_current_text_editor()
            return None
        return None

    def insert_date_at_cursor(self, text_editor=None):
        """Вставляет текущую дату в позицию курсора активного редактора."""
        if not isinstance(text_editor, TextEditor):
            text_editor = None
        if text_editor is None:
            name_edit = self._focused_tree_name_line_edit()
            if name_edit is not None:
                self._insert_date_into_line_edit(name_edit)
                return
        editor = self._editor_for_insert_command(text_editor)
        if not editor:
            return
        date_format, include_time = self.get_date_settings()
        date_str = format_date(date_format, include_time)
        cursor = editor.textCursor()
        cursor.insertText(date_str)
        editor.setTextCursor(cursor)

    def insert_separator_at_cursor(self, text_editor=None):
        """Вставляет пользовательский разделитель в позицию курсора активного редактора."""
        editor = self._editor_for_insert_command(text_editor)
        if not editor:
            return
        try:
            sep = self.get_separator_text()
        except Exception:
            sep = ""
        cursor = editor.textCursor()
        cursor.insertText(str(sep or ""))
        editor.setTextCursor(cursor)

    # ------------------------------------------------------------
    # FocusGuard helpers
    # ------------------------------------------------------------
    def _allow_editor_focus(self, timeout_ms: int = 250):
        """Разрешает фокус в редактор на короткий интервал (явное действие пользователя)."""
        try:
            timeout_s = max(0.0, float(timeout_ms) / 1000.0)
        except Exception:
            timeout_s = 0.25
        try:
            self._allow_editor_focus_until = time.monotonic() + timeout_s
        except Exception:
            self._allow_editor_focus_until = 0.0

    def _widget_has_ancestor(self, widget, ancestor) -> bool:
        try:
            w = widget
            while w is not None:
                if w is ancestor:
                    return True
                try:
                    w = w.parentWidget()
                except Exception:
                    break
        except Exception:
            return False
        return False

    def _find_ancestor_text_editor(self, widget):
        """Возвращает ближайший TextEditor ancestor для widget или None."""
        try:
            w = widget
            while w is not None:
                if isinstance(w, TextEditor):
                    return w
                try:
                    w = w.parentWidget()
                except Exception:
                    break
        except Exception:
            return None
        return None

    def _iter_tab_text_editors(self):
        """Все TextEditor во вкладках (O(n) вкладок)."""
        tw = getattr(self, "tab_widget", None)
        if tw is None:
            return
        try:
            for i in range(tw.count()):
                w = tw.widget(i)
                if isinstance(w, TextEditor):
                    yield w
        except Exception:
            return

    def _sync_editor_selection_appearance(self, old_widget, new_widget):
        """Обновляет палитру выделения во всех редакторах вкладок."""
        try:
            for ed in self._iter_tab_text_editors():
                ed.apply_selection_appearance()
        except Exception:
            pass

    def _on_app_focus_changed(self, old, new):
        """Смена фокуса: палитра выделения редакторов + FocusGuard для дерева."""
        self._sync_editor_selection_appearance(old, new)

        if not getattr(self, "_focus_guard_enabled", False):
            return
        if getattr(self, "_focus_guard_in_progress", False):
            return
        if new is None:
            return
        if not getattr(self, "tree", None):
            return

        # Интересует только переход: (дерево или его дочерние) -> (TextEditor или его дочерние)
        try:
            old_in_tree = (old is not None) and self._widget_has_ancestor(old, self.tree)
        except Exception:
            old_in_tree = False

        new_editor = self._find_ancestor_text_editor(new)
        if not old_in_tree or new_editor is None:
            return

        try:
            allowed = time.monotonic() <= float(getattr(self, "_allow_editor_focus_until", 0.0))
        except Exception:
            allowed = False

        # Явное действие пользователя: клик ЛКМ в редакторе.
        # В некоторых случаях Qt успевает сменить фокус до доставки mousePressEvent,
        # поэтому проверяем виджет под курсором на момент смены фокуса.
        if not allowed:
            try:
                if QApplication.mouseButtons() & Qt.LeftButton:
                    w_at = QApplication.widgetAt(QCursor.pos())
                    if w_at is not None and self._find_ancestor_text_editor(w_at) is not None:
                        allowed = True
            except Exception:
                pass

        if allowed:
            return

        self._focus_guard_in_progress = True

        def restore_tree_focus():
            try:
                if getattr(self, "tree", None):
                    self.tree.setFocus()
            except Exception:
                pass
            finally:
                self._focus_guard_in_progress = False

        QTimer.singleShot(0, restore_tree_focus)

    def _prune_stale_tab_marks(self):
        """Удаляет из множества отметок редакторы, которых уже нет среди вкладок."""
        try:
            alive = set()
            tw = getattr(self, "tab_widget", None)
            if tw:
                for i in range(int(tw.count())):
                    ed = tw.widget(i)
                    if ed is not None:
                        alive.add(ed)
            self._marked_tab_editors &= alive
        except Exception:
            try:
                self._marked_tab_editors = set()
            except Exception:
                pass

    def _has_marked_tabs(self):
        self._prune_stale_tab_marks()
        return bool(getattr(self, "_marked_tab_editors", None))

    def _is_tab_marked(self, text_editor):
        if not text_editor:
            return False
        return text_editor in getattr(self, "_marked_tab_editors", set())

    def _tab_base_name_for_editor(self, text_editor):
        """Базовое имя вкладки без префикса отметки."""
        if not text_editor:
            return ""
        item = self.tab_items.get(text_editor) if hasattr(self, "tab_items") else None
        if item:
            try:
                return item.text(0) or ""
            except (RuntimeError, AttributeError):
                pass
        try:
            if text_editor == getattr(self, "_link_tab_editor", None) or bool(text_editor.property("is_link_tab")):
                # Редкий fallback: вкладка ссылок без привязки к item (до загрузки файла).
                return "Link"
        except Exception:
            pass
        return ""

    def _sync_tab_label(self, text_editor, base_name=None):
        """Обновляет текст вкладки с учётом отметки (префикс TAB_MARK_PREFIX)."""
        tw = getattr(self, "tab_widget", None)
        if not tw or not text_editor:
            return
        try:
            idx = int(tw.indexOf(text_editor))
        except Exception:
            idx = -1
        if idx < 0:
            return
        if base_name is None:
            base_name = self._tab_base_name_for_editor(text_editor)
        display = (TAB_MARK_PREFIX + base_name) if self._is_tab_marked(text_editor) else base_name
        try:
            tw.setTabText(idx, display)
        except Exception:
            pass

    def _set_tab_marked(self, text_editor, marked: bool):
        if not text_editor:
            return
        if marked:
            self._marked_tab_editors.add(text_editor)
        else:
            self._marked_tab_editors.discard(text_editor)
        self._sync_tab_label(text_editor)

    def _clear_tab_mark(self, text_editor):
        if not text_editor:
            return
        self._marked_tab_editors.discard(text_editor)
        self._sync_tab_label(text_editor)

    def _clear_all_tab_marks(self):
        try:
            self._marked_tab_editors.clear()
        except Exception:
            self._marked_tab_editors = set()

    def toggle_tab_mark_at_index(self, tab_index):
        """Переключает отметку вкладки по двойному клику."""
        tw = getattr(self, "tab_widget", None)
        if not tw:
            return
        try:
            idx = int(tab_index)
        except Exception:
            return
        if idx < 0 or idx >= int(tw.count()):
            return
        editor = tw.widget(idx)
        if not editor:
            return
        self._set_tab_marked(editor, not self._is_tab_marked(editor))

    def _is_root_tab_editor(self, text_editor):
        if not text_editor or not getattr(self, "tree", None) or not self.tree:
            return False
        try:
            root_item = self.tree.topLevelItem(0)
        except Exception:
            root_item = None
        if not root_item:
            return False
        return self.tab_items.get(text_editor) == root_item

    def _close_all_tabs_single_tab_legacy(self):
        """Единственная вкладка, отметок нет: переключить на корень (если нужно), фокус не трогаем."""
        try:
            if not getattr(self, "tree", None) or not self.tree:
                return
            root_item = self.tree.topLevelItem(0)
            if not root_item:
                return
            editor = self.tab_widget.widget(0)
            current_item = self.tab_items.get(editor) if hasattr(self, "tab_items") else None
            if current_item == root_item:
                return
            if editor and self._is_tab_marked(editor):
                return
            if editor and current_item:
                self.update_item_content(current_item, editor.toPlainText())
            self.tab_widget.setCurrentIndex(0)
            self.tree.setCurrentItem(root_item)
            self.tree.scrollToItem(root_item)
            self.on_tree_selection_changed(root_item)
        except Exception:
            pass

    def _close_unmarked_tabs(self):
        """Закрывает все неотмеченные вкладки; отмеченные остаются."""
        if not getattr(self, "tab_widget", None):
            return

        try:
            tab_count = int(self.tab_widget.count())
        except Exception:
            tab_count = 0

        if tab_count <= 1:
            if tab_count == 1:
                editor = self.tab_widget.widget(0)
                if self._is_root_tab_editor(editor):
                    return
                if self._is_tab_marked(editor):
                    return
            return

        unmarked_indices = []
        marked_indices = []
        for i in range(tab_count):
            ed = self.tab_widget.widget(i)
            if ed is not None and self._is_tab_marked(ed):
                marked_indices.append(i)
            else:
                unmarked_indices.append(i)

        if not unmarked_indices:
            return

        current_editor = self.get_current_text_editor()
        if current_editor is not None and self._is_tab_marked(current_editor):
            target_editor = current_editor
        else:
            target_editor = self.tab_widget.widget(marked_indices[-1])

        try:
            self.setUpdatesEnabled(False)
        except Exception:
            pass
        try:
            self.tab_widget.setUpdatesEnabled(False)
        except Exception:
            pass
        try:
            if getattr(self, "tree", None) and self.tree:
                self.tree.setUpdatesEnabled(False)
        except Exception:
            pass

        try:
            for i in sorted(unmarked_indices, reverse=True):
                try:
                    self.close_tab(i)
                except Exception:
                    pass

            try:
                target_index = self.tab_widget.indexOf(target_editor) if target_editor else -1
            except Exception:
                target_index = -1
            if target_index >= 0:
                self.tab_widget.setCurrentIndex(target_index)

            try:
                self.previous_tab_index = self.tab_widget.currentIndex()
            except Exception:
                pass
        finally:
            try:
                if getattr(self, "tree", None) and self.tree:
                    self.tree.setUpdatesEnabled(True)
            except Exception:
                pass
            try:
                self.tab_widget.setUpdatesEnabled(True)
            except Exception:
                pass
            try:
                self.setUpdatesEnabled(True)
            except Exception:
                pass
            try:
                self.update()
            except Exception:
                pass

        if target_editor is not None:
            def _focus_active_editor(ed=target_editor):
                if not _editor_is_alive(ed):
                    return
                try:
                    tw = getattr(self, "tab_widget", None)
                    if tw is None or tw.indexOf(ed) < 0:
                        return
                    ed.setFocus()
                except Exception:
                    pass
            QTimer.singleShot(0, _focus_active_editor)

        try:
            self._sync_tab_pane_top_line()
        except Exception:
            pass

    def close_all_tabs(self):
        """
        Без отметок: закрывает все вкладки, оставляет корневую обложку (как раньше).
        С отметками: закрывает все неотмеченные вкладки, отмеченные остаются.
        """
        if not getattr(self, "tab_widget", None):
            return

        self._prune_stale_tab_marks()
        if self._has_marked_tabs():
            self._close_unmarked_tabs()
            return

        try:
            tab_count = int(self.tab_widget.count())
        except Exception:
            tab_count = 0

        if tab_count <= 1:
            self._close_all_tabs_single_tab_legacy()
            return

        # Находим корневой элемент (обложка корня должна остаться открытой)
        root_item = None
        try:
            if getattr(self, "tree", None) and self.tree:
                root_item = self.tree.topLevelItem(0)
        except Exception:
            root_item = None

        # Заморозка перерисовки (инвариант производительности)
        try:
            self.setUpdatesEnabled(False)
        except Exception:
            pass
        try:
            self.tab_widget.setUpdatesEnabled(False)
        except Exception:
            pass
        try:
            if getattr(self, "tree", None) and self.tree:
                self.tree.setUpdatesEnabled(False)
        except Exception:
            pass

        try:
            # 1) Выбираем вкладку, которую оставим (предпочтительно уже открытый корень)
            keep_index = None
            if root_item is not None and hasattr(self, "tab_items"):
                try:
                    for i in range(self.tab_widget.count()):
                        ed = self.tab_widget.widget(i)
                        if self.tab_items.get(ed) == root_item:
                            keep_index = i
                            break
                except Exception:
                    keep_index = None

            # 2) Если корень не открыт — сразу открываем корень в новой вкладке,
            #    чтобы затем закрыть ВСЕ остальные вкладки через close_tab().
            if keep_index is None:
                if root_item is not None:
                    try:
                        opened_editor = self.open_item_in_new_tab(root_item)
                        if opened_editor is not None:
                            keep_index = self.tab_widget.indexOf(opened_editor)
                    except Exception:
                        pass

                if keep_index is None:
                    try:
                        keep_index = int(self.tab_widget.currentIndex())
                    except Exception:
                        keep_index = 0

            # 3) Закрываем все вкладки, кроме keep_index, используя существующий close_tab()
            #    (сохранение/очистка состояния делаются внутри close_tab()).
            try:
                i = self.tab_widget.count() - 1
                while i >= 0:
                    if i != keep_index:
                        self.close_tab(i)
                        if i < keep_index:
                            keep_index -= 1
                    i -= 1
            except Exception:
                pass

            # 4) Финальное состояние: одна вкладка, активна, и в ней корневая обложка
            try:
                if self.tab_widget.count() > 0:
                    if keep_index < 0:
                        keep_index = 0
                    if keep_index >= self.tab_widget.count():
                        keep_index = self.tab_widget.count() - 1
                    self.tab_widget.setCurrentIndex(keep_index)
            except Exception:
                pass

            if root_item is not None and getattr(self, "tree", None) and self.tree and self.tab_widget.count() > 0:
                try:
                    ed = self.tab_widget.widget(self.tab_widget.currentIndex())
                    current_item = self.tab_items.get(ed) if hasattr(self, "tab_items") else None
                    if current_item != root_item:
                        # Сохраняем содержимое вкладки перед заменой обложкой корня
                        if ed and current_item:
                            self.update_item_content(current_item, ed.toPlainText())
                        self.tree.setCurrentItem(root_item)
                        self.tree.scrollToItem(root_item)
                        self.on_tree_selection_changed(root_item)
                    # Финально отдаём фокус дереву, чтобы редактор не "держал" его после закрытия вкладок.
                    QTimer.singleShot(0, self.focus_tree)
                except Exception:
                    pass

            try:
                self.previous_tab_index = self.tab_widget.currentIndex()
            except Exception:
                pass
        finally:
            # Возвращаем перерисовку
            try:
                if getattr(self, "tree", None) and self.tree:
                    self.tree.setUpdatesEnabled(True)
            except Exception:
                pass
            try:
                self.tab_widget.setUpdatesEnabled(True)
            except Exception:
                pass
            try:
                self.setUpdatesEnabled(True)
            except Exception:
                pass
            try:
                self.update()
            except Exception:
                pass

    def _purge_editor_from_autosave_job(self, text_editor):
        """Убирает закрытый редактор из активного snapshot job."""
        job = getattr(self, "_autosave_job", None)
        if job is None or text_editor is None:
            return
        try:
            dirty = job.get("dirty_editors")
            if dirty:
                job["dirty_editors"] = [e for e in dirty if e is not text_editor]
        except Exception:
            pass
        try:
            cap = job.get("capture")
            if cap and cap.get("editor") is text_editor:
                job["capture"] = None
        except Exception:
            pass

    def _dispose_tab_editor(self, text_editor):
        """Снимает ссылки MainWindow и планирует уничтожение виджета вкладки."""
        if text_editor is None:
            return
        # Сбрасываем флаги restore до deleteLater: отложенные QTimer не трогают мёртвый виджет.
        try:
            text_editor._tab_state_needs_restore = False
            text_editor._restoring_state = False
            text_editor._restoring_scroll = False
        except Exception:
            pass
        self._marked_tab_editors.discard(text_editor)
        self._remove_tab_item_binding(text_editor)
        self.tab_states.pop(text_editor, None)
        self._purge_editor_from_autosave_job(text_editor)
        try:
            self._dirty_editors.discard(text_editor)
        except Exception:
            pass
        try:
            if text_editor is getattr(self, "_link_tab_editor", None):
                self._link_tab_editor = None
        except Exception:
            pass
        try:
            text_editor.removeEventFilter(self)
        except Exception:
            pass
        try:
            TextEditor._clear_document_undo_redo(text_editor.document())
        except Exception:
            pass
        text_editor.deleteLater()

    def _dispose_all_tab_editors(self):
        """Закрывает все вкладки редактора и освобождает виджеты."""
        tw = getattr(self, "tab_widget", None)
        if tw is not None:
            while tw.count() > 0:
                editor = tw.widget(0)
                tw.removeTab(0)
                self._dispose_tab_editor(editor)
        self.tab_items = {}
        self._clear_all_tab_marks()
        self._open_tab_by_node_id = {}
        try:
            self.tab_states.clear()
        except Exception:
            self.tab_states = {}
        try:
            self._dirty_editors.clear()
        except Exception:
            self._dirty_editors = set()
        self.previous_tab_index = -1
        self._link_tab_editor = None

    def close_tab(self, index):
        """Закрывает вкладку"""
        # Проверяем, является ли это последней вкладкой
        is_last_tab = (self.tab_widget.count() == 1)
        
        # Сохраняем изменения перед закрытием
        text_editor = self.tab_widget.widget(index)
        if text_editor and text_editor in self.tab_items:
            item = self.tab_items[text_editor]
            if item:
                self.update_item_content(item, text_editor.toPlainText())
                
                # Если это последняя вкладка и она открывает корневую папку - блокируем закрытие
                if is_last_tab:
                    root_item = self.tree.topLevelItem(0)
                    if root_item and item == root_item:
                        # Закрытие вкладки корневой папки заблокировано, если она единственная
                        return
        
        # Удаляем вкладку
        self.tab_widget.removeTab(index)
        self._dispose_tab_editor(text_editor)
        
        # Обновляем индекс предыдущей вкладки
        if self.previous_tab_index == index:
            # Если закрыли текущую вкладку, сбрасываем индекс
            self.previous_tab_index = -1
        elif self.previous_tab_index > index:
            # Если закрыли вкладку перед текущей, уменьшаем индекс
            self.previous_tab_index -= 1
        
        # Если вкладок не осталось и файл открыт, открываем корневую папку
        if self.tab_widget.count() == 0 and self.current_file:
            root_item = self.tree.topLevelItem(0)
            if root_item:
                try:
                    _ = root_item.text(0)
                    self.open_item_in_new_tab(root_item)
                    QTimer.singleShot(0, self.focus_tree)
                except (RuntimeError, AttributeError):
                    pass
        else:
            # Обновляем previous_tab_index на текущую активную вкладку
            current_index = self.tab_widget.currentIndex()
            if current_index >= 0:
                self.previous_tab_index = current_index

        # После любых операций с вкладками синхронизируем видимость линии-разделителя под tabBar.
        try:
            self._sync_tab_pane_top_line()
        except Exception:
            pass

    def _compute_next_tab_widget_after_closures(self, editors_to_close, anchor_tab_index=None):
        """
        До закрытия вкладок: какая вкладка должна стать активной после удаления связанных с item.
        Политика: первая справа от якоря среди НЕ закрываемых; если такой нет — крайняя справа среди оставшихся.
        anchor_tab_index: индекс «удаляемой» по смыслу вкладки (indexOf(get_open_editor_for_item) или
        min(индексов) при batch). Если None — tab_widget.currentIndex() (резерв).
        """
        tw = self.tab_widget
        try:
            n = int(tw.count())
        except Exception:
            n = 0
        if n <= 0:
            return None
        close_set = set(e for e in (editors_to_close or []) if e)
        if anchor_tab_index is not None:
            try:
                C = int(anchor_tab_index)
            except Exception:
                C = 0
        else:
            try:
                C = int(tw.currentIndex())
            except Exception:
                C = 0
        if C < 0:
            C = 0
        if C >= n:
            C = n - 1
        widgets = []
        for i in range(n):
            try:
                widgets.append(tw.widget(i))
            except Exception:
                widgets.append(None)
        for j in range(C + 1, n):
            w = widgets[j]
            if w is not None and w not in close_set:
                return w
        for j in range(n - 1, -1, -1):
            w = widgets[j]
            if w is not None and w not in close_set:
                return w
        return None

    def _collect_editors_for_deleted_tree_items(self, deleted_items):
        """
        Один editor на item: get_open_editor_for_item (O(1)), без полного скан tab_items
        (исключает лишние close_tab соседних вкладок при дублирующих привязках).
        """
        if not deleted_items:
            return []
        out = []
        seen = set()
        for it in deleted_items:
            if not it:
                continue
            try:
                ed = self.get_open_editor_for_item(it)
            except Exception:
                ed = None
            if ed and id(ed) not in seen:
                seen.add(id(ed))
                out.append(ed)
        return out

    def _close_tabs_for_deleted_tree_items(self, deleted_items):
        """
        Закрывает вкладки удаляемых элементов: индексы по убыванию, затем явно восстанавливает текущую вкладку.
        Якорь для «сосед справа» — min(индексов) закрываемых (или один indexOf для одиночного item).
        """
        editors = self._collect_editors_for_deleted_tree_items(deleted_items)
        if not editors:
            return
        indices = []
        for ed in editors:
            try:
                ix = self.tab_widget.indexOf(ed)
                if ix >= 0:
                    indices.append(ix)
            except Exception:
                pass
        if not indices:
            return
        try:
            anchor_c = int(min(indices))
        except Exception:
            anchor_c = 0
        n_tabs = 0
        try:
            n_tabs = int(self.tab_widget.count())
        except Exception:
            n_tabs = 0
        if anchor_c < 0:
            anchor_c = 0
        if n_tabs and anchor_c >= n_tabs:
            anchor_c = n_tabs - 1
        target_w = self._compute_next_tab_widget_after_closures(editors, anchor_c)
        indices = sorted(set(indices), reverse=True)
        for ix in indices:
            try:
                self.close_tab(ix)
            except Exception:
                pass
        if target_w is not None:
            try:
                if self.tab_widget.indexOf(target_w) >= 0:
                    self.tab_widget.setCurrentWidget(target_w)
            except Exception:
                try:
                    self.tab_widget.setCurrentWidget(target_w)
                except Exception:
                    pass

    def _setup_scroll_tracking(self, text_editor):
        """Настраивает отслеживание прокрутки и курсора для сохранения состояния вкладки"""
        if not text_editor:
            return
        
        # Настраиваем отслеживание прокрутки
        scrollbar = text_editor.verticalScrollBar()
        if scrollbar:
            # Создаем таймер для отложенного сохранения состояния при прокрутке (debouncing)
            scroll_timer = QTimer(text_editor)
            scroll_timer.setSingleShot(True)
            scroll_timer.timeout.connect(lambda: self._save_tab_state(text_editor))
            
            # Сохраняем ссылку на таймер в виджете для последующего доступа
            text_editor._scroll_save_timer = scroll_timer
            
            # Флаг для отслеживания программного восстановления прокрутки
            text_editor._restoring_scroll = False
            
            # Подключаемся к сигналу изменения прокрутки
            # Сохраняем прокрутку независимо от состояния ввода
            def on_scroll_changed():
                # Не сохраняем, если идет программное восстановление
                if getattr(text_editor, '_restoring_scroll', False):
                    return
                
                # Прокрутка должна сохраняться всегда, даже во время ввода
                # Сохраняем сразу, без задержки, чтобы не потерять состояние
                self._save_tab_state(text_editor)
            
            scrollbar.valueChanged.connect(on_scroll_changed)
            
            # Также сохраняем прокрутку при отпускании мыши (когда пользователь закончил прокрутку)
            def on_scroll_action_triggered(action):
                # Сохраняем прокрутку сразу после завершения действия прокрутки
                self._save_tab_state(text_editor)
            
            scrollbar.actionTriggered.connect(on_scroll_action_triggered)
            
            # Сохраняем прокрутку при отпускании мыши (когда пользователь закончил перетаскивание бегунка)
            def on_scroll_slider_released():
                # Сохраняем прокрутку сразу после отпускания бегунка
                self._save_tab_state(text_editor)
            
            scrollbar.sliderReleased.connect(on_scroll_slider_released)
            
            # Устанавливаем стандартный курсор для полосы прокрутки
            scrollbar.setCursor(Qt.ArrowCursor)
        
        # Настраиваем отслеживание изменения курсора
        # Создаем таймер для отложенного сохранения состояния при изменении курсора
        cursor_timer = QTimer(text_editor)
        cursor_timer.setSingleShot(True)
        cursor_timer.timeout.connect(lambda: self._save_tab_state(text_editor))
        text_editor._cursor_save_timer = cursor_timer
        
        # Сохраняем ссылку на main_window для доступа из keyPressEvent
        text_editor._main_window = self
        
        # Подключаемся к сигналу изменения курсора
        # Сохраняем состояние только если не идет активный ввод
        def on_cursor_changed():
            if not getattr(text_editor, '_is_typing', False):
                cursor_timer.start(300)  # Увеличиваем задержку до 300мс
        
        text_editor.cursorPositionChanged.connect(on_cursor_changed)
    
    def _save_tab_state(self, text_editor):
        """Сохраняет состояние вкладки (позиция курсора, прокрутка, выделение)"""
        if not text_editor:
            return
        
        cursor = text_editor.textCursor()
        scrollbar = text_editor.verticalScrollBar()
        
        # Получаем значение прокрутки
        scroll_value = scrollbar.value() if scrollbar else 0
        
        cursor_pos = cursor.position()
        selection_start = cursor.selectionStart() if cursor.hasSelection() else None
        selection_end = cursor.selectionEnd() if cursor.hasSelection() else None
        
        state = {
            'cursor_position': cursor_pos,
            'scroll_value': scroll_value,
            'selection_start': selection_start,
            'selection_end': selection_end
        }
        
        self.tab_states[text_editor] = state

    def _schedule_restore_tab_state_if_needed(self, text_editor):
        """Откладывает restore на следующий тик event-loop (без processEvents)."""
        if not _editor_is_alive(text_editor):
            return
        try:
            if not getattr(text_editor, "_tab_state_needs_restore", False):
                return
        except RuntimeError:
            return
        try:
            tw = getattr(self, "tab_widget", None)
            if tw is None or tw.indexOf(text_editor) < 0:
                return
        except Exception:
            return
        QTimer.singleShot(0, lambda ed=text_editor: self._restore_tab_state_if_needed(ed))

    def _restore_tab_state_if_needed(self, text_editor):
        """Restore только если документ сбрасывали программно и флаг ещё актуален."""
        if not _editor_is_alive(text_editor):
            return
        try:
            tw = getattr(self, "tab_widget", None)
            if tw is None or tw.indexOf(text_editor) < 0:
                return
        except Exception:
            return
        try:
            if not getattr(text_editor, "_tab_state_needs_restore", False):
                return
        except RuntimeError:
            return
        try:
            text_editor._tab_state_needs_restore = False
        except Exception:
            pass
        self._restore_tab_state(text_editor)

    def _apply_saved_scroll(self, text_editor, scroll_value, _retries=0):
        """Ставит scroll из tab_states; при неготовности range — до 2 отложенных retry."""
        if not _editor_is_alive(text_editor):
            return
        try:
            tw = getattr(self, "tab_widget", None)
            if tw is not None and tw.indexOf(text_editor) < 0:
                return
        except Exception:
            return
        try:
            scrollbar = text_editor.verticalScrollBar()
        except RuntimeError:
            return
        if scrollbar is None:
            _clear_editor_flag_safe(text_editor, "_restoring_scroll", False)
            return
        try:
            scroll_value = int(scroll_value)
        except Exception:
            _clear_editor_flag_safe(text_editor, "_restoring_scroll", False)
            return

        try:
            text_editor._restoring_scroll = True
        except RuntimeError:
            return
        try:
            scrollbar.blockSignals(True)
        except RuntimeError:
            return
        try:
            scroll_min = scrollbar.minimum()
            scroll_max = scrollbar.maximum()
            if scroll_value > scroll_max and int(_retries) < 2:
                try:
                    scrollbar.blockSignals(False)
                except Exception:
                    pass
                QTimer.singleShot(
                    0,
                    lambda ed=text_editor, v=scroll_value, r=int(_retries) + 1: self._apply_saved_scroll(ed, v, r),
                )
                return
            clamped = min(max(scroll_value, scroll_min), scroll_max)
            scrollbar.setValue(clamped)
        except RuntimeError:
            return
        finally:
            try:
                scrollbar.blockSignals(False)
            except Exception:
                pass
        QTimer.singleShot(
            300,
            lambda ed=text_editor: _clear_editor_flag_safe(ed, "_restoring_scroll", False),
        )
    
    def _restore_tab_state(self, text_editor):
        """Восстанавливает scroll/cursor/selection из tab_states.

        При обычном переключении вкладок тот же QTextEdit остаётся в памяти,
        виджет уже хранит позицию. Restore нужен, если в tab_states есть
        сохранённое состояние и документ мог быть сброшен программно.
        Флаг _restoring_state выставляется только здесь и сбрасывается по таймеру.
        Без QApplication.processEvents() — во избежание реентранса.
        """
        if not _editor_is_alive(text_editor):
            return
        if text_editor not in self.tab_states:
            return
        try:
            tw = getattr(self, "tab_widget", None)
            if tw is not None and tw.indexOf(text_editor) < 0:
                return
        except Exception:
            return

        # Защита от повторного входа, пока идёт restore (reentrant currentChanged и т.п.)
        try:
            if getattr(text_editor, '_restoring_state', False):
                return
            text_editor._restoring_state = True
        except RuntimeError:
            return
        
        state = self.tab_states.get(text_editor)
        if not state:
            _clear_editor_flag_safe(text_editor, "_restoring_state", False)
            return
        
        # Восстанавливаем прокрутку
        try:
            scrollbar = text_editor.verticalScrollBar()
        except RuntimeError:
            return
        if scrollbar and 'scroll_value' in state:
            scroll_value = state['scroll_value']
            try:
                scroll_value = int(scroll_value)
            except Exception:
                scroll_value = 0
            try:
                scroll_min = scrollbar.minimum()
                scroll_max = scrollbar.maximum()
            except RuntimeError:
                return
            if scroll_value > scroll_max:
                # Layout/range ещё не готовы — один-два retry без processEvents.
                self._apply_saved_scroll(text_editor, scroll_value, 0)
            elif scroll_value >= scroll_min:
                try:
                    text_editor._restoring_scroll = True
                    scrollbar.blockSignals(True)
                    try:
                        scrollbar.setValue(scroll_value)
                    finally:
                        scrollbar.blockSignals(False)
                except RuntimeError:
                    return
                QTimer.singleShot(
                    300,
                    lambda ed=text_editor: _clear_editor_flag_safe(ed, "_restoring_scroll", False),
                )
        
        # Восстанавливаем позицию курсора и выделение
        try:
            cursor = text_editor.textCursor()
            doc = text_editor.document()
        except RuntimeError:
            return
        if 'cursor_position' in state and doc is not None:
            cursor_position = state['cursor_position']
            try:
                doc_length = doc.characterCount()
            except RuntimeError:
                return
            # Проверяем, что позиция валидна (позиции от 0 до doc_length-1)
            # Если документ изменился и позиция больше не валидна, ограничиваем её
            if cursor_position < 0:
                cursor_position = 0
            elif cursor_position >= doc_length:
                cursor_position = max(0, doc_length - 1)
            
            # Устанавливаем позицию курсора только если документ не пустой
            if doc_length > 0:
                try:
                    cursor.setPosition(cursor_position, QTextCursor.MoveAnchor)
                    
                    # Восстанавливаем выделение, если оно было
                    if state.get('selection_start') is not None and state.get('selection_end') is not None:
                        selection_start = state['selection_start']
                        selection_end = state['selection_end']
                        # Ограничиваем позиции выделения границами документа
                        selection_start = min(max(0, selection_start), doc_length - 1)
                        selection_end = min(max(0, selection_end), doc_length - 1)
                        # Устанавливаем выделение только если позиции валидны
                        if selection_start != selection_end:
                            cursor.setPosition(selection_start, QTextCursor.MoveAnchor)
                            cursor.setPosition(selection_end, QTextCursor.KeepAnchor)
                    
                    text_editor.setTextCursor(cursor)
                    text_editor.ensureCursorVisible()
                except RuntimeError:
                    return
        
        # Сбрасываем _restoring_state: focusOutEvent снова может писать в tab_states
        QTimer.singleShot(
            300,
            lambda ed=text_editor: _clear_editor_flag_safe(ed, "_restoring_state", False),
        )
    
    def _create_control_panel_icons(self):
        """Кнопка «Закрыть все вкладки» в corner host (фон на контейнере, кнопка на весь rect)."""
        self._close_all_tab_button = QToolButton()
        self._close_all_tab_button.setIconSize(QSize(16, 16))
        self._close_all_tab_button.setCursor(Qt.ArrowCursor)
        self._close_all_tab_button.setStyleSheet(build_tab_side_button_style())
        self._close_all_tab_button.setIcon(IconManager.instance().icon("close_all_tab"))
        self._close_all_tab_button.setToolTip(tr("tooltip.close_all_unmarked_tabs", "Закрыть все вкладки"))
        try:
            self._close_all_tab_button.clicked.connect(self.close_all_tabs)
        except Exception:
            pass
        self.control_panel = _TabBarCornerButtonHost(
            self._close_all_tab_button, QSize(24, 24), None
        )
        show_tooltips = getattr(self, 'show_tooltips', True)
        self._update_tooltips_visibility(show_tooltips)
    
    def _set_always_on_top(self, enable):
        """Устанавливает режим «поверх всех окон».

        Каскад: Win API (Windows) → QWindow.setFlag (Linux/macOS, в т.ч. Wayland)
        → setWindowFlags (fallback, пересоздаёт окно).
        """
        # Windows: Win API SetWindowPos(HWND_TOPMOST)
        if sys.platform == 'win32':
            try:
                # Константы Win API
                HWND_TOPMOST = -1
                HWND_NOTOPMOST = -2
                SWP_NOMOVE = 0x0002
                SWP_NOSIZE = 0x0001
                SWP_SHOWWINDOW = 0x0040
                
                # Получаем HWND окна
                hwnd = self.winId()
                # Преобразуем в int для использования в ctypes
                # В PyQt5 winId() возвращает sip.voidptr, нужно правильно преобразовать
                try:
                    # Пробуем разные способы преобразования
                    if hasattr(hwnd, '__int__'):
                        hwnd_int = hwnd.__int__()
                    elif hasattr(hwnd, 'value'):
                        hwnd_int = hwnd.value
                    elif isinstance(hwnd, int):
                        hwnd_int = hwnd
                    else:
                        # Простое преобразование в int
                        hwnd_int = int(hwnd)
                except:
                    # Последняя попытка - простое преобразование
                    hwnd_int = int(hwnd)
                
                # Загружаем user32.dll (доступно только на Windows)
                user32 = ctypes.windll.user32
                
                # Настраиваем сигнатуру SetWindowPos для правильной работы
                # BOOL SetWindowPos(HWND hWnd, HWND hWndInsertAfter, int X, int Y, int cx, int cy, UINT uFlags)
                user32.SetWindowPos.argtypes = [
                    ctypes.c_void_p,  # HWND hWnd
                    ctypes.c_void_p,  # HWND hWndInsertAfter
                    ctypes.c_int,      # int X
                    ctypes.c_int,      # int Y
                    ctypes.c_int,      # int cx
                    ctypes.c_int,      # int cy
                    ctypes.c_uint      # UINT uFlags
                ]
                user32.SetWindowPos.restype = ctypes.c_int  # BOOL (int)
                
                # Вызываем SetWindowPos с правильными типами
                # SetWindowPos возвращает не-zero значение при успехе
                if enable:
                    # Устанавливаем окно поверх всех
                    # Преобразуем HWND в c_void_p
                    hwnd_ptr = ctypes.c_void_p(hwnd_int)
                    result = user32.SetWindowPos(
                        hwnd_ptr,
                        ctypes.c_void_p(HWND_TOPMOST),
                        0, 0, 0, 0,
                        SWP_NOMOVE | SWP_NOSIZE | SWP_SHOWWINDOW
                    )
                    if result != 0:
                        # Принудительно обновляем окно
                        self.raise_()
                        self.activateWindow()
                        if hasattr(self, "_deferred_apply_dwm_window_shadow"):
                            QTimer.singleShot(0, self._deferred_apply_dwm_window_shadow)
                        return  # Успешно установлено через Win API
                else:
                    # Убираем режим поверх всех
                    # Преобразуем HWND в c_void_p
                    hwnd_ptr = ctypes.c_void_p(hwnd_int)
                    result = user32.SetWindowPos(
                        hwnd_ptr,
                        ctypes.c_void_p(HWND_NOTOPMOST),
                        0, 0, 0, 0,
                        SWP_NOMOVE | SWP_NOSIZE | SWP_SHOWWINDOW
                    )
                    if result != 0:
                        # Принудительно обновляем окно
                        self.raise_()
                        self.activateWindow()
                        if hasattr(self, "_deferred_apply_dwm_window_shadow"):
                            QTimer.singleShot(0, self._deferred_apply_dwm_window_shadow)
                        return  # Успешно снято через Win API
            except (AttributeError, OSError, Exception):
                # AttributeError - если windll недоступен (не должно быть на Windows)
                # OSError - если DLL не найдена
                # Другие ошибки Win API
                pass

        # Linux/macOS и fallback Windows: QWindow.setFlag (без пересоздания surface)
        if _qwindow_set_stays_on_top(self, enable):
            return

        # Fallback: setWindowFlags + show (пересоздаёт окно; надёжнее на старых Qt / X11)
        try:
            # Сохраняем текущие флаги окна (включая FramelessWindowHint)
            flags = self.windowFlags()
            if enable:
                flags |= Qt.WindowStaysOnTopHint
            else:
                flags &= ~Qt.WindowStaysOnTopHint
            # Сохраняем геометрию окна перед изменением флагов
            geometry = self.geometry()
            is_maximized = self.isMaximized()
            self.setWindowFlags(flags)
            # Восстанавливаем геометрию
            if is_maximized:
                self.showMaximized()
            else:
                self.setGeometry(geometry)
                self.show()
            self._sync_window_shadow_layout()
        except Exception as e:
            print(f"Ошибка установки режима 'поверх всех окон': {e}")
    
    def _toggle_control_icons(self, show_on):
        """Переключает режим «поверх всех окон»; иконка переключения — в titlebar."""
        self._always_on_top_enabled = show_on
        self._set_always_on_top(show_on)
        self._update_always_on_top_button_icon()

    def _toggle_always_on_top_from_favorites(self):
        """Переключает режим «Поверх всех окон» по клику на кнопку в titlebar."""
        self._toggle_control_icons(not getattr(self, '_always_on_top_enabled', False))

    def _apply_theme_icons(self):
        """Подставляет кэшированные QIcon после пересборки IconManager (без повторной перекраски)."""
        try:
            if hasattr(self, "title_bar") and self.title_bar:
                self.title_bar.update_icons()
            self._update_always_on_top_button_icon()
            self._update_add_temp_file_button_icon()
            if hasattr(self, "_close_all_tab_button") and self._close_all_tab_button:
                self._close_all_tab_button.setIcon(IconManager.instance().icon("close_all_tab"))
            fav = getattr(self, "favorites_bar_sandbox", None)
            if fav and hasattr(fav, "_update_add_button_icon"):
                fav._update_add_button_icon()
        except Exception:
            pass

    def _update_always_on_top_button_icon(self):
        """Устанавливает иконку и подсказку кнопки «Поверх всех окон» в titlebar."""
        tb = getattr(self, "title_bar", None)
        if not tb:
            return
        btn = getattr(tb, "always_on_top_button", None)
        if not btn:
            return
        enabled = getattr(self, '_always_on_top_enabled', False)
        im = IconManager.instance()
        if enabled:
            btn.setIcon(im.icon("always_on_top_enabled"))
            if getattr(self, 'show_tooltips', True):
                btn.setToolTip(tr("tooltip.always_on_top", "Поверх всех окон"))
            else:
                btn.setToolTip("")
        else:
            btn.setIcon(im.icon("always_on_top_disabled"))
            if getattr(self, 'show_tooltips', True):
                btn.setToolTip(tr("tooltip.always_on_top", "Поверх всех окон"))
            else:
                btn.setToolTip("")

    def _update_control_panel_icons_position(self):
        """Синхронизирует corner host «Закрыть все вкладки» с высотой строки tabBar."""
        if not hasattr(self, "tab_widget") or not self.tab_widget:
            return
        tab_bar = self.tab_widget.tabBar()
        if not tab_bar:
            return
        h = editor_tab_bar_row_height_px(tab_bar)
        if h <= 0:
            return
        panel = getattr(self, "control_panel", None)
        if panel is None:
            return
        if hasattr(panel, "setFixedSizeValue"):
            panel.setFixedSizeValue(h, h)
        else:
            panel.setFixedSize(h, h)
        if panel is not None and hasattr(panel, "_sync_tool_button_geometry"):
            panel._sync_tool_button_geometry()
    
    def set_show_tooltips(self, show):
        """Устанавливает видимость подсказок для всех панелей"""
        self.show_tooltips = show
        self._update_tooltips_visibility(show)
        # Всегда запрещаем tooltip на кнопках закрытия вкладок (Qt ставит "Close Tab" при включённых подсказках).
        try:
            if hasattr(self, "tab_widget") and self.tab_widget:
                tab_bar = self.tab_widget.tabBar()
                if tab_bar and hasattr(tab_bar, "_suppress_close_tab_button_tooltips"):
                    tab_bar._suppress_close_tab_button_tooltips()
        except Exception:
            pass

    def set_link_highlight_enabled(self, enabled):
        """Включает/выключает подсветку ссылок внутри текста для всех открытых редакторов."""
        self.highlight_links_in_text = bool(enabled)
        try:
            for tab_index in range(self.tab_widget.count()):
                text_editor = self.tab_widget.widget(tab_index)
                if text_editor and isinstance(text_editor, TextEditor):
                    text_editor.set_link_highlight_enabled(self.highlight_links_in_text)
        except Exception:
            pass

    def _normalize_view_width_px(self, v, default):
        try:
            v = int(v)
        except Exception:
            v = int(default)
        return max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(v)))

    def set_max_favorites_item_width_px(self, w):
        """Устанавливает и сразу применяет максимум ширины элементов избранного (px)."""
        w = self._normalize_view_width_px(w, getattr(self, "max_favorites_item_width_px", DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX))
        self.max_favorites_item_width_px = int(w)
        self.max_favorites_item_width_px_saved = int(w)
        try:
            if getattr(self, "favorites_bar_sandbox", None) and hasattr(self.favorites_bar_sandbox, "set_max_item_width_px"):
                self.favorites_bar_sandbox.set_max_item_width_px(int(w))
        except Exception:
            pass

    def apply_max_editor_tab_width_px(self, w):
        """Применяет максимум ширины вкладок редактора (px) в текущем запуске."""
        w = self._normalize_view_width_px(w, getattr(self, "max_editor_tab_width_px", DEFAULT_EDITOR_TAB_MAX_WIDTH_PX))
        self.max_editor_tab_width_px = int(w)
        # Источник истины — QApplication property.
        try:
            app = QApplication.instance()
            if app is not None:
                app.setProperty("jbpad_max_editor_tab_width_px", int(w))
        except Exception:
            pass

    def apply_editor_right_indent_px(self, px):
        """Применяет правый отступ (px) для режима выравнивания по правому краю."""
        try:
            px = int(px)
        except Exception:
            try:
                px = int(getattr(self, "editor_right_indent_px", getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10)))
            except Exception:
                px = int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))
        px = max(0, min(500, int(px)))

        try:
            self.editor_right_indent_px = int(px)
        except Exception:
            pass
        try:
            TextEditor.RIGHT_MARGIN_RIGHT_ALIGN_PX = int(px)
        except Exception:
            pass

        # Обновляем right margin у всех открытых редакторов
        try:
            for tab_index in range(self.tab_widget.count()):
                text_editor = self.tab_widget.widget(tab_index)
                if text_editor and isinstance(text_editor, TextEditor):
                    try:
                        text_editor._update_margin()
                    except Exception:
                        try:
                            text_editor.viewport().update()
                        except Exception:
                            pass
        except Exception:
            pass
    
    def _update_tooltips_visibility(self, show):
        """Централизованно включает/выключает подсказки для всех кнопок/действий.

        Реализация:
        - При выключении: кешируем текущие toolTip-тексты (если они не пустые) и очищаем toolTip у всех видимых объектов.
        - При включении: восстанавливаем ранее кешированные toolTip-тексты.

        Дополнительно: обновляем "динамические" подсказки, зависящие от состояния (например, «Поверх всех окон»).
        """

        # 1) Динамические подсказки, зависящие от состояния приложения.
        try:
            self._update_always_on_top_button_icon()
        except Exception:
            pass

        # Подсказки навигационных кнопок titlebar (текст уже задан при создании).
        try:
            tb = getattr(self, "title_bar", None)
            if tb:
                for btn in getattr(tb, "nav_tool_buttons", ()):
                    try:
                        tip = btn.toolTip()
                        if tip:
                            btn.setToolTip(tip)
                    except Exception:
                        pass
        except Exception:
            pass

        # 2) Глобально применяем политику подсказок ко всем top-level окнам приложения.
        # Это покрывает и диалоги/окна, созданные позже, если у них есть parent=MainWindow или они top-level.
        try:
            app = QApplication.instance()
        except Exception:
            app = None

        roots = []
        try:
            if app:
                roots = list(app.topLevelWidgets())
        except Exception:
            roots = []
        if self not in roots:
            roots.append(self)

        def _iter_targets(root_widget):
            # QWidget
            try:
                yield root_widget
            except Exception:
                return
            try:
                for w in root_widget.findChildren(QWidget):
                    yield w
            except Exception:
                pass
            # QAction (может быть не-child конкретного QWidget, но часто имеет parent в дереве QObject)
            try:
                for a in root_widget.findChildren(QAction):
                    yield a
            except Exception:
                pass
            # Действия, прикреплённые к конкретным виджетам (widget.actions()), на случай если они не попали в findChildren(QAction)
            try:
                for w in root_widget.findChildren(QWidget):
                    try:
                        for a in w.actions():
                            yield a
                    except Exception:
                        pass
            except Exception:
                pass

        for root in roots:
            for obj in _iter_targets(root):
                # У разных QObject могут быть свои реализации toolTip/setToolTip (QWidget/QAction).
                if not hasattr(obj, "toolTip") or not hasattr(obj, "setToolTip"):
                    continue
                # "Умные" подсказки (по обрезанию текста) должны быть полностью независимы
                # от глобального переключателя обычных tooltip'ов в Settings.
                try:
                    if bool(getattr(obj, "_jbpad_skip_global_tooltip_policy", False)):
                        continue
                except Exception:
                    pass
                try:
                    if not bool(show):
                        # Disable: кешируем непустые подсказки и очищаем.
                        current_tt = obj.toolTip()
                        if isinstance(current_tt, str) and current_tt:
                            try:
                                # Всегда обновляем кеш на текущий текст (если он непустой),
                                # чтобы корректно поддерживать изменения подсказок в рантайме.
                                setattr(obj, "_jbpad_tooltip_original", current_tt)
                            except Exception:
                                pass
                        obj.setToolTip("")
                    else:
                        # Enable: не трогаем, если подсказка уже задана (например, динамически выше).
                        try:
                            if isinstance(obj.toolTip(), str) and obj.toolTip():
                                continue
                        except Exception:
                            pass
                        orig = getattr(obj, "_jbpad_tooltip_original", None)
                        if isinstance(orig, str):
                            obj.setToolTip(orig)
                except Exception:
                    # Никогда не ломаем UI из-за подсказок.
                    pass
    
    def _update_control_panel_size(self):
        """Обновляет размер и позицию панели управления на основе высоты tabBar"""
        if hasattr(self, 'tab_widget') and self.tab_widget:
            tab_bar = self.tab_widget.tabBar()
            if tab_bar and hasattr(self, 'control_panel') and self.control_panel:
                tab_bar_height = editor_tab_bar_row_height_px(tab_bar)
                # Квадратная панель управления (кнопка «Закрыть все вкладки»)
                if hasattr(self.control_panel, "setFixedSizeValue"):
                    self.control_panel.setFixedSizeValue(tab_bar_height, tab_bar_height)
                else:
                    self.control_panel.setFixedSize(tab_bar_height, tab_bar_height)
                # На всякий случай фиксируем панель как правый cornerWidget (без overlay).
                try:
                    if self.tab_widget.cornerWidget(Qt.TopRightCorner) != self.control_panel:
                        self.tab_widget.setCornerWidget(self.control_panel, Qt.TopRightCorner)
                except Exception:
                    pass
                # Подгоняем размер левого угла (кнопка «Добавить временный файл») под фактическую высоту tab bar
                left_corner = None
                try:
                    left_corner = self.tab_widget.cornerWidget(Qt.TopLeftCorner)
                except Exception:
                    left_corner = None
                if left_corner and hasattr(left_corner, "setFixedSizeValue"):
                    left_corner.setFixedSizeValue(tab_bar_height + 1, tab_bar_height)
                elif left_corner:
                    left_corner.setFixedSize(tab_bar_height + 1, tab_bar_height)
                if getattr(self, "add_temp_file_button", None):
                    btn_h = tab_row_tool_button_content_height(tab_bar_height, self.tab_widget)
                    self.add_temp_file_button.setFixedSize(btn_h, btn_h)
                # Подгоняем высоту панели избранного под панель вкладок (визуальное совпадение при любой теме/платформе)
                if tab_bar_height > 0:
                    if getattr(self, "favorites_bar_sandbox", None):
                        self.favorites_bar_sandbox.setFixedHeight(tab_bar_height)
                        self.favorites_bar_sandbox.list_view.setFixedHeight(tab_bar_height)
                        self.favorites_bar_sandbox.add_button.setFixedSize(tab_bar_height, tab_bar_height)
                        try:
                            # Ширину стрелок прокрутки избранного подгоняем под "родные" кнопки прокрутки QTabBar,
                            # чтобы визуально совпадали и сами кнопки, и треугольники внутри.
                            try:
                                scroll_btn_w = int(tab_bar.style().pixelMetric(QStyle.PM_TabBarScrollButtonWidth, None, tab_bar))
                            except Exception:
                                scroll_btn_w = int(tab_bar_height)
                            # Безопасные границы: не даём кнопке стать слишком узкой/широкой.
                            scroll_btn_w = max(10, min(int(tab_bar_height), int(scroll_btn_w)))
                            if hasattr(self.favorites_bar_sandbox, "_favorites_scroll_left_btn") and self.favorites_bar_sandbox._favorites_scroll_left_btn:
                                self.favorites_bar_sandbox._favorites_scroll_left_btn.setFixedSize(scroll_btn_w, tab_bar_height)
                            if hasattr(self.favorites_bar_sandbox, "_favorites_scroll_right_btn") and self.favorites_bar_sandbox._favorites_scroll_right_btn:
                                self.favorites_bar_sandbox._favorites_scroll_right_btn.setFixedSize(scroll_btn_w, tab_bar_height)
                        except Exception:
                            pass
                    if getattr(self, "_favorites_bar_placeholder", None):
                        self._favorites_bar_placeholder.setFixedHeight(tab_bar_height)
                # В режиме cornerWidget позиционирование/ограничение ширины tabBar делает сам QTabWidget.
                try:
                    tab_bar.setUsesScrollButtons(True)
                except Exception:
                    pass
                # Обновляем размер кнопки в control_panel под фактическую высоту.
                self._update_control_panel_icons_position()
                self._sync_tab_corner_widgets_y()
                self._sync_tab_corner_tool_buttons()
                self._sync_tab_bar_bottom_line()
                self._raise_tab_bar_chrome()
                QTimer.singleShot(0, self._sync_tab_corner_widgets_y)
                QTimer.singleShot(0, self._sync_tab_corner_tool_buttons)
                QTimer.singleShot(0, self._sync_tab_bar_bottom_line)

    def _sync_tab_corner_tool_buttons(self):
        """Подгоняет высоту corner-кнопок и разделителя под строку tabBar."""
        tw = getattr(self, "tab_widget", None)
        if not tw:
            return
        try:
            th = editor_tab_bar_row_height_px(tw.tabBar())
            btn_h = tab_row_tool_button_content_height(th, tw)
        except Exception:
            return
        add_btn = getattr(self, "add_temp_file_button", None)
        if add_btn is not None:
            try:
                add_btn.setFixedSize(btn_h, btn_h)
            except Exception:
                pass
        sep = getattr(self, "_tab_corner_separator", None)
        if sep is not None:
            try:
                sep.setFixedHeight(btn_h)
            except Exception:
                pass
        panel = getattr(self, "control_panel", None)
        if panel is not None and hasattr(panel, "_sync_tool_button_geometry"):
            try:
                panel._sync_tool_button_geometry()
            except Exception:
                pass

    def _sync_tab_bar_bottom_line(self):
        """1px разделитель на всю ширину строки вкладок (включая corner), поверх QTabWidget."""
        tw = getattr(self, "tab_widget", None)
        line = getattr(self, "_tab_bar_bottom_line", None)
        tc = getattr(self, "_tab_container", None)
        if tw is None or line is None:
            return
        try:
            pane_top_line = str(tw.property("paneTopLine") or "")
            try:
                tab_count = int(tw.count())
            except Exception:
                tab_count = 0
            has_json = bool(getattr(self, "current_file", None))
            show = pane_top_line == "1" or (has_json and tab_count > 0)
            line.setVisible(show)
            if not show:
                return
            tab_bar = tw.tabBar()
            ty = int(tab_bar.geometry().y())
            th = int(tab_bar.geometry().height())
            host = tc if tc is not None else tw
            w = int(host.width())
            if w < 1 or th < 1:
                return
            try:
                tw_off = tw.mapTo(host, QPoint(0, 0))
                line_y = int(tw_off.y()) + ty + th - 1
            except Exception:
                line_y = ty + th - 1
            line.setGeometry(0, line_y, w, 1)
            line.raise_()
            self._raise_tab_bar_chrome()
        except Exception:
            pass

    def _sync_tab_corner_widgets_y(self):
        """Выравнивает левый/правый cornerWidget по Y с QTabBar (Fusion: corner на y=-1)."""
        tw = getattr(self, "tab_widget", None)
        if not tw:
            return
        try:
            tab_bar = tw.tabBar()
            ty = int(tab_bar.geometry().y())
            th = int(tab_bar.geometry().height())
        except Exception:
            return
        for corner in (
            getattr(self, "control_panel", None),
            getattr(self, "_tabwidget_left_corner", None),
        ):
            if corner is None:
                continue
            try:
                if hasattr(corner, "_align_y_to_tab_bar_row"):
                    corner._align_y_to_tab_bar_row()
                else:
                    g = corner.geometry()
                    if int(g.y()) != ty:
                        corner.move(int(g.x()), ty)
                if int(corner.height()) != th and hasattr(corner, "setFixedSizeValue"):
                    corner.setFixedSizeValue(int(corner.width()), th)
            except Exception:
                pass

    def _raise_tab_bar_chrome(self):
        """TabBar и corner-кнопки поверх pane; линия _TabBarBottomLine — под строкой вкладок (Fusion)."""
        tw = getattr(self, "tab_widget", None)
        if not tw:
            return
        try:
            tb = tw.tabBar()
            if tb is not None:
                tb.raise_()
        except Exception:
            pass
        for w in (
            getattr(self, "control_panel", None),
            getattr(self, "_tabwidget_left_corner", None),
        ):
            if w is not None:
                try:
                    w.raise_()
                except Exception:
                    pass
        line = getattr(self, "_tab_bar_bottom_line", None)
        if line is not None and line.isVisible():
            try:
                line.raise_()
            except Exception:
                pass

    def _sync_tab_pane_top_line(self):
        """Показывает/скрывает линию-разделитель под строкой вкладок (_TabBarBottomLine на всю ширину).

        Нужна, чтобы при старте без вкладок линия не “прилипала” сверху и не оказывалась над кнопками оверлеев.
        Реализовано через dynamic property `paneTopLine` + виджет _TabBarBottomLine.
        """
        tab_widget = getattr(self, "tab_widget", None)
        if not tab_widget:
            return
        try:
            cnt = int(tab_widget.count())
        except Exception:
            cnt = 0

        desired = "1" if cnt > 0 else "0"
        try:
            current = tab_widget.property("paneTopLine")
            current = "" if current is None else str(current)
        except Exception:
            current = ""

        if current == desired:
            try:
                self._sync_tab_bar_bottom_line()
            except Exception:
                pass
            return

        try:
            tab_widget.setProperty("paneTopLine", desired)
        except Exception:
            return

        # Переполировываем стиль только при изменении, чтобы не тратить время на массовых операциях.
        try:
            st = tab_widget.style()
            if st:
                st.unpolish(tab_widget)
                st.polish(tab_widget)
        except Exception:
            # Fallback: переустановка stylesheet тоже заставляет пересчитать правила.
            try:
                tab_widget.setStyleSheet(tab_widget.styleSheet())
            except Exception:
                pass
        try:
            tab_widget.update()
        except Exception:
            pass
        try:
            self._sync_tab_corner_tool_buttons()
            self._sync_tab_bar_bottom_line()
            self._raise_tab_bar_chrome()
        except Exception:
            pass

    def _sync_editor_chrome_visibility(self):
        """O(1) синхронизация видимости UI редактора (вкладки/кнопки/разделитель).

        Требование: когда JSON не загружен (нет tabBar и текстового поля),
        не должны отображаться:
        - кнопка «Добавить временный файл» (левый cornerWidget)
        - кнопка «Закрыть все вкладки» (control_panel)
        - линия-разделитель под панелью вкладок (border-top у QTabWidget::pane)

        При открытии JSON всё появляется как обычно.
        """
        has_json = bool(getattr(self, "current_file", None))

        tab_widget = getattr(self, "tab_widget", None)
        tab_container = getattr(self, "_tab_container", None)
        splitter = getattr(self, "splitter", None)

        # 1) Запоминаем пропорции splitter перед скрытием правой панели,
        # чтобы при показе восстановить (иначе QSplitter может оставить правую часть = 0).
        if not has_json:
            try:
                if splitter is not None and hasattr(splitter, "sizes"):
                    # На старте без файла finish_init может выполниться до load_settings().
                    # Если настройки уже загружены — фиксируем размеры из ini (они приоритетнее дефолта),
                    # иначе берём текущие.
                    desired = getattr(self, "_startup_splitter_sizes", None)
                    if getattr(self, "_startup_settings_loaded", False) and isinstance(desired, (list, tuple)) and len(desired) >= 2:
                        self._last_splitter_sizes_editor_visible = list(desired)
                    else:
                        self._last_splitter_sizes_editor_visible = splitter.sizes()
            except Exception:
                pass

        # 2) Скрываем/показываем всю правую панель (tab_container).
        try:
            if tab_container is not None:
                tab_container.setVisible(has_json)
        except Exception:
            pass

        # 3) Скрываем/показываем элементы в строке вкладок.
        for attr in ("control_panel", "_tabwidget_left_corner", "add_temp_file_button", "_tab_corner_separator"):
            try:
                w = getattr(self, attr, None)
                if w is not None:
                    w.setVisible(has_json)
            except Exception:
                pass

        # На всякий случай: сам QTabWidget тоже синхронизируем.
        try:
            if tab_widget is not None:
                tab_widget.setVisible(has_json)
        except Exception:
            pass

        # 4) Линия-разделитель под tabBar: при has_json=False выключаем принудительно,
        # чтобы она не "залипала" после tab_widget.clear() и не перескакивала над кнопками.
        if tab_widget is not None:
            if has_json:
                try:
                    self._sync_tab_pane_top_line()
                    self._sync_tab_bar_bottom_line()
                except Exception:
                    pass
            else:
                try:
                    cur = tab_widget.property("paneTopLine")
                    cur = "" if cur is None else str(cur)
                except Exception:
                    cur = ""
                if cur != "0":
                    try:
                        tab_widget.setProperty("paneTopLine", "0")
                        line = getattr(self, "_tab_bar_bottom_line", None)
                        if line is not None:
                            line.setVisible(False)
                        st = tab_widget.style()
                        if st:
                            st.unpolish(tab_widget)
                            st.polish(tab_widget)
                        tab_widget.update()
                    except Exception:
                        pass

        # 5) Восстанавливаем размеры splitter при показе правой панели.
        if has_json:
            try:
                if splitter is not None and hasattr(splitter, "sizes") and hasattr(splitter, "setSizes"):
                    sizes = splitter.sizes()
                    if isinstance(sizes, (list, tuple)) and len(sizes) >= 2 and int(sizes[1]) <= 0:
                        desired = getattr(self, "_last_splitter_sizes_editor_visible", None) or getattr(self, "_startup_splitter_sizes", None)
                        if isinstance(desired, (list, tuple)) and len(desired) >= 2 and int(desired[1]) > 0:
                            splitter.setSizes(list(desired))
                        else:
                            splitter.setSizes([242, 602])
            except Exception:
                pass
    
    def _update_control_panel_position(self):
        """Legacy: раньше позиционировали overlay-панель и душили tabBar.

        Теперь `control_panel` является `TopRightCorner` cornerWidget у `QTabWidget`,
        поэтому позиционирование и резервирование ширины делает Qt.
        """
        try:
            self._update_control_panel_size()
        except Exception:
            pass
    
    def resizeEvent(self, event):
        """Обработчик изменения размера окна"""
        super().resizeEvent(event)
        # До первого show() не трогаем геометрию/оверлеи (инвариант старта).
        if not getattr(self, "_startup_initialized", False):
            return
        # Синхронно: resizeEvent приходит после пересчёта размеров.
        self._update_control_panel_size()
    
    def on_tab_changed(self, index):
        """Обработчик переключения вкладок"""
        if index < 0:
            return
        
        # Сохраняем состояние предыдущей вкладки перед переключением
        if self.previous_tab_index >= 0 and self.previous_tab_index < self.tab_widget.count():
            previous_text_editor = self.tab_widget.widget(self.previous_tab_index)
            if previous_text_editor:
                # Принудительно останавливаем таймеры, чтобы сохранить состояние немедленно
                if hasattr(previous_text_editor, '_scroll_save_timer'):
                    previous_text_editor._scroll_save_timer.stop()
                if hasattr(previous_text_editor, '_cursor_save_timer'):
                    previous_text_editor._cursor_save_timer.stop()
                # Сохраняем состояние немедленно
                self._save_tab_state(previous_text_editor)
        
        # В новой архитектуре НЕ синхронизируем дерево/тексты на смене вкладки:
        # - ввод текста помечает dirty (O(1) на textChanged)
        # - autosave (500мс) сам коалесит и снимет снапшот без фризов
        
        # Обновляем индекс предыдущей вкладки
        self.previous_tab_index = index
        
        # Получаем виджет текущей вкладки
        text_editor = self.tab_widget.widget(index)
        if not text_editor:
            return
        
        # Обычный tab-switch: QTextEdit уже хранит scroll/cursor — restore не нужен.
        # Restore только после программной смены документа (_tab_state_needs_restore),
        # и только через singleShot(0) без processEvents (нет реентранса).
        self._schedule_restore_tab_state_if_needed(text_editor)
        
        # Получаем элемент, открытый в этой вкладке
        item = self.tab_items.get(text_editor)
        
        # Обновляем Tree View
        if item:
            # Проверяем, что элемент еще существует (не был удален)
            try:
                # Пытаемся получить текст элемента для проверки его существования
                _ = item.text(0)
                # Выделяем соответствующий элемент в дереве
                # Защита от реентрантности: синхронизация выбора из вкладок — программная.
                try:
                    self.tree._last_nav_source = "programmatic"
                except Exception:
                    pass
                self.tree.setCurrentItem(item)
                self.tree.scrollToItem(item)
                self.current_item = item
            except (RuntimeError, AttributeError):
                # Элемент был удален (например, при загрузке нового файла)
                # Очищаем выделение и связь с элементом
                self.tree.clearSelection()
                self.current_item = None
                # Удаляем связь из словаря, так как элемент больше не существует
                if text_editor in self.tab_items:
                    self._remove_tab_item_binding(text_editor)
        else:
            # Если вкладка пустая, очищаем выделение
            self.tree.clearSelection()
            self.current_item = None
    
    def _macos_tree_creation_shortcut_kind(self, event):
        """macOS: 'file' | 'folder' | None — ⌘/Ctrl+N (Shift=папка); ⌘ перехватывается Cocoa до QAction."""
        if sys.platform != "darwin" or event is None:
            return None
        try:
            if int(event.key()) != int(Qt.Key_N):
                return None
        except Exception:
            return None
        try:
            mods = event.modifiers()
        except Exception:
            return None
        if mods & Qt.AltModifier:
            return None
        if not (mods & (Qt.ControlModifier | Qt.MetaModifier)):
            return None
        if mods & Qt.ShiftModifier:
            return "folder"
        return "file"

    def _macos_tree_shortcut_event_target_ok(self, obj):
        """True — шорткат дерева можно обрабатывать для obj (не модальный чужой диалог)."""
        try:
            if QApplication.activeModalWidget() is not None:
                return False
        except Exception:
            pass
        if obj is self:
            return True
        if not isinstance(obj, QWidget):
            return False
        try:
            w = obj
            while w is not None:
                if w is self:
                    return True
                if isinstance(w, QDialog):
                    try:
                        if w.isModal() and w.window() is not self:
                            return False
                    except Exception:
                        return False
                w = w.parentWidget()
        except Exception:
            return False
        return False

    def _trigger_macos_tree_creation_shortcut(self, kind):
        if kind == "folder":
            self.add_folder(self._current_tree_item())
        elif kind == "file":
            self.add_file(self._current_tree_item())

    def eventFilter(self, obj, event):
        """Фильтр событий для перехвата Tab в дереве, обновления позиции панели управления и обработки мыши для изменения размера"""
        if sys.platform == "darwin" and isinstance(event, QKeyEvent):
            et = event.type()
            if et in (QEvent.KeyPress, QEvent.ShortcutOverride):
                kind = self._macos_tree_creation_shortcut_kind(event)
                if kind is not None and self._macos_tree_shortcut_event_target_ok(obj):
                    if et == QEvent.ShortcutOverride:
                        event.accept()
                        return True
                    self._trigger_macos_tree_creation_shortcut(kind)
                    event.accept()
                    return True

        # ------------------------------------------------------------
        # Централизованное включение/выключение подсказок для всей программы
        # ------------------------------------------------------------
        try:
            if event is not None and event.type() == QEvent.ToolTip:
                skip_policy = False
                try:
                    w = obj
                    while w is not None:
                        if bool(getattr(w, "_jbpad_skip_global_tooltip_policy", False)):
                            skip_policy = True
                            break
                        w = w.parent()
                except Exception:
                    pass
                blocked = skip_policy or not bool(getattr(self, "show_tooltips", True))
                return blocked
        except Exception:
            pass

        # Перехватываем события мыши от центрального виджета для обработки изменения размера
        if obj == self.centralWidget() and isinstance(event, QMouseEvent):
            try:
                if self.isMaximized():
                    return False
            except Exception:
                pass
            # Преобразуем координаты события в координаты главного окна
            global_pos = obj.mapToGlobal(event.pos())
            local_pos = self.mapFromGlobal(global_pos)
            if self._is_titlebar_chrome_at(local_pos):
                return False
            
            # Создаем новое событие для главного окна с правильными координатами
            if event.type() == QEvent.MouseMove:
                new_event = QMouseEvent(
                    QEvent.MouseMove,
                    local_pos,
                    global_pos,
                    event.button(),
                    event.buttons(),
                    event.modifiers()
                )
                # Вызываем обработчик главного окна
                self.mouseMoveEvent(new_event)
                # Не блокируем событие, чтобы дочерние виджеты тоже могли его обработать
                return False
            elif event.type() == QEvent.MouseButtonPress:
                new_event = QMouseEvent(
                    QEvent.MouseButtonPress,
                    local_pos,
                    global_pos,
                    event.button(),
                    event.buttons(),
                    event.modifiers()
                )
                self.mousePressEvent(new_event)
                # Если мышь на краю, блокируем событие для дочерних виджетов
                edge = self._get_resize_edge(local_pos)
                if edge:
                    return True
                return False
            elif event.type() == QEvent.MouseButtonRelease:
                new_event = QMouseEvent(
                    QEvent.MouseButtonRelease,
                    local_pos,
                    global_pos,
                    event.button(),
                    event.buttons(),
                    event.modifiers()
                )
                self.mouseReleaseEvent(new_event)
                return False
        
        # Пересчёт corner «Закрыть все вкладки» при изменении высоты tabBar.
        if hasattr(self, "tab_widget") and self.tab_widget:
            try:
                tab_bar = self.tab_widget.tabBar()
            except Exception:
                tab_bar = None
            if tab_bar is not None and obj == tab_bar and event.type() == QEvent.Resize:
                if getattr(self, "_startup_initialized", False):
                    QTimer.singleShot(0, self._update_control_panel_size)
                    QTimer.singleShot(0, self._sync_tab_bar_bottom_line)
                return False

        for corner in (
            getattr(self, "control_panel", None),
            getattr(self, "_tabwidget_left_corner", None),
        ):
            if corner is not None and obj == corner and event.type() in (QEvent.Move, QEvent.Show, QEvent.Resize):
                if getattr(self, "_startup_initialized", False):
                    QTimer.singleShot(0, self._sync_tab_corner_widgets_y)
                    QTimer.singleShot(0, self._sync_tab_bar_bottom_line)
                return False

        tab_container = getattr(self, "_tab_container", None)
        if tab_container is not None and obj == tab_container and event.type() == QEvent.Resize:
            if getattr(self, "_startup_initialized", False):
                QTimer.singleShot(0, self._sync_tab_bar_bottom_line)
            return False
        
        # Перехватываем Tab только для дерева
        if hasattr(self, 'tree') and obj == self.tree and event.type() == QEvent.KeyPress:
            if event.key() == Qt.Key_Tab and not (event.modifiers() & (Qt.ShiftModifier | Qt.ControlModifier | Qt.AltModifier)):
                # Получаем текущий выделенный элемент
                current_item = self.tree.currentItem()
                if current_item:
                    # Открываем элемент в новой вкладке (или переключаемся на существующую)
                    # Теперь работает и для корневой папки
                    self.open_item_in_new_tab(current_item)
                    # Tab — явная команда пользователя перейти к редактированию.
                    self.focus_text_editor()
                    # Возвращаем True, чтобы событие не обрабатывалось дальше
                    return True
        
        # Для всех остальных событий вызываем стандартную обработку
        return super().eventFilter(obj, event)
    
    def get_program_directory(self):
        """Возвращает путь к каталогу программы"""
        return str(APP_DIR)
    
    def get_data_directory(self):
        """Возвращает путь к каталогу Data"""
        return str(APP_DIR / "Data")
    
    def get_settings_file_path(self):
        """Возвращает путь к файлу настроек Setting.ini"""
        return str(APP_DIR / "Setting.ini")
    
    def get_date_settings(self):
        """
        Получает настройки формата даты из файла настроек.

        Returns:
            tuple: (date_format, include_time)
        """
        settings_file = self.get_settings_file_path()
        return normalize_date_settings(settings_file)

    def get_separator_text(self) -> str:
        """Возвращает текст разделителя из Setting.ini (или кешированное значение)."""
        settings_file = self.get_settings_file_path()
        fallback_value = str(getattr(self, "separator_text", "") or "")

        if _io_exists(settings_file):
            config = _read_settings_ini(settings_file)
            try:
                if config.has_section("Separator"):
                    return str(config.get("Separator", "text", fallback=fallback_value) or "")
            except Exception:
                pass
        return fallback_value
    
    def to_relative_path(self, absolute_path):
        """
        Конвертирует абсолютный путь в относительный (относительно директории программы).
        Если путь не может быть сделан относительным, возвращает исходный путь.
        """
        if not absolute_path:
            return ''
        
        try:
            program_dir = self.get_program_directory()
            # Нормализуем пути для корректного сравнения (без \\?\ для Qt/ini).
            abs_path = os.path.normpath(os.path.abspath(_win_display_path(absolute_path)))
            prog_dir = os.path.normpath(os.path.abspath(_win_display_path(program_dir)))
            
            # Если путь находится внутри директории программы, делаем его относительным
            try:
                relative = os.path.relpath(abs_path, prog_dir)
                # Проверяем, что относительный путь не выходит за пределы директории программы
                if not relative.startswith('..'):
                    return _portable_relative_path_for_ini(relative)
            except ValueError:
                # Если пути на разных дисках (Windows), возвращаем исходный путь
                pass
            
            # Если путь не может быть сделан относительным, возвращаем исходный
            return absolute_path
        except Exception:
            return absolute_path
    
    def to_absolute_path(self, relative_path):
        """
        Конвертирует относительный путь в абсолютный (относительно директории программы).
        Если путь уже абсолютный, возвращает его как есть.
        """
        if not relative_path or str(relative_path) == "":
            return None
        
        try:
            cleaned = _normalize_portable_relative_path(relative_path)
            if cleaned == "":
                return None
            # Если путь уже абсолютный, возвращаем его
            if os.path.isabs(cleaned):
                return os.path.normpath(_win_display_path(cleaned))

            # Иначе делаем его абсолютным относительно директории программы
            program_dir = self.get_program_directory()
            absolute = os.path.normpath(os.path.join(_win_display_path(program_dir), cleaned))
            return absolute
        except Exception:
            try:
                cleaned = _normalize_portable_relative_path(relative_path)
            except Exception:
                return None
            if cleaned == "":
                return None
            if os.path.isabs(cleaned):
                return os.path.normpath(_win_display_path(cleaned))
            program_dir = self.get_program_directory()
            return os.path.normpath(os.path.join(_win_display_path(program_dir), cleaned))
    
    def load_settings(self):
        """Загружает настройки из файла Setting.ini.

        ВАЖНО (инварианты старта):
        - Этот метод НЕ трогает геометрию/видимость/перемещения UI напрямую.
        - Не использует QTimer/processEvents.
        - Он только читает файл и заполняет *_startup_* поля, которые применяются один раз в showEvent().
        """
        settings_file = self.get_settings_file_path()
        
        # Значения по умолчанию
        default_width = 867
        default_height = 725
        default_splitter_sizes = [242, 602]
        
        # Пытаемся загрузить настройки
        if _io_exists(settings_file):
            config = _read_settings_ini(settings_file)
            try:

                try:
                    self._load_font_settings_from_config(config)
                except Exception:
                    pass

                # Загружаем размер и позицию окна.
                # Секция зависит от ОС ([Window_Win]/[Window_Linux]/[Window_macOS]);
                # общая [Window] используется как fallback для конфигов прежних версий.
                _window_section = _settings_section_name(config, "Window")
                if _window_section:
                    x = config.getint(_window_section, 'x', fallback=None)
                    y = config.getint(_window_section, 'y', fallback=None)
                    width = config.getint(_window_section, 'width', fallback=default_width)
                    height = config.getint(_window_section, 'height', fallback=default_height)
                    # Загружаем состояние максимизации
                    is_maximized = config.getboolean(_window_section, 'maximized', fallback=False)
                    
                    # Проверка для старых версий конфига: если флаг maximized отсутствует,
                    # но размер окна близок к рабочей области экрана, предполагаем максимизацию
                    if not is_maximized and x is not None and y is not None:
                        screen = QApplication.primaryScreen().availableGeometry()
                        pos_tol = 2
                        if (abs(int(x) - int(screen.x())) <= pos_tol and
                                abs(int(y) - int(screen.y())) <= pos_tol and
                                width >= screen.width() * 0.9 and
                                height >= screen.height() * 0.9):
                            is_maximized = True
                    
                    if x is not None and y is not None:
                        self._startup_window_geometry = QRect(x, y, width, height)
                    else:
                        screen = QApplication.primaryScreen().availableGeometry()
                        cx = screen.x() + (screen.width() - width) // 2
                        cy = screen.y() + (screen.height() - height) // 2
                        self._startup_window_geometry = QRect(cx, cy, width, height)
                    self._startup_window_maximized = bool(is_maximized)
                else:
                    screen = QApplication.primaryScreen().availableGeometry()
                    cx = screen.x() + (screen.width() - default_width) // 2
                    cy = screen.y() + (screen.height() - default_height) // 2
                    self._startup_window_geometry = QRect(cx, cy, default_width, default_height)
                    self._startup_window_maximized = False
                
                # Загружаем размеры splitter
                if config.has_section('Splitter'):
                    size1 = config.getint('Splitter', 'size1', fallback=default_splitter_sizes[0])
                    size2 = config.getint('Splitter', 'size2', fallback=default_splitter_sizes[1])
                    self._startup_splitter_sizes = [size1, size2]
                else:
                    self._startup_splitter_sizes = list(default_splitter_sizes)

                # Загружаем настройку показа подсказок
                self._startup_show_tooltips = True
                if config.has_section('Toolbar'):
                    self._startup_show_tooltips = config.getboolean('Toolbar', 'show_tooltips', fallback=True)
                self._startup_highlight_links_in_text = True
                if config.has_section('View'):
                    self._startup_highlight_links_in_text = config.getboolean('View', 'highlight_links_in_text', fallback=True)
                    # Ограничения ширины (px) — по умолчанию из констант
                    try:
                        w_tab = config.getint('View', 'max_editor_tab_width_px', fallback=int(DEFAULT_EDITOR_TAB_MAX_WIDTH_PX))
                    except Exception:
                        w_tab = int(DEFAULT_EDITOR_TAB_MAX_WIDTH_PX)
                    try:
                        w_fav = config.getint('View', 'max_favorites_item_width_px', fallback=int(DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX))
                    except Exception:
                        w_fav = int(DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX)
                    w_tab = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(w_tab)))
                    w_fav = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(w_fav)))
                    self._startup_max_editor_tab_width_px = int(w_tab)
                    self._startup_max_favorites_item_width_px = int(w_fav)
                    # "Saved" значения должны соответствовать ini
                    self.max_editor_tab_width_px_saved = int(w_tab)
                    self.max_favorites_item_width_px_saved = int(w_fav)
                else:
                    # Если секции [View] нет — используем дефолты
                    self._startup_max_editor_tab_width_px = int(getattr(self, "max_editor_tab_width_px", DEFAULT_EDITOR_TAB_MAX_WIDTH_PX))
                    self._startup_max_favorites_item_width_px = int(getattr(self, "max_favorites_item_width_px", DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX))

                # Загружаем текст разделителя
                try:
                    if config.has_section("Separator"):
                        self.separator_text = str(config.get("Separator", "text", fallback="") or "")
                    else:
                        self.separator_text = str(getattr(self, "separator_text", "") or "")
                except Exception:
                    self.separator_text = str(getattr(self, "separator_text", "") or "")
                
                # Загружаем путь к последнему открытому файлу
                if config.has_section('File'):
                    relative_path = config.get('File', 'last_file', fallback=None)
                    # Конвертируем относительный путь в абсолютный
                    self.last_file_path = self.to_absolute_path(relative_path)
                    # Проверяем, что путь не пустой
                    if self.last_file_path and not self.last_file_path.strip():
                        self.last_file_path = None
                else:
                    self.last_file_path = None
                
                # Загружаем избранное
                if config.has_section('Favorites'):
                    favorites_count = config.getint('Favorites', 'count', fallback=0)
                    favorites_paths = []
                    for i in range(favorites_count):
                        favorite_key = f'file_{i}'
                        if config.has_option('Favorites', favorite_key):
                            relative_path = config.get('Favorites', favorite_key)
                            if relative_path:
                                absolute_path = self.to_absolute_path(relative_path)
                                if absolute_path:
                                    resolved = _abs_realpath_for_comparison(absolute_path)
                                    favorites_paths.append(resolved or absolute_path)
                    
                    self._startup_favorites_paths_list = list(favorites_paths)
                    # Видимость только из panel_visible; без ключа или без секции — скрыта (False).
                    self._startup_favorites_visible = config.getboolean(
                        'Favorites', 'panel_visible', fallback=False
                    )
                
                # Загружаем отступ редактора и настройки быстрого доступа
                if config.has_section('Editor'):
                    self.editor_left_margin = config.getint('Editor', 'left_margin', fallback=27)
                    
                    # Загружаем настройки быстрого доступа к строкам
                    self.newlines_count = config.getint('Editor', 'newlines_count', fallback=50)

                    # Межстрочный интервал (проценты от высоты шрифта)
                    line_spacing = config.getint('Editor', 'line_spacing', fallback=100)
                    line_spacing = max(50, min(200, line_spacing))
                    # В этом запуске применяем только значение, считанное при старте
                    self.editor_line_spacing = line_spacing
                    # Это значение пишем в Setting.ini при сохранении настроек
                    self.editor_line_spacing_saved = line_spacing

                    # Выравнивание (trailing/leading) — применяем только значение, считанное при старте
                    try:
                        right_alignment = config.getboolean('Editor', 'right_alignment', fallback=False)
                    except Exception:
                        # На всякий случай: старые ini могли хранить строки/числа
                        try:
                            right_alignment = str(config.get('Editor', 'right_alignment', fallback='False')).strip().lower() in ("1", "true", "yes", "y", "on")
                        except Exception:
                            right_alignment = False
                    self.editor_right_alignment = bool(right_alignment)
                    self.editor_right_alignment_saved = bool(right_alignment)

                    # Правый отступ (px) для режима выравнивания справа
                    try:
                        right_indent = config.getint('Editor', 'right_indent', fallback=int(getattr(self, "editor_right_indent_px", getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))))
                    except Exception:
                        try:
                            right_indent = int(str(config.get('Editor', 'right_indent', fallback=str(getattr(self, "editor_right_indent_px", getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))))).strip())
                        except Exception:
                            right_indent = int(getattr(self, "editor_right_indent_px", getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10)))
                    right_indent = max(0, min(500, int(right_indent)))
                    self.editor_right_indent_px = int(right_indent)
                    self.editor_right_indent_px_saved = int(right_indent)
                    try:
                        TextEditor.RIGHT_MARGIN_RIGHT_ALIGN_PX = int(right_indent)
                    except Exception:
                        pass
                else:
                    # Используем значения по умолчанию
                    self.newlines_count = 50
                    self.editor_line_spacing = 100
                    self.editor_line_spacing_saved = 100
                    self.editor_right_alignment = False
                    self.editor_right_alignment_saved = False
                    try:
                        _d = int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))
                    except Exception:
                        _d = 10
                    self.editor_right_indent_px = int(_d)
                    self.editor_right_indent_px_saved = int(_d)

                # Язык интерфейса (перевод): имя файла в папке languages без расширения
                try:
                    lang_name = str(config.get('languages', 'translation', fallback='') or '').strip()
                except Exception:
                    lang_name = ''
                self.ui_translation = str(lang_name or '')
                self.ui_translation_saved = str(lang_name or '')

                # Переименование по клику (Tree)
                try:
                    if config.has_section('Tree'):
                        min_ms = config.getint('Tree', 'slow_double_click_min_interval_ms', fallback=getattr(self, 'slow_double_click_min_interval_ms', SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT))
                        max_ms = config.getint('Tree', 'slow_double_click_max_interval_ms', fallback=getattr(self, 'slow_double_click_max_interval_ms', SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT))
                    else:
                        min_ms = int(getattr(self, 'slow_double_click_min_interval_ms', SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT))
                        max_ms = int(getattr(self, 'slow_double_click_max_interval_ms', SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT))
                    min_ms = max(0, min(59999, int(min_ms)))
                    max_ms = max(1, min(60000, int(max_ms)))
                    if max_ms <= min_ms:
                        max_ms = min(60000, min_ms + 1)
                        if max_ms <= min_ms:
                            min_ms = max(0, max_ms - 1)
                    self.slow_double_click_min_interval_ms = int(min_ms)
                    self.slow_double_click_max_interval_ms = int(max_ms)
                except Exception:
                    self.slow_double_click_min_interval_ms = SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT
                    self.slow_double_click_max_interval_ms = SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT

                # Если дерево уже создано (finish_init мог выполниться до load_settings) — применяем сразу
                try:
                    if hasattr(self, "tree") and isinstance(self.tree, JsonTreeWidget):
                        self.tree.slow_double_click_min_interval_ms = int(getattr(self, "slow_double_click_min_interval_ms", SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT))
                        self.tree.slow_double_click_max_interval_ms = int(getattr(self, "slow_double_click_max_interval_ms", SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT))
                except Exception:
                    pass
                self.highlight_links_in_text = bool(getattr(self, "_startup_highlight_links_in_text", True))
            except Exception:
                # При ошибке загрузки используем значения по умолчанию
                # (большинство значений уже инициализированы в __init__)
                
                # Устанавливаем настройки редактора по умолчанию
                self.editor_left_margin = 27
                self.newlines_count = 50
                self.editor_line_spacing = 100
                self.editor_line_spacing_saved = 100
                self.editor_right_alignment = False
                self.editor_right_alignment_saved = False
                self.ui_translation = ""
                self.ui_translation_saved = ""
                try:
                    _d = int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))
                except Exception:
                    _d = 10
                self.editor_right_indent_px = int(_d)
                self.editor_right_indent_px_saved = int(_d)
                try:
                    TextEditor.RIGHT_MARGIN_RIGHT_ALIGN_PX = int(_d)
                except Exception:
                    pass
                self.slow_double_click_min_interval_ms = SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT
                self.slow_double_click_max_interval_ms = SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT
                self._startup_highlight_links_in_text = True
                self.highlight_links_in_text = True
                self._startup_max_editor_tab_width_px = int(getattr(self, "max_editor_tab_width_px", DEFAULT_EDITOR_TAB_MAX_WIDTH_PX))
                self._startup_max_favorites_item_width_px = int(getattr(self, "max_favorites_item_width_px", DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX))
        else:
            screen = QApplication.primaryScreen().geometry()
            cx = (screen.width() - default_width) // 2
            cy = (screen.height() - default_height) // 2
            self._startup_window_geometry = QRect(cx, cy, default_width, default_height)
            self._startup_window_maximized = False
            self._startup_splitter_sizes = list(default_splitter_sizes)
            self._startup_show_tooltips = True
            self._startup_highlight_links_in_text = True
            self._startup_max_editor_tab_width_px = int(getattr(self, "max_editor_tab_width_px", DEFAULT_EDITOR_TAB_MAX_WIDTH_PX))
            self._startup_max_favorites_item_width_px = int(getattr(self, "max_favorites_item_width_px", DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX))
            # Устанавливаем настройки редактора по умолчанию
            # (они уже инициализированы в __init__, но явно устанавливаем для надежности)
            self.editor_left_margin = 27
            self.newlines_count = 50
            self.editor_line_spacing = 100
            self.editor_line_spacing_saved = 100
            self.editor_right_alignment = False
            self.editor_right_alignment_saved = False
            self.ui_translation = ""
            self.ui_translation_saved = ""
            try:
                _d = int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))
            except Exception:
                _d = 10
            self.editor_right_indent_px = int(_d)
            self.editor_right_indent_px_saved = int(_d)
            try:
                TextEditor.RIGHT_MARGIN_RIGHT_ALIGN_PX = int(_d)
            except Exception:
                pass
            self.slow_double_click_min_interval_ms = SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT
            self.slow_double_click_max_interval_ms = SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT
            self.highlight_links_in_text = True
            self._editor_text_font_loaded = True
            self._startup_settings_file_missing = True

        self._startup_settings_loaded = True
        
    
    def show_settings_dialog(self):
        """Показывает диалоговое окно настроек или редактор тем при несохранённой сессии."""
        if ThemeManager.instance().is_session_dirty():
            self.show_theme_editor_dialog()
            return
        dialog = NewSettingsDialog(self)
        dialog.exec_()
        if getattr(self, "_reopen_settings_after_theme_editor", False):
            self._reopen_settings_after_theme_editor = False
            self.show_theme_editor_dialog(wait=True, independent=True)
            if not ThemeManager.instance().is_session_dirty():
                dialog = NewSettingsDialog(self)
                dialog.exec_()

    def show_theme_editor_dialog(self, *, wait=False, independent=None):
        """Открывает редактор тем.

        На Wayland — немодальное окно (parent=main), как окно поиска.
        На остальных платформах — модальный exec_().
        wait=True — exec_() до закрытия (Wayland: после выхода из exec_() настроек).
        """
        if independent is None:
            independent = _theme_editor_independent_window()

        if not independent:
            try:
                dlg = ThemeEditorDialog(self, independent_window=False)
                dlg.exec_()
                return dlg
            except Exception:
                return None

        try:
            if wait:
                dlg = ThemeEditorDialog(self, independent_window=True)
                self.theme_editor_dialog = dlg
                loop = QEventLoop()

                def _on_theme_editor_finished(_code):
                    if getattr(self, "theme_editor_dialog", None) is dlg:
                        self.theme_editor_dialog = None
                    loop.quit()

                dlg.finished.connect(_on_theme_editor_finished)
                dlg.show()
                dlg.raise_()
                dlg.activateWindow()
                loop.exec_()
                try:
                    dlg.finished.disconnect(_on_theme_editor_finished)
                except Exception:
                    pass
                return dlg

            dlg = getattr(self, "theme_editor_dialog", None)
            if dlg is not None and dlg.isVisible():
                dlg.raise_()
                dlg.activateWindow()
                return dlg

            dlg = ThemeEditorDialog(self, independent_window=True)
            self.theme_editor_dialog = dlg

            def _on_theme_editor_finished(_code):
                if getattr(self, "theme_editor_dialog", None) is dlg:
                    self.theme_editor_dialog = None

            dlg.finished.connect(_on_theme_editor_finished)
            dlg.show()
            dlg.raise_()
            dlg.activateWindow()
            return dlg
        except Exception:
            return None

    def show_file_management_dialog(self):
        """Диалог удаления блокнотов, локализаций и тем."""
        dialog = FileManagementDialog(self)
        dialog.exec_()

    def _apply_file_management_deletions(self, deleted_paths):
        """Побочные эффекты после успешного удаления файлов из Data/."""
        if not deleted_paths:
            return

        notebook_paths = []
        language_paths = []
        theme_paths = []
        for path in deleted_paths:
            if _deleted_file_parent_is(str(data_languages_dir()), path):
                language_paths.append(path)
            elif _deleted_file_parent_is(str(data_themes_dir()), path):
                theme_paths.append(path)
            elif _deleted_file_parent_is(str(data_directory()), path):
                notebook_paths.append(path)

        if notebook_paths:
            self._purge_favorites_for_deleted_notebooks(notebook_paths)
            try:
                json_cache = JsonMemoryCache()
                for path in notebook_paths:
                    try:
                        json_cache.remove(path)
                    except Exception:
                        pass
            except Exception:
                pass

        if theme_paths:
            tm = ThemeManager.instance()
            for path in theme_paths:
                try:
                    filename = os.path.basename(str(path))
                    normalized = tm._normalize_custom_theme_filename(filename)
                    if normalized and normalized in tm._custom_themes:
                        del tm._custom_themes[normalized]
                except Exception:
                    pass

        # language_paths: runtime translator не перезагружаем для неактивных языков.

    def _purge_favorites_for_deleted_notebooks(self, deleted_paths):
        """Убирает удалённые блокноты из избранного."""
        deleted = [p for p in (deleted_paths or []) if p]
        if not deleted:
            return

        def _is_deleted_notebook(favorite_path) -> bool:
            return any(_paths_refer_to_same_file(favorite_path, dp) for dp in deleted)

        try:
            fav_docs = getattr(self, "favorites_documents_by_path", None)
            if isinstance(fav_docs, dict):
                for key in list(fav_docs.keys()):
                    if _is_deleted_notebook(key):
                        del fav_docs[key]
        except Exception:
            pass

        fav = getattr(self, "favorites_bar_sandbox", None)
        if fav is None or not getattr(fav, "model", None):
            return

        try:
            current_list = list(fav.model.stringList())
        except Exception:
            return

        new_list = [fp for fp in current_list if not _is_deleted_notebook(fp)]
        if new_list == current_list:
            return

        try:
            fav.model.setStringList(new_list)
        except Exception:
            return

        self._sync_favorites_bar_after_list_change(new_list)
    
    def _current_notebook_filepath(self):
        try:
            fp = getattr(self, "current_file", None)
            if fp:
                return fp
            doc = getattr(self, "current_document", None)
            if doc is not None:
                return getattr(doc, "filepath", None)
        except Exception:
            pass
        return None

    def _sync_favorites_bar_after_list_change(self, remaining_paths, removed_path=None):
        """Синхронизирует панель избранного после изменения списка.

        favoriteActivated эмитится только если нужно переключить открытый документ
        (удалили активное избранное). При удалении неактивной вкладки открытый
        файл не меняется.
        """
        fav = getattr(self, "favorites_bar_sandbox", None)
        if fav is None:
            return

        remaining = list(remaining_paths or [])
        removed_norm = _canonical_file_path(removed_path)
        current_fp = self._current_notebook_filepath()
        current_norm = _canonical_file_path(current_fp)

        if not remaining:
            fav.set_active_file(None)
            try:
                fav.favoriteActivated.emit(None)
            except Exception:
                pass
            return

        if current_norm and any(_canonical_file_path(p) == current_norm for p in remaining):
            fav.set_active_file(current_fp)
            return

        if removed_norm and current_norm and removed_norm == current_norm:
            first_path = remaining[0]
            fav.set_active_file(first_path)
            try:
                fav.favoriteActivated.emit(first_path)
            except Exception:
                pass
            return

        if current_norm:
            fav.set_active_file(None)
            return

        fav.set_active_file(remaining[0])

    def show_search_dialog(self):
        """Показывает диалоговое окно поиска"""
        if not self.current_file:
            return
        
        # Создаем диалог, если его еще нет, или показываем существующий
        if self.search_dialog is None:
            self.search_dialog = SearchDialog(self)
        
        self.search_dialog.show()
        self.search_dialog.raise_()
        self.search_dialog.activateWindow()
        self.search_dialog.search_input.setFocus()

        def _after_show():
            if self.search_dialog is None:
                return
            if not getattr(self.search_dialog, "_initial_placement_done", False):
                te = self.get_current_text_editor()
                if te is None:
                    return
                if self.search_dialog._place_on_initial_open(te):
                    self.search_dialog._initial_placement_done = True
            else:
                self.search_dialog._restore_session_position()

        QApplication.processEvents()
        _after_show()
        QTimer.singleShot(0, _after_show)
    
    def get_text_font_from_settings(self):
        """Возвращает шрифт текстового поля (кеш сессии, без повторного чтения Setting.ini)."""
        if not getattr(self, "_editor_text_font_loaded", False):
            self._reload_editor_text_font_from_settings()
        try:
            cached = getattr(self, "editor_text_font", None)
            if cached is not None:
                return QFont(cached)
        except Exception:
            pass
        return QFont(self.get_system_proportional_font())

    def _load_font_settings_from_config(self, config):
        """Загружает ui_font и editor_text_font из секции шрифтов текущей ОС.

        Секция зависит от ОС ([Font_Win]/[Font_Linux]/[Font_macOS]); общая [Font]
        используется как fallback для конфигов прежних версий.
        """
        _font_section = _settings_section_name(config, "Font")
        if not _font_section:
            self._editor_text_font_loaded = True
            return
        self.editor_text_font = self._build_editor_text_font_from_config(config)
        base_ui = self.get_system_proportional_font()
        self.ui_font = QFont(base_ui)
        try:
            ui_font_family = config.get(_font_section, 'ui_family', fallback='').strip()
        except Exception:
            ui_font_family = ''
        try:
            ui_font_size = config.getint(_font_section, 'ui_size', fallback=-1)
        except Exception:
            ui_font_size = -1
        ui_font_bold = config.getboolean(_font_section, 'ui_bold', fallback=bool(base_ui.bold()))
        ui_font_italic = config.getboolean(_font_section, 'ui_italic', fallback=bool(base_ui.italic()))
        if ui_font_family:
            try:
                _qfont_apply_family_if_available(self.ui_font, ui_font_family)
            except Exception:
                pass
        if ui_font_size and int(ui_font_size) > 0:
            try:
                self.ui_font.setPointSize(int(ui_font_size))
            except Exception:
                pass
        try:
            self.ui_font.setBold(bool(ui_font_bold))
        except Exception:
            pass
        try:
            self.ui_font.setItalic(bool(ui_font_italic))
        except Exception:
            pass
        self._editor_text_font_loaded = True

    def _reload_editor_text_font_from_settings(self):
        """Ленивая подстраховка: один раз читает [Font] из Setting.ini."""
        if getattr(self, "_editor_text_font_loaded", False):
            return
        settings_file = self.get_settings_file_path()
        if not _io_exists(settings_file):
            self._editor_text_font_loaded = True
            return
        config = _read_settings_ini(settings_file)
        try:
            self._load_font_settings_from_config(config)
        except Exception:
            self._editor_text_font_loaded = True

    def _build_editor_text_font_from_config(self, config):
        """Собирает editor_text_font из секции шрифтов текущей ОС (один раз при load_settings)."""
        base = self.get_system_proportional_font()
        f = QFont(base)
        _font_section = _settings_section_name(config, "Font")
        if not _font_section:
            return f
        try:
            family = config.get(_font_section, 'text_family', fallback='').strip()
        except Exception:
            family = ''
        try:
            size = config.getint(_font_section, 'text_size', fallback=-1)
        except Exception:
            size = -1
        try:
            bold = config.getboolean(_font_section, 'text_bold', fallback=bool(base.bold()))
        except Exception:
            bold = bool(base.bold())
        try:
            italic = config.getboolean(_font_section, 'text_italic', fallback=bool(base.italic()))
        except Exception:
            italic = bool(base.italic())
        _qfont_apply_family_if_available(f, family)
        if size and int(size) > 0:
            try:
                f.setPointSize(int(size))
            except Exception:
                pass
        try:
            f.setBold(bool(bold))
        except Exception:
            pass
        try:
            f.setItalic(bool(italic))
        except Exception:
            pass
        return f

    def get_system_proportional_font(self) -> 'QFont':
        """Системный пропорциональный шрифт (кроссплатформенно через Qt)."""
        try:
            app = QApplication.instance()
            if app is not None:
                return QFont(app.font())
        except Exception:
            pass
        return QFont()

