    def apply_ui_font_to_tabs(self):
        """Применяет шрифт интерфейса к вкладкам"""
        if hasattr(self, 'tab_widget') and self.tab_widget:
            tab_bar = self.tab_widget.tabBar()
            if tab_bar:
                tab_bar.setFont(self.ui_font)

        # Применяем шрифт к новой панели избранного (QListView)
        if hasattr(self, 'favorites_bar_sandbox') and self.favorites_bar_sandbox and getattr(self, "ui_font", None):
            try:
                if hasattr(self.favorites_bar_sandbox, "list_view"):
                    self.favorites_bar_sandbox.list_view.setFont(self.ui_font)
                    try:
                        self.favorites_bar_sandbox.list_view.doItemsLayout()
                    except Exception:
                        pass
            except Exception:
                pass
        
        # После смены шрифта высота панели вкладок пересчитывается при следующем layout;
        # отложенно подстраиваем высоту панели избранного под новую высоту вкладок
        QTimer.singleShot(0, self._update_control_panel_size)
    
    def _get_persistable_splitter_sizes(self):
        """Возвращает (size1, size2), если размеры splitter можно безопасно сохранить в Setting.ini.

        Инвариант: пишем [Splitter] только когда реально существует дерево + текстовое поле
        (есть активный документ и хотя бы одна вкладка редактора).
        """
        try:
            # Должен быть открыт документ (иначе UI "схлопнут" логически).
            if not getattr(self, "current_file", None):
                return None

            splitter = getattr(self, "splitter", None)
            if splitter is None or not hasattr(splitter, "sizes"):
                return None

            # Дерево должно быть создано (не плейсхолдер).
            if getattr(self, "tree", None) is None:
                return None

            tab_widget = getattr(self, "tab_widget", None)
            if tab_widget is None:
                return None
            try:
                if int(tab_widget.count()) <= 0:
                    return None
            except Exception:
                return None

            try:
                editor = self.get_current_text_editor()
            except Exception:
                editor = None
            if editor is None:
                return None

            sizes = splitter.sizes()
            if not isinstance(sizes, (list, tuple)) or len(sizes) < 2:
                return None

            try:
                s0 = int(sizes[0])
                s1 = int(sizes[1])
            except Exception:
                return None

            # Когда правая панель скрыта/схлопнута, QSplitter может дать 0 — это нельзя сохранять.
            if s0 <= 0 or s1 <= 0:
                return None

            return (s0, s1)
        except Exception:
            return None

    def _persist_splitter_sizes_to_ini(self):
        """Точечно сохраняет только секцию [Splitter] (не трогая last_file и прочие настройки)."""
        sizes = self._get_persistable_splitter_sizes()
        if not sizes:
            return

        settings_file = self.get_settings_file_path()
        config = _read_settings_ini(settings_file)
        try:
            if not config.has_section("Splitter"):
                config.add_section("Splitter")
            config.set("Splitter", "size1", str(int(sizes[0])))
            config.set("Splitter", "size2", str(int(sizes[1])))
        except Exception:
            return

        try:
            _write_settings_ini_atomic(settings_file, config)
        except Exception:
            return

    def _schedule_splitter_persist(self, delay_ms: int = 250):
        """Debounce сохранения размеров splitter в Setting.ini при ручном изменении пользователем."""
        try:
            delay_ms = int(delay_ms)
        except Exception:
            delay_ms = 250
        if delay_ms < 0:
            delay_ms = 0

        t = getattr(self, "_splitter_persist_timer", None)
        if t is None:
            try:
                t = QTimer(self)
                t.setSingleShot(True)

                def _do():
                    try:
                        self._persist_splitter_sizes_to_ini()
                        # Обновляем кэш стартовых размеров на текущие валидные, чтобы восстановление в этом же запуске было корректным.
                        s = self._get_persistable_splitter_sizes()
                        if s:
                            self._startup_splitter_sizes = [int(s[0]), int(s[1])]
                    except Exception:
                        pass

                t.timeout.connect(_do)
                self._splitter_persist_timer = t
            except Exception:
                return

        try:
            t.start(delay_ms)
        except Exception:
            pass

    def _on_splitter_moved(self, *args):
        """Слот: пользователь изменил ширину дерева/редактора."""
        try:
            self._schedule_splitter_persist(250)
        except Exception:
            pass

    def save_settings(self):
        """Сохраняет настройки в файл Setting.ini"""
        settings_file = self.get_settings_file_path()
        config = _read_settings_ini(settings_file)
        
        try:
            # Сохраняем размер и позицию окна
            # Если окно максимизировано, сохраняем нормальную геометрию, а не максимизированную
            if self.isMaximized():
                window_geometry = self.normalGeometry()
            else:
                window_geometry = self.geometry()
            # Пишем в секцию текущей ОС ([Window_Win]/[Window_Linux]/[Window_macOS]);
            # общую [Window] намеренно не изменяем (совместимость прежних версий).
            _window_section = _ensure_settings_section(config, "Window")
            config.set(_window_section, 'x', str(window_geometry.x()))
            config.set(_window_section, 'y', str(window_geometry.y()))
            config.set(_window_section, 'width', str(window_geometry.width()))
            config.set(_window_section, 'height', str(window_geometry.height()))
            # Сохраняем состояние максимизации
            config.set(_window_section, 'maximized', str(self.isMaximized()))
            
            # Сохраняем размеры splitter
            try:
                persist_sizes = self._get_persistable_splitter_sizes()
                if persist_sizes:
                    if not config.has_section('Splitter'):
                        config.add_section('Splitter')
                    config.set('Splitter', 'size1', str(int(persist_sizes[0])))
                    config.set('Splitter', 'size2', str(int(persist_sizes[1])))
            except Exception:
                # Если UI схлопнут или размеры невалидны — [Splitter] не трогаем.
                pass

            # Сохраняем настройку показа подсказок (группа "Панель инструментов" в настройках остаётся)
            try:
                if not config.has_section('Toolbar'):
                    config.add_section('Toolbar')
                # Удаляем устаревшие параметры панели инструментов (панель удалена)
                for _k in ("visible", "area", "floating", "x", "y", "width", "height"):
                    try:
                        config.remove_option("Toolbar", _k)
                    except Exception:
                        pass
                show_tooltips = getattr(self, 'show_tooltips', True)  # По умолчанию True
                config.set('Toolbar', 'show_tooltips', str(show_tooltips))
            except Exception:
                pass

            # Сохраняем настройку подсветки ссылок внутри текста (вкладка "Вид")
            try:
                if not config.has_section('View'):
                    config.add_section('View')
                config.set('View', 'highlight_links_in_text', str(bool(getattr(self, 'highlight_links_in_text', True))))
                # Ограничения ширины (px)
                try:
                    w_tab = int(getattr(self, "max_editor_tab_width_px_saved", getattr(self, "max_editor_tab_width_px", DEFAULT_EDITOR_TAB_MAX_WIDTH_PX)))
                except Exception:
                    w_tab = int(DEFAULT_EDITOR_TAB_MAX_WIDTH_PX)
                try:
                    w_fav = int(getattr(self, "max_favorites_item_width_px_saved", getattr(self, "max_favorites_item_width_px", DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX)))
                except Exception:
                    w_fav = int(DEFAULT_FAVORITES_ITEM_MAX_WIDTH_PX)
                w_tab = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(w_tab)))
                w_fav = max(int(VIEW_WIDTH_MIN_PX), min(int(VIEW_WIDTH_MAX_PX), int(w_fav)))
                config.set('View', 'max_editor_tab_width_px', str(int(w_tab)))
                config.set('View', 'max_favorites_item_width_px', str(int(w_fav)))
            except Exception:
                pass

            # Сохраняем "Разделитель"
            try:
                if not config.has_section("Separator"):
                    config.add_section("Separator")
                config.set("Separator", "text", str(getattr(self, "separator_text", "") or ""))
            except Exception:
                pass

            # Переименование по клику (Tree)
            try:
                if not config.has_section('Tree'):
                    config.add_section('Tree')
                min_ms = int(getattr(self, 'slow_double_click_min_interval_ms', SLOW_DOUBLE_CLICK_MIN_INTERVAL_MS_DEFAULT))
                max_ms = int(getattr(self, 'slow_double_click_max_interval_ms', SLOW_DOUBLE_CLICK_MAX_INTERVAL_MS_DEFAULT))
                min_ms = max(0, min(59999, int(min_ms)))
                max_ms = max(1, min(60000, int(max_ms)))
                if max_ms <= min_ms:
                    max_ms = min(60000, min_ms + 1)
                    if max_ms <= min_ms:
                        min_ms = max(0, max_ms - 1)
                config.set('Tree', 'slow_double_click_min_interval_ms', str(int(min_ms)))
                config.set('Tree', 'slow_double_click_max_interval_ms', str(int(max_ms)))
            except Exception:
                pass
            
            # Сохраняем путь к последнему открытому файлу (как относительный путь)
            if not config.has_section('File'):
                config.add_section('File')
            if self.current_file:
                # Конвертируем абсолютный путь в относительный перед сохранением
                relative_path = self.to_relative_path(self.current_file)
                config.set('File', 'last_file', relative_path)
            else:
                config.set('File', 'last_file', '')
            
            # Сохраняем избранное
            if not config.has_section('Favorites'):
                config.add_section('Favorites')
            # Удаляем устаревшие file_N (после удаления из избранного count уменьшается, ключи остаются).
            try:
                for _k in list(config.options('Favorites')):
                    if _k.startswith('file_'):
                        config.remove_option('Favorites', _k)
            except Exception:
                pass
            # Сохраняем все пути избранного (используем интерфейс get_favorites)
            favorites_list = []
            favorites_paths = self.get_favorites()
            for file_path in favorites_paths:
                if file_path:
                    relative_path = self.to_relative_path(file_path)
                    if relative_path:
                        favorites_list.append(relative_path)
            config.set('Favorites', 'count', str(len(favorites_list)))
            for i, relative_path in enumerate(favorites_list):
                config.set('Favorites', f'file_{i}', relative_path)
            
            # Сохраняем видимость панели избранного
            if hasattr(self, 'favorites_container') and self.favorites_container:
                # ВАЖНО: сохраняем логическое состояние (intent), а не "эффективную" видимость.
                # При закрытии окна вызывается self.hide(), и isVisible() станет False из-за скрытого родителя.
                favorites_visible = bool(getattr(self, "_favorites_panel_visible_state", self.favorites_container.isVisible()))
                config.set('Favorites', 'panel_visible', str(favorites_visible))
            
            # Сохраняем отступ редактора и настройки быстрого доступа
            if not config.has_section('Editor'):
                config.add_section('Editor')
            config.set('Editor', 'left_margin', str(self.editor_left_margin))
            config.set('Editor', 'newlines_count', str(getattr(self, 'newlines_count', 50)))
            # Удаляем устаревшую настройку (могла остаться в старых ini)
            try:
                if config.has_option('Editor', 'cursor_line'):
                    config.remove_option('Editor', 'cursor_line')
            except Exception:
                pass
            # Межстрочный интервал сохраняем отдельно от "активного" значения (применяется после перезапуска)
            line_spacing_to_save = getattr(self, 'editor_line_spacing_saved', getattr(self, 'editor_line_spacing', 100))
            try:
                line_spacing_to_save = int(line_spacing_to_save)
            except Exception:
                line_spacing_to_save = 100
            line_spacing_to_save = max(50, min(200, line_spacing_to_save))
            config.set('Editor', 'line_spacing', str(line_spacing_to_save))

            # Выравнивание по правому краю (trailing) сохраняем отдельно от "активного" значения
            right_align_to_save = getattr(self, 'editor_right_alignment_saved', getattr(self, 'editor_right_alignment', False))
            config.set('Editor', 'right_alignment', str(bool(right_align_to_save)))

            # Правый отступ (px) для режима выравнивания справа
            try:
                right_indent_to_save = getattr(self, 'editor_right_indent_px_saved', getattr(self, 'editor_right_indent_px', getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10)))
                right_indent_to_save = int(right_indent_to_save)
            except Exception:
                right_indent_to_save = int(getattr(TextEditor, "RIGHT_MARGIN_RIGHT_ALIGN_PX", 10))
            right_indent_to_save = max(0, min(500, int(right_indent_to_save)))
            config.set('Editor', 'right_indent', str(int(right_indent_to_save)))

            # Язык интерфейса (перевод)
            try:
                if not config.has_section('languages'):
                    config.add_section('languages')
                # Пишем значение в NFC: в памяти на macOS имя может быть в NFD,
                # а в ini оно должно оставаться переносимым между ОС.
                lang_to_save = _locale_name_nfc(
                    getattr(self, 'ui_translation_saved', getattr(self, 'ui_translation', ''))
                )
                config.set('languages', 'translation', str(lang_to_save))
            except Exception:
                pass

            # Тема: active (текущая)
            try:
                if not config.has_section('Theme'):
                    config.add_section('Theme')
                tm = ThemeManager.instance()
                active = str(tm.active_theme_name())
                config.set('Theme', 'active', active)
                try:
                    tm.sync_ini_active_from_current()
                except Exception:
                    pass
                if config.has_option('Theme', 'custom_theme'):
                    config.remove_option('Theme', 'custom_theme')
                for legacy_key in ('Theme', 'dark_theme'):
                    if config.has_option('Theme', legacy_key):
                        config.remove_option('Theme', legacy_key)
            except Exception:
                pass
            
            # Записываем в файл
            _write_settings_ini_atomic(settings_file, config)
        except Exception:
            pass
    
    def ensure_data_directory(self):
        """Проверяет и создаёт каталог Data, если его нет."""
        if ensure_data_directory():
            return True
        _notify_data_directory_create_failed(self)
        return False
    
    def _save_path_key(self, filepath):
        """Нормализованный ключ пути для per-file политики записи."""
        if not filepath:
            return None
        key = _filesystem_path_key(filepath)
        if key:
            return key
        try:
            return os.path.normcase(os.path.normpath(os.path.abspath(str(filepath))))
        except Exception:
            try:
                return os.path.normcase(os.path.normpath(str(filepath)))
            except Exception:
                return None

    def _queue_pending_save(self, filepath, payload):
        """O(1): коалесит отложенный снапшот для filepath (не затирает другие файлы)."""
        key = self._save_path_key(filepath)
        if not key:
            return
        pending = getattr(self, "_pending_saves", None)
        if not isinstance(pending, dict):
            self._pending_saves = {}
            pending = self._pending_saves
        pending[key] = (str(filepath), payload)

    def _drop_pending_save_for(self, filepath):
        """O(1): снимает отложенный снапшот только для указанного filepath."""
        key = self._save_path_key(filepath)
        if not key:
            return
        pending = getattr(self, "_pending_saves", None)
        if isinstance(pending, dict):
            pending.pop(key, None)

    def _dequeue_next_pending_save(self, after_filepath=None):
        """O(1): следующий отложенный снапшот (предпочитает after_filepath, иначе любой)."""
        pending = getattr(self, "_pending_saves", None)
        if not isinstance(pending, dict) or not pending:
            return None
        key = self._save_path_key(after_filepath) if after_filepath else None
        if key and key in pending:
            return pending.pop(key)
        return pending.popitem()[1]

    def _try_start_next_pending_save(self, after_filepath=None):
        """Запускает следующий отложенный save из очереди per-file."""
        prefer_filepath = after_filepath
        pending = getattr(self, "_pending_saves", None)
        pending_count = len(pending) if isinstance(pending, dict) else 0
        skipped_disabled = 0
        while True:
            item = self._dequeue_next_pending_save(prefer_filepath)
            prefer_filepath = None
            if not item:
                return False
            filepath, payload = item
            if self._is_disk_write_disabled_for(filepath):
                self._queue_pending_save(filepath, payload)
                skipped_disabled += 1
                if skipped_disabled >= pending_count:
                    return False
                continue
            self._save_in_progress = True
            self._disk_write_pending = True
            self._save_in_progress_filepath = str(filepath)
            try:
                self.save_request_signal.emit(str(filepath), payload)
            except Exception:
                self._save_in_progress = False
                self._disk_write_pending = False
                self._save_in_progress_filepath = None
                continue
            self._arm_shutdown_save_watchdog()
            return True

    def _is_disk_write_disabled_for(self, filepath) -> bool:
        key = self._save_path_key(filepath)
        if not key:
            return False
        return key in getattr(self, "_save_write_disabled_paths", set())

    def _is_disk_write_disabled_for_current(self) -> bool:
        return self._is_disk_write_disabled_for(getattr(self, "current_file", None))

    def _sync_autosave_disabled_indicator(self):
        try:
            tb = getattr(self, "title_bar", None)
            if tb is not None and hasattr(tb, "set_autosave_disabled_indicator"):
                tb.set_autosave_disabled_indicator(self._is_disk_write_disabled_for_current())
        except Exception:
            pass

    def _pause_autosave_timers(self):
        """Останавливает debounce/fallback autosave (перед принудительным flush)."""
        try:
            t = getattr(self, "autosave_debounce_timer", None)
            if t is not None:
                t.stop()
        except Exception:
            pass
        try:
            t = getattr(self, "autosave_fallback_timer", None)
            if t is not None:
                t.stop()
        except Exception:
            pass

    def _resume_autosave_timers(self):
        """Возобновляет fallback autosave после flush."""
        if self._is_disk_write_disabled_for_current():
            return
        try:
            t = getattr(self, "autosave_fallback_timer", None)
            if t is not None:
                t.start()
        except Exception:
            pass

    def _schedule_autosave_after_pause(self):
        """Перезапускает debounce autosave — запись только после паузы в вводе."""
        if self._is_disk_write_disabled_for_current():
            return
        if not getattr(self, "current_document", None) or not getattr(self, "current_file", None):
            return
        try:
            t = getattr(self, "autosave_debounce_timer", None)
            if t is None:
                return
            ms = int(getattr(self, "autosave_debounce_ms", 2000))
            t.start(max(500, ms))
        except Exception:
            pass

    def _autosave_debounce_fired(self):
        """Autosave после паузы в вводе (debounce истёк)."""
        self._autosave_tick()

    def _autosave_fallback_tick(self):
        """Страховочный тик: сохранить dirty, если debounce не сработал."""
        if not getattr(self, "_autosave_snapshot_pending", False) and not getattr(self, "_tree_data_changed", False):
            return
        try:
            debounce = getattr(self, "autosave_debounce_timer", None)
            if debounce is not None and debounce.isActive():
                return
        except Exception:
            pass
        self._autosave_tick()

    def get_file_name_without_extension(self):
        """Возвращает имя текущего файла без расширения"""
        if self.current_file:
            filename = os.path.basename(self.current_file)
            # Убираем расширение .json если есть
            if filename.endswith('.json'):
                return filename[:-5]
            return filename
        return "root"
        
    def new_file(self):
        """Создает новый JSON файл"""
        if self._notebook_navigation_blocked_during_snapshot_wait():
            return
        dialog = NewNotebookDialog(
            self,
            item_height=NewNotebookDialog.tree_item_height(self),
        )
        if dialog.exec_() != QDialog.Accepted:
            return

        sanitized = sanitize_filename(str(dialog.filename()), default_stem=None, extension=".json")
        if not sanitized:
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                self,
                APP_BRAND,
                tr("tr_dialog.save_error_empty_name", "Введите имя файла"),
            )
            return

        data_dir = self.get_data_directory()
        if not self.ensure_data_directory():
            return

        if filename_exists_in_dir_case_insensitive(data_dir, sanitized):
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                self,
                APP_BRAND,
                tr("message.file_duplicate", "Файл с таким именем уже существует"),
            )
            return

        # Перед сменой блокнота: flush текущего документа (как в open_file / избранном).
        if self.current_file:
            try:
                self.on_text_changed()
            except Exception:
                pass
            try:
                if not self._flush_current_document_async_if_dirty():
                    return
            except Exception:
                return

        root_name = sanitized[:-5] if sanitized.lower().endswith(".json") else sanitized

        # Создаем пустую структуру
        # Добавляем переводы каретки для быстрого доступа к строкам обложки
        initial_cover = "\n" * self.newlines_count
        root_data = {
            "type": "folder",
            "name": root_name,
            "cover": initial_cover,
            "children": []
        }

        filepath = _win_qt_path(os.path.join(data_dir, sanitized))

        try:
            jbp_dump_json(filepath, root_data, JBP_KIND_NOTEBOOK, exclusive=True)
        except FileExistsError:
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                self,
                APP_BRAND,
                tr("message.file_duplicate", "Файл с таким именем уже существует"),
            )
            return
        except OSError as exc:
            if filename_exists_in_dir_case_insensitive(data_dir, sanitized):
                _qmessagebox_single_ok(
                    QMessageBox.Warning,
                    self,
                    APP_BRAND,
                    tr("message.file_duplicate", "Файл с таким именем уже существует"),
                )
            else:
                _qmessagebox_single_ok(
                    QMessageBox.Critical,
                    self,
                    APP_BRAND,
                    _disk_io_fail_message(filepath=filepath, exc=exc),
                )
            return

        # Создаем документ-владелец данных (в памяти) после успешной записи на диск
        json_cache = JsonMemoryCache()
        doc = json_cache.create_document(filepath, root_data)

        self._activate_document(doc)
        self.setWindowTitle(f"{APP_BRAND} - {sanitized}")
        if getattr(self, "favorites_bar_sandbox", None):
            self.favorites_bar_sandbox.set_active_file(filepath)
    
    def _file_size_bytes(self, path):
        try:
            return int(_io_getsize(path))
        except Exception:
            return None

    def _confirm_large_file_open(self, size_bytes):
        size_label = _format_file_size_human(size_bytes)
        res = ThemedMessageDialog.question_yes_no(
            self,
            APP_BRAND,
            _tr_with_line(
                "message.file_size_warning",
                "Этот файл очень большой. Загрузка может занять много времени и использовать много памяти. Продолжить?",
                size_label,
            ),
            default_button=QMessageBox.No,
            button_labels={
                QMessageBox.Yes: tr("dialog.button_continue", "Продолжить"),
                QMessageBox.No: tr("dialog.button_cancel", "Отмена"),
            },
        )
        return res == QMessageBox.Yes

    def _confirm_large_txt_import_batch(self, warn_entries):
        """Подтверждение импорта одного или нескольких больших txt (GUI-поток, до worker)."""
        if not warn_entries:
            return True
        if len(warn_entries) == 1:
            _path, _label, size = warn_entries[0]
            return self._confirm_large_file_open(size)
        labels = [str(label or "—") for _path, label, _size in warn_entries]
        names_text = self._format_export_name_list(labels)
        res = ThemedMessageDialog.question_yes_no(
            self,
            APP_BRAND,
            _tr_with_line(
                "message.file_size_warning",
                "Этот файл очень большой. Загрузка может занять много времени и использовать много памяти. Продолжить?",
                names_text,
            ),
            default_button=QMessageBox.No,
            button_labels={
                QMessageBox.Yes: tr("dialog.button_continue", "Продолжить"),
                QMessageBox.No: tr("dialog.button_cancel", "Отмена"),
            },
        )
        return res == QMessageBox.Yes

    def _prepare_txt_import_file_paths(self, file_paths):
        """Фильтрует/подтверждает txt перед фоновым импортом. None — пользователь отменил."""
        entries = _scan_txt_import_file_entries(file_paths)
        if not entries:
            return []

        allowed_paths = []
        warn_entries = []
        rejected_max_names = []

        for file_path, _rel, fail_label in entries:
            label = str(fail_label or os.path.basename(str(file_path or "")) or "—")
            size = self._file_size_bytes(file_path)
            if size is not None and size > _TXT_SIZE_MAX_BYTES:
                rejected_max_names.append(label)
                continue
            if size is not None and size > _TXT_SIZE_WARN_BYTES:
                warn_entries.append((file_path, label, size))
            allowed_paths.append(file_path)

        if rejected_max_names:
            names_text = (
                rejected_max_names[0]
                if len(rejected_max_names) == 1
                else self._format_export_name_list(rejected_max_names)
            )
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                self,
                APP_BRAND,
                _tr_with_line(
                    "message.file_size_too_large",
                    "Файл слишком большой для импорта:",
                    names_text,
                ),
            )

        if not allowed_paths:
            return []

        if warn_entries and not self._confirm_large_txt_import_batch(warn_entries):
            return None

        return allowed_paths

    def _check_notebook_size_allowed(self, filepath) -> bool:
        size = self._file_size_bytes(filepath)
        if size is None:
            return True
        if size > _NOTEBOOK_SIZE_WARN_BYTES:
            return self._confirm_large_file_open(size)
        return True

    def _check_txt_size_allowed(self, filepath) -> bool:
        size = self._file_size_bytes(filepath)
        if size is None:
            return True
        if size > _TXT_SIZE_MAX_BYTES:
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                self,
                APP_BRAND,
                _tr_with_line(
                    "message.file_size_too_large",
                    "Файл слишком большой для импорта:",
                    _format_file_size_human(size),
                ),
            )
            return False
        if size > _TXT_SIZE_WARN_BYTES:
            return self._confirm_large_file_open(size)
        return True

    def _set_notebook_load_busy(self, busy: bool):
        if busy:
            if not getattr(self, "_notebook_load_busy", False):
                try:
                    QApplication.setOverrideCursor(Qt.WaitCursor)
                except Exception:
                    pass
                self._notebook_load_busy = True
            return
        if getattr(self, "_notebook_load_busy", False):
            try:
                QApplication.restoreOverrideCursor()
            except Exception:
                pass
            self._notebook_load_busy = False

    def _try_get_cached_notebook_document(self, filepath):
        """Возвращает документ из RAM-кэша без чтения с диска."""
        if not filepath:
            return None
        try:
            json_cache = JsonMemoryCache()
            doc = json_cache.get_document(filepath)
            if doc is not None:
                norm_fp = _canonical_file_path(filepath)
                norm_doc = _canonical_file_path(getattr(doc, "filepath", ""))
                if norm_doc and norm_fp and norm_doc != norm_fp:
                    doc = None
            if doc is not None:
                return doc
        except Exception:
            pass
        try:
            norm_fp = _canonical_file_path(filepath)
            doc = getattr(self, "favorites_documents_by_path", {}).get(norm_fp)
            if doc is not None:
                doc_norm = _canonical_file_path(getattr(doc, "filepath", ""))
                if doc_norm and norm_fp and doc_norm != norm_fp:
                    return None
                if _io_exists(getattr(doc, "filepath", "")):
                    return doc
        except Exception:
            pass
        return None

    def _invalidate_pending_notebook_load(self):
        """O(1): отменяет устаревший async open (sync-переключение документа)."""
        self._notebook_load_request_id = int(getattr(self, "_notebook_load_request_id", 0)) + 1
        self._set_notebook_load_busy(False)
        self._notebook_load_block_tab_signals = False
        self._notebook_load_after_success = None
        self._notebook_load_pin_favorites = False

    def _apply_opened_notebook_document(
        self,
        doc,
        *,
        block_tab_signals=False,
        from_notebook_load=False,
    ) -> bool:
        if doc is None or not getattr(doc, "data", None):
            return False
        if block_tab_signals and hasattr(self, "tab_widget") and self.tab_widget:
            self.tab_widget.blockSignals(True)
            try:
                activated = self._activate_document(doc, from_notebook_load=from_notebook_load)
            finally:
                self.tab_widget.blockSignals(False)
        else:
            activated = self._activate_document(doc, from_notebook_load=from_notebook_load)
        if not activated:
            return False
        try:
            self.setWindowTitle(f"{APP_BRAND} - {os.path.basename(doc.filepath)}")
        except Exception:
            pass
        try:
            if getattr(self, "favorites_bar_sandbox", None):
                self.favorites_bar_sandbox.set_active_file(doc.filepath)
        except Exception:
            pass
        if getattr(self, "_notebook_load_pin_favorites", False):
            self._notebook_load_pin_favorites = False
            try:
                norm_fp = _canonical_file_path(doc.filepath)
                if norm_fp:
                    self.favorites_documents_by_path[norm_fp] = doc
            except Exception:
                pass
        if getattr(self, "_notebook_load_after_success", None) == "startup_tree_focus":
            self._notebook_load_after_success = None
            try:
                if hasattr(self, "tree") and self.tree:
                    root_item = self.tree.topLevelItem(0)
                    if root_item:
                        self.tree.setCurrentItem(root_item)
                        self.tree.setFocus()
            except Exception:
                pass
        if getattr(self, "_notebook_load_after_success", None) == "startup_help_saved":
            self._notebook_load_after_success = None
            # Сохраняем состояние только после успешного открытия справки
            # (к этому моменту current_file уже установлен в _activate_document).
            try:
                self.save_settings()
            except Exception:
                pass
        return True

    def _show_notebook_open_failed(self, filepath):
        _qmessagebox_single_ok(
            QMessageBox.Critical,
            self,
            APP_BRAND,
            _tr_with_line(
                "message.file_load_failed",
                "Не удалось загрузить файл:",
                filepath,
            ),
        )

    def _request_async_notebook_open(
        self,
        filepath,
        *,
        block_tab_signals=False,
        after_success=None,
        pin_favorites_cache=False,
    ):
        """Открывает блокнот: из кэша синхронно, иначе читает JSON в save_thread."""
        filepath = str(filepath)
        self._notebook_load_pin_favorites = bool(pin_favorites_cache)
        if not filepath or not _io_exists(filepath):
            self._notebook_load_pin_favorites = False
            return
        if not self._check_notebook_size_allowed(filepath):
            self._notebook_load_pin_favorites = False
            return
        if not jbp_is_valid(filepath, JBP_KIND_NOTEBOOK):
            self._notebook_load_pin_favorites = False
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                self,
                APP_BRAND,
                tr("message.not_a_jbpad_notebook", "Этот файл не является блокнотом JBPad"),
            )
            return

        doc = self._try_get_cached_notebook_document(filepath)
        if doc is not None and doc.data:
            self._notebook_load_after_success = after_success
            if not self._apply_opened_notebook_document(doc, block_tab_signals=block_tab_signals):
                self._notebook_load_pin_favorites = False
                self._show_notebook_open_failed(filepath)
            self._notebook_load_after_success = None
            return

        self._notebook_load_request_id = int(getattr(self, "_notebook_load_request_id", 0)) + 1
        request_id = self._notebook_load_request_id
        self._notebook_load_block_tab_signals = bool(block_tab_signals)
        self._notebook_load_after_success = after_success
        self._set_notebook_load_busy(True)
        try:
            self._ensure_save_thread()
            self.load_notebook_signal.emit(filepath, request_id)
        except Exception:
            self._set_notebook_load_busy(False)
            self._notebook_load_block_tab_signals = False
            self._notebook_load_after_success = None
            self._notebook_load_pin_favorites = False
            _qmessagebox_single_ok(
                QMessageBox.Critical,
                self,
                APP_BRAND,
                _tr_with_line(
                    "message.file_open_failed",
                    "Не удалось открыть файл:",
                    filepath,
                ),
            )

    def _on_notebook_loaded(self, filepath: str, data, request_id: int):
        if int(request_id) != int(getattr(self, "_notebook_load_request_id", 0)):
            return
        self._set_notebook_load_busy(False)
        block_tab_signals = bool(getattr(self, "_notebook_load_block_tab_signals", False))
        self._notebook_load_block_tab_signals = False
        filepath = str(filepath or "")

        if data and isinstance(data, dict):
            try:
                json_cache = JsonMemoryCache()
                doc = json_cache.set_document_data(filepath, data)
                if doc and doc.data:
                    if self._apply_opened_notebook_document(
                        doc,
                        block_tab_signals=block_tab_signals,
                        from_notebook_load=True,
                    ):
                        return
            except Exception:
                pass
            self._notebook_load_after_success = None
            self._notebook_load_pin_favorites = False
            self._show_notebook_open_failed(filepath)
            return

        self._notebook_load_after_success = None
        self._notebook_load_pin_favorites = False
        if filepath and not jbp_is_valid(filepath, JBP_KIND_NOTEBOOK):
            _qmessagebox_single_ok(
                QMessageBox.Warning,
                self,
                APP_BRAND,
                tr("message.not_a_jbpad_notebook", "Этот файл не является блокнотом JBPad"),
            )
        else:
            self._show_notebook_open_failed(filepath)

    def open_file(self):
        """Открывает JSON файл"""
        if self._notebook_navigation_blocked_during_snapshot_wait():
            return
        # Перед любым переключением JSON: принудительно помечаем текущий редактор dirty (O(1), без toPlainText()),
        # затем отправляем snapshot на запись в фон, чтобы исключить потерю последних правок.
        try:
            self.on_text_changed()
        except Exception:
            pass
        try:
            if not self._flush_current_document_async_if_dirty():
                return
        except Exception:
            return

        # Используем каталог Data по умолчанию
        data_dir = self.get_data_directory()
        if not self.ensure_data_directory():
            return

        filename, _ = QFileDialog.getOpenFileName(self, tr("dialog.open_json_file", "Открыть JSON-файл"),
                                                  data_dir, "JSON Files (*.json)")
        if filename:
            try:
                self._request_async_notebook_open(filename)
            except Exception as e:
                _qmessagebox_single_ok(
                    QMessageBox.Critical,
                    self,
                    APP_BRAND,
                    _tr_with_line(
                        "message.file_open_failed",
                        "Не удалось открыть файл:",
                        str(e),
                    ),
                )

    
    # ============================================================
    # Интерфейс работы с избранным (контракт для новой панели)
    # ============================================================
    
    def get_favorites(self):
        """Возвращает список путей к файлам избранного"""
        # Используем новую панель как источник истины, если она существует
        if hasattr(self, 'favorites_bar_sandbox') and self.favorites_bar_sandbox:
            return self.favorites_bar_sandbox.model.stringList()
        return []
    
    def add_favorite(self, path):
        """Добавляет файл в избранное"""
        if not path:
            return False

        stored_path = _abs_realpath_for_comparison(path)
        if not stored_path:
            return False

        if self.is_favorite(stored_path):
            return False

        # Добавляем в новую панель
        if hasattr(self, 'favorites_bar_sandbox') and self.favorites_bar_sandbox:
            current_list = self.favorites_bar_sandbox.model.stringList()
            current_list.append(stored_path)
            self.favorites_bar_sandbox.model.setStringList(current_list)
            return True

        return False

    def remove_favorite(self, path):
        """Удаляет файл из избранного"""
        if not path:
            return False

        target = _canonical_file_path(path)
        if not target:
            return False

        # Удаляем strong-ссылку по пути (для новой панели), чтобы не держать память после удаления из избранного.
        try:
            fav_docs = getattr(self, "favorites_documents_by_path", {})
            for key in list(fav_docs.keys()):
                if _canonical_file_path(key) == target:
                    del fav_docs[key]
        except Exception:
            pass

        # Удаляем из новой панели
        if hasattr(self, 'favorites_bar_sandbox') and self.favorites_bar_sandbox:
            current_list = self.favorites_bar_sandbox.model.stringList()
            removed_path = None
            new_list = []
            for fp in current_list:
                if _canonical_file_path(fp) == target:
                    if removed_path is None:
                        removed_path = fp
                    continue
                new_list.append(fp)
            if removed_path is None:
                return False
            self.favorites_bar_sandbox.model.setStringList(new_list)
            self._sync_favorites_bar_after_list_change(new_list, removed_path=removed_path)
            return True

        return False

    def is_favorite(self, path):
        """Проверяет, добавлен ли файл в избранное"""
        if not path:
            return False

        target = _canonical_file_path(path)
        if not target:
            return False

        # Проверяем в новой панели
        if hasattr(self, 'favorites_bar_sandbox') and self.favorites_bar_sandbox:
            current_list = self.favorites_bar_sandbox.model.stringList()
            for favorite_path in current_list:
                if favorite_path and _canonical_file_path(favorite_path) == target:
                    return True

        return False
    
    def _restore_favorites_bar_selection(self):
        """Восстанавливает выделение избранного по текущему открытому файлу."""
        fav = getattr(self, "favorites_bar_sandbox", None)
        if fav is None:
            return
        fav.set_active_file(self._current_notebook_filepath())

    def _on_sandbox_favorite_activated(self, path):
        """Обработчик активации элемента в новой панели"""
        if not path:
            return
        if self._notebook_navigation_blocked_during_snapshot_wait():
            self._restore_favorites_bar_selection()
            return

        try:
            target_norm = _canonical_file_path(str(path))
        except Exception:
            target_norm = _canonical_file_path(path) or str(path)

        # Игнорируем клик по уже открытому файлу, чтобы не было лишней перезагрузки и перетирания несохранённых правок.
        try:
            current_fp = self.current_file or (getattr(self.current_document, "filepath", None) if getattr(self, "current_document", None) else None)
            current_norm = _canonical_file_path(current_fp) if current_fp else None
            if current_norm and target_norm and current_norm == target_norm:
                return
        except Exception:
            pass

        # На практике в отдельных ветках UI бывают сценарии, когда textChanged не успевает/не срабатывает
        # (например, из-за временно заблокированных сигналов при программной загрузке текста).
        # Перед переключением принудительно помечаем текущий редактор dirty (O(1), без toPlainText()),
        # чтобы snapshot job точно захватил последние изменения.
        try:
            self.on_text_changed()
        except Exception:
            pass

        # Перед сменой JSON-файла: если текущий документ грязный — отправляем снапшот на запись в фон.
        if not self._flush_current_document_async_if_dirty():
            self._restore_favorites_bar_selection()
            return

        # Пытаемся переключиться на документ из strong-кэша по пути (без I/O).
        try:
            by_path = getattr(self, "favorites_documents_by_path", {})
            doc = by_path.get(target_norm)
            if doc is not None:
                try:
                    doc_norm = _canonical_file_path(getattr(doc, "filepath", ""))
                    if doc_norm and target_norm and doc_norm != target_norm:
                        doc = None
                except Exception:
                    doc = None
            if doc is not None and _io_exists(getattr(doc, "filepath", "")):
                if self._activate_document(doc):
                    self.setWindowTitle(f"{APP_BRAND} - {os.path.basename(doc.filepath)}")
                    if getattr(self, "favorites_bar_sandbox", None):
                        self.favorites_bar_sandbox.set_favorite_path_exists(doc.filepath, True)
                        self.favorites_bar_sandbox.set_active_file(doc.filepath)
                else:
                    self._restore_favorites_bar_selection()
                return
        except Exception:
            pass

        # Fallback: открываем с диска/weak-кэша (как раньше), но потом закрепляем документ по пути.
        if _io_exists(str(path)):
            if getattr(self, "favorites_bar_sandbox", None):
                self.favorites_bar_sandbox.set_favorite_path_exists(path, True)
            self._open_favorite_file(str(path))
        else:
            self._restore_favorites_bar_selection()
    
    def _on_sandbox_favorite_removed(self, path):
        """Обработчик удаления элемента из новой панели"""
        # Удаляем через интерфейс (уже удалено из модели делегатом)
        self.remove_favorite(path)
        try:
            if getattr(self, "favorites_bar_sandbox", None):
                remaining = self.favorites_bar_sandbox.model.stringList()
                if not remaining:
                    current_fp = self.current_file or (getattr(self.current_document, "filepath", None) if getattr(self, "current_document", None) else None)
                    normalized_current = os.path.normcase(os.path.normpath(os.path.abspath(current_fp))) if current_fp else None
                    normalized_target = os.path.normcase(os.path.normpath(os.path.abspath(path))) if path else None
                    if normalized_current and normalized_target and normalized_current == normalized_target:
                        # ВАЖНО: перед разрывом последней strong-ссылки на JsonDocument
                        # отправляем снапшот на асинхронную запись именно в файл закрываемой вкладки.
                        self._flush_ui_snapshot_async_to_path(path, getattr(self, "current_document", None))
                        # Перед "схлопыванием" UI сохраняем только [Splitter], не трогая last_file.
                        try:
                            self._persist_splitter_sizes_to_ini()
                        except Exception:
                            pass
                        self._clear_current_document()
                        # Очищаем дерево и вкладки
                        self.tree.clear()
                        self._dispose_all_tab_editors()
                        self.setWindowTitle(APP_BRAND)
        except Exception:
            pass
        # Сохраняем настройки
        self.save_settings()
    
    def add_to_favorites(self):
        """Добавляет файл в избранное через диалог открытия файла"""
        # Защита от повторных вызовов (например, при двойном клике)
        if self._adding_to_favorites:
            return
        self._adding_to_favorites = True
        
        try:
            # Используем каталог Data по умолчанию
            data_dir = self.get_data_directory()
            if not self.ensure_data_directory():
                return

            filename, _ = QFileDialog.getOpenFileName(self, tr("tooltip.add_to_favorites", "Добавить в избранное"),
                                                      data_dir, "JSON Files (*.json)")
            
            if filename:
                if not jbp_is_valid(filename, JBP_KIND_NOTEBOOK):
                    _qmessagebox_single_ok(
                        QMessageBox.Warning,
                        self,
                        APP_BRAND,
                        tr("message.not_a_jbpad_notebook", "Этот файл не является блокнотом JBPad"),
                    )
                    return

                # Проверяем, не добавлен ли уже этот файл
                if self.is_favorite(filename):
                    file_name = os.path.basename(filename)
                    _qmessagebox_single_ok(
                        QMessageBox.Information,
                        self,
                        APP_BRAND,
                        _tr_with_line(
                            "message.file_added",
                            "Следующий файл уже добавлен:",
                            file_name,
                        ),
                    )
                    return
                
                # Добавляем через интерфейс
                if self.add_favorite(filename):
                    if getattr(self, "favorites_bar_sandbox", None):
                        self.favorites_bar_sandbox.set_active_file(filename)
                    # Открываем файл
                    self._open_favorite_file(filename)
                    # Сохраняем настройки
                    self.save_settings()
        finally:
            # Снимаем блокировку после завершения операции
            self._adding_to_favorites = False
    
    def _update_add_temp_file_button_icon(self):
        """Обновляет иконку кнопки добавления временного файла в зависимости от темы"""
        if not hasattr(self, 'add_temp_file_button') or not self.add_temp_file_button:
            return
        self.add_temp_file_button.setIcon(IconManager.instance().icon("add_tab"))
    
    def _open_favorite_file(self, file_path):
        """Открывает файл из избранного - использует ТОЧНО ТУ ЖЕ логику, что и open_file"""
        if not file_path or not _io_exists(file_path):
            return

        # Перед сменой JSON: помечаем текущий редактор dirty и форсируем flush (без disk I/O в UI),
        # чтобы переключение через избранное/диалоги не теряло последние изменения.
        try:
            self.on_text_changed()
        except Exception:
            pass
        try:
            if not self._flush_current_document_async_if_dirty():
                return
        except Exception:
            return

        try:
            json_cache = JsonMemoryCache()
            doc = json_cache.get_document(file_path)
            if doc is not None:
                norm_fp = os.path.normcase(os.path.normpath(os.path.abspath(file_path)))
                norm_doc = os.path.normcase(
                    os.path.normpath(os.path.abspath(getattr(doc, "filepath", "")))
                )
                if norm_doc and norm_doc != norm_fp:
                    json_cache.remove(file_path)
        except Exception:
            pass

        self._notebook_load_pin_favorites = True
        try:
            self._request_async_notebook_open(file_path, pin_favorites_cache=True)
        except Exception as e:
            self._notebook_load_pin_favorites = False
            _qmessagebox_single_ok(
                QMessageBox.Critical,
                self,
                APP_BRAND,
                _tr_with_line(
                    "message.file_open_failed",
                    "Не удалось открыть файл:",
                    str(e),
                ),
            )
    
    def _apply_favorites_panel_visibility(self, visible):
        """Применяет видимость панели избранного"""
        # Сохраняем логическое состояние (intent) независимо от состояния главного окна.
        try:
            self._favorites_panel_visible_state = bool(visible)
        except Exception:
            self._favorites_panel_visible_state = False
        if hasattr(self, 'favorites_container') and self.favorites_container:
            self.favorites_container.setVisible(visible)
            # Также скрываем/показываем разделитель вместе с панелью
            if hasattr(self, 'favorites_separator') and self.favorites_separator:
                self.favorites_separator.setVisible(visible)
    
    def toggle_favorites_panel(self):
        """Переключает видимость панели избранного"""
        if hasattr(self, 'favorites_container') and self.favorites_container:
            # Используем логическое состояние, чтобы не зависеть от видимости родителя (окна).
            is_visible = bool(getattr(self, "_favorites_panel_visible_state", self.favorites_container.isVisible()))
            new_visible = not bool(is_visible)
            self._apply_favorites_panel_visibility(new_visible)
            # Сохраняем настройки после изменения видимости
            self.save_settings()
    
    def save_to_file(self, filepath):
        """Ручное сохранение: запускает snapshot job и запись в save_thread (без disk I/O в UI)."""
        if not filepath:
            return
        key = self._save_path_key(filepath)
        if key and key in getattr(self, "_save_write_disabled_paths", set()):
            # Ручное сохранение — повторная попытка после восстановления носителя.
            self._save_write_disabled_paths.discard(key)
            self._sync_autosave_disabled_indicator()
        # Ручное сохранение всегда форсирует построение снапшота
        self._autosave_snapshot_pending = True
        self._start_snapshot_job(filepath=str(filepath), reason="manual", force=True)
    
    def has_unsaved_changes(self):
        """Проверяет наличие несохраненных изменений"""
        # Простая проверка - можно улучшить
        return True
    
    def load_json_structure(self, data):
        """Загружает JSON stруктуру в дерево"""
        self._cancel_autosave_job()
        self._document_ui_loaded = False
        # При смене документа dirty уже сняты в _flush_open_tabs_to_document_cache.
        # Здесь — только dirty-редакторы текущего документа (без полного toPlainText).
        if getattr(self, "current_document", None) is not None and hasattr(self, "tab_widget") and self.tab_widget:
            for tab_index in range(self.tab_widget.count()):
                text_editor = self.tab_widget.widget(tab_index)
                if not text_editor:
                    continue
                item = self.tab_items.get(text_editor)
                if not item:
                    continue
                try:
                    _ = item.text(0)
                except (RuntimeError, AttributeError):
                    continue
                self._sync_editor_to_item_cache_if_dirty(text_editor, item)

        # Обновляем содержимое дерева без полного reset
        self.tree.setUpdatesEnabled(False)
        tree_signals_were_blocked = False
        try:
            tree_signals_were_blocked = self.tree.signalsBlocked()
            self.tree.blockSignals(True)
        except Exception:
            pass
        tab_updates_were_enabled = True
        try:
            tab_updates_were_enabled = self.tab_widget.updatesEnabled()
        except Exception:
            pass
        try:
            self.tab_widget.setUpdatesEnabled(False)
        except Exception:
            pass
        tab_signals_were_blocked = False
        try:
            tab_signals_were_blocked = self.tab_widget.signalsBlocked()
            self.tab_widget.blockSignals(True)
        except Exception:
            pass

        self.current_item = None
        
        # Сбрасываем флаг изменений при загрузке файла (данные загружаются с диска)
        self._tree_data_changed = False
        
        # Очищаем все вкладки и освобождаем виджеты редакторов
        self._dispose_all_tab_editors()
        # Кеш данных элементов — пер-документный, глобально очищать не нужно (и может фризить).
        
        try:
            if isinstance(data, dict):
                # Пытаемся переиспользовать существующий корневой элемент,
                # чтобы избежать полного сброса дерева
                root_item = self.tree.topLevelItem(0)

                if root_item is None:
                    doc = getattr(self, "current_document", None)
                    attached = False
                    if doc is not None:
                        attached = self._try_attach_cached_ui_tree(doc)
                        if attached:
                            root_item = self.tree.topLevelItem(0)
                    if root_item is None:
                        if doc is not None and not attached:
                            self._discard_cached_ui_tree(doc)
                        # Новые QTreeWidgetItem → новые node_id: старый LRU документов невалиден.
                        try:
                            self._clear_node_editor_doc_cache(doc)
                        except Exception:
                            pass
                        root_item = self.dict_to_item(data)
                        self.tree.addTopLevelItem(root_item)
                else:
                    # Обновляем существующий корневой элемент по новым данным
                    try:
                        self._clear_node_editor_doc_cache()
                    except Exception:
                        pass
                    root_item.setText(0, data.get("name", "unnamed"))
                    root_type = data.get("type", "file")
                    root_item.setData(0, Qt.UserRole, root_type)

                    # ОПТИМИЗАЦИЯ: Используем кеш вместо прямого setData
                    if root_type == "file":
                        content = data.get("content", "")
                        self._set_item_content_to_cache(root_item, content, root_type)
                        icon, is_link = get_file_icon(content, self.style(), return_is_link=True)
                        root_item.setIcon(0, icon)
                        root_item.setData(0, ROLE_IS_LINK_FILE, bool(is_link))
                    else:
                        cover = data.get("cover", "")
                        self._set_item_content_to_cache(root_item, cover, root_type)
                        root_item.setIcon(0, self.style().standardIcon(self.style().SP_DirIcon))
                        root_item.setData(0, ROLE_IS_LINK_FILE, False)

                    # Пересобираем только детей корневого элемента (O(N), не takeChild(0))
                    while root_item.childCount():
                        root_item.takeChild(root_item.childCount() - 1)
                    for child_data in data.get("children", []):
                        child_item = self.dict_to_item(child_data)
                        root_item.addChild(child_item)

                # Если корневой элемент имеет имя "root", заменяем его на имя файла
                if root_item.text(0) == "root":
                    root_item.setText(0, self.get_file_name_without_extension())

                # Для корневого элемента разрешаем только drop, но не drag
                # Важно: корневая папка может быть выбрана для редактирования данных обложки
                root_flags = (Qt.ItemIsEnabled | Qt.ItemIsSelectable | Qt.ItemIsEditable | 
                             Qt.ItemIsDropEnabled)
                root_item.setFlags(root_flags)

                # Убеждаемся, что данные обложки корневой папки инициализированы
                if root_item.data(0, Qt.UserRole) == "folder":
                    cover = self._get_item_content_from_cache(root_item)
                    if cover is None or cover == "":
                        # Если обложки нет или она пустая, добавляем переводы каретки для быстрого доступа
                        initial_cover = "\n" * self.newlines_count
                        self._set_item_content_to_cache(root_item, initial_cover, "folder")

                root_item.setExpanded(True)

                doc = getattr(self, "current_document", None)
                if doc is not None:
                    doc._ui_tree_ui_dirty = False

                # Сразу открываем корневую папку в единственной вкладке (без промежуточной пустой вкладки)
                self.open_item_in_new_tab(root_item)

            self.apply_ui_font_to_tabs()
        finally:
            self._document_ui_loaded = True
            try:
                self.tree.blockSignals(tree_signals_were_blocked)
            except Exception:
                pass
            try:
                self.tab_widget.blockSignals(tab_signals_were_blocked)
            except Exception:
                pass
            try:
                self.tab_widget.setUpdatesEnabled(tab_updates_were_enabled)
            except Exception:
                pass
            self.tree.setUpdatesEnabled(True)

    def _flush_open_tabs_to_document_cache(self, doc):
        """Сохраняет открытые вкладки в item_cache указанного документа (до смены current_document)."""
        if doc is None or not hasattr(self, "tab_widget") or not self.tab_widget:
            return
        saved_cache = self._item_data_cache
        try:
            self._item_data_cache = doc.item_cache
            for tab_index in range(self.tab_widget.count()):
                text_editor = self.tab_widget.widget(tab_index)
                if not text_editor:
                    continue
                item = self.tab_items.get(text_editor)
                if not item:
                    continue
                try:
                    _ = item.text(0)
                    if self._is_editor_dirty_for_autosave(text_editor):
                        self._capture_editor_to_item_cache(text_editor, item)
                except (RuntimeError, AttributeError):
                    pass
        finally:
            self._item_data_cache = saved_cache

    def _detach_document_ui_tree(self, doc):
        """Снимает корень QTreeWidget с виджета и сохраняет на документ для быстрого возврата."""
        if doc is None or not getattr(self, "tree", None):
            return
        try:
            if self.tree.topLevelItemCount() > 0:
                root = self.tree.takeTopLevelItem(0)
                if root is not None:
                    doc._ui_tree_root = root
        except Exception:
            pass

    def _discard_cached_ui_tree(self, doc):
        """Удаляет отсоединённый кэш UI-дерева документа."""
        if doc is None:
            return
        root = getattr(doc, "_ui_tree_root", None)
        if root is None:
            return
        doc._ui_tree_root = None
        try:
            while root.childCount():
                child = root.takeChild(root.childCount() - 1)
                try:
                    del child
                except Exception:
                    pass
            del root
        except Exception:
            pass

    def _try_attach_cached_ui_tree(self, doc):
        """Прикрепляет кэшированное UI-дерево документа без пересборки dict_to_item."""
        if doc is None:
            return False
        if getattr(doc, "_ui_tree_ui_dirty", False):
            self._discard_cached_ui_tree(doc)
            return False
        root = getattr(doc, "_ui_tree_root", None)
        if root is None:
            return False
        try:
            doc._ui_tree_root = None
            self.tree.addTopLevelItem(root)
            return True
        except Exception:
            doc._ui_tree_root = root
            return False

    def _activate_document(self, doc, *, from_notebook_load=False):
        """Переключает UI на документ; при ошибке построения дерева откатывает прежнее состояние."""
        if doc is None or not getattr(doc, "data", None):
            return False
        old_doc = getattr(self, "current_document", None)
        try:
            if old_doc is not None and old_doc is not doc:
                self._flush_open_tabs_to_document_cache(old_doc)
            self._set_current_document(doc, from_notebook_load=from_notebook_load)
            self.load_json_structure(doc.data)
            return True
        except Exception:
            try:
                if old_doc is not None and old_doc is not doc:
                    self._set_current_document(old_doc)
                    self.load_json_structure(old_doc.data)
                elif old_doc is None:
                    self._clear_current_document()
            except Exception:
                pass
            return False

    def _set_current_document(self, doc, *, from_notebook_load=False):
        """Устанавливает активный документ и привязывает пер-документные кеши (O(1)).

        Старый документ отдаём на освобождение в save_thread, чтобы не фризить UI.
        """
        old_doc = getattr(self, "current_document", None)
        if old_doc is not doc and not from_notebook_load:
            self._invalidate_pending_notebook_load()
        if old_doc is not None and old_doc is not doc:
            self._detach_document_ui_tree(old_doc)
            try:
                self.release_document_signal.emit(old_doc)
            except Exception:
                pass

        self.current_document = doc
        self.current_file = _win_qt_path(doc.filepath) if doc is not None else None
        try:
            self._item_data_cache = doc.item_cache if doc is not None else {}
        except Exception:
            self._item_data_cache = {}

        # При появлении/смене документа синхронизируем видимость вкладок/кнопок/разделителя.
        try:
            self._sync_editor_chrome_visibility()
        except Exception:
            pass
        try:
            self._sync_autosave_disabled_indicator()
            if not self._is_disk_write_disabled_for_current():
                self._resume_autosave_timers()
        except Exception:
            pass

    def _clear_current_document(self):
        """Сбрасывает активный документ (O(1), без I/O) и отдаёт его на освобождение в фоне."""
        self._invalidate_pending_notebook_load()
        old_doc = getattr(self, "current_document", None)
        if old_doc is not None:
            self._flush_open_tabs_to_document_cache(old_doc)
            self._detach_document_ui_tree(old_doc)
        self.current_document = None
        self.current_file = None
        self._item_data_cache = {}
        if old_doc is not None:
            try:
                self.release_document_signal.emit(old_doc)
            except Exception:
                pass

        # Если документа нет — скрываем вкладки/кнопки/разделитель.
        try:
            self._sync_editor_chrome_visibility()
            self._sync_autosave_disabled_indicator()
        except Exception:
            pass

    def _ensure_titlebar_saving_arm_timer(self):
        """Лениво создаёт single-shot таймер индикатора «Сохранение…» (один на MainWindow)."""
        timer = getattr(self, "_titlebar_saving_arm_timer", None)
        if timer is not None:
            return timer
        timer = QTimer(self)
        timer.setSingleShot(True)
        timer.timeout.connect(self._show_titlebar_saving_indicator)
        self._titlebar_saving_arm_timer = timer
        return timer

    def _show_titlebar_saving_indicator(self):
        try:
            tb = getattr(self, "title_bar", None)
            if tb is not None and hasattr(tb, "set_saving_indicator"):
                tb.set_saving_indicator(True)
        except Exception:
            pass

    def _arm_titlebar_saving_indicator(self):
        """Показывает «Сохранение…» в titlebar только если wait длится дольше grace period."""
        self._disarm_titlebar_saving_indicator(show=False)
        try:
            self._ensure_titlebar_saving_arm_timer().start(400)
        except Exception:
            pass

    def _disarm_titlebar_saving_indicator(self, *, show=False):
        try:
            timer = getattr(self, "_titlebar_saving_arm_timer", None)
            if timer is not None:
                timer.stop()
        except Exception:
            pass
        if show:
            return
        try:
            tb = getattr(self, "title_bar", None)
            if tb is not None and hasattr(tb, "set_saving_indicator"):
                tb.set_saving_indicator(False)
        except Exception:
            pass

    def _cancel_autosave_job(self):
        """Отменяет текущий snapshot job (без dispatch на диск)."""
        job = getattr(self, "_autosave_job", None)
        if job is not None:
            try:
                job["cancelled"] = True
            except Exception:
                pass
        self._autosave_job = None

    def _has_pending_notebook_changes(self) -> bool:
        """True — в текущем блокноте есть несохранённые изменения или идёт запись."""
        try:
            return bool(
                getattr(self, "_tree_data_changed", False)
                or getattr(self, "_autosave_snapshot_pending", False)
                or getattr(self, "_dirty_node_ids", None)
                or getattr(self, "_dirty_editors", None)
                or getattr(self, "_disk_write_pending", False)
                or getattr(self, "_save_in_progress", False)
                or getattr(self, "_autosave_job", None) is not None
            )
        except Exception:
            return False

    def _shutdown_has_orphan_disk_io(self) -> bool:
        """True — запись/очередь save_thread жива, хотя current_file уже сброшен."""
        if getattr(self, "_save_in_progress", False) or getattr(self, "_disk_write_pending", False):
            return True
        if getattr(self, "_autosave_job", None) is not None:
            return True
        pending = getattr(self, "_pending_saves", None)
        return isinstance(pending, dict) and bool(pending)

    def _discard_pending_changes_for_current_document(self):
        """Сбрасывает dirty-состояние текущего блокнота (явный discard при смене файла)."""
        self._cancel_autosave_fail_reminder()
        self._cancel_autosave_job()
        self._tree_data_changed = False
        self._autosave_snapshot_pending = False
        self._drop_pending_save_for(getattr(self, "current_file", None))
        self._disk_write_pending = False
        try:
            self._dirty_node_ids.clear()
        except Exception:
            self._dirty_node_ids = set()
        try:
            self._dirty_editors.clear()
        except Exception:
            self._dirty_editors = set()

    def _needs_snapshot_before_file_switch(self):
        """True — перед сменой файла нужен snapshot или ожидание текущего job."""
        if self._is_disk_write_disabled_for(getattr(self, "current_file", None)):
            return False
        if getattr(self, "_autosave_job", None) is not None:
            return True
        if getattr(self, "_dirty_node_ids", None):
            return True
        pending = bool(getattr(self, "_autosave_snapshot_pending", False))
        tree_changed = bool(getattr(self, "_tree_data_changed", False))
        if not pending and not tree_changed:
            return False
        try:
            counter = int(getattr(self, "_change_counter", 0))
            last_disp = int(getattr(self, "_last_dispatched_save_counter", 0))
        except Exception:
            counter = 0
            last_disp = 0
        in_flight = bool(
            getattr(self, "_save_in_progress", False)
            or getattr(self, "_disk_write_pending", False)
        )
        if in_flight and counter <= last_disp:
            return False
        return True

    def _filepath_has_pending_disk_io(self, filepath) -> bool:
        """True — для filepath ещё есть snapshot/save в очереди или на диске."""
        key = self._save_path_key(filepath)
        if not key:
            return False
        job = getattr(self, "_autosave_job", None)
        if isinstance(job, dict):
            if self._save_path_key(job.get("filepath")) == key:
                return True
        if getattr(self, "_save_in_progress", False):
            if self._save_path_key(getattr(self, "_save_in_progress_filepath", None)) == key:
                return True
        pending = getattr(self, "_pending_saves", None)
        if isinstance(pending, dict) and key in pending:
            return True
        return False

    def _ensure_save_ack_poll_timer(self):
        timer = getattr(self, "_save_ack_poll_timer", None)
        if timer is not None:
            return timer
        timer = QTimer(self)
        timer.setInterval(20)
        timer.setSingleShot(False)
        timer.timeout.connect(self._on_save_ack_poll)
        self._save_ack_poll_timer = timer
        return timer

    def _finish_save_ack_wait(self):
        try:
            timer = getattr(self, "_save_ack_poll_timer", None)
            if timer is not None:
                timer.stop()
        except Exception:
            pass
        loop = getattr(self, "_save_ack_wait_loop", None)
        if loop is not None:
            try:
                loop.quit()
            except Exception:
                pass

    def _on_save_ack_poll(self):
        wait_fp = getattr(self, "_save_ack_wait_filepath", None)
        if wait_fp and not self._filepath_has_pending_disk_io(wait_fp):
            if getattr(self, "_save_ack_wait_result", None) is None:
                self._save_ack_wait_result = "success"
            self._finish_save_ack_wait()
            return
        try:
            timeout_ms = int(getattr(self, "_save_ack_wait_timeout_ms", 0) or 0)
        except Exception:
            timeout_ms = 0
        if timeout_ms > 0:
            started = getattr(self, "_save_ack_wait_started", None)
            if started is not None:
                try:
                    elapsed_ms = (time.perf_counter() - started) * 1000.0
                    if elapsed_ms >= float(timeout_ms):
                        self._save_ack_wait_result = "timeout"
                        self._finish_save_ack_wait()
                except Exception:
                    pass

    def _maybe_release_save_ack_wait(self, filepath, success: bool):
        wait_fp = getattr(self, "_save_ack_wait_filepath", None)
        if not wait_fp:
            return
        if self._save_path_key(filepath) != self._save_path_key(wait_fp):
            return
        if self._filepath_has_pending_disk_io(wait_fp):
            return
        self._save_ack_wait_result = "success" if success else "fail"
        self._finish_save_ack_wait()

    def _wait_for_save_ack(self, filepath, timeout_ms: int = 0, *, show_saving_indicator: bool = False) -> str:
        """Ждёт завершения записи filepath на диск (success/fail), не только dispatch.

        Returns:
            idle | success | fail | timeout
        """
        if not filepath:
            return "idle"
        if not self._filepath_has_pending_disk_io(filepath):
            return "idle"

        if getattr(self, "_save_ack_wait_in_progress", False):
            return getattr(self, "_save_ack_wait_result", None) or "timeout"

        self._save_ack_wait_in_progress = True
        self._save_ack_wait_filepath = filepath
        self._save_ack_wait_result = None
        self._save_ack_suppress_fail_dialog = True
        if show_saving_indicator:
            self._arm_titlebar_saving_indicator()
        was_enabled = self.isEnabled()
        try:
            try:
                self.setEnabled(False)
            except Exception:
                pass
            loop = QEventLoop()
            self._save_ack_wait_loop = loop
            self._save_ack_wait_started = time.perf_counter()
            self._save_ack_wait_timeout_ms = int(timeout_ms or 0)
            poll = self._ensure_save_ack_poll_timer()
            poll.start()
            self._on_save_ack_poll()
            loop.exec_()
            return str(getattr(self, "_save_ack_wait_result", None) or "timeout")
        finally:
            if was_enabled:
                try:
                    self.setEnabled(True)
                except Exception:
                    pass
            try:
                poll = getattr(self, "_save_ack_poll_timer", None)
                if poll is not None:
                    poll.stop()
            except Exception:
                pass
            self._save_ack_wait_loop = None
            self._save_ack_wait_started = None
            self._save_ack_wait_timeout_ms = 0
            self._save_ack_suppress_fail_dialog = False
            self._save_ack_wait_filepath = None
            self._save_ack_wait_in_progress = False
            if show_saving_indicator:
                self._disarm_titlebar_saving_indicator()

    def _ensure_snapshot_dispatch_poll_timer(self):
        """Лениво создаёт poll-таймер ожидания snapshot dispatch (один на MainWindow)."""
        timer = getattr(self, "_snapshot_dispatch_poll_timer", None)
        if timer is not None:
            return timer
        timer = QTimer(self)
        timer.setInterval(20)
        timer.setSingleShot(False)
        timer.timeout.connect(self._on_snapshot_dispatch_poll)
        self._snapshot_dispatch_poll_timer = timer
        return timer

    def _finish_snapshot_dispatch_wait(self):
        try:
            timer = getattr(self, "_snapshot_dispatch_poll_timer", None)
            if timer is not None:
                timer.stop()
        except Exception:
            pass
        loop = getattr(self, "_snapshot_wait_loop", None)
        if loop is not None:
            try:
                loop.quit()
            except Exception:
                pass

    def _on_snapshot_dispatch_poll(self):
        if getattr(self, "_autosave_job", None) is None:
            self._finish_snapshot_dispatch_wait()
            return
        try:
            timeout_ms = int(getattr(self, "_snapshot_wait_timeout_ms", 0) or 0)
        except Exception:
            timeout_ms = 0
        if timeout_ms > 0:
            started = getattr(self, "_snapshot_wait_started", None)
            if started is not None:
                try:
                    elapsed_ms = (time.perf_counter() - started) * 1000.0
                    if elapsed_ms >= float(timeout_ms):
                        self._finish_snapshot_dispatch_wait()
                except Exception:
                    pass

    def _notebook_navigation_blocked_during_snapshot_wait(self) -> bool:
        """True — идёт flush/snapshot/save ack wait; навигацию по блокнотам откладываем."""
        return bool(
            getattr(self, "_snapshot_wait_in_progress", False)
            or getattr(self, "_save_ack_wait_in_progress", False)
            or getattr(self, "_file_switch_flush_in_progress", False)
        )

    def _wait_for_snapshot_dispatch(self, timeout_ms: int = 0, *, show_saving_indicator: bool = False):
        """Ждёт dispatch snapshot job. timeout_ms=0 — без лимита (flush-path).

        Returns:
            True — job завершён (payload отправлен или job не был).
            False — таймаут, job ещё активен.
        """
        if getattr(self, "_snapshot_wait_in_progress", False):
            return getattr(self, "_autosave_job", None) is None

        if getattr(self, "_autosave_job", None) is None:
            return True

        self._snapshot_wait_in_progress = True
        if show_saving_indicator:
            self._arm_titlebar_saving_indicator()
        was_enabled = self.isEnabled()
        try:
            try:
                self.setEnabled(False)
            except Exception:
                pass
            loop = QEventLoop()
            self._snapshot_wait_loop = loop
            self._snapshot_wait_started = time.perf_counter()
            self._snapshot_wait_timeout_ms = int(timeout_ms or 0)
            poll = self._ensure_snapshot_dispatch_poll_timer()
            poll.start()
            self._on_snapshot_dispatch_poll()
            loop.exec_()

            ok = getattr(self, "_autosave_job", None) is None
            return ok
        finally:
            if was_enabled:
                try:
                    self.setEnabled(True)
                except Exception:
                    pass
            try:
                poll = getattr(self, "_snapshot_dispatch_poll_timer", None)
                if poll is not None:
                    poll.stop()
            except Exception:
                pass
            self._snapshot_wait_loop = None
            self._snapshot_wait_started = None
            self._snapshot_wait_timeout_ms = 0
            self._snapshot_wait_in_progress = False
            if show_saving_indicator:
                self._disarm_titlebar_saving_indicator()
            if getattr(self, "_close_requested_during_snapshot_wait", False):
                self._close_requested_during_snapshot_wait = False
                try:
                    QTimer.singleShot(0, self.close)
                except Exception:
                    pass

    def _flush_current_document_async_if_dirty(self):
        """Если текущий документ изменён — snapshot + dispatch перед сменой файла.

        Returns:
            True — можно продолжать смену файла; False — flush не завершён, UI не трогать.
        """
        doc = getattr(self, "current_document", None)
        filepath = getattr(self, "current_file", None)
        if not doc or not filepath:
            return True
        if self._is_disk_write_disabled_for(filepath):
            if self._has_pending_notebook_changes():
                if self._prompt_switch_with_unsaved_write_disabled() != "switch":
                    return False
                self._discard_pending_changes_for_current_document()
            return True

        if not self._needs_snapshot_before_file_switch():
            return True

        self._pause_autosave_timers()
        self._file_switch_flush_in_progress = True
        try:
            if self._needs_snapshot_before_file_switch():
                if getattr(self, "_autosave_job", None) is None:
                    self._start_snapshot_job(filepath=str(filepath), reason="flush", force=True)
                if not self._wait_for_snapshot_dispatch(
                    timeout_ms=0,
                    show_saving_indicator=True,
                ):
                    return False

            if self._filepath_has_pending_disk_io(filepath):
                ack = self._wait_for_save_ack(
                    filepath,
                    timeout_ms=0,
                    show_saving_indicator=True,
                )
                if ack in ("idle", "success"):
                    return True
                if ack == "fail":
                    if self._prompt_switch_with_unsaved_write_disabled(filepath=filepath) != "switch":
                        return False
                    self._discard_pending_changes_for_current_document()
                    return True
                return False
            return True
        finally:
            self._file_switch_flush_in_progress = False
            self._resume_autosave_timers()

    def _flush_ui_snapshot_async_to_path(self, filepath: str, doc=None):
        """Снимает снапшот UI и отправляет на запись в указанный путь.

        Returns:
            True — dispatch завершён; False — job не успел завершиться.
        """
        if not filepath:
            return True
        if self._is_disk_write_disabled_for(filepath):
            return True
        filepath_norm = _win_qt_path(filepath)

        self._pause_autosave_timers()
        try:
            if getattr(self, "_autosave_job", None) is None:
                self._start_snapshot_job(filepath=str(filepath_norm), reason="flush", force=True)
            if not self._wait_for_snapshot_dispatch(
                timeout_ms=0,
                show_saving_indicator=True,
            ):
                return False
            if self._filepath_has_pending_disk_io(filepath_norm):
                ack = self._wait_for_save_ack(
                    filepath_norm,
                    timeout_ms=0,
                    show_saving_indicator=True,
                )
                return ack in ("idle", "success", "fail")
            return True
        finally:
            self._resume_autosave_timers()

    def _preload_favorites_documents_async(self):
        """Запускает фоновую загрузку всех избранных JSON (без блокировки UI)."""
        try:
            for path in self.get_favorites():
                if not path or not _io_exists(path):
                    continue
                try:
                    norm_fp = _canonical_file_path(path)
                except Exception:
                    norm_fp = None
                if norm_fp and norm_fp in getattr(self, "favorites_documents_by_path", {}):
                    continue
                self.preload_favorite_signal.emit(str(path))
        except Exception:
            pass

    def _on_favorite_loaded(self, filepath: str, data):
        """Принимает результат фоновой загрузки избранного (GUI-поток)."""
        if not filepath or not data or not isinstance(data, dict):
            return
        try:
            json_cache = JsonMemoryCache()
            doc = json_cache.set_document_data(filepath, data)
            if doc:
                norm_fp = _canonical_file_path(filepath)
                if norm_fp:
                    self.favorites_documents_by_path[norm_fp] = doc
        except Exception:
            pass
    
    def select_root_item_safe(self, root_item):
        """Безопасно выделяет корневую папку с проверкой существования элемента"""
        if not root_item:
            return
        
        try:
            # Проверяем, что элемент еще существует
            _ = root_item.text(0)
            self.select_root_item(root_item)
        except (RuntimeError, AttributeError):
            # Элемент был удален, пропускаем выделение
            pass
    
    def select_root_item(self, root_item):
        """Принудительно выделяет корневую папку и загружает данные обложки"""
        if not root_item:
            return
        
        try:
            # Проверяем, что элемент еще существует
            _ = root_item.text(0)
        except (RuntimeError, AttributeError):
            # Элемент был удален, пропускаем выделение
            return
        
        # Выделяем корневую папку
        try:
            self.tree.setCurrentItem(root_item)
            self.tree.scrollToItem(root_item)
        except (RuntimeError, AttributeError):
            # Элемент был удален, пропускаем выделение
            return
        
        # Без processEvents/таймеров: дальше просто форсируем обработчик выбора, чтобы обновить cover.
        
        # Вызываем обработчик выбора, чтобы загрузить данные обложки
        # Это гарантирует, что данные обложки загрузятся даже если сигнал не сработал
        try:
            # Проверяем, что элемент еще существует перед вызовом обработчика
            _ = root_item.text(0)
            self.on_tree_selection_changed(root_item)
        except (RuntimeError, AttributeError):
            # Элемент был удален, пропускаем вызов обработчика
            pass
    
    def dict_to_item(self, data):
        """Преобразует словарь в элемент дерева"""
        item = QTreeWidgetItem()
        item.setText(0, data.get("name", "unnamed"))
        
        # Сохраняем тип в данных элемента
        item_type = data.get("type", "file")
        item.setData(0, Qt.UserRole, item_type)
        
        # ОПТИМИЗАЦИЯ: Используем кеш для хранения содержимого вместо item.setData()
        if item_type == "file":
            content = data.get("content", "")
            self._set_item_content_to_cache(item, content, item_type)
            # Иконка для файла (зависит от содержимого)
            icon, is_link = get_file_icon(content, self.style(), return_is_link=True)
            item.setIcon(0, icon)
            item.setData(0, ROLE_IS_LINK_FILE, bool(is_link))
        else:
            # Для папок сохраняем данные обложки в кеш
            cover = data.get("cover", "")
            self._set_item_content_to_cache(item, cover, item_type)
            # Иконка для папки
            item.setIcon(0, self.style().standardIcon(self.style().SP_DirIcon))
            item.setData(0, ROLE_IS_LINK_FILE, False)
        
        # Устанавливаем флаги для drag & drop (кроме корневого элемента, который будет установлен отдельно)
        # Для всех элементов разрешаем drag и drop
        flags = (Qt.ItemIsEnabled | Qt.ItemIsSelectable | Qt.ItemIsEditable | 
                 Qt.ItemIsDragEnabled | Qt.ItemIsDropEnabled)
        item.setFlags(flags)
        
        # Рекурсивно добавляем детей
        if "children" in data:
            for child_data in data["children"]:
                child_item = self.dict_to_item(child_data)
                item.addChild(child_item)
        
        return item
    
    def item_to_dict(self, item):
        """Преобразует элемент дерева в словарь"""
        item_type = item.data(0, Qt.UserRole) or "file"
        # Не сериализуем дочерние элементы без имени (черновики inline-редактора)
        if not item.text(0).strip() and item.parent() is not None:
            return None
        item_name = item.text(0)
        # ОПТИМИЗАЦИЯ: Используем кеш вместо item.data()
        item_content = self._get_item_content_from_cache(item) or ""
        
        result = {
            "type": item_type,
            "name": item_name
        }
        
        if item_type == "file":
            result["content"] = item_content
        else:
            # Для папок сохраняем данные обложки (уже получены из кеша выше)
            if item_content:
                result["cover"] = item_content
            result["children"] = []
            for i in range(item.childCount()):
                child_dict = self.item_to_dict(item.child(i))
                if child_dict is not None:
                    result["children"].append(child_dict)
        
        return result
    
    def add_file(self, parent_item=None):
        """Добавляет новый файл с полем ввода на месте имени"""
        # Проверяем, открыт ли JSON-файл
        if not self.current_file:
            _qmessagebox_single_ok(
                QMessageBox.Information,
                self,
                APP_BRAND,
                tr("message.open_or_create_a_notebook", "Откройте существующий блокнот, или создайте новый"),
            )
            return

        # Убеждаемся, что корневой элемент существует (папка документа).
        root_item = self.tree.topLevelItem(0)
        if not root_item:
            root_item = QTreeWidgetItem()
            root_item.setText(0, self.get_file_name_without_extension())
            root_item.setData(0, Qt.UserRole, "folder")
            root_item.setIcon(0, self.style().standardIcon(self.style().SP_DirIcon))
            initial_cover = "\n" * self.newlines_count
            self._set_item_content_to_cache(root_item, initial_cover, "folder")
            self.tree.addTopLevelItem(root_item)
            root_item.setExpanded(True)

        # Inline-create (РЕШЕНИЕ А): показываем оверлейный редактор; item создастся только после валидного имени.
        try:
            self.tree.begin_inline_create("file")
        except Exception:
            pass
    
